-- Name: cree_monstre_hasard(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cree_monstre_hasard(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function cree_monstre_hasard:Procédure de création de monstre */
/* en position aleatoire                                         */
/*                                                               */
/* On passe en paramètre :                                       */
/*   $1 = le gmon_cod (monstre générique)                        */
/*   $2 = le niveau ou il doit apparaitre                        */
/* Le code sortie est :                                          */
/*    le numéro de monstre                                       */
/*****************************************************************/
/* Liste des modifications :                                     */
/*****************************************************************/
declare
	code_retour integer;
	v_gmon alias for $1;
	v_level alias for $2;
-- récupération des données génériques
	v_num_monstre integer;
	pos_portail integer;
begin
/**********************************************/
/* Etape 1 : on insère dans perso les valeurs */
/**********************************************/
	code_retour := 0;
	v_num_monstre := cree_monstre(v_gmon,v_level);
	pos_portail := pos_aleatoire(v_level);
	update perso_position set ppos_pos_cod = pos_portail where ppos_perso_cod = v_num_monstre;
	code_retour := v_num_monstre;
	return code_retour;
end;



$_$;


ALTER FUNCTION public.cree_monstre_hasard(integer, integer) OWNER TO delain;

--
-- Name: cree_monstre_hasard_nombre(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cree_monstre_hasard_nombre(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/******************************/
/* cree_monstre_hasard_nombre */
/******************************/
declare
	v_gmon_cod alias for $1;
	v_etage alias for $2;
	v_nombre alias for $3;
	temp integer;
	temp2 integer;
begin
	for temp in 1..v_nombre loop
		temp2 := cree_monstre_hasard(v_gmon_cod,v_etage);
	end loop;
	return 'monstres créés';
end;$_$;


