--
-- Name: cree_monstre_pos_nombre(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cree_monstre_pos_nombre(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/******************************/
/* cree_monstre_pos_nombre 		*/
/******************************/
declare
	v_gmon_cod alias for $1;
	v_etage alias for $2;
	v_nombre alias for $3;
	temp integer;
	temp2 text;
	code_monstre integer;
begin
	temp2 := '';
	for temp in 1..v_nombre loop
		code_monstre := cree_monstre_pos(v_gmon_cod,v_etage);
		temp2 := temp2||cast(code_monstre as text)||';';
	end loop;
	return temp2;
end;$_$;


