--
-- Name: cree_parchemin(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cree_parchemin(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function cree_parchemin : met un sort sur un parchemin        */
/* On passe en paramètres                                        */
/*   $1 = lanceur                                                */
/*   $2 = numéro du sort lancé                                   */
/*        0 = rune                                               */
/*        1 = mémo                                               */
/*   $3 = type lancer                                            */
/*        0 = rune                                               */
/*        1 = mémo                                               */
/* Le code sortie est une chaine html                            */
/*****************************************************************/
/* Créé le 20/07/2003                                            */
/* Liste des modifications :                                     */
/*   08/09/2003 : ajout d un tag pour amélioration auto          */
/*   29/01/2004 : modif du type code sortie                      */
/*   01/01/2014 : Alignement gestion PA sur magie                */
/*****************************************************************/
declare
-------------------------------------------------------------
-- variables servant pour la sortie
-------------------------------------------------------------
	code_retour text;				-- chaine html de sortie
	texte_evt text;				-- texte pour évènements
-------------------------------------------------------------
-- variables concernant le lanceur
-------------------------------------------------------------
	lanceur alias for $1;		-- perso_cod du lanceur
	px_gagne numeric;				-- nombre de px gagnés
	v_comp_m integer;				-- valeur compétence magique liée au sort
	v_comp_cod_m integer;		-- numéro compténce magique liée au sort
	v_comp_e integer;				-- valeur compétence enluminure
	v_nom_comp_e text;			-- nom de la compétence enluminure
	lanceur_pa integer;			-- pa du lanceur
	pa_magie integer;				-- bonus eventuel (PA) au lancement du sort
	compt_rune integer;			-- nombre de runes d'un type donné
	nom_rune text;					-- nom de la rune manquenate
	nb_sort integer;				-- nombre de fois ou le sort à été lancé ce tour
	v_pnbs_cod integer;			-- nombre de fois total où a été lancé ce sort
	v_comp_modifie integer;		-- valeur finale de la comp
	nv_parch	integer;				-- code objet_generique du nouveau parchemin
	temp_renommee numeric;
	nb_sort_niveau integer;
	des integer;
	bonus_pa integer;
	gain_renommee numeric;		-- gain (ou perte) de renommée artisanale
-------------------------------------------------------------
-- variables concernant le sort
-------------------------------------------------------------
	num_sort alias for $2;		-- numéro du sort à lancer
	type_lancer alias for $3;	-- type de lancer (memo ou rune)
	nom_sort text;
	cout_pa integer;
	aggressif text;
	niveau_sort integer;
	ligne_rune record;			-- sert pour les boucles de runes
	texte_memo	text;				-- texte de mémorisation du sort
	v_malus_niveau integer;
-------------------------------------------------------------
-- variables de contrôle
-------------------------------------------------------------
	v_code_parch integer;		-- obj_cod du parchemin vierge
	v_comp_cod2 integer; 	--code de la compétence utilisée
	v_comp_cod text;			-- code des compétences possible
-------------------------------------------------------------
-- variables de calcul
-------------------------------------------------------------
	compt integer;
	v_special integer;
	temp_ameliore_competence text;
begin
-------------------------------------------------------------
-- Etape 1 : intialisation des variables
-------------------------------------------------------------
	code_retour := '';
-- les px
	px_gagne := 0;
-------------------------------------------------------------
-- Etape 2 : contrôles
-------------------------------------------------------------
-- sur le sort
	select into nom_sort, aggressif, niveau_sort sort_nom, sort_bloquable, sort_niveau from sorts where sort_cod = num_sort;
	if not found then
		code_retour := code_retour || '<p>Erreur : sort non trouvé !';
		return code_retour;
	end if;
	gain_renommee := niveau_sort / 2;

	-- appel de la fonction cout_pa_magie pour les calculs de cout de pa avec correlation pour l’affichage dans la page magie_php
	select into cout_pa cout_pa_magie(lanceur, num_sort, type_lancer);
	bonus_pa := valeur_bonus(lanceur, 'PAM');

-- sur le lanceur
	select into v_code_parch
		obj_cod
	from perso_objets
	inner join objets on obj_cod = perobj_obj_cod
	left outer join transaction on tran_obj_cod = obj_cod
	where perobj_perso_cod = lanceur
		and perobj_identifie = 'O'
		and obj_gobj_cod IN (481, 482, 483, 729)
		and (case when obj_gobj_cod = 481 then 2
			when obj_gobj_cod = 482 then 3
			when obj_gobj_cod = 483 then 4
			when obj_gobj_cod = 729 then 5 end) >= niveau_sort
	order by (case when tran_obj_cod is null then 0 else 1 end),
		(case when obj_gobj_cod = 481 then 2
			when obj_gobj_cod = 482 then 3
			when obj_gobj_cod = 483 then 4
			when obj_gobj_cod = 729 then 5 end)
	limit 1;
	if not found then
		code_retour := code_retour || 'Erreur : Vous n’avez pas de parchemin vierge du bon niveau à disposition !';
		return code_retour;
	end if;

-- sur la compétence
	if (niveau_sort = 2 or niveau_sort = 3) then
		v_comp_cod := '(91, 92, 93)';
	elsif niveau_sort = 4 then
		v_comp_cod := '(92, 93)';
	elsif niveau_sort = 5 then
		v_comp_cod := '(93)';
	end if;

-- compétence magique
	select into v_comp_m, v_comp_cod_m
		pcomp_modificateur, pcomp_pcomp_cod
	from perso_competences,sorts,competences
	where pcomp_perso_cod = lanceur
		and pcomp_pcomp_cod = sort_comp_cod
		and sort_cod = num_sort
		and pcomp_pcomp_cod = comp_cod;
	if not found then
		code_retour := code_retour || '<p>Erreur : infos compétence non trouvées !';
		return code_retour;
	end if;

-- compétence enluminure : on vérifie qu'elle est bien présente
	v_comp_cod := 'select pcomp_pcomp_cod
		from perso_competences
		where pcomp_perso_cod = ' || to_char(lanceur, '9999999999999') || '
		and pcomp_pcomp_cod in ' || v_comp_cod;
	execute v_comp_cod into v_comp_cod2;
	if not found then
		code_retour := code_retour || '<p>Erreur : Vous n’avez pas la compétence nécessaire (enluminure du bon niveau) !';
		return code_retour;
	else	--On la sélectionne
		select into v_comp_e, v_nom_comp_e
			pcomp_modificateur, comp_libelle
		from perso_competences,competences
		where pcomp_perso_cod = lanceur
			and pcomp_pcomp_cod = v_comp_cod2
                        and pcomp_pcomp_cod = comp_cod;
	end if;

-- on controle les PA
	select into lanceur_pa
		perso_pa
	from perso
	where perso_cod = lanceur;

	if lanceur_pa < cout_pa then
		code_retour := 'Erreur : Vous n’avez pas assez de PA pour lancer ce sort !';
		return code_retour;
	end if;

-- on controle les runes si type lancer = 0
	if type_lancer = 0 then
		for ligne_rune in
			select * from sort_rune where srune_sort_cod = num_sort
		loop
			select into compt_rune perobj_obj_cod
			from perso_objets,objets
			where perobj_perso_cod = lanceur
				and perobj_obj_cod = obj_cod
				and obj_gobj_cod = ligne_rune.srune_gobj_cod;
			if not found then
				select into nom_rune gobj_nom
				from objet_generique
				where gobj_cod = ligne_rune.srune_gobj_cod;

				code_retour := 'Erreur : Vous ne possédez pas de rune '||nom_rune||' nécessaire pour ce sort !';
				return code_retour;
			end if;
		end loop;
	end if;
	if type_lancer = 1 then
		select into compt_rune psort_cod from perso_sorts
		where psort_perso_cod = lanceur
			and psort_sort_cod = num_sort;
		if not found then
			code_retour := 'Erreur : Vous n’avez pas mémorisé le sort !';
			return code_retour;
		end if;
	end if;
	if type_lancer > 1 then
		code_retour := 'Erreur sur le type de lancer !';
		return code_retour;
	end if;
	if type_lancer < 0 then
		code_retour := 'Erreur sur le type de lancer !';
		return code_retour;
	end if;
-- on vérifie que le sort ait pas déjà été lancé plusieurs fois
	if not exists (select 1 from perso_nb_sorts where pnbs_perso_cod = lanceur and pnbs_sort_cod = num_sort) then
		values (nextval('seq_pnbs_cod'),lanceur,num_sort,0);
	end if;

	select into nb_sort,v_pnbs_cod pnbs_nombre,pnbs_cod from perso_nb_sorts
	where pnbs_perso_cod = lanceur
		and pnbs_sort_cod = num_sort;

	if nb_sort >= 2 then
		code_retour := 'Erreur : Vous ne pouvez pas lancer le même plus de 2 fois dans le même tour !';
		return code_retour;
	end if;

	update perso_nb_sorts
	set pnbs_nombre = pnbs_nombre + 1
	where pnbs_cod = v_pnbs_cod;
-----------------------------------------------------------
-- fin de contrôles
------------------------------------------------------------
-- les controles semblent bons, on peut passer à la suite
------------------------------------------------------------
	code_retour := code_retour||'<p>Vous avez tenté d’enluminer le sort <b>'||nom_sort||'</b> sur un parchemin vierge, ';
	code_retour := code_retour||'en utilisant la compétence <b>'||v_nom_comp_e||'</b>.<br><br>';
-- on rajoute le lancement du sort dans le total
	select into compt pnbst_cod from perso_nb_sorts_total
	where pnbst_perso_cod = lanceur
		and pnbst_sort_cod = num_sort;
	if not found then
		values (lanceur,num_sort,0);
	end if;

	update perso_nb_sorts_total
	set pnbst_nombre = pnbst_nombre + 1
	where pnbst_sort_cod = num_sort
		and pnbst_perso_cod = lanceur;

-- on regarde s il y a concentration
	select into compt concentration_perso_cod from concentrations
		where concentration_perso_cod = lanceur;
	if found then
		v_comp_modifie := v_comp_m + 20;
		delete from concentrations where concentration_perso_cod = lanceur;
	else
		v_comp_modifie = v_comp_m;
	end if;
	--
-- modificateurs en fonction du niveau
--
	if type_lancer = 0 then
		v_malus_niveau := (2 - niveau_sort) * 10;
		select into nb_sort_niveau
			coalesce(sum(pnbst_nombre),0)
		from perso_nb_sorts_total,sorts
		where pnbst_perso_cod = lanceur
			and pnbst_sort_cod = sort_cod
			and sort_niveau = niveau_sort;
		if nb_sort_niveau is null then
			nb_sort_niveau := 0;
		end if;
		v_malus_niveau := v_malus_niveau + floor(nb_sort_niveau/15);
		if v_malus_niveau > 0 then
			v_malus_niveau := 0;
		end if;
		v_comp_modifie := v_comp_modifie + v_malus_niveau;
	end if;
--
-- on rajoute maintenant le morceau de choix : enluminure
--
	v_comp_modifie := round(v_comp_modifie * v_comp_e / 100);
--
-- fin modificateurs en fonction du niveau
--
	if v_comp_modifie < 1 then
		v_comp_modifie := 1;
	end if;
	v_special := floor(v_comp_modifie / 5);


	code_retour := code_retour || 'Votre chance de réussir (en tenant compte des modificateurs) est de <b>' || trim(to_char(v_comp_modifie, '9999')) || '</b> ';
-- on regarde si le sort est lancé
	des := lancer_des(1, 100);
	code_retour := code_retour || 'et votre lancer de dés est de <b>' || trim(to_char(des, '9999')) || '</b>.<br>';


	if des > 96 then
	-- echec critique
		if type_lancer = 0 then
		-- on enlève les runes
			for ligne_rune in select * from sort_rune where srune_sort_cod = num_sort loop
				compt := drop_rune(ligne_rune.srune_gobj_cod,lanceur);
			end loop;
		end if;
		gain_renommee := gain_renommee * (-0.5);
		-- on enlève le parchemin vierge
		compt := f_del_objet(v_code_parch);
		code_retour := code_retour||'Il s’agit donc d’un échec automatique.<br><br>';
		update perso set perso_renommee_artisanat = perso_renommee_artisanat + gain_renommee,perso_pa = perso_pa - (4 + bonus_pa) where perso_cod = lanceur;
		texte_evt := '[perso_cod1] a lamentablement échoué dans l’enluminure du sort '||nom_sort;
		perform insere_evenement(lanceur, lanceur, 77, texte_evt, 'O', '[num_sort]=' || num_sort::text);

		return code_retour;
	end if;
	if des > v_comp_modifie then
		gain_renommee := gain_renommee * (-0.2);
		update perso set perso_renommee_artisanat = perso_renommee_artisanat + gain_renommee,perso_pa = perso_pa - (4 + bonus_pa) where perso_cod = lanceur;
		code_retour := code_retour||'Vous avez donc <b>échoué</b>.<br><br>';
		-- on regarde si on améliore la comp
		if v_comp_e <= getparm_n(1) then
			code_retour := code_retour || 'Votre compétence est inférieure à ' || trim(to_char(getparm_n(1),'9999')) || ' %. Vous tentez une amélioration.<br>';
			temp_ameliore_competence := ameliore_competence(lanceur, v_comp_cod2, v_comp_e);
			code_retour := code_retour || 'Votre lancer de dés est de <b>' || split_part(temp_ameliore_competence,';',1) || '</b>, ';
			if split_part(temp_ameliore_competence,';', 2) = '1' then
				code_retour := code_retour || 'Vous avez amélioré cette compétence. Sa nouvelle valeur est <b>' || split_part(temp_ameliore_competence,';',3) || '</b><br><br>.';
			else
				code_retour := code_retour || 'Vous n’avez pas réussi à améliorer cette compétence.<br><br>';
			end if;
		end if;
		if type_lancer = 0 then
			for ligne_rune in select * from sort_rune where srune_sort_cod = num_sort loop
				if lancer_des(1, 100) <= getparm_n(33) then
					compt := drop_rune(ligne_rune.srune_gobj_cod, lanceur);
				end if;
			end loop;
		end if;
		texte_evt := '[perso_cod1] a échoué dans l’enluminure du sort ' || nom_sort;
		perform insere_evenement(lanceur, lanceur, 77, texte_evt, 'O', '[num_sort]=' || num_sort::text);

		return code_retour;
	end if;
	if des <= 5 then
		code_retour := code_retour || 'il s’agit donc d’une <b>réussite critique</b>.<br><br>';
		px_gagne := px_gagne + 1;
		cout_pa := floor(cout_pa / 2);
	else
			if des <= v_special then
				code_retour := code_retour || 'il s’agit donc d’une <b>réussite spéciale</b>.<br><br>';
				cout_pa := cout_pa - 1;
			else
				code_retour := code_retour || 'Vous avez donc <b>réussi</b>.<br><br>';
			end if;
	end if;
-- on enlève les PA
	update perso set perso_pa = perso_pa - cout_pa, perso_renommee_artisanat = perso_renommee_artisanat + gain_renommee where perso_cod = lanceur;
-- px
	if (type_lancer = 0) then
		px_gagne := px_gagne + niveau_sort - 1;
	else
		px_gagne := px_gagne + ((niveau_sort - 1) / 3.0::numeric);
	end if;
-- on tente l amélioration
	temp_ameliore_competence := ameliore_competence_px(lanceur, v_comp_cod2, v_comp_e);
	code_retour := code_retour || 'Votre jet d’amélioration est de <b>' || split_part(temp_ameliore_competence, ';', 1) || '</b>, ';
	if split_part(temp_ameliore_competence, ';', 2) = '1' then
		code_retour := code_retour || 'Vous avez amélioré cette compétence. Sa nouvelle valeur est <b>' || split_part(temp_ameliore_competence, ';', 3) || '</b>.<br><br>';
		px_gagne := px_gagne + 1;
	else
		code_retour := code_retour || 'Vous n’avez pas réussi à améliorer cette compétence.<br><br>';
	end if;
-- on supprime les runes si besoin est
	if type_lancer = 0 then
		for ligne_rune in select * from sort_rune where srune_sort_cod = num_sort loop
			compt := drop_rune(ligne_rune.srune_gobj_cod,lanceur);
		end loop;
	end if;
-- on attribue les PX
	update perso set perso_px = perso_px + px_gagne where perso_cod = lanceur;
-- on regarde pour la mémorisation
	texte_memo := memo_sort(lanceur,num_sort);
	if split_part(texte_memo,';',1) = '-1' then
		code_retour := code_retour||'Vous ne pouvez pas mémoriser ce sort car vous avez atteint votre limite de mémorisation.<br>';
	end if;
	if split_part(texte_memo,';',1) = '1' then
		code_retour := code_retour||'Vous tentez de mémoriser le sort. Votre probabilité de mémorisation est de <b>'||split_part(texte_memo,';',2)||'</b>. ';
		code_retour := code_retour||'Votre lancer des dés est de <b>'||split_part(texte_memo,';',3)||'</b>.<br>';
		if split_part(texte_memo,';',4) = '1' then
			code_retour := code_retour||'Vous avez donc <b>mémorisé</b> ce sort.<br><br>';
			px_gagne := px_gagne + 1;
		else
			code_retour := code_retour||'Vous n’avez pas réussi à mémoriser ce sort.<br><br>';
		end if;
	end if;
	code_retour := code_retour||'Le sort est maintenant enluminé sur un parchemin.';
	code_retour := code_retour||'<br>Vous gagnez '||trim(to_char(px_gagne,'999999D99'))||' PX pour cette action.';
-- on efface le parchemin vierge
	compt := f_del_objet(v_code_parch);

-- on rajoute le parchemin valide
	select into nv_parch gobj_cod
	from objet_generique
	where gobj_sort_cod = num_sort;
	if not found then
		code_retour := code_retour||'<br>Erreur, parchemin type non trouvé! ! (désolé.... )';
		return code_retour;
	end if;

	texte_memo := cree_objet_perso_nombre(nv_parch,lanceur,1);
	texte_evt := '[perso_cod1] a enluminé le sort '||nom_sort;
	perform insere_evenement(lanceur, lanceur, 77, texte_evt, 'O', '[num_sort]=' || num_sort::text);

	return code_retour;
end;
$_$;


ALTER FUNCTION public.cree_parchemin(integer, integer, integer) OWNER TO delain;

--
-- Name: FUNCTION cree_parchemin(integer, integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.cree_parchemin(integer, integer, integer) IS 'Réalise une opération d’enluminure';


--
-- Name: cree_pochette_surprise(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cree_pochette_surprise() RETURNS text
    LANGUAGE plpgsql
    AS $$/*****************************************************************/
/* function cree_pochette_surprise : Procédure de création       */
/*         des pochettes surprises de Léno                       */
/*                                                               */
/* La sortie donne le nombre réussites et d échecs à l ajout de  */
/*pochettes                                                      */
/*****************************************************************/
/* Liste des modifications :                                     */
/* Reivax 27/01/2012 : Création                                  */
/*****************************************************************/
begin
	-- Suppression des pochettes existantes
--	select f_del_objet(obj_cod) from objets where obj_gobj_cod = 642;
	delete from perso_pochette;

	-- Création des nouvelles pochettes
	return cree_objet_tous_persos(642, 1);
end; $$;


ALTER FUNCTION public.cree_pochette_surprise() OWNER TO delain;

--
-- Name: cree_receptacle(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cree_receptacle(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function cree_receptable : met un sort dans un réceptavle     */
/* On passe en paramètres                                        */
/*   $1 = lanceur                                                */
/*   $2 = numéro du sort lancé                                   */
/*        0 = rune                                               */
/*        1 = mémo                                               */
/*   $3 = type lancer                                            */
/*        0 = rune                                               */
/*        1 = mémo                                               */
/* Le code sortie est une chaine html                            */
/*****************************************************************/
/* Créé le 20/07/2003                                            */
/* Liste des modifications :                                     */
/*   08/09/2003 : ajout d un tag pour amélioration auto          */
/*   29/01/2004 : modif du type code sortie                      */
/*****************************************************************/
declare
-------------------------------------------------------------
-- variables servant pour la sortie
-------------------------------------------------------------
	code_retour text;				-- chaine html de sortie
	texte_evt text;				-- texte pour évènements
	texte_memo text;				-- texte pour mémorisation
-------------------------------------------------------------
-- variables concernant le lanceur
-------------------------------------------------------------
	lanceur alias for $1;		-- perso_cod du lanceur
	lanceur_pa integer;			-- pa du lanceur
	pos_lanceur integer;			-- position du lanceur
	v_comp integer;				-- valeur de compétence initiale
	v_comp_modifie integer;		-- valeur de compétence modifiée
	v_comp_cod integer;			-- comp_cod utilisée
	nom_comp text;					-- nom de la compétence utilisée
	px_gagne numeric;				-- px gagnes pour ce sort
	temp_renommee numeric;		-- calcul pour renommee
	pa_magie integer;				-- bonus en cout de lancer de sort
	v_nb_receptacle integer;	-- nombre de réceptacle du perso
	v_nb_rec_utilise integer;	-- nb de réceptacle utilisé
	v_malus_niveau integer;		-- malus lié au niveau
	v_bonus_malus integer;		-- limiteur au malus de niveau
	nb_sort_niveau integer; 	-- nombre de sorts du même niveau déjà lancés
        v_voie_magique integer;         -- voie magique du lanceur
-------------------------------------------------------------
-- variables concernant le sort
-------------------------------------------------------------
	num_sort alias for $2;		-- numéro du sort à lancer
	type_lancer alias for $3;	-- type de lancer (memo ou rune)
	cout_pa integer;				-- Cout en PA du sort
	distance_sort integer;		-- portée du sort
	nom_sort varchar(50);		-- nom du sort
	niveau_sort integer;			-- niveau du sort
	aggressif varchar(2);		-- sort aggressif ?
	temp integer;					-- fourre tout
	compt_rune integer;
	nom_rune text;
	nb_sort integer;
	v_pnbs_cod integer;
        v_special integer;            -- chance de faire un spécial
-------------------------------------------------------------
-- variables de contrôle
-------------------------------------------------------------
	deb_res_controle text;		-- partie 1 du controle sort
	res_controle text;			-- totalité du contrôle sort
	distance_cibles integer;	-- distance entre lanceur et cible
	ligne_rune record;			-- record des rune à dropper
	temp_ameliore_competence text;
										-- chaine temporaire pour amélioration
	niveau_reussite integer;
-------------------------------------------------------------
-- variables de calcul
-------------------------------------------------------------
	des integer;					-- lancer de dés
	compt integer;
begin
-------------------------------------------------------------
-- Etape 1 : intialisation des variables
-------------------------------------------------------------
	code_retour := '';
-- les px
	px_gagne := 0;
-------------------------------------------------------------
-- Etape 2 : contrôles
-------------------------------------------------------------
-- sur le lanceur
	select into v_nb_receptacle perso_nb_receptacle
		from perso where perso_cod = lanceur;
	select into v_nb_rec_utilise count(recsort_cod)
		from recsort
		where recsort_perso_cod = lanceur;
	if v_nb_rec_utilise >= v_nb_receptacle then
		code_retour := code_retour||'<p>Erreur : tous les réceptacles sont utilisés !';
		return code_retour;
	end if;

-- sur le sort
	select into nom_sort,cout_pa,aggressif,niveau_sort sort_nom,sort_cout,sort_bloquable,sort_niveau from sorts where sort_cod = num_sort;
	if not found then
		code_retour := code_retour||'<p>Erreur : sort non trouvé !';
		return code_retour;
	end if;
	temp_renommee := ((niveau_sort-1)*0.1)::numeric;
-- sur la compétence
	select into 	v_comp,
						v_comp_cod,
						nom_comp
					pcomp_modificateur,
					pcomp_pcomp_cod,
					comp_libelle
		from perso_competences,sorts,competences
		where pcomp_perso_cod = lanceur
		and pcomp_pcomp_cod = sort_comp_cod
		and sort_cod = num_sort
		and pcomp_pcomp_cod = comp_cod;
	if not found then
		code_retour := code_retour||'<p>Erreur : infos compétence non trouvées !';
		return code_retour;
	end if;
-- on verifie les voies magiques
        select into v_voie_magique perso_voie_magique from perso
        where perso_cod = lanceur;
    -- les maitres du savoir pouvant lancer tous les sorts, on les exclues du test sauf pour le sort de familier sorcier qui reste uniquement pour les sorciers
  if v_voie_magique != 7 then
        -- guerisseur
        if num_sort = 150 then
            if v_voie_magique != (1) then
                code_retour := 'Erreur vous n''etes pas guérisseur !';
		return code_retour;
            end if;
        end if;
        -- maitre des arcanes
        if num_sort = 146 then
            if v_voie_magique != 2 then
                code_retour := 'Erreur vous n''etes pas Maître des runes !';
		return code_retour;
            end if;
        end if;
        -- enchanteur runique
        if num_sort in(138,167) then
            if v_voie_magique != 5 then
                code_retour := 'Erreur vous n''etes pas enchanteur runique !';
		return code_retour;
            end if;
        end if;
        -- Mage de guerre
        if num_sort = 152 then
            if v_voie_magique != 4 then
                code_retour := 'Erreur vous n''etes pas mage de guerre !';
		return code_retour;
            end if;
        end if;
         -- Mage de bataille
        if num_sort in(153,168) then
            if v_voie_magique != 6 then
                code_retour := 'Erreur vous n''etes pas mage de bataille !';
		return code_retour;
            end if;
        end if;
         -- Sorcier
        if num_sort in(149,166)then
            if v_voie_magique != 3 then
                code_retour := 'Erreur vous n''etes pas sorcier !';
		return code_retour;
            end if;
        end if;
 end if;
-- exclusion du sort familier sorcier
 if v_voie_magique != 7 then
       if num_sort in(149)then
            if v_voie_magique != 3 then
                code_retour := 'Erreur vous n''etes pas sorcier !';
		return code_retour;
            end if;
        end if;
 end if;
-- on controle les PA
	select into cout_pa sort_cout from sorts where sort_cod = num_sort;
	select into lanceur_pa,pos_lanceur
		perso_pa,ppos_pos_cod
		from perso,perso_position
		where perso_cod = lanceur
		and ppos_perso_cod = lanceur;
	cout_pa := cout_pa + valeur_bonus(lanceur, 'PAM');
        if type_lancer != 4 and num_sort in(11,25,38,67,128,136,139) then
		cout_pa := cout_pa + valeur_bonus(lanceur, 'ERU');
         end if;
	if lanceur_pa < cout_pa then
		code_retour := 'Erreur : Vous n’avez pas assez de PA pour lancer ce sort !';
		return code_retour;
	end if;
-- on controle les runes si type lancer = 0
	if type_lancer = 0 then
		for ligne_rune in select * from sort_rune where srune_sort_cod = num_sort loop
			select into compt_rune perobj_obj_cod from perso_objets,objets
				where perobj_perso_cod = lanceur
				and perobj_obj_cod = obj_cod
				and obj_gobj_cod = ligne_rune.srune_gobj_cod;
			if not found then
				select into nom_rune gobj_nom
					from objet_generique
					where gobj_cod = ligne_rune.srune_gobj_cod;
				code_retour := 'Erreur : Vous ne possédez pas de rune '||nom_rune||' nécessaire pour ce sort !';
				return code_retour;
			end if;
		end loop;
	end if;
	if type_lancer = 1 then
		select into compt_rune psort_cod from perso_sorts
			where psort_perso_cod = lanceur
			and psort_sort_cod = num_sort;
		if not found then
			code_retour := 'Erreur : Vous n’avez pas mémorisé le sort !';
			return code_retour;
		end if;
	end if;
	if type_lancer > 1 then
		code_retour := 'Erreur sur le type de lancer !';
		return code_retour;
	end if;
	if type_lancer < 0 then
		code_retour := 'Erreur sur le type de lancer !';
		return code_retour;
	end if;
-- on vérifie que le sort ait pas déjà été lancé plusieurs fois
	if not exists (select 1 from perso_nb_sorts
		where pnbs_perso_cod = lanceur
		and pnbs_sort_cod = num_sort) then
			values (nextval('seq_pnbs_cod'),lanceur,num_sort,0);
	end if;
	select into nb_sort,v_pnbs_cod pnbs_nombre,pnbs_cod from perso_nb_sorts
		where pnbs_perso_cod = lanceur
		and pnbs_sort_cod = num_sort;
	if nb_sort >= 2 then
		code_retour := 'Erreur : Vous ne pouvez pas lancer le même plus de 2 fois dans le même tour !';
		return code_retour;
	end if;
	update perso_nb_sorts
		set pnbs_nombre = pnbs_nombre + 1
		where pnbs_cod = v_pnbs_cod;
-----------------------------------------------------------
-- fin de contrôles
------------------------------------------------------------
-- les controles semblent bons, on peut passer à la suite
------------------------------------------------------------
	code_retour := code_retour||'<p>Vous avez lancé le sort <b>'||nom_sort||'</b> dans un réceptacle, ';
	code_retour := code_retour||'en utilisant la compétence <b>'||nom_comp||'</b>.<br><br>';
-- on rajoute le lancement du sort dans le total
	select into compt pnbst_cod from perso_nb_sorts_total
		where pnbst_perso_cod = lanceur
		and pnbst_sort_cod = num_sort;
	if not found then
			values (lanceur,num_sort,0);
	end if;
	update perso_nb_sorts_total
		set pnbst_nombre = pnbst_nombre + 1
		where pnbst_sort_cod = num_sort
		and pnbst_perso_cod = lanceur;
-- on regarde s il y a concentration
	select into compt concentration_perso_cod from concentrations
		where concentration_perso_cod = lanceur;
	if found then
		v_comp_modifie := v_comp + 20;
		delete from concentrations where concentration_perso_cod = lanceur;
	else
		v_comp_modifie = v_comp;
	end if;
	--
-- modificateurs en fonction du niveau
--
	if type_lancer = 0 then
		v_malus_niveau := (2 - niveau_sort) * 10;
		select into nb_sort_niveau
			coalesce(sum(pnbst_nombre),0)
			from perso_nb_sorts_total,sorts
			where pnbst_perso_cod = lanceur
			and pnbst_sort_cod = sort_cod
			and sort_niveau = niveau_sort;
		if nb_sort_niveau is null then
			nb_sort_niveau := 0;
		end if;
		v_malus_niveau := v_malus_niveau + floor(nb_sort_niveau/15);
		if v_malus_niveau > 0 then
			v_malus_niveau := 0;
		end if;
		v_comp_modifie := v_comp_modifie + v_malus_niveau;
	end if;
--
-- fin modificateurs en fonction du niveau
--
	if v_comp_modifie < 1 then
		v_comp_modifie := 1;
	end if;
-- on determine les chances de faire un spécial
v_special := floor(v_comp_modifie/5);

	code_retour := code_retour||'Votre chance de réussir (en tenant compte des modificateurs) est de <b>'||trim(to_char(v_comp_modifie,'9999'))||'</b> ';
-- on regarde si le sort est lancé
	des := lancer_des(1,100);
	code_retour := code_retour||'et votre lancer de dés est de <b>'||trim(to_char(des,'9999'))||'</b>.<br>';


	if des > 96 then
	-- echec critique
		if type_lancer = 0 then
		-- on enlève les runes
			for ligne_rune in select * from sort_rune where srune_sort_cod = num_sort loop
				compt := drop_rune(ligne_rune.srune_gobj_cod,lanceur);
			end loop;
		end if;
		code_retour := code_retour||'Il s’agit donc d’un échec automatique.<br><br>';
		update perso set perso_renommee_magie = perso_renommee_magie - (temp_renommee*2),perso_pa = perso_pa - 4 where perso_cod = lanceur;
	texte_evt := '[perso_cod1] a lamentablement échoué dans la préparation du sort '||nom_sort;
     	values(nextval('seq_levt_cod'),28,now(),1,lanceur,texte_evt,'O','O',lanceur);
		return code_retour;
		-- renomme magique
	end if;
	if des > v_comp_modifie then
	-- sort loupé
		-- renomme magique
		update perso set perso_renommee_magie = perso_renommee_magie - temp_renommee,perso_pa = perso_pa - 4 where perso_cod = lanceur;
		code_retour := code_retour||'Vous avez donc <b>échoué</b>.<br><br>';
		-- on regarde si on améliore la comp
		if v_comp <= getparm_n(1) then
			code_retour := code_retour||'Votre compétence est inférieure à '||trim(to_char(getparm_n(1),'9999'))||' %. Vous tentez une amélioration.<br>';
			temp_ameliore_competence := ameliore_competence(lanceur,v_comp_cod,v_comp);
			code_retour := code_retour||'Votre lancer de dés est de <b>'||split_part(temp_ameliore_competence,';',1)||'</b>, ';
			if split_part(temp_ameliore_competence,';',2) = '1' then
				code_retour := code_retour||'Vous avez amélioré cette compétence. Sa nouvelle valeur est <b>'||split_part(temp_ameliore_competence,';',3)||'</b><br><br>.';
			else
				code_retour := code_retour||'Vous n’avez pas réussi à améliorer cette compétence.<br><br>';
			end if;
		end if;
		if type_lancer = 0 then
			for ligne_rune in select * from sort_rune where srune_sort_cod = num_sort loop
				if lancer_des(1,100) <= getparm_n(33) then
					compt := drop_rune(ligne_rune.srune_gobj_cod,lanceur);
				end if;
			end loop;
		end if;
	texte_evt := '[perso_cod1] a échoué dans la préparation du sort '||nom_sort;
     	values(nextval('seq_levt_cod'),28,now(),1,lanceur,texte_evt,'O','O',lanceur);
		return code_retour;
	end if;
if des <= 5 then
			code_retour := code_retour||'il s’agit donc d’une <b>réussite critique</b>.<br><br>';
			px_gagne := px_gagne + 1;
			cout_pa := floor(cout_pa/2);
		else
                      if des <= v_special then
                        code_retour := code_retour||'il s’agit donc d’une <b>réussite spéciale</b>.<br><br>';
                        cout_pa := cout_pa - 1;
	              else
			code_retour := code_retour||'Vous avez donc <b>réussi</b>.<br><br>';
                      end if;
		end if;

	niveau_reussite := v_comp_modifie - des;
-- on enlève les PA
	update perso set perso_pa = perso_pa - cout_pa where perso_cod = lanceur;
-- renomme magique
	update perso set perso_renommee_magie = perso_renommee_magie + temp_renommee where perso_cod = lanceur;
-- px
	if (type_lancer = 0) then
		px_gagne := px_gagne + niveau_sort - 1;
	else
		px_gagne := px_gagne + ((niveau_sort - 1)/3.0::numeric);
	end if;
-- on tente l amélioration
	temp_ameliore_competence := ameliore_competence_px(lanceur,v_comp_cod,v_comp);
	code_retour := code_retour||'Votre jet d’amélioration est de <b>'||split_part(temp_ameliore_competence,';',1)||'</b>, ';
	if split_part(temp_ameliore_competence,';',2) = '1' then
		code_retour := code_retour||'Vous avez amélioré cette compétence. Sa nouvelle valeur est <b>'||split_part(temp_ameliore_competence,';',3)||'</b>.<br><br>';
		px_gagne := px_gagne + 1;
	else
		code_retour := code_retour||'Vous n’avez pas réussi à améliorer cette compétence.<br><br>';
	end if;
-- on supprime les runes si besoin est
	if type_lancer = 0 then
		for ligne_rune in select * from sort_rune where srune_sort_cod = num_sort loop
			compt := drop_rune(ligne_rune.srune_gobj_cod,lanceur);
		end loop;
	end if;
-- on attribue les PX
	update perso set perso_px = perso_px + px_gagne where perso_cod = lanceur;
-- on regarde pour la mémorisation
	texte_memo := memo_sort(lanceur,num_sort);
	if split_part(texte_memo,';',1) = '-1' then
		code_retour := code_retour||'Vous ne pouvez pas mémoriser ce sort car vous avez atteint votre limite de mémorisation.<br>';
	end if;
	if split_part(texte_memo,';',1) = '1' then
		code_retour := code_retour||'Vous tentez de mémoriser le sort. Votre probabilité de mémorisation est de <b>'||split_part(texte_memo,';',2)||'</b>. ';
		code_retour := code_retour||'Votre lancer des dés est de <b>'||split_part(texte_memo,';',3)||'</b>.<br>';
		if split_part(texte_memo,';',4) = '1' then
			code_retour := code_retour||'Vous avez donc <b>mémorisé</b> ce sort.<br><br>';
			px_gagne := px_gagne + 1;
		else
			code_retour := code_retour||'Vous n’avez pas réussi à mémoriser ce sort.<br><br>';
		end if;
	end if;
	code_retour := code_retour||'Le sort est maintenant dans un réceptacle.';
	code_retour := code_retour||'<br>Vous gagnez '||trim(to_char(px_gagne,'999999D99'))||' PX pour cette action.';
	texte_evt := '[perso_cod1] a préparé le sort '||nom_sort;
     	values(nextval('seq_levt_cod'),28,now(),1,lanceur,texte_evt,'O','O',lanceur);
	return code_retour;
end;
$_$;


ALTER FUNCTION public.cree_receptacle(integer, integer, integer) OWNER TO delain;

--
-- Name: cree_revolution(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cree_revolution(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*******************************************************************/
/* fonction cree_revolution : crée une révolution de guilde        */
/*  on passe en paramètre :                                        */
/*  $1 = perso_cod du lanceur                                      */
/*  $2 = perso_cod de l'anim ciblé                                 */
/* on a en retour une chaine html                                  */
/*******************************************************************/
declare
-------------------------------------------------
-- variables du lanceur
-------------------------------------------------
	lanceur alias for $1;			-- perso_cod du lanceur
	guilde_lanceur integer;			-- guilde_cod du lanceur
	nom_lanceur text;					-- nom du lanceur
	rang_lanceur text;				-- rang du lanceur dans la guilde
-------------------------------------------------
-- variables de la cible
-------------------------------------------------
	cible alias for $2;				-- perso_cod de la cible
	guilde_cible integer;			-- guilde_cod de la cible
	rang_cible text;					-- rang de la cible dans la guilde
	nom_cible text;					-- nom de la cible
	deja_revolution integer;		-- cible déjà en révolution ?
-------------------------------------------------
-- variables de retour
-------------------------------------------------
	code_retour text;					-- texte du code retour
-------------------------------------------------
-- variables de calcul
-------------------------------------------------
	duree interval;					-- durée de la révolution
	code_msg integer;					-- msg_cod du message qui sera envoyé
	texte_msg text;					-- texte des messages
	titre_msg text;					-- titre des messages
	liste_membres record;			-- liste des membres
	code_revolution integer;		-- code de la révolution

begin
-------------------------------------------------
-- On cherche les infos du lanceur
-------------------------------------------------
	select into nom_lanceur
		perso_nom
		from perso
		where perso_cod = lanceur
		and perso_actif = 'O';
	if not found then
		code_retour := '<p>Erreur ! Lanceur non trouvé !';
		return code_retour;
	end if;
	select into guilde_lanceur,rang_lanceur
		guilde_cod,rguilde_admin
		from guilde,guilde_perso,guilde_rang
		where pguilde_perso_cod = lanceur
		and pguilde_guilde_cod = guilde_cod
		and rguilde_guilde_cod = guilde_cod
		and rguilde_rang_cod = pguilde_rang_cod
		and pguilde_valide = 'O';
	if not found then
		code_retour := '<p>Erreur ! Guilde lanceur non trouvé !';
		return code_retour;
	end if;
	if rang_lanceur = 'O' then
		code_retour := '<p>Erreur ! Le lanceur est un administrateur de guilde !';
		return code_retour;
	end if;
-------------------------------------------------
-- On cherche les infos de la cible
-------------------------------------------------
	select into nom_cible
		perso_nom
		from perso
		where perso_cod = cible
		and perso_actif = 'O';
	if not found then
		code_retour := '<p>Erreur ! Cible non trouvée !';
		return code_retour;
	end if;
	select into guilde_cible,rang_cible
		guilde_cod,rguilde_admin
		from guilde,guilde_perso,guilde_rang
		where pguilde_perso_cod = cible
		and pguilde_guilde_cod = guilde_cod
		and rguilde_guilde_cod = guilde_cod
		and rguilde_rang_cod = pguilde_rang_cod
		and pguilde_valide = 'O';
	if not found then
		code_retour := '<p>Erreur ! Guilde cible non trouvé !';
		return code_retour;
	end if;
	if rang_cible != 'O' then
		code_retour := '<p>Erreur ! Le cible n''est pas administrateur de guilde !';
		return code_retour;
	end if;
-------------------------------------------------
-- On fait les vérifs
-------------------------------------------------
	if guilde_cible != guilde_lanceur then
		code_retour := '<p>Erreur ! Le lanceur et la cible ne sont pas dans la même guilde !';
		return code_retour;
	end if;
--
	select into deja_revolution
		revguilde_cod
		from guilde_revolution
		where revguilde_cible = cible;
	if found then
		code_retour := '<p>Erreur ! La cible est déjà visée par une révolution !';
		return code_retour;
	end if;
--
	select into deja_revolution
		revguilde_cod
		from guilde_revolution
		where revguilde_lanceur = lanceur;
	if found then
		code_retour := '<p>Erreur ! Le lanceur est déjà dans une révolution !';
		return code_retour;
	end if;
-------------------------------------------------
-- Tout semble OK, on continue
-------------------------------------------------
-- en premier, on enregistre les params liés à la révolution
	duree := trim(to_char(getparm_n(34),'9999'))||' days';
	select into code_revolution revguilde_cod
		from guilde_revolution
		where revguilde_lanceur = lanceur
		and revguilde_cible = cible
		and revguilde_guilde_cod = guilde_lanceur;
	if not found then
		code_retour := '<p>Erreur Application : code révolution non trouvé !';
		return code_retour;
	end if;
-- ensuite, on envoie les messages
-- d'abord, pour faire plaisir, celui à la cible
	code_msg := nextval('seq_msg_cod');
	texte_msg := 'Le joueur '||nom_lanceur||' a lancé une révolution contre vous. Les membres de votre guilde ont maintenant '||trim(to_char(getparm_n(34),'9999'));
	texte_msg := texte_msg||' jours pour faire leur choix. D''ici là, vous ne pouvez pas intervenir au sein de votre guilde au sujet de ce membre.';
	titre_msg := 'Révolution !';
-- ensuite, tout le reste de la guilde
	code_msg := nextval('seq_msg_cod');
	texte_msg := 'Le joueur '||nom_lanceur||' a lancé une révolution contre l''administrateur '||nom_cible||'. Vous avez maintenant '||trim(to_char(getparm_n(34),'9999'));
	texte_msg := texte_msg||' jours pour faire votre choix en allant voter dans votre page de guilde.';
	for liste_membres in
		select perso_cod
		from guilde_perso,perso
		where pguilde_guilde_cod = guilde_lanceur
		and pguilde_perso_cod = perso_cod
		and pguilde_valide = 'O'
		and perso_actif = 'O'
		and perso_type_perso = 1
		and perso_cod != cible loop
	end loop;
-- ok, tout le monde est au courant maintenant, il nous reste à initialiser les deux premiers votes
	code_retour := '<p>Vous avez lancé une révolution contre <b>'||nom_cible||'</b>.';
	return code_retour;
end;$_$;


ALTER FUNCTION public.cree_revolution(integer, integer) OWNER TO delain;

--
-- Name: cree_riposte(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cree_riposte(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*********************************************************/
/* fonction cree_riposte : cree un enregistrement dans   */
/*   riposte en fonction de l'existant                   */
/* On passe en paramètres :                              */
/*   $1 = attaquant                                      */
/*   $2 = cible                                          */
/* on a un entier en sortie                              */
/*********************************************************/
declare
	code_retour integer;
	v_attaquant alias for $1;
	v_cible alias for $2;
	v_riposte integer;

begin
	select into v_riposte riposte_cod
		from riposte
		where riposte_attaquant = v_cible
		and riposte_cible = v_attaquant;
	if v_riposte is null then
	-- nouvel enregistrement
	-- on efface les enregistremens éventuellement existants
		delete from riposte
			where riposte_attaquant = v_attaquant
			and riposte_cible = v_cible;
			values (v_attaquant,v_cible,getparm_n(26));
	-- sinon, on ne fait rien
	end if;
	code_retour := 0;
	return code_retour;
end;
$_$;


ALTER FUNCTION public.cree_riposte(integer, integer) OWNER TO delain;

--
-- Name: cree_stat(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cree_stat() RETURNS text
    LANGUAGE plpgsql
    AS $$declare
	code_retour text;
	nb_compte integer;
begin
	code_retour := '';
	select count(compt_cod) into nb_compte from compte where compt_actif != 'N';
	return code_retour;
end;$$;


ALTER FUNCTION public.cree_stat() OWNER TO delain;

--
-- Name: creer_perso_obj_etage(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.creer_perso_obj_etage(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function cree_objet  :Procédure de création d objet     en    */
/*   dans l'inventaire d'un perso                                */
/*                                                               */
/* On passe en paramètre :                                       */
/*   $1 = le gobj_cod (objet   générique)                        */
/*   $2 = le type de perso                                       */
/*   $3 = l'etage concerné                                       */
/* Le code sortie est :                                          */
/*    0 = Tout s est bien passé                                  */
/*   -1 = le gmon_cod n existe pas                               */
/*    2 = cree perso anomalie                                    */
/*****************************************************************/
/* Liste des modifications :                                     */
/*****************************************************************/
declare
	code_retour integer;
	v_gobj alias for $1;
	v_type alias for $2;
	v_etage alias for $3;
-- variables d'enregistrement
        ligne record;

-- variables globales
	compt integer;
	v_code_objet integer;
        v_perso integer;
	retour_cree_perso integer;
begin
-- etape 1 on enregistre les valeurs dans la zone record
for ligne in select pos_etage,pos_cod,perso_cod
 from perso,perso_position,positions
 where perso_actif = 'O'
 and ppos_pos_cod = pos_cod
 and perso_cod = ppos_perso_cod
 and perso_type_perso = v_type
 and pos_etage = v_etage
 order by perso_cod loop

/************************************************/
/* Etape 2 : on insère dans l'étage les valeurs */
/************************************************/
	code_retour := 0;
	v_code_objet := nextval('seq_obj_cod');
	select into compt gobj_cod from objet_generique
		where gobj_cod = v_gobj;
	if not found then
		code_retour := -1;
		return code_retour;
	end if;


/*************************/
/* Etape 4 : on le place */
/*************************/
         v_perso := ligne.perso_cod;
	values (v_code_objet,v_perso,'N','O');
         code_retour := v_code_objet;
end loop;
return code_retour;
end;
$_$;


ALTER FUNCTION public.creer_perso_obj_etage(integer, integer, integer) OWNER TO delain;

--
-- Name: creuser(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.creuser(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function creuser : un perso creuse dans un mur                */
/* On passe en paramètres                                   */
/*    $1 = perso_cod mineur                                      */
/*    $2 = pos_cod position du mur à creuser                     */
/* Le code sortie est une chaine html utilisable directement     */
/*****************************************************************/
/* Créé le 11/02/2006                                  */
/* Modifié le 12/05/2015 par kahlann                   */
/* Modifiction en profondeur des gains du minage :     */
/* Nouvelle répartition des gains, nouveaux gains      */
/*****************************************************************/
declare
--------------------------------------------------------------------------------
-- variables fourre tout
--------------------------------------------------------------------------------
	texte_evt text;	                -- Texte de l'évennement
	code_retour text;				-- chaine qui contiendra le html de retour
	compt integer;					-- compteur mutli usage
	des integer;					-- lancer de des
	nom_competence competences.comp_libelle%type;
	temp_ameliore_competence text;
	tmp_txt text;
	poison integer;			-- Si on a du poison
	ligne record;					-- enregistrements
--------------------------------------------------------------------------------
-- renseignements de l attaquant
--------------------------------------------------------------------------------
	v_mineur alias for $1;	-- perso_cod mineur
	v_pos_mur alias for $2;		-- perso_cod cible
	pa integer; 					-- pa du mineur
	v_force integer; 					-- force du mineur
	pos_mineur integer; 					-- position du mineur
	race_mineur integer; 					-- race du mineur
	v_cout_pa integer;			-- cout en PA de l'action
	comp_creuser  integer;
	comp_creuser_modifie  integer;
	limite_comp_maitre integer; -- limite pour le coup spécial
	v_mur_creusable text;
	v_mur_usure integer;
	v_mur_richesse integer;
	v_mur_texte text;
	num_comp integer;				-- comp_cod utilisée
	res_succes integer;
	res_echec_critique integer;
	res_amelioration integer;
	px_gagne numeric;
	g_obj_cod integer; -- objet obtenu par minage
	obj_nom text;
	v_degats integer;
	v_etage integer;
	v_bonus_creusage integer; --Bonus de creusage de 30% et 7 en dégâts mur
	gain_renommee numeric;		-- gain (ou perte) de renommée artisanale
        nb_objets integer;              -- nombre d'objets utiles gagnés
        v_obj_cod integer;
        v_usure numeric;
begin
	num_comp := 83;
	px_gagne := 0;
	v_cout_pa := 4;
	gain_renommee := 0.1;

	code_retour := '<p>'; -- par défaut, tout est OK
	/***********************************************/
	/* Etape 1 : on vérifie que le mineur existe */
	/***********************************************/
	select into
		pa,
		v_force,
		race_mineur,
		pos_mineur
		perso_pa,
		perso_for,
		perso_race_cod,
		ppos_pos_cod
	from perso,perso_position
	where perso_cod = v_mineur
		and ppos_perso_cod = perso_cod;
	if not found then
		code_retour := '<p>Erreur ! Mineur non trouvé !';
		return code_retour;
	end if;
	/***********************************************/
	/* Etape 2 : on vérifie que le mur existe      */
	/***********************************************/
	select into
		v_mur_creusable,
		v_mur_usure,
		v_mur_richesse
		mur_creusable,
		mur_usure,
		mur_richesse
	from murs
	where mur_pos_cod = v_pos_mur;
	if not found then
		code_retour := '<p>Erreur ! Pas de mur trouvé à cet endroit !';
		return code_retour;
	end if;
	if v_mur_creusable <> 'O' then
		code_retour := '<p>Erreur ! Ce mur ne peut pas être creusé !';
		return code_retour;
	end if;

	/***********************************************/
	/* Etape 3 : on vérifie que le mineur a bien équipé une pioche      */
	/***********************************************/


	/***********************************************/
	/* Etape 4 : on vérifie que le mineur a suffisament de PAs */
	/***********************************************/
	if pa < v_cout_pa then
		code_retour := '<p>Erreur ! Pas assez de PA pour effectuer cette action';
		return code_retour;
	end if;

	-- A partir d'ici on peut creuser.

	/***********************************************/
	/* Etape 5 : on vérifie que le mineur a la competence */
	/***********************************************/
	-- valeur de la competence de base
	select into comp_creuser
		pcomp_modificateur
	from perso_competences
	where pcomp_perso_cod = v_mineur
		and pcomp_pcomp_cod = num_comp;
	if not found then
		code_retour := code_retour|| '<p>Vous n’avez pas encore la compétence requise pour creuser.<br>Celle-ci est donc ajoutée à votre fiche.<br>';
		comp_creuser := 20;
	end if;

	-- Bonus-Malus - 1 - Concentration
	select into compt concentration_perso_cod from concentrations
	where concentration_perso_cod = v_mineur;
	if found then
		comp_creuser_modifie := comp_creuser + 20;
		delete from concentrations where concentration_perso_cod = v_mineur;
		code_retour := code_retour||'Votre concentration augmente vos chances de réussite: 20%<br>';
	else
		comp_creuser_modifie := comp_creuser;
	end if;
	-- Bonus-Malus - 1 - Nains: +20
	if race_mineur = 2 then
		code_retour := code_retour||'Vous êtes un(e) nain(e), les gestes vous viennent naturellement, vos chances de réussite sont augmentées de 20%.<br>';
		comp_creuser_modifie := comp_creuser_modifie + 20;
	end if;

	-- Bonus de creusage
	comp_creuser_modifie := comp_creuser_modifie + valeur_bonus(v_mineur, 'CRE');
	v_force := v_force + round(valeur_bonus(v_mineur, 'CRE')/4);
	-- limite pour un coup spécial
	limite_comp_maitre := round(comp_creuser_modifie*0.25);
	/***********************************************/
	/* Etape 6 : on creuse */
	/***********************************************/
	--  enleve les pa
	update perso
	set perso_pa = pa - v_cout_pa
	where perso_cod = v_mineur;

        -- *******************************************************************************
        -- ajout de l'usure de la pioche
        -- *******************************************************************************
        SELECT into v_obj_cod perobj_obj_cod from perso_objets, objets
        where perobj_obj_cod = obj_cod and perobj_equipe = 'O' and perobj_perso_cod = v_mineur and obj_gobj_cod in ( 332, 858, 1091, 1101, 1105, 1106, 1107);

        SELECT into v_usure obj_usure FROM objets WHERE obj_cod = v_obj_cod;

        UPDATE objets SET obj_etat = obj_etat - v_usure WHERE obj_cod = v_obj_cod;

        -- *******************************************************************************

	select into nom_competence comp_libelle from competences
	where comp_cod = num_comp;
	code_retour := code_retour||'Vous avez utilisé la compétence <b>'||nom_competence;
	code_retour := code_retour||'</b> (chance de réussite en tenant compte des modificateurs :<b>'||trim(to_char(comp_creuser_modifie,'999'))||'</b> %)<br>';

	-- lancer de dés
	des := lancer_des3(1,100, cast (valeur_bonus(v_mineur, 'BEN') + valeur_bonus(v_mineur, 'MAU') as integer));
	res_succes := 0;
	res_echec_critique := 0;
	code_retour := code_retour||'Votre lancer de dés est de <b>'||trim(to_char(des,'999'))||'</b>, '; -- pos 5 lancer des
	if des > 96 then -- echec critique
		res_echec_critique := 1;
		code_retour := code_retour||'il s’agit donc d’un échec automatique.<br><br>';
	elsif ((des > 5) and (des > limite_comp_maitre) and (des > comp_creuser_modifie)) then
		code_retour := code_retour||'il s’agit donc d’un échec.<br><br>';
		if comp_creuser <= getparm_n(1) then
			res_amelioration := 1;
		end if;
	elsif ((des > 5) and (des > limite_comp_maitre) and (des <= comp_creuser_modifie)) then
		code_retour := code_retour||'il s’agit donc d’une réussite.<br><br>';
		res_amelioration := 1;
		res_succes := 1;
	elsif ((des > 5) and (des <= limite_comp_maitre)) then
		code_retour := code_retour||'il s’agit donc d’une réussite spéciale.<br><br>';
		res_amelioration := 1;
		res_succes := 2;
	elsif (des <= 5) then
		code_retour := code_retour||'il s’agit donc d’une réussite critique.<br><br>';
		res_amelioration := 1;
		res_succes := 3;
	end if;
	-- AMELIORATION
	if res_amelioration > 0 then
		temp_ameliore_competence := ameliore_competence_px(v_mineur,num_comp,comp_creuser);
		code_retour := code_retour||'Votre jet d’amélioration est de '||split_part(temp_ameliore_competence,';',1)||', ';
		if split_part(temp_ameliore_competence,';',2) = '1' then
			code_retour := code_retour||'vous avez donc <b>amélioré</b> cette compétence.<br> ';
			code_retour := code_retour||'Sa nouvelle valeur est '||split_part(temp_ameliore_competence,';',3)||'<br><br>';
			px_gagne := px_gagne + 1;
		else
			code_retour := code_retour||'vous n’avez pas amélioré cette compétence.<br><br> ';
		end if;
	end if;
	if res_succes > 0 then
		-- USURE DU MUR
		des := lancer_des(1,8 + v_force);
		v_mur_usure := v_mur_usure - des;
		if v_mur_usure > 0 then
			update murs set mur_usure = v_mur_usure where mur_pos_cod = v_pos_mur;
			if v_mur_usure > 999 then
				v_mur_texte := 'intact';
			elseif v_mur_usure > 799 then
				v_mur_texte := 'presque intact';
			elseif v_mur_usure > 599 then
				v_mur_texte := 'légèrement usé';
			elseif v_mur_usure > 349 then
				v_mur_texte := 'usé';
			elseif v_mur_usure > 99 then
				v_mur_texte := 'très usé';
			else
				v_mur_texte := 'presque épuisé';
			end if;
			code_retour := code_retour||'Le filon s’use un peu plus il est maintenant <b>'||v_mur_texte||'</b>.<br><br> ';
		else
			delete from murs where mur_pos_cod = v_pos_mur;
			tmp_txt := init_automap_pos (v_pos_mur);
			code_retour := code_retour||'Le filon est épuisé, le mur s’écroule devant vos yeux !.<br><br> ';
			gain_renommee := gain_renommee * 5;
		end if;

		-- RESULTAT DU SUCCES
		des := lancer_des(1,100);
		-- Azaghal le 5/09/08, amélioration des gains en cas de spéciaux et critiques
		des := des + ( 10 * ( res_succes - 1 ) );
		if des < 15 then
			px_gagne := px_gagne + 0.3;
			code_retour := code_retour||'Pas de bol, vous n’avez rien trouvé !.<br><br> ';
		elseif   des < 25 then
			-- Objet inutile
			-- Choix de l'objet trouvé
			px_gagne := px_gagne + 0.5;
			des := lancer_des(1,100);
			if des < 20 then
				-- GRAVATS
				g_obj_cod = 333;
			elseif   des <40 then
				-- STATUE
				g_obj_cod = 164;
			elseif   des <60 then
				-- FOSSILE 1
				g_obj_cod = 370;
			elseif   des <80 then
				-- FOSSILE 2
				g_obj_cod = 371;
			else
				-- FOSSILE 3
				g_obj_cod = 372;
			end if;
			tmp_txt := cree_objet_perso_nombre (g_obj_cod, v_mineur, 1);
			select into
				obj_nom
				gobj_nom
			from objet_generique
			where 	gobj_cod = g_obj_cod;
			code_retour := code_retour||'Vous réussissez à extraire du filon:  <b>'||obj_nom||'</b>.<br><br> ';
		elseif des < 55 then
			-- quelques Br
			px_gagne := px_gagne + 0.5;

			-- Azaghal le 5/09/08, amélioration des gains en cas de spéciaux et critiques
			des := des * 5 + ( 50 * ( res_succes - 1 ) );
			update perso
			set perso_po = perso_po + des
			where perso_cod = v_mineur;
			code_retour := code_retour||'Vous réussissez à extraire du filon:  <b>'||trim(to_char(des,'999999999'))||' Br</b>.<br><br> ';
			obj_nom := trim(to_char(des,'999999999'))||' Brouzoufs';
		elseif des < 75 then
			g_obj_cod := 26 + lancer_des(1, 20);
	                px_gagne := px_gagne + 1;
			gain_renommee := gain_renommee * 3;
			tmp_txt := cree_objet_perso_nombre (g_obj_cod, v_mineur, 1);
			select into
				obj_nom
				gobj_nom
			from objet_generique
			where 	gobj_cod = g_obj_cod;
			code_retour := code_retour||'Vous réussissez à extraire du filon:  <b>'||obj_nom||'</b>.<br><br> ';
		else
                        nb_objets := lancer_des(1, 2) +  ( res_succes - 1 );
                        WHILE nb_objets > 0 LOOP
			     -- AJOUT DE L'OBJET
			     -- Choix de l'objet trouvé
			     px_gagne := px_gagne + 0.1;
			     des := lancer_des(1,v_mur_richesse);
			     -- Azaghal le 5/09/08, amélioration des gains en cas de spéciaux et critiques
			     des := des + ( 50 * ( res_succes - 1 ) );
			     if des < 81 then
				-- CHARBON
				g_obj_cod = 336;
			     elseif   des < 201 then
				-- FER
				g_obj_cod = 335;
			     elseif   des < 231 then
				-- GEMME E
				g_obj_cod = 356;
                             elseif   des < 261 then
				-- Citrinoline
				g_obj_cod = 1056;
			     elseif   des <291 then
				-- GEMME D
				g_obj_cod = 355;
                             elseif   des < 321 then
				-- Orpimentien
				g_obj_cod = 1061;
			     elseif   des <351 then
				-- MITHRIL
				g_obj_cod = 342;
			     elseif   des <381 then
				-- Schorlactide
				g_obj_cod = 1066;
                             elseif   des <411 then
				-- JADE
				g_obj_cod = 360;
				px_gagne := px_gagne + 0.5;
				gain_renommee := gain_renommee * 2;
			     elseif   des <441 then
				-- Pyrrholitoline
				g_obj_cod = 1059;
			     elseif   des <471 then
				-- TOPAZE
				g_obj_cod = 359;
				px_gagne := px_gagne + 0.5;
				gain_renommee := gain_renommee * 2;
			     elseif   des <501 then
				-- Boraximère
				g_obj_cod = 1064;
			     elseif   des <531 then
				-- GEMME A
				g_obj_cod = 352;
			     elseif   des <561 then
				-- GEMME B
				g_obj_cod = 353;
			     elseif   des <591 then
				-- OBSIDIENNE
				g_obj_cod = 357;
			     elseif   des <621 then
				-- GEMME C
				g_obj_cod = 354;
			     elseif   des <651 then
				--  Chalcopyritiminou
				g_obj_cod = 1060;
			     elseif   des <681 then
				-- AMETHYSTE
				g_obj_cod = 358;
				px_gagne := px_gagne + 0.5;
				gain_renommee := gain_renommee * 2;
			     elseif   des <711 then
				--  Torbénitiste
				g_obj_cod = 1058;
			     elseif   des <741 then
				-- AMBRE
				g_obj_cod = 361;
				px_gagne := px_gagne + 0.5;
				gain_renommee := gain_renommee * 2;
			     elseif   des <771 then
				--  Autunizolinette
				g_obj_cod = 1057;
			     elseif   des <801 then
				-- PEPITE D'OR
				g_obj_cod = 341;
				px_gagne := px_gagne + 0.5;
				gain_renommee := gain_renommee * 2;
			     elseif   des <831 then
				--  Crocoït sublime
				g_obj_cod = 1062;
			     elseif   des <861 then
				-- SAPHIR
				g_obj_cod = 340;
				px_gagne := px_gagne + 0.5;
				gain_renommee := gain_renommee * 2;
			     elseif   des <891 then
				--  Tibnitrion
				g_obj_cod = 1065;
			     elseif   des <921 then
				-- RUBIS
				g_obj_cod = 339;
				px_gagne := px_gagne + 0.5;
				gain_renommee := gain_renommee * 2;
			     elseif   des <951 then
				-- EMERAUDE
				g_obj_cod = 338;
				px_gagne := px_gagne + 1;
				gain_renommee := gain_renommee * 2;
			     else
				-- DIAMANT
				g_obj_cod = 337;
				px_gagne := px_gagne + 1;
				gain_renommee := gain_renommee * 2;
  			     end if;
                             nb_objets := nb_objets - 1;
                             tmp_txt := cree_objet_perso_nombre (g_obj_cod, v_mineur, 1);
			     select into
				obj_nom
				gobj_nom
			     from objet_generique
			     where gobj_cod= g_obj_cod;
			     code_retour := code_retour||'Vous réussissez à extraire du filon:  <b>'||obj_nom||'</b>.<br><br> ';
                        END LOOP;
		end if;

		-- augmentation des gains pour les réussites critiques et les spéciaux
		-- gain de 0.5 et 1 px supplémentaire
		-- Azaghal le 05/09/2008
		if res_succes = 2 then
			px_gagne := px_gagne + 0.25;
			gain_renommee := gain_renommee * 1.5;
		elseif   res_succes = 3 then
			px_gagne := px_gagne + 0.5;
			gain_renommee := gain_renommee * 2;
		end if;
	else
		-- ECHEC DE L'ACTION
		if res_echec_critique > 0 then
			-- ECHEC CRITIQUE: EVT SPECIAL
			des := lancer_des(1,100);
			gain_renommee := gain_renommee * (-5);
			if des < 33 then
				-- COUP DE GRISOU
				for ligne in select perso_cod,perso_nom,perso_pv,perso_pv_max
					from perso,perso_position,positions
					where perso_actif = 'O'
						and perso_tangible = 'O'
						and ppos_perso_cod = perso_cod
						and ppos_pos_cod = pos_cod
						and pos_cod = pos_mineur
				loop
					v_degats := lancer_des(1,10);
					texte_evt := '[perso_cod1] a été victime d’un coup de grisou.';
					values(66,now(),ligne.perso_cod,texte_evt,'O','O');
					update perso set perso_pv = max(1,perso_pv - v_degats) where perso_cod = ligne.perso_cod;
					perform ajoute_bonus(ligne.perso_cod, 'POI', 1, 3);
				end loop;
				code_retour := code_retour||'Votre erreur provoque un <b>Coup de grisou</b> !.<br><br> ';
			/*elseif   des < 66 then
				-- EFFONDREMENT
				for ligne in select perso_cod,perso_nom,perso_pv,perso_pv_max
					from perso,perso_position,positions
					where perso_actif = 'O'
						and perso_tangible = 'O'
						and ppos_perso_cod = perso_cod
						and ppos_pos_cod = pos_cod
						and pos_cod = pos_mineur
				loop
					v_degats := lancer_des(1,15);
					texte_evt := '[perso_cod1] a été victime d’un effondrement.';
					values(66,now(),ligne.perso_cod,texte_evt,'O','O');
					update perso set perso_pv = max(1,perso_pv - v_degats) where perso_cod = ligne.perso_cod;
					perform ajoute_bonus(ligne.perso_cod, 'POI', 1, 3);
				end loop;
				code_retour := code_retour||'Votre erreur provoque un <b>Effondrement</b>, vous êtes esseveli sous les gravats !.<br><br> ';
				*/
			else
				-- ajout du 05/01/2010 par Merrick : test sur l'étage pour éviter les elems au 0
				select into v_etage pos_etage
				from positions
				where pos_cod = v_pos_mur;
				if (v_etage in (0, 32)) then
					tmp_txt := cree_monstre_pos (1, pos_mineur);
					tmp_txt := cree_monstre_pos (1, pos_mineur);
					tmp_txt := cree_monstre_pos (2, pos_mineur);
					tmp_txt := cree_monstre_pos (2, pos_mineur);
					code_retour := code_retour||'Votre erreur dérange une nichée de rats !.<br><br> ';
				else
					-- REVEIL DES ESPRITS
					tmp_txt := cree_monstre_pos (187, pos_mineur);
					code_retour := code_retour||'Votre erreur provoque le <b>réveil d’un esprit de la Terre</b> !.<br><br> ';
				end if;
			end if;

		else
			-- ECHEC SIMPLE 50% CHANCES DE BLESSURE LEGERE
			des := lancer_des(1,100);
			if des > 50 then
				des := lancer_des(1,5);
				gain_renommee := gain_renommee * (-1);
				update perso set perso_pv = max(1,perso_pv - des) where perso_cod = v_mineur;
				texte_evt := '[perso_cod1] a été victime d’une chute de pierre.';
				values(66,now(),v_mineur,texte_evt,'O','O');
				code_retour := code_retour||'Une chute de pierre vous occasionne <b>'||trim(to_char(des,'999999'))||'</b> dégâts.<br><br> ';
			end if;
		end if;
	end if;
	-- EVENEMENTS
	if res_succes > 0 then
		texte_evt := '[perso_cod1] a trouvé '||obj_nom||' en creusant.';
	else
		texte_evt := '[perso_cod1] n’a pas réussi à creuser.';
	end if;
	values (nextval('seq_levt_cod'),65,now(),1,v_mineur,texte_evt,'O','O');
	-- XP
	update perso
	set perso_px = perso_px + px_gagne,
		perso_renommee_artisanat = perso_renommee_artisanat + gain_renommee
	where perso_cod = v_mineur;
	code_retour := code_retour||'Vous gagnez <b>'||to_char(px_gagne,'999999990D99')||'</b> PX pour cette action.';
	return code_retour;
end;$_$;


ALTER FUNCTION public.creuser(integer, integer) OWNER TO delain;

