--
-- Name: cron_formule_parchemin(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cron_formule_parchemin() RETURNS void
    LANGUAGE plpgsql
    AS $$/*****************************************************************/
/* function cron_formule_parchemin : Crée les objets parchemins	 */
/*                                                               */
/*****************************************************************/
/* Créé le 18/04/2010                                            */
/*****************************************************************/
declare
		ligne record;
		objet_fini integer;
		temps text;
		texte_evt text;

begin
	for ligne in select foi_obj_cod,foi_gobj_cod,foi_formule_cod,foi_date_crea,frmpr_gobj_cod,frmpr_num,perobj_perso_cod,frm_temps_travail
											from formule_objet_inacheve,formule,formule_produit,perso_objets
											where foi_formule_cod = frm_cod
											and frmpr_frm_cod = frm_cod
											and frm_type = 4
											and perobj_obj_cod = foi_obj_cod loop
		temps := cast (ligne.frm_temps_travail as text);
		select into objet_fini foi_obj_cod from formule_objet_inacheve
						where foi_obj_cod = ligne.foi_obj_cod and (foi_date_crea + (temps || ' minutes')::interval) < now();
		if found then
			--On cree l'objet dans l'inventaire du perso possédant la peau
			perform cree_objet_perso_nombre(ligne.frmpr_gobj_cod,ligne.perobj_perso_cod,ligne.frmpr_num);
			--On efface l'objet en cours de réalisation
			delete from formule_objet_inacheve where foi_obj_cod = ligne.foi_obj_cod;
			perform f_del_objet (ligne.foi_obj_cod);
			--on rentre un évènement
	texte_evt := 'Une peau vient de finir de sécher, pour [perso_cod1].';
	      	values(nextval('seq_levt_cod'),83,now(),1,ligne.perobj_perso_cod,texte_evt,'N','N',ligne.perobj_perso_cod,ligne.perobj_perso_cod);
		end if;
	end loop;

end;$$;


ALTER FUNCTION public.cron_formule_parchemin() OWNER TO delain;

--
-- Name: cron_lance_mission(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cron_lance_mission() RETURNS void
    LANGUAGE plpgsql
    AS $$/*****************************************************************/
/* function cron_valide_mission 																 */
/*                                                               */
/*****************************************************************/
/* Créé le 07/06/2010                                            */
/*****************************************************************/
declare
		ligne record;
		ligne_fonction record;
		ligne_perso record;
		result text;

begin
	for ligne in select mission_cod,mission_fonction,mission_delai,(mission_date_deb + (mission_temps_relance::text||' days')::interval) as date_controle,now() as maintenant
													from quetes.mission
													where mission_statut = 'N' loop

		if ligne.date_controle < ligne.maintenant then --La mission doit être ouverte, on lance les fonctions
			for ligne_fonction in (select foo from regexp_split_to_table(ligne.mission_fonction,';') as foo)
					loop
						if ligne_fonction.foo is not null and ligne_fonction.foo != '' then
								execute 'select '||ligne_fonction.foo into result;
	          end if;
		    end loop;
		  --On ouvre les objectifs (normalement, cela devrait aussi être fait avec la cloture de la mission)
				update quetes.mission_objectif set mobject_statut = 'N' where mobject_mission_cod = ligne.mission_cod;
				for ligne_perso in select mobject_object_suivant from quetes.mission_objectif where mobject_mission_cod = ligne.mission_cod and mobject_object_suivant is not null loop
					update quetes.mission_objectif set mobject_statut = 'D' where mobject_object_cod in (translate(ligne_perso.mobject_object_suivant , ';', ','));
				end loop;
			-- On ouvre la mission !
			update quetes.mission set mission_statut = 'O',mission_date_deb = now(),mission_date_fin = now() where mission_cod = ligne.mission_cod;
		end if;
	end loop;
end;$$;


ALTER FUNCTION public.cron_lance_mission() OWNER TO delain;

