    LANGUAGE plpgsql
    AS $$/*****************************************************************/
/* function cron_repousse_composants : gère la repousse des      */
/*                                         composants de potion  */
/*                                                               */
/*****************************************************************/
/* Créé le 14/01/2007                                            */
/*****************************************************************/
declare
		ligne record;

begin
	for ligne in select ingrpos_cod,ingrpos_chance_crea from ingredient_position where ingrpos_qte < ingrpos_max loop
