--
-- Name: cron_sequence_etape_ia(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cron_sequence_etape_ia() RETURNS void
    LANGUAGE plpgsql
    AS $$/*****************************************************************/
/* function cron_sequence_etape_ia															 */
/*         								                                       */
/*****************************************************************/
/* Créé le 01/05/2010                                            */
/*****************************************************************/
declare
		ligne record;
		v_temp integer;
		v_param_etape integer;
		v_etape_suivante integer;
		v_pos_cod integer;


begin
	for ligne in select pia_perso_cod,pia_ia_type,pia_parametre,pia_iaetape_cod,pia_date_change,pia_iaetape_etape_cod
											from perso_ia where pia_iaetape_cod = 1 loop
		select into v_param_etape iaetape_param from ia_etape where iaetape_etape_cod = ligne.pia_iaetape_etape_cod and iaetape_cod = ligne.pia_iaetape_cod;
		--On doit vérifier que la position du perso est celle de la première étape, sinon on ne fait rien.
		select into v_pos_cod ppos_pos_cod from perso_position where ppos_perso_cod = ligne.pia_perso_cod;
		if v_param_etape = v_pos_cod then -- Le perso est arrivé là où il devait aller
			--On regarde si il y a une autre étape pour la suite
			select into v_temp,v_etape_suivante iaetape_param,iaetape_etape_cod from ia_etape
				where iaetape_etape_cod = ligne.pia_iaetape_etape_cod + 1 and iaetape_cod = ligne.pia_iaetape_cod;
			if found then
				update perso_ia set pia_parametre = v_temp,pia_date_change = now(),pia_iaetape_etape_cod = v_etape_suivante where pia_perso_cod = ligne.pia_perso_cod;
			end if;
		end if;
	end loop;
end;$$;


ALTER FUNCTION public.cron_sequence_etape_ia() OWNER TO delain;

--
-- Name: cron_valide_mission_text(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cron_valide_mission_text() RETURNS text
    LANGUAGE plpgsql
    AS $$/*****************************************************************/
/* function cron_valide_mission 																 */
/*                                                               */
/*****************************************************************/
/* Créé le 01/05/2010                                            */
/*****************************************************************/
declare
		ligne record;
		ligne2 record;
		ligne_recompense record;
		groupe_winner integer;
		object_valide integer;
		object_total integer;
		object_realise integer;
		nombre_perso integer;
		code_retour text;
		limitation integer;
		boucle integer;
		expression text;
		curs2 refcursor;
		ligne_perso record;
		-- Messages
	  v_mes integer;							-- Numéro du message de coterie
	  v_corps text;								-- Contenu du message
	  v_titre text;								-- Titre du message
		v_pos_x integer;
		v_pos_y integer;
		v_pos_etage integer;
		v_etage_libelle text;
		v_etage_cod integer;
		automap_etage text;
		automap text;
		result_automap record;
		req text;
		v_temp integer;
		mission_ratee integer;
		ligne_fonction record;
		result text;

begin
	code_retour := '';
	for ligne in select mission_cod,mission_fonction_cloture,mission_delai,(mission_date_deb + (mission_delai::text||' days')::interval) as date_controle,now() as maintenant
													from quetes.mission
													where mission_statut = 'O' loop
		mission_ratee := 0;
		-- On va checker que la mission est réussie en terme de temps. Si temps dépassé, on cloture avec message pour le groupe
		if ligne.mission_delai is not null and ligne.mission_delai != 0 then
			--On controle
			if ligne.date_controle < ligne.maintenant then

				v_mes := nextval('seq_msg_cod');
				v_corps := 'Malheureusement, le temps imparti pour cette mission est écoulé. Votre groupe a donc échoué dans sa tentative.<br>Ce n''est sans doute que partie remise !';
				v_titre := 'Cloture de mission, temps dépassé';
				mission_ratee := 1;
			end if;
		end if;
		-- On va checker que la mission est ratée sur un objectif
		select into object_valide count(mobject_statut) from quetes.mission_objectif
							where mobject_mission_cod = ligne.mission_cod
							and mobject_statut = 'R'
							group by mobject_statut  limit 1;
		if found then
				v_mes := nextval('seq_msg_cod');
				v_corps := 'Vous avez échoué sur au moins un des objectifs de la mission à laquelle vous participiez.';
				v_titre := 'Cloture de mission, mission ratée';
				mission_ratee := 1;
				code_retour := 'mission_ratee';
		end if;

		--Conséquences communes des missions ratées
		if mission_ratee = 1 then
														values (v_mes,now(),now(),v_titre,v_corps);
																values (v_mes,209808,'N');

			for ligne_perso in select mgroupe_perso_cod from quetes.mission_groupe,quetes.mission_groupe_def
												where mgroupe_groupe_cod = mgroupedef_cod
												and mgroupedef_mission_cod = ligne.mission_cod
												and mgroupedef_statut = 'O' loop
																values (v_mes,ligne_perso.mgroupe_perso_cod,'N','N');
			end loop;
				--On réinitialise les objectifs
			update quetes.mission_objectif set mobject_statut = 'N' where mobject_mission_cod = ligne.mission_cod;
			for ligne_perso in select mobject_object_suivant from quetes.mission_objectif where mobject_mission_cod = ligne.mission_cod and mobject_object_suivant is not null loop
				update quetes.mission_objectif set mobject_statut = 'D' where mobject_object_cod in (translate(ligne_perso.mobject_object_suivant , ';', ','));
			end loop;
				for ligne_fonction in (select foo from regexp_split_to_table(ligne.mission_fonction_cloture,';') as foo)
					loop
						if ligne_fonction.foo is not null and ligne_fonction.foo != '' then
								execute 'select '||ligne_fonction.foo into result;
	          end if;
		    end loop;
				-- on ferme la mission
			update quetes.mission set mission_statut = 'N' where mission_cod = ligne.mission_cod;
			-- on clot le groupe qui a participé à cela mais aussi tous les groupes encours pour la mission
			update quetes.mission_groupe_def set mgroupedef_statut = 'N' where mgroupedef_mission_cod = ligne.mission_cod;
		end if;

		if mission_ratee = 0 then --On est dans le cas d'une mission qui a pu réussir
			select into object_total count(mobject_statut)from quetes.mission_objectif where mobject_mission_cod = ligne.mission_cod;
			select into object_realise count(mobject_statut)from quetes.mission_objectif where mobject_mission_cod = ligne.mission_cod and mobject_statut = 'O';
			--On valide que la mission est réussie
			if object_total != object_realise then
				code_retour :='mission non encore achevée';
				exit;
			end if;
			--on compte les objectifs assignables à un seul groupe, et on compare au total des objectifs assignables
			select into object_total count(mobject_statut)from quetes.mission_objectif where mobject_mission_cod = ligne.mission_cod and mobject_type_object = 1;
			select into object_valide,groupe_winner count(mobject_statut),mgroupe_groupe_cod from quetes.mission_objectif,quetes.mission_groupe
								where mobject_mission_cod = ligne.mission_cod
								and mobject_statut = 'O'
								and mgroupe_perso_cod = mobject_perso_cod
								group by mgroupe_groupe_cod,mobject_statut  limit 1;
			if found and object_valide = object_total then
				--on lance la fin de la mission
				code_retour := code_retour||'object_valide : '||trim(to_char(object_valide,'9999999999999'))||'groupe_winner : '||trim(to_char(groupe_winner,'9999999999999'));
				code_retour := code_retour||'<br>object_total : '||trim(to_char(object_total,'9999999999999'));
				for ligne_fonction in (select foo from regexp_split_to_table(ligne.mission_fonction_cloture,';') as foo)
					loop
						if ligne_fonction.foo is not null and ligne_fonction.foo != '' then
								execute 'select '||ligne_fonction.foo into result;
	          end if;
		    end loop;
			-- on distribue les récompenses. Pour les récompenses en nombre, on va compter les persos du groupe pour distribuer
				select into nombre_perso count(mgroupe_perso_cod) from quetes.mission_groupe where mgroupe_groupe_cod = groupe_winner;
				code_retour := code_retour||'<br>nombre_perso : '||trim(to_char(nombre_perso,'9999999999999'));
				--Récompense pour tout le monde : récompense qui se compte en integer (pxs 1, brouzoufs 2, brouzoufs banque 11.. : On va répartir, donc compter les intervenants et diviser) / récompense Type titre pour tout le monde 6
				for ligne_recompense in select mrec_rec_valeur,mrec_type_rec,mrec_rec_texte from quetes.mission_recompense where mrec_type_rec in (1,2,3,6,7,11,12) and mrec_mission_cod = ligne.mission_cod loop
					v_temp := floor(ligne_recompense.mrec_rec_valeur / nombre_perso);
					for ligne2 in select mgroupe_perso_cod from quetes.mission_groupe where mgroupe_groupe_cod = groupe_winner loop
						if ligne_recompense.mrec_type_rec = 1 then
							update perso set perso_px = perso_px + v_temp	where perso_cod = ligne2.mgroupe_perso_cod;
						elsif ligne_recompense.mrec_type_rec = 2 then
							update perso set perso_po = perso_po + v_temp	where perso_cod = ligne2.mgroupe_perso_cod;
						elsif ligne_recompense.mrec_type_rec = 3 then
						elsif ligne_recompense.mrec_type_rec = 6 then
							update perso set perso_pp = perso_pp + v_temp where perso_cod = ligne2.mgroupe_perso_cod;
						elsif ligne_recompense.mrec_type_rec = 7 then -- BONUS
							perform ajoute_bonus(ligne2.mgroupe_perso_cod,ligne_recompense.mrec_rec_texte,20,ligne_recompense.mrec_rec_valeur);
						elsif ligne_recompense.mrec_type_rec = 11 then
							update perso_banque set pbank_or = pbank_or + v_temp where pbank_perso_cod = ligne2.mgroupe_perso_cod;
						elsif ligne_recompense.mrec_type_rec = 12 then -- Information exploration (automap), la valeur donnant l'étage. Attention, il s'agit du etage_numero. Evolution : texte contenant la taille de l'automap
							--On selection l'étage cod associé à l'étage_numero
							select into v_etage_cod etage_cod from etage where etage_numero = ligne_recompense.mrec_rec_valeur;
							automap := 'perso_vue_pos_'||cast(v_etage_cod as text);
							automap_etage := 'select pos_x,pos_y,etage_numero from positions,etage
								where etage_numero = pos_etage
								and etage_numero = '||ligne_recompense.mrec_rec_valeur||'
								and pos_cod not in (select pvue_pos_cod from '||automap||' where pvue_perso_cod = '||cast(ligne2.mgroupe_perso_cod as text)||')';
							code_retour := code_retour||'<br>select : '||automap_etage;
							 open curs2 for execute automap_etage;
								fetch curs2 into result_automap;
								select into v_temp vet_etage from etage_visite where vet_perso_cod 	= ligne2.mgroupe_perso_cod and vet_etage = result_automap.etage_numero;
								if not found then
								end if;
								req := 'delete from '||automap||' where pvue_perso_cod = '||cast(ligne2.mgroupe_perso_cod as text)||' and pvue_pos_cod in (select pos_cod
										from positions
										where pos_etage = '||cast(ligne_recompense.mrec_rec_valeur as text)||'
										and pos_x between '||cast(result_automap.pos_x as text)||' - 10 and '||cast(result_automap.pos_x as text)||' + 10
										and pos_y between '||cast(result_automap.pos_y as text)||' - 10 and '||cast(result_automap.pos_y as text)||' + 10)';
								code_retour := code_retour||'<br>delete : '||automap_etage;
								execute req;
								req := 'insert into '||automap||' (pvue_perso_cod,pvue_pos_cod) select '||cast(ligne2.mgroupe_perso_cod as text)||',pos_cod
										from positions
										where pos_etage = '||cast(result_automap.etage_numero as text)||'
										and pos_x between '||cast(result_automap.pos_x as text)||' - 10 and '||cast(result_automap.pos_x as text)||' + 10
										and pos_y between '||cast(result_automap.pos_y as text)||' - 10 and '||cast(result_automap.pos_y as text)||' + 10';
								execute req;
								code_retour := code_retour||'<br>insert : '||automap_etage;
							close curs2;
						else
							code_retour := 'anomalie : pas de type de récompense';
						end if;
					end loop;
				end loop;

					--recompense de type objet en fonction du nombre d'objets
				for ligne_recompense in select mrec_rec_valeur,mrec_type_rec,mrec_rec_texte from quetes.mission_recompense where mrec_type_rec in (4,5,8,9,10,13,14)  and mrec_mission_cod = ligne.mission_cod loop
					limitation := ligne_recompense.mrec_rec_valeur % nombre_perso;
					boucle := floor(ligne_recompense.mrec_rec_valeur / nombre_perso);
					code_retour := code_retour||'<br>limitation : '||trim(to_char(limitation,'9999999999999'))||'<br>boucle : '||trim(to_char(boucle,'9999999999999'));
					if ligne_recompense.mrec_rec_valeur is not null or ligne_recompense.mrec_rec_valeur != 0 then
						if boucle > 0 then
							for i in 1..boucle loop
								if i = 1 then
									expression := 'select mgroupe_perso_cod from quetes.mission_groupe where mgroupe_groupe_cod = '||trim(to_char(groupe_winner,'99999999999'));
								else
									expression := expression||' union all select mgroupe_perso_cod from quetes.mission_groupe where mgroupe_groupe_cod = '||trim(to_char(groupe_winner,'99999999999')) ;
								end if;
							end loop;
							expression := expression||' union all (select mgroupe_perso_cod from quetes.mission_groupe where mgroupe_groupe_cod = '||trim(to_char(groupe_winner,'99999999999'))||' order by random() limit '||trim(to_char(limitation,'99999999999'))||')';
						else
							expression := 'select mgroupe_perso_cod from quetes.mission_groupe where mgroupe_groupe_cod = '||trim(to_char(groupe_winner,'99999999999'))||' order by random() limit '||trim(to_char(limitation,'99999999999'));
						end if;
						--On intègre les différents bonus
						for ligne_perso in execute expression loop
							if ligne_recompense.mrec_type_rec = 4 then --objet
								perform cree_objet_perso(cast(ligne_recompense.mrec_rec_texte as integer),ligne_perso.mgroupe_perso_cod);
							elsif ligne_recompense.mrec_type_rec = 5 then --compétence
								select pcomp_modificateur from perso_competences where pcomp_pcomp_cod = ligne_recompense.mrec_rec_texte and pcomp_perso_cod = ligne_perso.mgroupe_perso_cod;
								if found then
									update perso_competences set pcomp_modificateur = pcomp_modificateur + ligne_recompense.mrec_rec_valeur where pcomp_perso_cod = ligne_perso.mgroupe_perso_cod;
								else
								end if;
							elsif ligne_recompense.mrec_type_rec = 8 then --Information cachette
								select into v_pos_x,v_pos_y,v_pos_etage,v_etage_libelle pos_x,pos_y,etage_numero,etage_libelle from positions,etage
												where pos_etage = etage_numero
												and pos_cod in (select cache_pos_cod from cachettes);
								v_corps := 'Suite à l''accomplissement d''une mission vous avez reçu en récompense l''information suivante :
								<br>Vous pourrez trouver une cachette aux coordonnées suivantes :<b> X '||trim(to_char(v_pos_x,'999'))||'/ Y '||trim(to_char(v_pos_y,'999'))||'</b> dans l''étage appelé'||v_etage_libelle;
								v_mes := nextval('seq_msg_cod');
								v_titre := 'Récompense de mission';
															values (v_mes,now(),now(),v_titre,v_corps);
																	values (v_mes,ligne_perso.mgroupe_perso_cod,'N');
																	values (v_mes,ligne_perso.mgroupe_perso_cod,'N','N');
							elsif ligne_recompense.mrec_type_rec = 9 then --Enchantement

							elsif ligne_recompense.mrec_type_rec = 10 then --Information potion ou enchantement
								select into v_etage_libelle obj_text_texte from potions.objet_texte where obj_text_gobj_cod = 723 order by random() limit 1;
								v_corps := 'Suite à l''accomplissement d''une mission vous avez reçu en récompense l''information suivante :
														<br><i>'||v_etage_libelle||'</i><br><br>Cela peut sembler mystérieux mais cela a sans doute un intérêt pour certains...';
								v_mes := nextval('seq_msg_cod');
								v_titre := 'Récompense de mission';
															values (v_mes,now(),now(),v_titre,v_corps);
																	values (v_mes,209808,'N');
																	values (v_mes,ligne_perso.mgroupe_perso_cod,'N','N');

							elsif ligne_recompense.mrec_type_rec = 13 then -- Formule (complète) de potion

							elsif ligne_recompense.mrec_type_rec = 14 then -- Formule (complète) d'enchantement

							else
								code_retour := 'anomalie : pas de type de récompense';
							end if;
						end loop;

					end if;
				end loop;
					--On envoie un message au groupe avec les récompenses obtenues

				v_corps := '<b>Récapitulatif des Récompenses octroyées pour cette mission : </b><br>';
				for ligne_recompense in select trec_libelle,mrec_rec_valeur,mrec_type_rec,mrec_rec_texte from quetes.mission_recompense,quetes.type_recompense
									where mrec_type_rec in (1,2,6,7,11)
									and trec_type_rec_cod = mrec_type_rec
									 and mrec_mission_cod = ligne.mission_cod loop
					v_corps := v_corps||'<br>'||ligne_recompense.trec_libelle||' : '||ligne_recompense.mrec_rec_valeur;
				end loop;
				for ligne_recompense in select trec_libelle,mrec_rec_valeur,mrec_type_rec,mrec_rec_texte from quetes.mission_recompense,quetes.type_recompense
									where mrec_type_rec in (3)
									and trec_type_rec_cod = mrec_type_rec and mrec_mission_cod = ligne.mission_cod loop
					v_corps := v_corps||'<br>'||ligne_recompense.trec_libelle||' : '||ligne_recompense.mrec_rec_texte;
				end loop;
				for ligne_recompense in select trec_libelle,mrec_rec_valeur,mrec_type_rec,mrec_rec_texte from quetes.mission_recompense,quetes.type_recompense
									where mrec_type_rec in (4,5,7,8,9,10,12,13,14)
									and trec_type_rec_cod = mrec_type_rec
									 and mrec_mission_cod = ligne.mission_cod loop
					v_corps := v_corps||'<br>'||ligne_recompense.trec_libelle||' : '||ligne_recompense.mrec_rec_texte;
				end loop;

				v_mes := nextval('seq_msg_cod');
				v_titre := 'Récapitulatif des récompenses de mission';
															values (v_mes,now(),now(),v_titre,v_corps);
																	values (v_mes,209808,'N');

				for ligne_perso in select mgroupe_perso_cod from quetes.mission_groupe where mgroupe_groupe_cod = groupe_winner loop
																	values (v_mes,ligne_perso.mgroupe_perso_cod,'N','N');
				end loop;

				-- on archive pour le hall of fame
											select ligne.mission_cod,groupe_winner,mgroupe_perso_cod,perso_nom from quetes.mission_groupe,perso
														 where mgroupe_groupe_cod = groupe_winner
														 and mgroupe_perso_cod = perso_cod;

					--On réinitialise les objectifs
				update quetes.mission_objectif set mobject_statut = 'N' where mobject_mission_cod = ligne.mission_cod;
				for ligne_perso in select mobject_object_suivant from quetes.mission_objectif where mobject_mission_cod = ligne.mission_cod and mobject_object_suivant is not null loop
					update quetes.mission_objectif set mobject_statut = 'D' where mobject_object_cod in (translate(ligne_perso.mobject_object_suivant , ';', ','));
				end loop;
					-- on ferme la mission
				update quetes.mission set mission_statut = 'N' where mission_cod = ligne.mission_cod;
				-- on clot le groupe qui a participé à cela mais aussi tous les groupes encours pour la mission
				update quetes.mission_groupe_def set mgroupedef_statut = 'N' where mgroupedef_mission_cod = ligne.mission_cod;
			end if;
		end if; --Fin des conséquences du traitement des missions réussies

	end loop;
return code_retour;
end;$$;


ALTER FUNCTION public.cron_valide_mission_text() OWNER TO delain;

--
-- Name: cron_valide_objectif(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.cron_valide_objectif() RETURNS void
    LANGUAGE plpgsql
    AS $$/*****************************************************************/
/* function cron_valide_objectif 																 */
/*         								                                       */
/*****************************************************************/
/* Créé le 01/05/2010                                            */
/*****************************************************************/
declare
		ligne record;
		v_temp text;
		v_temp_text text;
		v_liste text;
		i integer;
		num_perso text;
		reussite integer;
		query text;
		result text;
		ligne_fonction record;
		lance_query text;
		param_text text;
		remplace text;
		ligne_groupe record;

begin
	for ligne in select mission_cod,mgroupedef_nom,mgroupe_groupe_cod,mobject_object_cod,mobject_date_deb,mobject_date_prise,mobject_action,mobject_perso_cod,mobject_desc,mobject_pos_cod,mobject_type_object,mobject_statut,mobject_temps,(mobject_date_prise + (mobject_temps::text||' hours')::interval) as date_confirm,now() as maintenant,mobject_param_text,mobject_object_suivant
													from quetes.mission,quetes.mission_objectif
													left outer join (select perso_nom,mgroupedef_nom,mgroupedef_mission_cod,mgroupe_perso_cod,mgroupe_groupe_cod from quetes.mission_groupe,perso,quetes.mission_groupe_def
													where perso_cod = mgroupe_perso_cod
													and mgroupedef_cod = mgroupe_groupe_cod and mgroupedef_statut = 'O') as t1
													on (t1.mgroupedef_mission_cod = mobject_mission_cod and mgroupe_perso_cod = mobject_perso_cod )
													where mobject_mission_cod = mission_cod
													and mission_statut = 'O'
													and mobject_statut = 'N' loop
		reussite := 0;
		if ligne.mobject_type_object = 3 or ligne.mobject_type_object = 4 then
			--On vérifie que tous les monstres de cet objectif sont morts
					v_liste := '';
					for i in 1..1000 loop
					num_perso := split_part(ligne.mobject_param_text , ';', i);
						select into v_temp perso_actif from perso where perso_cod = num_perso;
						if v_temp = 'O' and num_perso is not null and num_perso != '' then
							v_liste := v_liste||num_perso||';';
						end if;
					exit when num_perso is null or num_perso = '';
					end loop;
					if v_liste != '' then
						update quetes.mission_objectif set mobject_param_text = v_liste where mobject_object_cod = ligne.mobject_object_cod;
					else --Objectif réussi
						reussite := 1;
						update quetes.mission_objectif set mobject_param_text = v_liste,mobject_statut = 'O' where mobject_object_cod = ligne.mobject_object_cod;
					end if;
		end if;
		if ligne.mobject_type_object = 5 then
			--On vérifie que tous les monstres de cet objectif sont encore vivants
					for i in 1..1000 loop
					num_perso := split_part(ligne.mobject_param_text , ';', i);
						select into v_temp perso_actif from perso where perso_cod = num_perso;
						if v_temp = 'N' then
							update quetes.mission_objectif set mobject_statut = 'R' where mobject_object_cod = ligne.mobject_object_cod;
							exit;
						end if;
						exit when num_perso is null or num_perso = '';
					end loop;
					if ligne.maintenant > ligne.date_confirm then
							update quetes.mission_objectif set mobject_statut = 'O' where mobject_object_cod = ligne.mobject_object_cod;
							reussite := 1;
					end if;

					--num_perso := '';
					--num_perso := translate(ligne.mobject_param_text , ';', ',');
					--num_perso := trim(trailing ',' from num_perso);
					--	query := 'select into '||v_temp||' perso_actif from perso where perso_cod in ('||num_perso||') and perso_actif = ''N'' ';
					--	execute query into result;
					--	if not found then
					--		update quetes.mission_objectif set mobject_object_suivant = num_perso where mobject_object_cod = ligne.mobject_object_cod;
					--	elsif found  then --and ligne.maintenant < ligne.date_confirm
					--		--On cloture la mission, et elle est ratée
					--		update quetes.mission_objectif set mobject_statut = 'R' where mobject_object_cod = ligne.mobject_object_cod;
					--	elsif ligne.maintenant > ligne.date_confirm then
					--		update quetes.mission_objectif set mobject_statut = 'O' where mobject_object_cod = ligne.mobject_object_cod;
					--		reussite := 1;
					--	end if;
		end if;
		if ligne.mobject_type_object = 2 then
			--On vérifie que toutes les positions de cet objectif sont vides de monstre
					v_liste := '';
					for i in 1..1000 loop
					num_perso := split_part(ligne.mobject_param_text , ';', i);
						select into v_temp perso_cod from perso,perso_position where ppos_pos_cod = num_perso and ppos_perso_cod = perso_cod and perso_actif = 'O' and perso_type_perso = 2;
						if found then
							v_liste := v_liste||v_temp;
							exit;
						end if;
						exit when num_perso is null or num_perso = '';
					end loop;
					if v_liste = '' and ligne.maintenant > ligne.date_confirm then	--Objectif réussi
							update quetes.mission_objectif set mobject_statut = 'O' where mobject_object_cod = ligne.mobject_object_cod;
							reussite := 1;
					end if;
		end if;
		if ligne.maintenant > ligne.date_confirm  and ligne.mgroupedef_nom is not null then -- On traite le cas d'un objectif qui doit être pris par un groupe
			update quetes.mission_objectif set mobject_statut = 'O' where mobject_object_cod = ligne.mobject_object_cod;
			reussite := 1;
		end if;
		if reussite = 1 then --Objectif réussi, on déclenche les conséquences communes
			--On lance les fonctions ensuite
				for ligne_fonction in (select foo from regexp_split_to_table(ligne.mobject_action,';') as foo)
					loop
						if ligne_fonction.foo is not null and ligne_fonction.foo != '' then
	            	if  split_part(ligne_fonction.foo, ',', 2) = '[groupe]' then
	            		for ligne_groupe in select mgroupedef_cod from quetes.mission_groupe_def where mgroupedef_mission_cod = ligne.mission_cod and mgroupedef_statut = 'O' loop
		            		query := replace(ligne_fonction.foo,'[groupe]',to_char(ligne_groupe.mgroupedef_cod,'99999999999999'));
										execute 'select '||query into result;
									end loop;
								else
									query := 'select '||ligne_fonction.foo;
									execute query into result;
								end if;
	          end if;
		    end loop;
			--On ouvre les objectfs suivants, et on affecte les paramètres
			if trim(ligne.mobject_object_suivant) is not null then
				lance_query := '';
				query :='';
				for i in 1..1000 loop
					v_temp_text := split_part(ligne.mobject_object_suivant , ';', i);
					select into v_temp mobject_object_cod from (select regexp_split_to_table(mobject_object_suivant, ';') as foo,mobject_object_cod,mobject_statut from quetes.mission_objectif) as t1 where t1.foo = v_temp_text and t1.mobject_statut != 'O';
					if not found then --Tous les objectifs précédents ont été réalisés, on ouvre le suivant
					 update quetes.mission_objectif set mobject_statut = 'N',mobject_date_prise = now() where mobject_object_cod = v_temp_text;
					 select into lance_query mobject_ouverture from quetes.mission_objectif where mobject_object_cod = v_temp_text;
						param_text := '';
						for ligne_fonction in (select foo from regexp_split_to_table(lance_query,';') as foo)
							loop
								if ligne_fonction.foo is not null then
			            if ligne_fonction.foo != '' then
					          query := replace(ligne_fonction.foo,'[groupe]',to_char(ligne.mgroupe_groupe_cod,'99999999999999'));
					          if query is null then
					          	query := 'select '||ligne_fonction.foo;
					          else
											query := 'select '||query;
										end if;
										execute query into result;
										param_text := result||param_text;
			            end if;
								end if;
				    	end loop;
							update quetes.mission_objectif set mobject_param_text = param_text where mobject_object_cod = v_temp_text;
					end if; --Fin des lancements des fonctions d'ouverture d'objectifs
					exit when v_temp_text is null or v_temp_text = '';
				end loop;
			end if; --Fin de lancement des objectifs suivants
		end if; --fin des conséquences de réussite de cet objectif

	end loop;
end;$$;


ALTER FUNCTION public.cron_valide_objectif() OWNER TO delain;

