--
-- Name: deb_tour_bipbip(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.deb_tour_bipbip(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/******************************************************/
/* deb_tour_bipbip : Bonus de déplacement  gratuits   */
/******************************************************/
declare
	code_retour text;
	personnage alias for $1;
	v_pos integer;
	ligne record;
	has_bloque integer;
	v_bloque_magie integer;
	v_pa_attaque integer;
	v_malus_degats integer;
	v_chance_toucher integer;
	v_pa_dep integer;
	texte_evt text;

begin
	select into v_pos
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	if not found then
		return 'Anomalie sur position !';
	end if;
	if lancer_des(1,100) < 30 then
		perform ajoute_bonus(personnage, 'DEP', 2, 2);
		texte_evt := 'A la manière d''un dervish tourneur, [perso_cod1] se met à virevolter sur lui même pour atteindre une vitesse incroyable !';
     			values(54,now(),1,personnage,texte_evt,'O','O');
	end if;

	return 'OK';
end;$_$;


ALTER FUNCTION public.deb_tour_bipbip(integer) OWNER TO delain;

--
-- Name: deb_tour_bloque_magie(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.deb_tour_bloque_magie(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* deb_tour_bloque magie rendant un monstre     */
/* insensible a la magie                        */
/************************************************/
declare
	code_retour text;
	personnage alias for $1;
	v_pos integer;
	ligne record;
	has_bloque integer;
	v_bloque_magie integer;
	v_pa_attaque integer;
	v_malus_degats integer;
	v_chance_toucher integer;
	texte_evt text;
	v_pa_dep integer;
begin
	select into v_pos
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	if not found then
		return 'Anomalie sur position !';
	end if;
	if lancer_des(1,100) < 30 then
		perform ajoute_bonus(personnage, 'DFM', 2, -2);
		texte_evt := 'Au dessus de la tête de [perso_cod1], des flux magiques semblent se rassembler ! Ceci semble lui conférer une puissance que peu de magiciens peuvent comprendre ...';
     			values(54,now(),1,personnage,texte_evt,'O','O');
	end if;

	return 'OK';
end;$_$;


ALTER FUNCTION public.deb_tour_bloque_magie(integer) OWNER TO delain;

--
-- Name: deb_tour_carapace(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.deb_tour_carapace(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* deb_tour_carapace augmentant l armure        */
/************************************************/
declare
	code_retour text;
	personnage alias for $1;
	v_pos integer;
	ligne record;
	has_bloque integer;
	v_bloque_magie integer;
	v_pa_attaque integer;
	v_malus_degats integer;
	v_chance_toucher integer;
	texte_evt text;
	v_pa_dep integer;
begin
	select into v_pos
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	if not found then
		return 'Anomalie sur position !';
	end if;
	if lancer_des(1,100) < 30 then
		perform ajoute_bonus(personnage, 'ARM', 2, 3);
		texte_evt := 'Des veines de couleur sombre commence à strier la peau de [perso_cod1]. Son apparence de plus en plus foncée la fait ressembler à une sorte de carapace !';
     			values(54,now(),1,personnage,texte_evt,'O','O');
	end if;

	return 'OK';
end;$_$;


ALTER FUNCTION public.deb_tour_carapace(integer) OWNER TO delain;


--
-- Name: deb_tour_esprit_damne(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.deb_tour_esprit_damne(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* deb_tour_esprit_damne                        */
/************************************************/
declare
	code_retour text;
	personnage alias for $1;
	v_pos integer;
	ligne record;
	has_bloque integer;
	v_bloque_magie integer;
	v_pa_attaque integer;
	v_malus_degats integer;
	v_chance_toucher integer;
	texte_evt text;
	v_pa_dep integer;
begin
	select into v_pos
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	if not found then
		return 'Anomalie sur position !';
	end if;
	if lancer_des(1,100) < 100 then
	-- frayeur
		for ligne in
			select perso_cod,perso_nom
			from perso,perso_position
			where perso_type_perso in (1,3)
			and perso_actif = 'O'
			and perso_tangible = 'O'
			and ppos_perso_cod = perso_cod
			and ppos_pos_cod = v_pos
			and not exists
			(select 1 from lieu,lieu_position
			where lpos_pos_cod = ppos_pos_cod
			and lpos_lieu_cod = lieu_cod
			and lieu_refuge = 'O')
			loop
                         -- ajout azaghal le 4/6, on a 50% par joueur d'être affecté
                        if lancer_des(1,100) < 50 then
                        v_bloque_magie := 0;
			v_bloque_magie := resiste_magie(ligne.perso_cod,personnage,3);
			if v_bloque_magie = 0 then
------------------------
-- magie non résistée --
------------------------
				v_chance_toucher  := -25;
				v_pa_attaque := +2;
				v_malus_degats := -3;
			else
--------------------
-- magie résistée --
--------------------
				v_chance_toucher := -12;
				v_pa_attaque := +1;
				v_malus_degats := -1;
			end if;
			perform ajoute_bonus(ligne.perso_cod, 'PAA', 2, v_pa_attaque);
			perform ajoute_bonus(ligne.perso_cod, 'TOU', 2, v_chance_toucher);
			perform ajoute_bonus(ligne.perso_cod, 'DEG', 2, v_malus_degats);
			texte_evt := '[cible] a été effrayé par [attaquant]';
     			values(54,now(),1,personnage,texte_evt,'O','N',personnage,ligne.perso_cod);
     			values(54,now(),1,ligne.perso_cod,texte_evt,'N','N',personnage,ligne.perso_cod);
                        else
                        end if;
		end loop;
	end if;
	if lancer_des(1,100) < 25 then
	-- melasse
	for ligne in
			select perso_cod,perso_nom
			from perso,perso_position
			where perso_type_perso in (1,3)
			and perso_actif = 'O'
			and perso_tangible = 'O'
			and ppos_perso_cod = perso_cod
			and ppos_pos_cod = v_pos
			and not exists
			(select 1 from lieu,lieu_position
			where lpos_pos_cod = ppos_pos_cod
			and lpos_lieu_cod = lieu_cod
			and lieu_refuge = 'O')
			loop
                        -- ajout azaghal le 4/6, on a 50% par joueur d'être affecté
                        if lancer_des(1,100) < 50 then
			v_bloque_magie := 0;
				v_bloque_magie := resiste_magie(ligne.perso_cod,personnage,3);
			if v_bloque_magie = 0 then
------------------------
-- magie non résistée --
------------------------
				v_pa_dep := 3;
			else
--------------------
-- magie résistée --
--------------------
				v_pa_dep := 2;
			end if;
			perform ajoute_bonus(ligne.perso_cod, 'DEP', 3, v_pa_dep);
			texte_evt := '[cible] a été ralenti par [attaquant]';
     			values(54,now(),1,personnage,texte_evt,'O','N',personnage,ligne.perso_cod);
     			values(54,now(),1,ligne.perso_cod,texte_evt,'N','N',personnage,ligne.perso_cod);
                        else
                        end if;
		end loop;
	end if;
	return 'OK';
end;$_$;


ALTER FUNCTION public.deb_tour_esprit_damne(integer) OWNER TO delain;

--
-- Name: deb_tour_generique2(integer, text, text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.deb_tour_generique2(integer, text, text, text, text, numeric, text) RETURNS text
    LANGUAGE plpgsql
    AS $_$/***********************************************/
/* deb_tour_generique                           */
/* Applique les bonus et effectue les actions   */
/* spécifiées lors de l'activation d'une DLT.   */
/* On passe en paramètres:                      */
/*   $1 = source (perso_cod du monstre)         */
/*   $2 = bonus (de la table bonus_type)        */
/*   $3 = valeur (Entier ou +/-nDy)             */
/*   $4 = distance (-1..n , nC pour une case)   */
/*   $5 = cibles (SAERT, et limite)             */
/*   $6 = Probabilité d atteindre chaque cible  */
/*   $7 = Message d événement associé           */
/************************************************/
/* Créé le 5 Septembre 2007                     */
/************************************************/
declare
    -- Parameters
    v_source alias for $1;
    v_bonus alias for $2;
    v_valeur alias for $3;
    v_distance alias for $4;
    v_cibles alias for $5;
    v_proba alias for $6;
    v_texte_evt alias for $7;

    -- initial data
    v_x_source integer; -- source X position
    v_y_source integer; -- source Y position
    v_et_source integer; -- etage de la source
    v_type_source integer; -- Type perso de la source
    v_distance_int integer; -- Range
    v_cibles_type character; -- Type de cible (SAERT)
    v_cibles_nombre integer; -- Nombre de cibles maxi
    v_race_source integer; -- La race de la source
    v_position_source integer; -- Le pos_cod de la source

    -- Output and data holders
    ligne record;  -- Une ligne d'enregistrements
    i integer; -- Compteur de boucle
    ch character; -- Un caractère tout ce qu'il y a de plus banal
    valeur integer; -- Valeur numérique de l'impact du bonus ou de l'action
    n integer; -- Nombre de dés.
    d integer; -- Nombre de faces du dé
    signe integer; -- Signe de la valeur (1 ou -1)
    cible_case integer; -- Cible une case
    -- Resistance magique
    v_bloque_magie integer;
    v_RM1 integer;
    compt integer;
    niveau_cible integer;
    v_int_cible integer;
    v_con_cible integer;
    niveau_attaquant integer;
    v_seuil integer;
    des integer;


begin
    -- Initialisation des conteneurs
    -- Distance
    cible_case := 0;
    for i in 1..length(v_distance) loop
        ch := substr(v_distance , i , 1);
        if ch IN ('c' , 'C') then
            cible_case := 1;
        end if;
    end loop;
    if (cible_case = 0) then
        v_distance_int := v_distance;
    else
        -- La cible est une case. Choisir une case puis définir case = source, et
        -- distance = 0
        -- TODO
        v_distance_int := 0;
    end if;

    -- Position et type perso
    select into v_x_source , v_y_source , v_et_source , v_type_source ,    v_race_source, v_position_source
                pos_x ,      pos_y ,      pos_etage ,   perso_type_perso , perso_race_cod, pos_cod
    from perso_position , positions , perso
    where ppos_perso_cod = v_source
    and pos_cod = ppos_pos_cod
    and perso_cod = v_source;

    -- Cibles
    v_cibles_type := 'T'; -- Tout le monde, par défaut
    v_cibles_nombre := 0; -- Pas de limite, par défaut
    for i in 1..length(v_cibles) loop
        ch := substr(v_cibles , i , 1);
        if ch IN ('S' , 'A' , 'E' , 'R' , 'T') then
            v_cibles_type := ch;
        else
            v_cibles_nombre := 10 * v_cibles_nombre + cast(ch AS integer);
        end if;
    end loop;
    if (v_cibles_nombre = 0) then
        v_cibles_nombre := 999999;
    end if;

    -- Détermination de la liste des cibles
    if (v_distance_int < 0) then
        v_distance_int = 0;
        v_cibles_type = 'S';
    end if;
    for ligne in (select perso_cod , perso_type_perso , perso_race_cod
        from perso , perso_position , positions
        where perso_actif = 'O'
        and ppos_perso_cod = perso_cod
        and ppos_pos_cod = pos_cod
        and perso_tangible = 'O'
        -- À portée
        and pos_x between (v_x_source - v_distance_int) and (v_x_source + v_distance_int)
        and pos_y between (v_y_source - v_distance_int) and (v_y_source + v_distance_int)
        and pos_etage = v_et_source
        and trajectoire_vue(pos_cod,v_position_source) = '1'
        -- Hors refuge
        and not exists
        (select 1 from lieu_position,lieu
        where lpos_pos_cod = pos_cod
        and lieu_refuge = 'O')
        -- Parmi les cibles spécifiées
        and
            ((v_cibles_type = 'S' and perso_cod = v_source) or
            (v_cibles_type = 'A' and perso_type_perso = v_type_source) or
            (v_cibles_type = 'E' and perso_type_perso != v_type_source) or
            (v_cibles_type = 'R' and perso_race_cod = v_race_source) or
            (v_cibles_type = 'T'))
        -- Répondant à une proba d'être touchées.
        and random() <= v_proba
        -- Dans les limites autorisées
        order by random()
        limit v_cibles_nombre)
    loop
        -- On peut maintenant appliquer le bonus ou l'action sur une cible unique.

        -- Valeur
        n := 0;
        d := -1;
        signe := 1;
        for i in 1..length(v_valeur) loop
            ch := substr(v_valeur , i , 1);
            if ch IN ('D' , 'd') then
                d := 0;
            else
                if ch = '-' then
                    signe := -1;
                elseif d = -1 then
                    n := n * 10 + cast(ch AS integer);
                else
                    d := d * 10 + cast(ch AS integer);
                end if;
            end if;
        end loop;
        if (d = -1) then
            d := 1;
        end if;
        valeur := signe * lancer_des(n , d);
        -- Ajout azaghal on teste un simili resiste magie pour chaque personne cible sauf si la     cible est le lanceur
        If v_cibles_type != 'S' then
	v_bloque_magie := 0;
-- on récupère les données de l'attaquant
	select into niveau_attaquant
		perso_niveau
		from perso
		where perso_cod = v_source;
-- on récupère les données de la cible
	select into niveau_cible,v_int_cible,v_con_cible
		perso_niveau,perso_int,perso_con
		from perso
		where perso_cod = ligne.perso_cod;
-- on calcule le seuil de résistance (en fonction de l'int, la con le niv du sort et la marge de réussite
        v_con_cible := floor(v_con_cible/10);
        niveau_cible := floor(niveau_cible/2);
	v_RM1 := (v_int_cible * 5) + v_con_cible + niveau_cible;
        compt := 0;
        compt := 30;
        compt := compt + (2*niveau_attaquant);
-- calcul du seuil effectif
        v_seuil = v_RM1 - compt;
-- on limite une premiere fois le seuil à 15
        if v_seuil < 15 then
        v_seuil := 15;
        end if;
 -- le seuil (v_seuil) est maintenant calculé on peut tester
	if lancer_des(1,100) > v_seuil then
	-- resistance ratée
		v_bloque_magie := 0;
		else
		v_bloque_magie := 1;
                valeur:= floor(valeur/2);
                if valeur = 0 then
                   valeur:= 1;
                end if; /*rajout Blade du cas ou valeur devient 0 à cause du floor*/
	end if;
    end if;
        -- Effet: Bonus ou action
        if not exists (select tbonus_libc from bonus_type
                       where tbonus_libc = v_bonus) then
            -- Ceci est une action à effet immédiat. On ignore pour le moment.
        else
            -- Un bonus. On met à jour la table bonus
            perform ajoute_bonus(ligne.perso_cod, v_bonus, 2, valeur);
        end if;
        -- On rajoute la ligne d'événements
        if strpos(v_texte_evt , '[attaquant]') != 0 then
		values(nextval('seq_levt_cod'),54,now(),1,v_source,v_texte_evt,'O','O',v_source,ligne.perso_cod);
        end if;
        if strpos(v_texte_evt , '[cible]') != 0 then
		values(nextval('seq_levt_cod'),54,now(),1,ligne.perso_cod,v_texte_evt,'N','O',v_source,ligne.perso_cod);
        end if;
    end loop;
    return 'OK';
end;$_$;


ALTER FUNCTION public.deb_tour_generique2(integer, text, text, text, text, numeric, text) OWNER TO delain;

--
-- Name: FUNCTION deb_tour_generique2(integer, text, text, text, text, numeric, text); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.deb_tour_generique2(integer, text, text, text, text, numeric, text) IS 'Fonction test Blade';


--
-- Name: deb_tour_generique_case(integer, text, text, text, text, numeric, text, text); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.deb_tour_generique_case(integer, text, text, text, text, numeric, text, text) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* deb_tour_generique_case                      */
/* Applique les bonus et effectue les actions   */
/* spécifiées lors de l'activation d'une DLT.   */
/* On passe en paramètres:                      */
/*   $1 = source (perso_cod du monstre)         */
/*   $2 = bonus (de la table bonus_type)        */
/*   $3 = valeur (Entier ou +/-nDy)             */
/*   $4 = distance (-1..n , nC pour une case)   */
/*   $5 = cibles (SAERTP, et limite)            */
/*   $6 = Probabilité d atteindre chaque cible  */
/*   $7 = Message d événement associé           */
/*   $8 = Message affiché à l'init de la dlt    */
/************************************************/
/* Créé le 15 Janvier 2010	                    */
/************************************************/
declare
    -- Parameters
    v_source alias for $1;
    v_bonus alias for $2;
    v_valeur alias for $3;
    v_distance alias for $4;
    v_cibles alias for $5;
    v_proba alias for $6;
    v_texte_evt alias for $7;
    v_texte_retour alias for $8;

    -- initial data
    v_x_source integer; -- source X position
    v_y_source integer; -- source Y position
    v_et_source integer; -- etage de la source
    v_type_source integer; -- Type perso de la source
    v_distance_int integer; -- Range
    v_cibles_type character; -- Type de cible (SAERT)
    v_cibles_nombre integer; -- Nombre de cibles maxi
    v_race_source integer; -- La race de la source
    v_position_source integer; -- Le pos_cod de la source

    -- Output and data holders
    ligne record;  -- Une ligne d'enregistrements
    i integer; -- Compteur de boucle
    ch character; -- Un caractère tout ce qu'il y a de plus banal
    valeur integer; -- Valeur numérique de l'impact du bonus ou de l'action
    n integer; -- Nombre de dés.
    d integer; -- Nombre de faces du dé
    signe integer; -- Signe de la valeur (1 ou -1)
    cible_case integer; -- Cible une case
    -- Resistance magique
    v_bloque_magie integer;
    v_RM1 integer;
    compt integer;
    niveau_cible integer;
    v_int_cible integer;
    v_con_cible integer;
    niveau_attaquant integer;
    v_seuil integer;
    des integer;
    code_retour text;
    action_immediate_result text;

begin
    -- Initialisation des conteneurs
		code_retour = '';
    cible_case := 0;
    for i in 1..length(v_distance) loop
        ch := substr(v_distance , i , 1);
        if ch IN ('c' , 'C') then
            cible_case := 1;
        end if;
    end loop;
    if (cible_case = 0) then
        v_distance_int := v_distance;
    else
        -- La cible est une case. Choisir une case puis définir case = source, et
        -- distance = 0
        -- TODO
        v_distance_int := 0;
    end if;

    -- Position et type perso
    select into v_x_source , v_y_source , v_et_source , v_type_source ,    v_race_source, v_position_source
                pos_x ,      pos_y ,      pos_etage ,   perso_type_perso , perso_race_cod, pos_cod
				    from perso_position , positions , perso
				    where ppos_perso_cod = v_source
				    and pos_cod = ppos_pos_cod
				    and perso_cod = v_source;

    -- Cibles : P = Perso individuel, même sur un lieu protégé, S = Soi même, R = Race spécifique, A = autre perso du même type, E = persos d'un type différent, T = Tout le monde
    v_cibles_type := 'T'; -- Tout le monde, par défaut
    v_cibles_nombre := 0; -- Pas de limite, par défaut
    for i in 1..length(v_cibles) loop
        ch := substr(v_cibles , i , 1);
        if ch IN ('S' , 'A' , 'E' , 'R' , 'T', 'P') then
            v_cibles_type := ch;
        else
            v_cibles_nombre := 10 * v_cibles_nombre + cast(ch AS integer);
        end if;
    end loop;
    if (v_cibles_nombre = 0) then
        --v_cibles_nombre := 999999; -- modif par merrick : boucles trop longues
	v_cibles_nombre := 100;
    end if;

    -- Détermination de la liste des cibles
    if (v_distance_int < 0) then
        v_distance_int = 0;
        v_cibles_type = 'S';
    end if;
    if (v_cibles_nombre >= 20) then
    	v_cibles_nombre := 20;
    end if;
    for ligne in (select perso_cod , perso_type_perso , perso_race_cod
			        from perso , perso_position , positions
			        where perso_actif = 'O'
			        and ppos_perso_cod = perso_cod
			        and ppos_pos_cod = pos_cod
			        -- À portée
			        and pos_x between (v_x_source - v_distance_int) and (v_x_source + v_distance_int)
			        and pos_y between (v_y_source - v_distance_int) and (v_y_source + v_distance_int)
			        and pos_etage = v_et_source
			        and trajectoire_vue(pos_cod,v_position_source) = '1'
			        -- Parmi les cibles spécifiées
			        and
			            ((v_cibles_type = 'S' and perso_cod = v_source) or
			            (v_cibles_type = 'A' and perso_type_perso = v_type_source) or
			            (v_cibles_type = 'E' and perso_type_perso != v_type_source) or
			            (v_cibles_type = 'R' and perso_race_cod = v_race_source) or
			            (v_cibles_type = 'P' and perso_cod = v_source) or
			            (v_cibles_type = 'T'))
			        -- Répondant à une proba d'être touchées.
			        and random() <= v_proba
			        -- Dans les limites autorisées
			        order by random()
			        limit v_cibles_nombre)
    loop
        -- On peut maintenant appliquer le bonus ou l'action sur une cible unique.
        -- Valeur
        n := 0;
        d := -1;
        signe := 1;
        for i in 1..length(v_valeur) loop
            ch := substr(v_valeur , i , 1);
            if ch IN ('D' , 'd') then
                d := 0;
            else
                if ch = '-' then
                    signe := -1;
                elseif d = -1 then
                    n := n * 10 + cast(ch AS integer);
                else
                    d := d * 10 + cast(ch AS integer);
                end if;
            end if;
        end loop;
        --if (v_valeur ilike 'd') then
        --	d := 0;
        --end if;
        --if (v_valeur < 0) then
        --	signe = -1;
        --else
        --	if d = -1 then
        --		n := v_valeur;
        --	else
        --		d:= v_valeur;
        --	end if;
        --end if;
        if (d = -1) then
            d := 1;
        end if;
        -- ajout Merrick, si on est sur du QENL, on ne fait pas le lancer de dés (avec des num de perso à plus d'un million, ça tourne trop longtemps)
        if (v_bonus = 'QENL') then
        	valeur := v_valeur;
        else
        	valeur := signe * lancer_des(n , d);
        end if;
        -- Ajout azaghal on teste un simili resiste magie pour chaque personne cible sauf si la     cible est le lanceur
        If v_cibles_type != 'S' then
					v_bloque_magie := 0;
				-- on récupère les données de l'attaquant
					select into niveau_attaquant
								perso_niveau
								from perso
								where perso_cod = v_source;
				-- on récupère les données de la cible
					select into niveau_cible,v_int_cible,v_con_cible
								perso_niveau,perso_int,perso_con
								from perso
								where perso_cod = ligne.perso_cod;
				-- on calcule le seuil de résistance (en fonction de l'int, la con le niv du sort et la marge de réussite
				  v_con_cible := floor(v_con_cible/10);
				  niveau_cible := floor(niveau_cible/2);
					v_RM1 := (v_int_cible * 5) + v_con_cible + niveau_cible;
				  compt := 30;
				  compt := compt + (2*niveau_attaquant);
				-- calcul du seuil effectif
				  v_seuil = v_RM1 - compt;
				-- on limite une premiere fois le seuil à 15
				  if v_seuil < 15 then
				     v_seuil := 15;
				   end if;

				 -- le seuil (v_seuil) est maintenant calculé on peut tester
					if lancer_des(1,100) > v_seuil then 	-- resistance ratée
						v_bloque_magie := 0;
					else
						v_bloque_magie := 1;
				    valeur:= floor(valeur/2);
				    if valeur = 0 then
				        valeur:= 1;
				    end if; /*rajout Blade du cas ou valeur devient 0 à cause du floor*/
					end if;
				end if;

        -- Effet: Bonus ou action
        if not exists (select tbonus_libc from bonus_type
                       where tbonus_libc = v_bonus) then
            -- Ceci est une action à effet immédiat, qui n'est pas gérée à travers les bonus (gains/perte de PV, ...)
            --Dans ce cas, v_bonus symbolise l'action qui va être lancée (de préférence utiliser 4 caractères), et valeur les indications de valeurs qui vont être mise en place.
					action_immediate_result := '';

          select into action_immediate_result action_immediate(ligne.perso_cod, v_bonus, valeur);
          if substr(action_immediate_result , 1, 2) != 'KO' then
			        -- On rajoute la ligne d'événements
				        if strpos(v_texte_evt , '[attaquant]') != 0 then
												values(nextval('seq_levt_cod'),54,now(),1,v_source,v_texte_evt,'O','O',v_source,ligne.perso_cod);
				        end if;
				        if strpos(v_texte_evt , '[cible]') != 0 then
												values(nextval('seq_levt_cod'),54,now(),1,ligne.perso_cod,v_texte_evt,'N','O',v_source,ligne.perso_cod);
				        end if;
				        code_retour := v_texte_retour||action_immediate_result;
	    					return code_retour;
          end if;
        else
            -- Un bonus. On met à jour la table bonus
            perform ajoute_bonus(ligne.perso_cod, v_bonus, 2, valeur);
		        -- On rajoute la ligne d'événements
		        if strpos(v_texte_evt , '[attaquant]') != 0 then
										values(nextval('seq_levt_cod'),54,now(),1,v_source,v_texte_evt,'O','O',v_source,ligne.perso_cod);
		        end if;
		        if strpos(v_texte_evt , '[cible]') != 0 then
										values(nextval('seq_levt_cod'),54,now(),1,ligne.perso_cod,v_texte_evt,'N','O',v_source,ligne.perso_cod);
			        code_retour := code_retour||v_texte_retour;
		        end if;
    			return code_retour;
        end if;

    end loop;
    return code_retour;
end;$_$;


