CREATE FUNCTION public.deb_tour_mts(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* deb_tour_mts : Bonus de toucher  gratuits   */
/************************************************/
declare
	code_retour text;
	personnage alias for $1;
	v_pos integer;
	ligne record;
	has_bloque integer;
	v_bloque_magie integer;
	v_pa_attaque integer;
	v_malus_degats integer;
	v_chance_toucher integer;
	texte_evt text;
	v_pa_dep integer;
begin
	select into v_pos
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	if not found then
		return 'Anomalie sur position !';
	end if;
	if lancer_des(1,100) < 30 then
		perform ajoute_bonus(personnage, 'TOU', 2, 25);
		texte_evt := '[perso_cod1] dégage une aura de puissance, ses coups semblent plus précis !';
     			values(54,now(),1,personnage,texte_evt,'O','O');
	end if;

	return 'OK';
end;$_$;


