--
-- Name: defi_abandonner(integer, character); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.defi_abandonner(integer, character) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$/*************************************************************/
/* fonction defi_abandonner                                  */
/*   Actions à exécuter lorsqu’un défi est rejeté            */
/*   on passe en paramètres :                                */
/*   $1 = v_defi : le numéro de défi                         */
/*   $2 = v_role : le rôle de celui qui abandonne le défi    */
/*        'L' = lanceur ; 'C' = cible ; '2' = commun accord  */
/* Sortie : la perte de renommée constatée, ou -1 en cas     */
/*    d’erreur.                                              */
/*************************************************************/
/* Créé le 10/01/2014                                        */
/*************************************************************/
declare
	-- Entrées de la fonction
	v_defi alias for $1;        -- Le code du défi rejeté
	v_role alias for $2;        -- Le rôle de celui qui abandonne le défi : 'L' = lanceur ; 'C' = cible ; '2' = commun accord

	-- Données de base
	donnees_defi record;        -- Les données du défi
	donnees_initiateur record;  -- Les données de l’initiateur de l’abandon
	donnees_adversaire record;  -- Les données de son adversaire

	-- Données de calcul
	v_diff_niveau integer;    -- La différence de rangs de renommée entre les protagonistes
	v_perte_renommee numeric;   -- La perte de renommée de la cible
	v_vainqueur character(1);   -- Le vainqueur du défi

	-- Événement
	v_texte text;               -- Le texte de l’événement à rajouter
begin
	-- Récupération des données du défi
	select into donnees_defi * from defi where defi_cod = v_defi;

	-- Vérification de son existence, et de son statut (pour être abandonné, un défi ne doit pas être terminé !)
	if not found or donnees_defi.defi_statut > 1 or v_role not in ('C', 'L', '2') then
		return -1;
	end if;

	-- Données de l’initiateur : code, nom, rang de renommée (magique ou guerrière, au mieux)
	select into donnees_initiateur
		perso_cod, perso_nom, perso_dlt, niveau_relatif(perso_px) as niveau
	from perso
	where perso_cod = (case v_role when 'L' then donnees_defi.defi_lanceur_cod
	                               when 'C' then donnees_defi.defi_cible_cod
	                               when '2' then donnees_defi.defi_lanceur_cod
	                               else NULL end);

	-- Données de son adversaire : code, nom, rang de renommée (magique ou guerrière, au mieux)
	select into donnees_adversaire
		perso_cod, perso_nom, niveau_relatif(perso_px) as niveau
	from perso
	where perso_cod = (case v_role when 'L' then donnees_defi.defi_cible_cod
	                               when 'C' then donnees_defi.defi_lanceur_cod
	                               when '2' then donnees_defi.defi_cible_cod
	                               else NULL end);

	-- TRAITEMENTS DE FIN DE DÉFI
	v_perte_renommee := 0;

	-- Malus à la renommée pour le perso qui abandonne le défi.
	-- Ce malus est proportionnel à la différence de rangs de renommée entre les deux protagonistes.
	if v_role <> '2' then
		v_diff_niveau := donnees_initiateur.niveau + 1 - donnees_adversaire.niveau;
		if v_diff_niveau > 0 then
			v_perte_renommee := v_diff_niveau / 30.0;
		end if;

		-- Perte de renommée limitée à 1.
		if v_perte_renommee > 1 then
			v_perte_renommee := 1;
		end if;

		-- Perte de renommée doublée si c’est l’initiateur du défi qui l’annule
		if donnees_initiateur.perso_cod = donnees_defi.defi_lanceur_cod then
			v_perte_renommee := v_perte_renommee * 2;
		end if;

		-- Perte de renommée nulle si la personne qui abandonne ne joue plus
		if donnees_initiateur.perso_dlt < donnees_defi.defi_date_debut then
			v_perte_renommee := 0;
		end if;

		if v_perte_renommee > 0 then
			update perso set perso_renommee = perso_renommee - v_perte_renommee where perso_cod = donnees_initiateur.perso_cod;
			update perso set perso_renommee = perso_renommee + v_perte_renommee where perso_cod = donnees_adversaire.perso_cod;
		end if;
	end if;

	-- Mise à jour du défi.
	v_vainqueur := case v_role when 'L' then 'C'
	                           when 'C' then 'L' end;

	-- Libération de la zone de combat
	update defi_zone set zone_libre = 'O' where zone_cod = donnees_defi.defi_zone_cod;

	-- Cas particulier : rejet du défi. Les protagonistes n’ont pas encore été déplacés.
	if donnees_defi.defi_statut = 0 then
		-- Mise à jour du défi
		update defi set defi_statut = 2, defi_date_fin = now(), defi_vainqueur = v_vainqueur where defi_cod = v_defi;
	else
		-- Autres cas : le défi est déjà commencé
		if v_role = '2' then
			update defi set defi_statut = 5, defi_date_fin = now() where defi_cod = v_defi;
		else
			update defi set defi_statut = 4, defi_date_fin = now(), defi_vainqueur = v_vainqueur where defi_cod = v_defi;
		end if;
		-- Remise à jour des persos
		perform defi_reinitialise_persos(v_defi);
	end if;

	-- On place un événement
	if v_role = 'L' and donnees_defi.defi_statut = 0 then
		v_texte := '[attaquant] a annulé son défi contre [cible].';
		perform insere_evenement(donnees_initiateur.perso_cod, donnees_adversaire.perso_cod, 99, v_texte, 'O', '[defi_cod]=' || donnees_defi.defi_cod::text);
	elsif v_role = 'C' and donnees_defi.defi_statut = 0 then
		v_texte := '[attaquant] a rejeté un défi de [cible].';
		perform insere_evenement(donnees_initiateur.perso_cod, donnees_adversaire.perso_cod, 96, v_texte, 'O', '[defi_cod]=' || donnees_defi.defi_cod::text);
	elsif v_role = '2' then
		v_texte := 'Le défi opposant [attaquant] et [cible] s’est soldé par un match nul.';
		perform insere_evenement(donnees_adversaire.perso_cod, donnees_initiateur.perso_cod, 98, v_texte, 'O', '[defi_cod]=' || donnees_defi.defi_cod::text);
	else
		v_texte := '[attaquant] a remporté son défi contre [cible].';
		perform insere_evenement(donnees_adversaire.perso_cod, donnees_initiateur.perso_cod, 97, v_texte, 'O', '[defi_cod]=' || donnees_defi.defi_cod::text);
	end if;

	-- Et on termine;
	return v_perte_renommee;
end;$_$;


ALTER FUNCTION public.defi_abandonner(integer, character) OWNER TO delain;

--
-- Name: FUNCTION defi_abandonner(integer, character); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.defi_abandonner(integer, character) IS 'Gère l’abandon d’un défi par un ou par les deux protagonistes.
$1 = defi_cod ; $2 = ''L'' si le lanceur abandonne, ''C'' si c’est la cible, ''2'' si les deux demandent un match nul.
Sortie : la perte de renommée constatée, ou -1 en cas d’erreur.';



--
-- Name: defi_creer(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.defi_creer(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*************************************************************/
/* fonction defi_creer                                       */
/*   Actions à exécuter lorsqu’un défi est instancié         */
/*   on passe en paramètres :                                */
/*   $1 = v_lanceur : le perso qui lance le défi             */
/*   $2 = v_cible : le perso qui reçoit le défi              */
/* Sortie de la forme n#message                              */
/*   n == statut : -1 (erreur) ou 0 (ok)                     */
/*   message == message d’erreur si nécessaire               */
/*************************************************************/
/* Créé le 09/01/2014                                        */
/*************************************************************/
declare
	v_lanceur alias for $1;   -- Le code de l’instance de mission
	v_cible alias for $2;     -- Le perso qui relève la mission

	v_actif text;             -- Perso actif ou non
	v_perso_type integer;     -- Le type de perso
	v_emplacement integer;    -- Le code de l’emplacement du défi
	v_resultat text;

begin
	select into v_resultat defi_possible(v_lanceur, v_cible);

	if v_resultat LIKE '-1%' then
		return v_resultat;
	end if;

	-- Vérification de la zone où le défi se résoudra
	select into v_emplacement zone_cod from defi_zone where zone_libre = 'O' limit 1;
	if not found then
		return '-1#Aucune arène pour relever votre défi n’est disponible ! Réessayez plus tard...';
	end if;

	-- On réserve l’emplacement
	update defi_zone set zone_libre = 'N' where zone_cod = v_emplacement;

	-- On crée le défi
	values (v_lanceur, v_cible, v_emplacement);

	-- On place un événement
	perform insere_evenement(v_lanceur, v_cible, 95, '[attaquant] a défié [cible].', 'O', null);

	-- Et on termine;
	return v_resultat;
end;$_$;


ALTER FUNCTION public.defi_creer(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION defi_creer(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.defi_creer(integer, integer) IS 'Crée un nouveau défi, lancé par $1 envers $2.
Renvoie statut#message, où statut vaut 1 si tout va bien, -1 si problème bloquant, 0 pour un avertissement.';


--
-- Name: defi_possible(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.defi_possible(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*************************************************************/
/* fonction defi_possible                                    */
/*   Vérifie qu’un défi est possible entre deux protagonistes*/
/*   on passe en paramètres :                                */
/*   $1 = v_lanceur : le perso qui lance le défi             */
/*   $2 = v_cible : le perso qui reçoit le défi              */
/* Sortie de la forme n#message                              */
/*   n == statut : -1 (erreur) ou 0 (avertissement)          */
/*                 ou 1 (ok)                                 */
/*   message == message d’erreur si nécessaire               */
/*************************************************************/
/* Créé le 09/01/2014                                        */
/*************************************************************/
declare
	v_lanceur alias for $1;   -- Le code de l’instance de mission
	v_cible alias for $2;     -- Le perso qui relève la mission

	v_actif text;             -- Perso actif ou non
	v_perso_type integer;     -- Le type de perso
	v_compte_l integer;       -- Le compte du lanceur
	v_compte_c integer;       -- Le compte de la cible
	v_resultat text;

begin
	-- Par défaut, tout est OK.
	v_resultat := '1#';

	-- Vérification : les personnages existent et sont actifs (pour le lanceur, c’est très probable, mais bon...)
	select into v_actif, v_perso_type, v_compte_l perso_actif, perso_type_perso, pcompt_compt_cod
	from perso
	inner join perso_compte on pcompt_perso_cod = perso_cod
	where perso_cod = v_lanceur;
	if not found or v_actif <> 'O' or v_perso_type = 3 then
		return '-1#Le lanceur du défi est en hibernation, ou n’existe pas, ou est un familier.';
	end if;

	-- Pour la cible, on est un peu plus précis, car l’erreur a une réelle valeur ajoutée pour le lanceur.
	select into v_actif, v_perso_type, v_compte_c perso_actif, perso_type_perso, pcompt_compt_cod
	from perso
	inner join perso_compte on pcompt_perso_cod = perso_cod
	where perso_cod = v_cible;
	if not found then
		return '-1#La cible du défi n’existe pas.';
	end if;
	if v_actif = 'N' then
		return '-1#La cible du défi est définitivement décédée.';
	end if;
	if v_actif <> 'O' then
		return '-1#La cible du défi est en hibernation.';
	end if;
	if v_perso_type = 3 then
		return '-1#Un défi ne peut pas cible un familier.';
	end if;
	if v_compte_c = v_compte_l then
		return '-1#Un défi ne peut pas opposer deux personnages d’un même compte.';
	end if;

	-- Vérification de la présence d’une des deux parties dans un autre défi
	if exists(select 1 from defi where v_lanceur IN (defi_lanceur_cod, defi_cible_cod) AND defi_statut < 2) then
		return '-1#Vous devez d’abord répondre aux défis dans lesquels vous êtes impliqués.';
	end if;
	if exists(select 1 from defi where v_cible IN (defi_lanceur_cod, defi_cible_cod) AND defi_statut < 2) then
		return '-1#Votre adversaire est actuellement impliqué dans un défi.';
	end if;

	-- Vérification qu’on n’est pas en train de harceler une victime
	if exists (select 1 from defi where defi_lanceur_cod = v_lanceur and defi_cible_cod = v_cible and (now() - defi_date_debut) < '5 days'::interval)
		and not exists (select 1 from defi where defi_lanceur_cod = v_cible and defi_cible_cod = v_lanceur and (now() - defi_date_debut) < '5 days'::interval)
	then
		return '-1#Vous avez déjà défié votre adversaire dans les 5 derniers jours. Laissez-le souffler !';
	end if;

	-- Vérification des ripostes (légitimes défenses)
	if exists(select 1 from riposte where v_lanceur IN (riposte_attaquant, riposte_cible) AND riposte_nb_tours < 2) then
		return '-1#Vous êtes engagé en combat, et ne pouvez pas vous en soustraire pour participer à un défi.';
	end if;
	if exists(select 1 from riposte where v_cible IN (riposte_attaquant, riposte_cible) AND riposte_nb_tours < 2) then
		v_resultat := '0#Votre cible est engagée en combat. ';
		v_resultat := v_resultat || 'Elle pourra donc ne pas être en mesure de répondre à votre défi dans le temps imparti. ';
	end if;

	-- Et on termine;
	return v_resultat;
end;$_$;


ALTER FUNCTION public.defi_possible(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION defi_possible(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.defi_possible(integer, integer) IS 'Vérifie si les conditions sont remplies pour pouvoir initier un nouveau défi.
$1 = perso_cod du lanceur de défi.
$2 = perso_cod du receveur du défi.
Return = ''statut#message'' avec statut : -1 (erreur), 0 (avertissement), 1 (ok).';

--
-- Name: degats_perso(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.degats_perso(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**********************************************************/
/* fonction degats_perso : affiche les degats min et max  */
/*  d un perso en fonction de son arme et bonus           */
/* on passe en parametre :                                */
/*  $1 = perso_cod                                        */
/* on a en sortie une chaine séparée par ;                */
/*   0 = degats min                                       */
/*   1 = degats max                                       */
/**********************************************************/
declare
	code_retour text;
	personnage alias for $1;
	compt integer;
	nb_des_attaque integer;
	valeur_des_attaque integer;
	bonus_attaque integer;
	v_amelioration_degats integer;
	v_amel_dist integer;
	v_nb_des_degats integer;
	v_val_des_degats integer;
	is_distance varchar(2);
	bonus_perm integer;
	deg_min integer;
	deg_max integer;
	bonus_sort integer;
	v_bonus_toucher integer;

begin
	bonus_sort := valeur_bonus(personnage, 'DEG');
	select into v_amelioration_degats,v_amel_dist,v_nb_des_degats,v_val_des_degats
		perso_amelioration_degats,perso_amel_deg_dex,perso_nb_des_degats,perso_val_des_degats
		from perso
		where perso_cod = personnage;
	select into nb_des_attaque,valeur_des_attaque,bonus_attaque,is_distance
			obj_des_degats,obj_val_des_degats,obj_bonus_degats,gobj_distance
			from perso_objets,objets,objet_generique,objets_caracs
			where perobj_perso_cod = personnage
			and perobj_equipe = 'O'
			and perobj_obj_cod = obj_cod
			and obj_gobj_cod = gobj_cod
			and gobj_tobj_cod = 1
			and gobj_obcar_cod = obcar_cod;
	if not found then -- pas d arme equipee, on passe aux poings
		nb_des_attaque := v_nb_des_degats;
		valeur_des_attaque := v_val_des_degats;
		bonus_attaque := 0;

		deg_min := nb_des_attaque + bonus_attaque + v_amelioration_degats + bonus_degats_melee(personnage) + bonus_sort;
		deg_max := (nb_des_attaque*valeur_des_attaque) + bonus_attaque + v_amelioration_degats + bonus_degats_melee(personnage) + bonus_sort;
			deg_min := deg_min + valeur_bonus(personnage, 'PDC');
			deg_max := deg_max + valeur_bonus(personnage, 'PDC');
	else -- on a une arme equipee
/* Cas des armes à distance */
		if is_distance = 'O' then
			deg_min := nb_des_attaque  + bonus_attaque + v_amel_dist + bonus_sort;
			deg_max := (nb_des_attaque*valeur_des_attaque) + bonus_attaque + v_amel_dist + bonus_sort;
			deg_min := deg_min + valeur_bonus(personnage, 'PDD');
			deg_max := deg_max + valeur_bonus(personnage, 'PDD');
		else
			deg_min := nb_des_attaque + bonus_attaque + v_amelioration_degats + bonus_degats_melee(personnage) + bonus_sort;
			deg_max := (nb_des_attaque*valeur_des_attaque) + bonus_attaque + v_amelioration_degats + bonus_degats_melee(personnage) + bonus_sort;
			deg_min := deg_min + valeur_bonus(personnage, 'PDC');
			deg_max := deg_max + valeur_bonus(personnage, 'PDC');
		end if;
	end if; -- arme equipee
	code_retour := trim(to_char(deg_min,'9999'))||';'||trim(to_char(deg_max,'9999'))||';';
	return code_retour;
end;$_$;


ALTER FUNCTION public.degats_perso(integer) OWNER TO delain;

--
-- Name: FUNCTION degats_perso(integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.degats_perso(integer) IS 'affiche les degats min et max d un perso en fonction de son arme et bonus';


--
-- Name: delta_x(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.delta_x(integer, integer) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $_$/***************************************************/
/* fonction delta_x : donne l ecart en valeur      */
/*  absolue des X entre deux positions             */
/* on passe en paramètres :                        */
/*  $1 = pos_cod 1                                 */
/*  $2 = pos_cod 2                                 */
/* on a en retour un entier                        */
/***************************************************/
declare
	code_retour integer;
	pos1 alias for $1;
	pos2 alias for $2;
	x1 integer;
	x2 integer;

begin
	select into x1 pos_x from positions
		where pos_cod = pos1;
	select into x2 pos_x from positions
		where pos_cod = pos2;
	code_retour := @(x1 - x2);
	return code_retour;
end;$_$;


