--
-- Name: dep_vers_cible(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.dep_vers_cible(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*************************************************/
/* fonction dep_vers_cible                       */
/*   reçoit en paramètre :                       */
/*   $1 = position actuelle                      */
/*   $2 = position vers laquelle on veut aller   */
/* On a en sortie :                              */
/*   -1 si pas de position plus proche           */
/*   sinon le pos_cod touchant la position       */
/*      actuelle et qui se rapproche du $2       */
/*************************************************/
/* Créé le 16/05/2003                            */
/* Modif Blade le 14/11/2009  : mise en          */
/* commentaire lieu refuge, pour éviter les      */
/* blocage de l’IA                               */
/*************************************************/
declare
-- variables E/S
	code_retour integer;
	pos_actuelle alias for $1;
	pos_dest alias for $2;
-- variables de calcul
	distance_init integer;
	distance_temp integer;
	nouvelle_pos integer;
	r_pos record;
	etage integer;
	v_x integer;
	v_y integer;

begin
	select into etage,v_x,v_y pos_etage,pos_x,pos_y from positions where pos_cod = pos_actuelle;
	distance_init := distance(pos_actuelle,pos_dest);
	nouvelle_pos := -1;
	for r_pos in select pos_cod from positions
		where pos_x >= (v_x - 1) and pos_x <= (v_x + 1)
		and pos_y >= (v_y - 1) and pos_y <= (v_y + 1)
		and pos_etage = etage
		and not exists (select 1 from murs where mur_pos_cod = pos_cod)
		/*and not exists
			(select 1 from lieu,lieu_position
			where lpos_pos_cod = pos_cod
			and lpos_lieu_cod = lieu_cod
			and lieu_refuge = 'O')*/
			loop
		distance_temp := distance(r_pos.pos_cod,pos_dest);
		if distance_temp < distance_init then
			nouvelle_pos := r_pos.pos_cod;
			distance_init := distance_temp;
		end if;
	end loop;
	return  nouvelle_pos;
end;			$_$;


ALTER FUNCTION public.dep_vers_cible(integer, integer) OWNER TO delain;

--
-- Name: deplace_antre_araignee(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.deplace_antre_araignee(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$declare
	personnage alias for $1;
	v_pos alias for $2;
	code_retour text;
begin
	update perso_position
		set ppos_pos_cod = v_pos
		where ppos_perso_cod = personnage;
	code_retour := 'Vous êtes brusquement transporté vers un nouveau lieu, sans pouvoir rien y faire.<br>
	 Le sol, ou plutôt la chose grisâtre sur laquelle vous posez le pied est collante... et instable, comme si toute la structure sur laquelle vous 	marchez était en mouvement, ce qui tend déjà à vous donner la nausée et à ralentir fortement votre marche. Le silence est pesant, inquiétant... Les sons, au lieu de se répercuter sur les murs comme dans le reste des souterrains, sont absorbés par les centaines de fils de soie qui forment autour de vous une paroi fragile et impénétrable à la fois, tel un tunnel capitonné... ou une prison insoupçonnée ?<br>
Par endroit, là où la toile laisse une ouverture, tel un passage pour l''habitant, on peut apercevoir le vide béant et menaçant, qui fait craindre la moindre rupture de la fine cloison filandreuse. Le plus impressionnant reste peut-être de pouvoir deviner, loin, très loin en contrebas, les décors et même les aventuriers qui évoluent au masque de mort... ';
	return code_retour;
end;
	$_$;


ALTER FUNCTION public.deplace_antre_araignee(integer, integer) OWNER TO delain;

--
-- Name: deplace_fontaine(integer, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.deplace_fontaine(integer, integer, integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* Fontaine de jouvence                         */
/* les monstres ne sont pas affectés            */
/* 12/01/2010                                   */
/* perso : $1                                   */
/* bonus PV immediat dés : $2                   */
/* bonus PV immediat nbre dés : $3              */
/* bonus Régèn : $4                             */
/* nombre de tour Régèn : $5                    */
/************************************************/

declare
-------------------------------------------------------------
-- variables servant pour la sortie
-------------------------------------------------------------
	code_retour text;			-- texte pour action
	texte_evt text;				-- texte pour évènements
-------------------------------------------------------------
-- variables concernant le perso
-------------------------------------------------------------
	personnage alias for $1;        -- perso_cod du perso
	type_perso integer;             -- perso_type_perso du perso ou monstre
	pv_perso integer;               -- PV du perso
	pv_max integer;									--PV max du perso
	pos_perso integer;		-- position du perso
-------------------------------------------------------------
-- variables de calcul
-------------------------------------------------------------
	gain_pv_des alias for $2;
	gain_pv_nbre_des alias for $3;
	gain_pv integer;		--gain pv accordé
	gain_regen alias for $4;
	gain_regen_nbre_dlt alias for $5;
	texte2 text;
	des integer; 				-- correspond à l'aléatoire

begin
      code_retour := '';
      select into type_perso,pv_perso,pv_max
				perso_type_perso,perso_pv,perso_pv_max
				from perso
				where perso_cod = personnage;
	if not found then
		return 'soucis sur la sélection de type de perso !';
	end if;
	if type_perso = 2             --On teste si il s'agit d'un monstre
			then return 'Sans conséquence';
	else
                       --un perso est entré sur la case
		code_retour := 'Vous venez d''arriver sur une fontaine de jouvence. Vous en profitez pour vous refaire une santé, et profiter de la vue magnifique.
		<br>Oh tiens, mais quel est donc ce monstre si bucolique qui court après cet aventurier ?';


		texte_evt := '[perso_cod1] vient de visiter une fontaine de jouvence.';
     		values(54,now(),1,personnage,texte_evt,'O','O');
		gain_pv := lancer_des(gain_pv_nbre_des,gain_pv_des);
		if  gain_pv > (pv_max-pv_perso) then
			gain_pv := (pv_max-pv_perso);
		end if;
		-- personnage : mise à jour des pvs
		update perso set perso_pv = pv_perso + gain_pv where perso_cod = personnage;
		code_retour := code_retour||'<br>Vous gagnez '||trim(to_char(gain_pv,'99999999'))||' PV, ainsi qu''un bonus de régénération';
-------------------------------------------------------------
-- MAJ bonus Régén
-------------------------------------------------------------
		if gain_regen != 0 then
			perform ajoute_bonus(personnage,'REG',gain_regen,gain_regen_nbre_dlt);
		end if;
-------------------------------------------------------------
-- Code retour des évènements et du texte
-------------------------------------------------------------
		return code_retour;
	end if;
end;$_$;


