--
-- Name: depose_objet(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.depose_objet(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function depose_objet : repose à terre un objet               */
/* On passe en paramètres                                        */
/*    $1 = perso_cod                                             */
/*    $2 = obj_cod                                               */
/* Le code sortie est une chaine séparée par ;                   */
/*    Caractère 1 =>                                             */
/*       0 = tout est OK, on peut équiper                        */
/*      -1 = anomalie + description                              */
/*****************************************************************/
/* Créée le 27/03/2003                                           */
/* Liste des modifications :                                     */
/*  19/02/2004 : gestion des objets non droppables               */
/*  19/02/2004 : modif du code sortie pour du html               */
/*  26/06/2012 : modif de l’événement enregistré                 */
/*****************************************************************/
declare
	code_retour text;                           -- code retour
	personnage alias for $1;                    -- perso_cod
	num_objet alias for $2;                     -- obj_cod
	pa perso.perso_pa%type;                     -- pa du perso
	v_obj_identifie perso_objets.perobj_identifie%type;
	pos_perso perso_position.ppos_pos_cod%type; -- position actuelle du perso
	perobj perso_objets.perobj_cod%type;        -- le perobj à supprimer
	tobjet objet_generique.gobj_tobj_cod%type;  -- le type d’objet à déposer
	nom_objet objets.obj_nom_generique%type;    -- le nom de l’objet déposé
	texte_evt text;
	nb_trans integer;
	v_deposable text;
begin
	code_retour := '0'; -- par défaut, tout est OK
	texte_evt := '';

	/********************************************/
	/* Etape 1 : on vérifie que le perso existe */
	/********************************************/
	select into pa, pos_perso
		perso_pa, ppos_pos_cod
	from perso, perso_position
	where perso_cod = personnage
		and ppos_perso_cod = perso_cod;
	if not found then
		code_retour := 'Erreur ! Personnage non trouvé !';
		return code_retour;
	end if;

	/*******************************************/
	/* Etape 2 : on vérifie que l’objet existe */
	/*******************************************/
	select into nom_objet, tobjet, v_deposable
		obj_nom_generique, gobj_tobj_cod, obj_deposable
	from objets
	inner join objet_generique on gobj_cod = obj_gobj_cod
	where obj_cod = num_objet;
	if not found then
		code_retour := 'Erreur ! Objet non trouvé !';
		return code_retour;
	end if;

	/********************************************************************/
	/* Etape 3 : on vérifie que l’objet soit dans l’inventaire du perso */
	/********************************************************************/
	select into perobj, v_obj_identifie
		perobj_cod, perobj_identifie
	from perso_objets
	where perobj_perso_cod = personnage
		and perobj_obj_cod = num_objet;
	if not found then
		code_retour := 'Erreur ! L’objet n’est pas dans l’inventaire !';
		return code_retour;
	end if;

	-- petit changement temporaire : on vérfie que ce ne soit pas un poisson
	if tobjet = 16 then
		code_retour := 'Vous ne pouvez pas déposer cet objet !';
		return code_retour;
	end if;

	/*****************************************************/
	/* Etape 4 : on vérifie que le perso ait assez de pa */
	/*****************************************************/
	if pa < 1 then
		code_retour:= 'Erreur ! Pas assez de PA pour cette action !';
		return code_retour;
	end if;

	/**************************************/
	/* Etape 5 : tout est OK, on continue */
	/**************************************/
	-- 5.0 : on enlève les transactions sur cet objet
	delete from transaction
	where tran_obj_cod = num_objet;
	get diagnostics nb_trans = row_count;
	if nb_trans != 0 then
		texte_evt := 'La transaction en cours sur l’objet « ' || nom_objet || ' » (' || trim(to_char(num_objet,'99999999')) || ') a été annulée !';
		values (nextval('seq_levt_cod'), 17, 'now()', 1, personnage, texte_evt, 'O', 'N');
		texte_evt := '<p>' || texte_evt || '</p>';
	end if;

	-- 5.1 : on enlève les pa du perso
	update perso
	set perso_pa = pa - 1
	where perso_cod = personnage;

	-- 5.2 : on détruit le perso_objet
	code_retour := code_retour || ';' || to_char(perobj,'9999');
	delete from perso_objets
	where perobj_cod = perobj;

	-- 5.3 : si objet déposable on crée un objet_position
	if v_deposable != 'N' then
		values (nextval('seq_pobj_cod'), num_objet, pos_perso);
		code_retour := texte_evt || '<p>L’objet « ' || nom_objet || ' » (' || trim(to_char(num_objet,'99999999')) || ') a été déposé au sol.</p>';
		texte_evt := '[perso_cod1] a posé au sol l’objet « ' || nom_objet || ' » (' || trim(to_char(num_objet,'99999999')) || ')';
	else
		delete from perso_identifie_objet where pio_obj_cod = num_objet;
		delete from objets where obj_cod = num_objet;
		code_retour := texte_evt || '<p>L’objet « ' || nom_objet || ' » (' || trim(to_char(num_objet,'99999999')) || ') a été déposé au sol, mais s’est désintégré immédiatement.</p>';
		texte_evt := '[perso_cod1] a posé au sol l’objet « ' || nom_objet || ' » (' || trim(to_char(num_objet,'99999999')) || ') qui s’est désintégré';
	end if;

	-- 5.4 : on crée la ligne d’événement
	values(nextval('seq_levt_cod'), 7, now(), 1, personnage, texte_evt, 'O', 'O');

	-- 5.5 : et pour finir on retourne le bon code
	return code_retour;
end;
$_$;


ALTER FUNCTION public.depose_objet(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION depose_objet(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.depose_objet(integer, integer) IS 'Gère le dépôt d’un objet au sol.';


--
-- Name: depose_or(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.depose_or(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function depose_or : depose de l or au sol                    */
/* On passe en paramètres                                        */
/*    $1 = perso_cod                                             */
/*    $2 = qte                                                   */
/* Le code sortie est une chaine séparée par ;                   */
/*    Caractère 1 =>                                             */
/*       0 = tout est OK, on peut déposer                        */
/*      -1 = anomalie + description                              */
/*****************************************************************/
/* Créé le 27/03/2003                                            */
/* Liste des modifications :                                     */
/*****************************************************************/
declare
	code_retour text;					-- code retour
	personnage alias for $1;		-- perso_cod
	qte_or alias for $2;			-- obj_cod
	compt integer;						-- compteur mutli utilisations
	pa perso.perso_pa%type;			-- pa du perso
	pos_perso perso_position.ppos_pos_cod%type; -- position actuelle du perso
	qte_or_actuelle integer;
	nom_perso perso.perso_nom%type;	-- nom du perso pour evt
	texte_evt text;
	total_paquet integer;
	n_total_paquet integer;
begin
	code_retour := '0'; -- par défaut, tout est OK
/********************************************/
/* Etape 1 : on vérifie que le perso existe */
/********************************************/
	select into compt count(*) from perso
		where perso_cod = personnage;
	if compt != 1 then
		code_retour := '-1;Personnage non trouvé !';
		return code_retour;
	else -- sinon, on récupère maintenant les infos dont on aura besoin
		select into pa,pos_perso,nom_perso perso_pa,ppos_pos_cod,perso_nom
			from perso,perso_position
			where perso_cod = personnage
			and ppos_perso_cod = perso_cod;
	end if;
/**********************************************************/
/* Etape 2 : on vérifie que l or existe en qte suffisante */
/**********************************************************/
	select into compt perso_po from perso
		where perso_cod = personnage;
	if compt < qte_or then
		code_retour := '-1;Pas assez riche.... ';
		return code_retour;
	-- penser à mettre un else si on a des infos à récupérer !
	end if;
        if qte_or < 0 then
                code_retour := '-1;Bien essayé, mais on ne peut pas poser de qté négative.';
                return code_retour;
        end if;
        if qte_or = 0 then
                code_retour := '-1;Tu as déjà essayé de poser rien par terre ?.';
                return code_retour;
        end if;
/*****************************************************/
/* Etape 4 : on vérifie que le perso ait assez de pa */
/*****************************************************/
	if pa < 1 then
		code_retour:= '-1;Pas assez de PA pour cette action';
		return code_retour;
	end if;
/**************************************/
/* Etape 5 : tout est OK, on continue */
/**************************************/
-- 5.1 : on enlève les pa du perso
	update perso
		set perso_pa = pa - 1 where perso_cod = personnage;
		values (nextval('seq_por_cod'),pos_perso,qte_or);
-- 5.5 : on crée la ligne d evenement
	texte_evt :='[perso_cod1] a posé au sol '||trim(to_char(qte_or,'99999999'))||' brouzoufs';
		values(nextval('seq_levt_cod'),13,now(),1,personnage,texte_evt,'O','O');
-- 5.7 : et on n oublie pas d enlever l or du perso
	update perso
		set perso_po = perso_po - qte_or
		where perso_cod = personnage;
-- 5.6 : et pour finir on retourne le bon code

	return code_retour;
end;
$_$;


ALTER FUNCTION public.depose_or(integer, integer) OWNER TO delain;

--
-- Name: depot_banque(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.depot_banque(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* fonction depot_banque                        */
/*   fait un dépot en banque                    */
/* on passe en paramètres :                     */
/*   $1 = perso_cod                             */
/*   $2 = qte or déposée                        */
/* on a en retour une chaine séparée par ;      */
/*   pos 0 = code retour (0 OK, -1 BAD)         */
/*   pos 1 = description de l erreur            */
/************************************************/
/* Créé le 26/05/2003                           */
/************************************************/
declare
	code_retour text;
	personnage alias for $1;
	qte_or alias for $2;
	texte_evt text;
	num_compte integer;
	or_actuel integer;
	nom_perso perso.perso_nom%type;

begin
	code_retour := '0';
/*************************************************/
/* Etape 1 : on récupère les infos               */
/*************************************************/
	if qte_or < 0 then
		code_retour := '-1;Montant négatif. Bien essayé.';
		return code_retour;
	end if;
	select into or_actuel,nom_perso perso_po,perso_nom from perso
		where perso_cod = personnage;
	if or_actuel < qte_or then
		code_retour := '-1;Vous n''avez pas assez d''or pour faire de dépot.';
		return code_retour;
	end if;
/*************************************************/
/* Etape 2 : on recherche le compte              */
/*************************************************/
	select into num_compte pbank_cod from perso_banque
		where pbank_perso_cod = personnage;
	if num_compte is null then
		num_compte := nextval('seq_pbank_cod');
			values(num_compte,personnage,qte_or);
	else
		update perso_banque
			set pbank_or = pbank_or + qte_or
			where pbank_cod = num_compte;
	end if;
/*************************************************/
/* Etape 3 : on vire l or du perso               */
/*************************************************/
	update perso set perso_po = or_actuel - qte_or
		where perso_cod = personnage;
/*************************************************/
/* Etape 4 : on met un évènement                 */
/*************************************************/
	texte_evt := nom_perso||' a déposé '||trim(to_char(qte_or,'99999999'))||' brouzoufs en banque.';
		values(nextval('seq_levt_cod'),19,now(),1,personnage,texte_evt,'O','N');
	return code_retour;
end;
		$_$;


ALTER FUNCTION public.depot_banque(integer, integer) OWNER TO delain;

--
-- Name: desengagement(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.desengagement(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/***************************************************************/
/* désengagement                                               */
/*  on passe en param :                                        */
/*    $1 = le perso_cod qui doit se désengager                 */
/*    $2 = la cible/assaillant que l'on veut désengager        */
/***************************************************************/
declare
	code_retour text;
	personnage alias for $1;
	cible alias for $2;
	v_pa integer;
	nom_cible text;
      	nb_off integer;			-- locks offensifs
	nb_def integer;			-- locks défensifs
	v_competence_init integer;
	v_competence_modifie integer;
	nb_concentrations integer;
	des integer;
	texte text;
	tmp_txt text;
	temp integer;
        bonmal integer;
        malus integer;

begin
	code_retour := '';
	select into v_pa perso_pa from perso
		where perso_cod = personnage;
	if not found then
		code_retour := 'Anomalie ! Personnage non trouvé !';
		return code_retour;
	end if;
	if v_pa < getparm_n(60) then
		code_retour := 'Anomalie ! pas assez de PA pour se désengager !';
		return code_retour;
	end if;
	select into nom_cible perso_nom
		from perso
		where perso_cod = cible;
	if not found then
		code_retour := 'Anomalie ! perso cible non trouvé !';
		return code_retour;
	end if;
	select into nb_off count(lock_cod)
		from lock_combat
		where lock_attaquant = personnage
		and lock_cible = cible;
	select into nb_def count(lock_cod)
		from lock_combat
		where lock_attaquant = cible
		and lock_cible = personnage;
	if (nb_off + nb_def) = 0 then
		code_retour := 'Aucune action n''a été effectuée car vous n''êtes pas en combat avec <b>'||nom_cible||'</b>.<br>';
		return code_retour;
	end if;
	if valeur_bonus(personnage, 'HON') != 0 then
		code_retour := 'Vous ne pouvez pas vous désengager en étant sous l''effet du sort <b>Honneur</b>.<br>';
		return code_retour;
	end if;
-- on fait les jets de compétence
	select into v_competence_init pcomp_modificateur
			from perso_competences
			where pcomp_perso_cod = personnage
			and pcomp_pcomp_cod = 71;
	v_competence_modifie := v_competence_init - (2 * nb_def) - (2 * nb_off);
	select into nb_concentrations concentration_cod from concentrations
		where concentration_perso_cod = personnage;
	if found then
		v_competence_modifie := v_competence_modifie + 20;
		delete from concentrations
		where concentration_perso_cod = personnage;
	end if;
	if v_competence_modifie <= 10 then
		v_competence_modifie := 10;
	end if;
	code_retour := code_retour||'Vous avez utilisé la compétence <b>désengagement</b> ';
	code_retour := code_retour||'(compétence en tenant compte des modificateurs : '||trim(to_char(v_competence_modifie,'99999'))||' %)<br>';
-- on regarde si la cible est bénie ou maudite
bonmal = 0;
         malus = 0;
	  bonmal := valeur_bonus(personnage, 'BEN') + valeur_bonus(personnage, 'MAU');
	if bonmal <> 0 then
        des := lancer_des3(1,100,bonmal);
                else
        des := lancer_des(1,100);
        end if;
	code_retour := code_retour||'Votre lancer de dés est de <b>'||trim(to_char(des,'999'))||'</b>, ';
     if des >= 96 then -- echec critique
     texte := '[attaquant] a tenté de rompre le combat avec [cible]mais a lamentablement échoué.';
		values (52,'now()',1,personnage,texte,'O','O',personnage,cible);
		values (52,'now()',1,cible,texte,'N','O',personnage,cible);
		code_retour := code_retour||' vous avez donc <b>échoué.</b><br>';
         -- on enlève les pa
	update perso set perso_pa = perso_pa - getparm_n(60) where perso_cod = personnage;
	else
	if des > v_competence_modifie then
		texte := '[attaquant] a tenté de rompre le combat avec [cible].';
		values (52,'now()',1,personnage,texte,'O','O',personnage,cible);
		values (52,'now()',1,cible,texte,'N','O',personnage,cible);
		code_retour := code_retour||' vous avez donc <b>échoué.</b><br>';
		if v_competence_init <= getparm_n(1) then
			code_retour := code_retour||'Votre compétence est inférieure à '||trim(to_char(getparm_n(1),'999999999'))||'.<br>';
			tmp_txt := ameliore_competence_px(personnage,71,v_competence_init);
			code_retour := code_retour||'Votre jet d''amélioration est de '||split_part(tmp_txt,';',1)||'. ';
			if split_part(tmp_txt,';',2) = '1' then
				code_retour := code_retour||'Vous avez donc amélioré cette compétence. Sa nouvelle valeur est de <b>'||split_part(tmp_txt,';',3)||'</b>.<br><br>';
				code_retour := code_retour||'Vous gagnez un PX.<br>';
			else
				code_retour := code_retour||'Vous n''avez pas amélioré cette compétence. ';
			end if;
		end if;
        -- on enlève les pa
	update perso set perso_pa = perso_pa - getparm_n(60) where perso_cod = personnage;
		return code_retour;
        else
	code_retour := code_retour||' vous avez donc <b>réussi</b>.<br>';
	tmp_txt := ameliore_competence_px(personnage,71,v_competence_init);
	code_retour := code_retour||'Votre jet d''amélioration est de '||split_part(tmp_txt,';',1)||'. ';
	   if split_part(tmp_txt,';',2) = '1' then
		code_retour := code_retour||'Vous avez donc <b>amélioré</b> cette compétence. Sa nouvelle valeur est de <b>'||split_part(tmp_txt,';',3)||'</b>.<br><br>';
		code_retour := code_retour||'Vous gagnez un PX.<br>';
	   else
		code_retour := code_retour||'Vous n''avez pas amélioré cette compétence.<br><br>';
	   end if;
-- on efface les locks
	delete from lock_combat
		where lock_attaquant = cible
		and lock_cible = personnage;
	delete from lock_combat
		where lock_attaquant = personnage
		and lock_cible = cible;
-- on enlève les pa
	update perso set perso_pa = perso_pa - getparm_n(60) where perso_cod = personnage;
-- on met les évènements
	texte := '[attaquant] a rompu le combat avec [cible].';
		values (nextval('seq_levt_cod'),34,'now()',1,personnage,texte,'O','O',personnage,cible);
		values (nextval('seq_levt_cod'),34,'now()',1,cible,texte,'N','O',personnage,cible);
-- on met un code retour
	code_retour := code_retour||'Vous avez rompu tous les blocages de combat avec <b>'||nom_cible||'</b>.<br>';
--
        end if;
     end if;
return code_retour;
end;$_$;


ALTER FUNCTION public.desengagement(integer, integer) OWNER TO delain;

--
-- Name: detail_carte_monstre(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.detail_carte_monstre(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vue_perso :Procédure de détermination de la zone     */
/*                        de vue du personnage                   */
/* On passe en paramètres                                        */
/*    $1 = etage                                                 */
/* En sortie, on a la chaine exploitable par JS                  */
/*		ordre de sortie :                                          */
/*		1 - position                                               */
/*    2 - X                                                      */
/*    3 - Y                                                      */
/*    4 - Nb persos                                              */
/*    5 - Nb monstres                                            */
/*    6 - Type affichage                                         */
/*    7 - Objets                                                 */
/*    8 - Or                                                     */
/*    9 - Distance                                               */
/*   10 - Type mur                                               */
/*   11 - Type case                                              */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications : 19/01/2004 : adaptation pour JS     */
/*****************************************************************/
declare
	ligne record;
	v_etage alias for $1;
	v_ligne alias for $2;
	v_debut alias for $3;
	texte_retour text;
	nb_monstre integer;
	cpt integer;
	position_actuelle integer;
	x_actuel integer;
	y_actuel integer;
	etage_actuel integer;
	d_vue integer;
	nb_objet integer;
	nb_or integer;
	nb_joueur integer;
	v_dauto_valeur integer;
	v_dauto_type_bat integer;
	v_dauto_vue integer;
	v_decor integer;
	detail_monstre text;
	ligne_detail record;

begin
	texte_retour := '';
	cpt := v_debut;
	for ligne in SELECT 	pos_cod,
			pos_x,
			pos_y,
			pos_etage,
			pos_type_aff,
			pos_decor,
			pos_decor_dessus
	FROM 	positions
	where pos_etage = v_etage
	and pos_y = v_ligne
	ORDER BY pos_y desc,pos_x asc loop
		detail_monstre := ' ';
		select into v_dauto_valeur,v_dauto_type_bat,v_dauto_vue
			dauto_valeur,dauto_type_bat,dauto_vue
			from donnees_automap
			where dauto_pos_cod = ligne.pos_cod;

		select into nb_objet count(distinct(pobj_cod)) from objet_position
				where pobj_pos_cod = ligne.pos_cod;
		select into nb_or count(distinct(por_cod)) from or_position
				where por_pos_cod = ligne.pos_cod;
		select into nb_joueur COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 1
				and perso_actif = 'O';
		select into nb_monstre COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 2
				and perso_actif != 'N';
		if nb_monstre != 0 then
			for ligne_detail in select gmon_nom,count(distinct(perso_cod)) as nb
				from perso_position,perso,monstre_generique
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 2
				and perso_actif != 'N'
				and perso_gmon_cod = gmon_cod
				group by gmon_nom loop
			detail_monstre := detail_monstre||trim(to_char(ligne_detail.nb,'9999999'))||'&nbsp;'||ligne_detail.gmon_nom||'<br>';
		end loop;

		end if;
		texte_retour := texte_retour||'carte['''||trim(to_char(cpt,'999999'))||''']=';
		texte_retour := texte_retour||'['||trim(to_char(ligne.pos_cod,'999999'))||','; -- position
		texte_retour := texte_retour||trim(to_char(ligne.pos_x,'999999'))||','; -- X
		texte_retour := texte_retour||trim(to_char(ligne.pos_y,'999999'))||','; -- Y
		texte_retour := texte_retour||trim(to_char(nb_joueur,'999999'))||',';  -- nb persos
		texte_retour := texte_retour||trim(to_char(nb_monstre,'9999999'))||',';  -- nb monstre
		texte_retour := texte_retour||trim(to_char(v_dauto_valeur,'999999'))||','; -- type affichage
		texte_retour := texte_retour||trim(to_char(nb_objet,'999999'))||','; -- objets
		texte_retour := texte_retour||trim(to_char(nb_or,'999999'))||','; -- or
		texte_retour := texte_retour||'1'||','; -- distance
		texte_retour := texte_retour||trim(to_char(v_dauto_vue,'999999'))||','; -- type mur
		texte_retour := texte_retour||trim(to_char(ligne.pos_type_aff,'999999'))||','; -- type case
		texte_retour := texte_retour||trim(to_char(v_dauto_type_bat,'999999'))||','; -- type case
		v_decor := 0;
		if ligne.pos_decor is not null then
			v_decor = ligne.pos_decor;
		end if;
		texte_retour := texte_retour||trim(to_char(v_decor,'999999'))||','; -- decor
		texte_retour := texte_retour||trim(to_char(ligne.pos_decor_dessus,'999999'))||','; -- decor dessus
		texte_retour := texte_retour||''''||replace(detail_monstre,chr(39),' ')||'''];';
		texte_retour := texte_retour||E'\r\n';
		cpt := cpt + 1;

	end loop;
	texte_retour := texte_retour||'#'||trim(to_char(cpt,'9999999999999'));



return texte_retour;
end;


$_$;


ALTER FUNCTION public.detail_carte_monstre(integer, integer, integer) OWNER TO delain;

--
-- Name: detail_redispatch(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.detail_redispatch(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/********************************************************/
/* fonction f_pass_niveau : effectue toutes les actions */
/*   liées au passage de niveau et retourne une chaine  */
/*   exploitable en html                                */
/* on passe en paramètres :                             */
/*   $1 = le perso_cod du passage                       */
/*   $2 = le type d'amélioration choisie                */
/*        1 = temps                                     */
/*        2 = dégats distance                           */
/*        3 = régénération                              */
/*        4 = dégats corps à corps                      */
/*        5 = armure                                    */
/*        6 = vue                                       */
/*        7 = réparation                                */
/*        8 = sorts mémorisables                        */
/*        9 = vampirisme                                */
/*       10 = af lvl 2                                  */
/*       11 = af lvl 3                                  */
/*       12 = feinte                                    */
/*       13 = feinte lvl 2                              */
/*       14 = feinte lvl 3                              */
/*       15 = Coup de grace                             */
/*       16 = Coup de grace lvl 2                       */
/*       17 = Coup de grace lvl 3                       */
/*       18 = af                                        */
/*       19 = réceptacle magique                        */
/*       20 = amel memo                                 */
/*       21 -> 23 : bour portant                        */
/*       24 -> 26 : tir précis                          */
/*       27 force                                       */
/*       28 dex                                         */
/*       29 con                                         */
/*       30 int                                         */
/********************************************************/
declare
	code_retour text;					-- chaine de retour
	personnage alias for $1;		-- perso_cod
	amel alias for $2;				-- type amélioration
	v_pa integer;						-- nombre de PA du perso
	v_niveau_actu integer;			-- niveau actuel du perso
	v_limite_niveau integer;		-- PX nécessaires pour monter de niveau
	v_px numeric;						-- PX du perso
	v_nom_perso text;					-- nom du perso
	pv_max_actuel integer;			-- PV max du perso
	v_constitution integer;			-- constit du perso
	gain_pv integer;					-- gain en PV du perso
	temp integer;						-- temp
	fait integer;						-- amélioration faite ou non ?
	v_temps_actuel integer;			-- temps de tour du perso en minutes
	amel_temps integer;				-- amélioration de temps en minutes
	texte_evt text;					-- texte pour évènements
	v_repar integer;					-- capacité de réparation
	v_modif_repar integer;			-- ce qu'on monte en répar
	v_lvl_vamp integer;
	v_nb_amel_comp integer;
	compt integer;
	v_force integer;
	v_nb_redist integer;
	v_nb_sort integer;
	v_race integer;
begin
-- etape 1 : on vérifie
	select into 	v_pa,
						v_niveau_actu,
						v_limite_niveau,
						v_px,
						v_nom_perso,
						pv_max_actuel,
						v_constitution,
						v_repar,
						v_nb_amel_comp,v_race
			perso_pa,
			perso_niveau,
			limite_niveau(perso_cod),
			perso_px,
			perso_nom,
			perso_pv_max,
			perso_con,
			perso_capa_repar,
			perso_nb_amel_comp,
			perso_race_cod
		from perso
		where perso_cod = personnage
		and perso_actif = 'O';
	if not found then
		code_retour := '<p>Erreur ! Perso non trouvé !';
		return code_retour;
	end if;
	/*if v_px < v_limite_niveau then
		code_retour := '<p>Erreur ! Pas assez de PX pour monter de niveau !';
		return code_retour;
	end if;
	if v_pa < getparm_n(8) then
		code_retour := '<p>Erreur ! Pas assez de PA pour monter de niveau !';
		return code_retour;
	end if;*/
	select into v_nb_redist perso_nb_redist from perso
		where perso_cod = personnage;
	if v_nb_redist <= 0 then
		code_retour := '<p>Erreur ! Action non autorisée !';
		return code_retour;
	end if;
--------------------------------------------------
-- tout semble correct, on passe aux améliorations
--------------------------------------------------
-- génériques
	/*temp := round(floor(v_constitution/4));
	gain_pv := lancer_des(1,temp);
	gain_pv := gain_pv + 1;
	update perso
		set perso_pa = perso_pa - getparm_n(8), perso_niveau = perso_niveau + 1, perso_pv_max = pv_max_actuel + gain_pv
		where perso_cod = personnage;
	v_niveau_actu := v_niveau_actu + 1;*/
	code_retour := '<p>Vous êtes maintenant niveau <b>'||trim(to_char(v_niveau_actu,'999999'))||'</b>.<br>';
	--code_retour := code_retour||'Vous gagnez <b>'||trim(to_char(gain_pv,'999999'))||'</b> points de vie.<br>';
	/*texte_evt := '[perso_cod1] s''est entrainé, est passé au niveau '||trim(to_char(v_niveau_actu,'999'));
	texte_evt := texte_evt||' et a gagné '||trim(to_char(gain_pv,'999'))||' points de vie.';
			values(nextval('seq_levt_cod'),11,now(),1,personnage,texte_evt,'O','N');*/

-- spécifiques
-- temps
	if amel = 1 then
		select into v_temps_actuel
			perso_temps_tour from perso
			where perso_cod = personnage;
		amel_temps := 30;
		if v_temps_actuel > 660 then
			amel_temps := 30;
		end if;
		if ((v_temps_actuel >585) and (v_temps_actuel <= 660)) then
			amel_temps := 25;
		end if;
		if ((v_temps_actuel >525) and (v_temps_actuel <= 585)) then
			amel_temps := 20;
		end if;
		if ((v_temps_actuel >480) and (v_temps_actuel <= 525)) then
			amel_temps := 15;
		end if;
		if ((v_temps_actuel >450) and (v_temps_actuel <= 480)) then
			amel_temps := 10;
		end if;
		if v_temps_actuel <= 450 then
			amel_temps := 5;
		end if;
		update perso set perso_temps_tour = perso_temps_tour - amel_temps where perso_cod = personnage;
	end if;
-- dégats à distance
	if amel = 2 then
		update perso set perso_amel_deg_dex = perso_amel_deg_dex + 1 where perso_cod = personnage;
	end if;
-- régénération
	if amel = 3 then
		update perso set perso_des_regen = perso_des_regen + 1 where perso_cod = personnage;
	end if;
-- dégats corps à corps
	if amel = 4 then
		update perso set perso_amelioration_degats = perso_amelioration_degats + 1 where perso_cod = personnage;
	end if;
-- armure
