COMMENT ON FUNCTION public.dieu_avancement(integer, integer) IS 'Donne un pourcentage d’avancement dans la religion.';


--
-- Name: dissipation(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.dissipation(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*******************************************************/
/* fonction dissipation : dissipe une illusion         */
/*   on passe en paramètres :                          */
/*   $1 = perso_cod à dissiper                         */
/*******************************************************/
declare
	code_retour integer;
	personnage alias for $1;
	texte_evt text;
	v_nom_perso text;
begin
	select into v_nom_perso perso_nom from perso
		where perso_cod = personnage;
	-- d'abord on met en inactif
	update perso set perso_actif = 'N' where perso_cod = personnage;
	-- on enlève les locks
	delete from lock_combat
		where lock_cible = personnage;
	delete from lock_combat
		where lock_attaquant = personnage;
	-- on enlève des actions
	delete from action
		where act_perso1 = personnage;
	delete from action
		where act_perso2 = personnage;
	-- on enlève la relation familier/perso
	delete from perso_familier
		where pfam_familier_cod = personnage;
	-- on met un évènement
  texte_evt := v_nom_perso||' s''est dissipé !';
   return 0;
end;$_$;


ALTER FUNCTION public.dissipation(integer) OWNER TO delain;

--
-- Name: dissipation_magique(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.dissipation_magique() RETURNS text
    LANGUAGE plpgsql
    AS $$/***********************************************************************/
/* dissipation magique                                                 */
/***********************************************************************/
declare
	code_retour text;
	ligne record;
	v_magie integer;
	temp integer;
begin
	for ligne in select * from positions where pos_magie > 0 loop
		v_magie := ligne.pos_magie;
		if v_magie >= 100 then
			temp := 0;
		else
			update positions
				set pos_magie = pos_magie - 1
				where pos_cod = ligne.pos_cod;
		end if;
	code_retour := 'OK';

	end loop;
return code_retour;
end;$$;


ALTER FUNCTION public.dissipation_magique() OWNER TO delain;



--
-- Name: dlt_passee(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.dlt_passee(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function dlt_passee : dit si la dlt d un jeour est passe      */
/*                                                               */
/* On passe en paramètres                                        */
/*    $1 = perso à effacer                                       */
/* Le code sortie est :                                          */
/*    0 = dlt non passe                                          */
/*    1 = dlt passee                                             */
/*****************************************************************/
/* Créé le 26/05/2003                                            */
/*****************************************************************/
declare
	code_retour integer;
	personnage alias for $1;
	dlt perso.perso_dlt%type;

begin
	code_retour := 0; /* par défaut, tout s est bien passé */
	select into dlt perso_dlt from perso where perso_cod = personnage;
	if dlt < now() then
		code_retour := 1;
	end if;
	return code_retour;
end;
$_$;


ALTER FUNCTION public.dlt_passee(integer) OWNER TO delain;

