/* fonction don_br                 */
/*  $1 = perso_cod donnant         */
/*  $2 = perso_cod receveur        */
/*  $3 = qte                       */
/***********************************/
declare
	code_retour text;
	donneur alias for $1;
	receveur alias for $2;
	quantite alias for $3;
	pos_donneur integer;
	pos_receveur integer;
	or_donneur integer;
	nom_receveur text;
begin
	if quantite < 0 then
		code_retour := 'Erreur ! Quantité négative !';
		return code_retour;
	end if;
	select into or_donneur,pos_donneur
		perso_po,ppos_pos_cod
		from perso,perso_position
		where perso_cod = donneur
		and ppos_perso_cod = perso_cod;
	if not found then
		code_retour := 'Erreur ! Position non trouvée !';
		return code_retour;
	end if;
	select into nom_receveur perso_nom from perso where perso_cod = receveur;
	if not found then
		code_retour := 'Erreur ! Receveur non trouvé !';
		return code_retour;
	end if;

	-- Interdit de commercer pendant un défi
	if exists(select 1 from defi where defi_statut = 1 and donneur in (defi_lanceur_cod, defi_cible_cod)) then
		code_retour := '<p>Erreur ! Il est interdit de commercer pendant un défi !</p>';
		return code_retour;
	end if;

	if or_donneur < quantite then
		code_retour := 'Erreur ! Pas assez de brouzoufs pour faire ce don !';
		return code_retour;
	end if;
	if ((select ppos_pos_cod from perso_position where ppos_perso_cod = receveur) != pos_donneur) then
		code_retour := 'Erreur ! le donneur et le receveur ne sont pas sur la même position !';
		return code_retour;
	end if;
	update perso set perso_po = perso_po - quantite where perso_cod = donneur;
	update perso set perso_po = perso_po + quantite where perso_cod = receveur;
	code_retour := '[attaquant] a donné '||trim(to_char(quantite,'999999999999999999'))||' brouzoufs à [cible].';
		values(40,now(),donneur,code_retour,'O','O',donneur,receveur);
		values(40,now(),receveur,code_retour,'N','O',donneur,receveur);
	code_retour := 'Vous venez de donner '||trim(to_char(quantite,'999999999999999999'))||' brouzoufs à '||nom_receveur||'.<br>';
	return code_retour;
end;
	$_$;


ALTER FUNCTION public.don_br(integer, integer, integer) OWNER TO delain;

--
-- Name: donne_bonbon(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.donne_bonbon(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*******************************************************/
/* fonction donne_bonbon                               */
/*  pour animation halloween 2006                      */
/* permet de donner des bonbons à des monstres         */
/* spécifiques                                         */
/* Paramètres :                                        */
/*  $1 = perso_cod donnant                             */
/*  $2 = perso_cod recevant (monstre)                  */
/* Sortie :                                            */
/*  texte complet                                      */
/*******************************************************/
/* Créé le 28/10/2006 par Merrick                      */
/*******************************************************/
/* Pour la petite anecdote, cette fonction est la première fonction
entièrement codée sous Linux (Fedora Core 6), sous gedit.
Je quitte doucement le monde Windows, je deviens un vrai geek :( */
declare
	code_retour text;
	personnage alias for $1;
	receveur alias for $2;
	--
	temp integer; 			-- fourre tout
	ligne record;			-- variable de type record pour la suppression des bonbons
	v_pos_personnage integer;	-- position donneur
	v_pos_receveur integer;		-- position receveur
	v_gmon_cod integer;			-- type du monstre
	v_sexe text;					-- sexe du donneur
	v_lancer_des integer;		-- lancer de dés pour surprise aléatoire
	v_br integer;
	texte_evt text;
begin
	--
	-- on commence bien sur par des controles ;)
	--
	-- existence des protagonistes
	select into temp
		perso_cod from perso
		where perso_cod = personnage
		and perso_actif = 'O' ;
	if not found then
		return 'Personnage donneur non trouvé ou non actif !';
	end if;
	select into v_sexe
		perso_sex from perso
		where perso_cod = personnage;
	select into temp
		perso_cod from perso
		where perso_cod = receveur
		and perso_actif = 'O' ;
	if not found then
		return 'Personnage receveur non trouvé ou non actif !';
	end if;
	-- positions correspondantes ?
	select into v_pos_personnage
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	select into v_pos_receveur
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = receveur;
	if v_pos_personnage != v_pos_receveur then
		return 'Vous ne pouvez pas donner de bonbons à un monstre qui n''est pas sur la même case que vous !';
	end if;
	-- Nombre de PA pour donner des bonbons ?
	select into temp
		perso_pa from perso
		where perso_cod = personnage;
	if temp < getparm_n(102) then
		return 'Vous n''avez pas assez de Pa pour donner des bonbons... ';
	end if;
	-- a-t-on assez de bonbons ?
	select into temp
		count(obj_cod)
		from perso_objets,objets
		where perobj_perso_cod = personnage
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = 448;
	if temp < getparm_n(103) then
		return 'Vous n''avez pas assez de bonbons à donner....';
	end if;
	-- le receveur est il bien un monstre capable de recevoir les bonbons ?
	select into v_gmon_cod
		perso_gmon_cod
		from perso
		where perso_cod = receveur;
	if v_gmon_cod not in (30,331) then
		return 'Vous ne pouvez pas donner de bonbons à autre chose de Jack''O ou des sorcières !';
	end if;
/***************************************************/
/* Fin des controles, on passe à la réalisation    */
/***************************************************/
	-- on enlève les pa
	update perso
		set perso_pa = perso_pa - getparm_n(102)
		where perso_cod = personnage;
	-- on enlève les bonbons
	-- par facilité, on considère que le receveur les mange, ça évite une multiplication
	for ligne in select obj_cod
		from perso_objets,objets
		where perobj_perso_cod = personnage
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = 448
		limit getparm_n(103) loop
		temp := f_del_objet(ligne.obj_cod);
	end loop;
	--
	-- a partir d'ici, on a tout fait, reste à voir le résultat de l'action
	-- on commence à regarder le titre
	select into temp
		ptitre_cod
		from perso_titre
		where ptitre_perso_cod = personnage
		and ptitre_titre ilike '%pue le poisson pourri%';
	if found then
		--
		-- on a un titre poisson pourri, on le supprime...
		--
		delete from perso_titre
			where ptitre_perso_cod = personnage
			and ptitre_titre ilike '%pue le poisson pourri%';
		--
		-- on génère un petit message...
		--
		if v_gmon_cod = 331 then
			-- sorciere
			if v_sexe = 'M' then
			-- un homme....
				code_retour := 'La sorcière accepte vos bonbons. Elle les prend, les ouvre, et les mange....<br>
					Soudain, elle se jette sur vous, attrape votre visage dans ses mains et vous embrasse.<br>
					Trop surpris pour réagir, vous remarquez au moment où ses lèvres quittent les votre que l''odeur qui vous suivait depuis tellement longtemps a maintenant disparu....';
			else
			-- une femme ....
				code_retour := 'La sorcière accepte vos bonbons. Elle les prend, les ouvre, et les mange....<br>
					Elle vous regarde, murmure quelque mots et agite les doigts en votre direction.<br>
					Vous remarquez à ce moment que l''odeur qui vous suivait depuis tellement longtemps a maintenant disparu....';
			end if;
		else
			-- Jack'o
			code_retour := 'Vous tendez les bonbons au monstre, qui tourne la tête vers vous. Vous apercez une lueur au fond des orbites creusées dans la citrouille.<br>
			Il semble se passer quelque chose, un vent se lève et tourbillonne autour de vous.<br>
			Vous remarquez à ce moment que l''odeur qui vous suivait depuis tellement longtemps a maintenant disparu....';
		end if;
	else
	--
	-- il n'y avait pas de titre de poisson pourri, on va générer autre chose
	--
		v_lancer_des := lancer_des(1,100);
		if v_lancer_des <= 35 then
			-- don de quelques brouzoufs
			v_br := lancer_des(1,10);
			update perso
				set perso_po = perso_po + v_br
				where perso_cod = personnage;
			if v_gmon_cod = 331 then
				code_retour := 'La sorcière ';
			else
				code_retour := 'Le monstre ';
			end if;
			code_retour := code_retour||'vous donne '||trim(to_char(v_br,'999'))||' brouzoufs en échange de vos bonbons;';
		elsif v_lancer_des <= 55 then
			-- don de quelques brouzoufs
			v_br := lancer_des(1,50) + 10;
			update perso
				set perso_po = perso_po + v_br
				where perso_cod = personnage;
			if v_gmon_cod = 331 then
				code_retour := 'La sorcière ';
			else
				code_retour := 'Le monstre ';
			end if;
			code_retour := code_retour||'vous donne '||trim(to_char(v_br,'999'))||' brouzoufs en échange de vos bonbons;';
		elsif v_lancer_des <= 65 then
			-- chapeau inutile :)
			code_retour := cree_objet_perso_nombre(70,personnage,1);
			if v_gmon_cod = 331 then
				code_retour := 'La sorcière ';
			else
				code_retour := 'Le monstre ';
			end if;
			code_retour := 'vous donne un joli chapeau pointu en échange de vos bonbons.';
			if v_gmon_cod = 331 then
				code_retour := code_retour||' La sorcière vous fait un sourire énigmatique...';
			else
				code_retour := code_retour||' Vous croyez déceler sur la face de citrouille un sourire moqueur.';
			end if;
		elsif v_lancer_des <= 75 then
			-- LE BAISER !! LE BAISER !! LE BAISER !!
			if v_gmon_cod = 331 then
					code_retour := 'La sorcière s''avance vers vous, accepte vos bonbons. Elle vous regarde et dépose doucement un baiser sur votre joue.';
			else
				code_retour := 'Le jack''O s''avance vers vous et prend vos bonbons. Avant que nous puissiez réagir, il ouvre ses bras, se jette sur vous et ...
				Vous vous demandiez depuis toujours quel effet pouvait faire l''accolade d''un monstre, vous avez maintenant la réponse....';
			end if;
		elsif v_lancer_des <= 80 then
			-- oeuf de baba
			code_retour := cree_objet_perso_nombre(269,personnage,1);
			code_retour := 'Vos bonbons sont pris à peine vous les tendez. ';
			if v_gmon_cod = 331 then
				code_retour := code_retour||'La sorcière ';
			else
				code_retour := code_retour||'Le monstre ';
			end if;
			code_retour := code_retour||' regarde autour, vérifie que personne ne regarde, et met rapidement dans votre inventaire un objet';
		elsif v_lancer_des <= 85 then
			-- parchemin
			temp := 362 + lancer_des(1,6);
			code_retour := cree_objet_perso_nombre(temp,personnage,1);
			code_retour := 'Vos bonbons sont pris à peine vous les tendez. ';
			if v_gmon_cod = 331 then
				code_retour := code_retour||'La sorcière ';
			else
				code_retour := code_retour||'Le monstre ';
			end if;
			code_retour := code_retour||' regarde autour, vérifie que personne ne regarde, et met rapidement dans votre inventaire un objet';
		elsif v_lancer_des <=90 then
			-- bipbip
			select into temp perso_pa
				from perso
				where perso_cod = receveur;
			if temp < 4 then
				update perso
					set perso_pa= perso_pa + 4
					where perso_cod = receveur;
				code_retour := nv_magie_bipbip(receveur,personnage,1);
			else
				code_retour := nv_magie_bipbip(receveur,personnage,1);
				update perso
					set perso_pa= perso_pa + 4
					where perso_cod = receveur;
			end if;
			code_retour := 'Vos bonbons disparaissent immédiatement, et comme par magie, vous vous sentez soudain plus rapide !';
		elsif v_lancer_des <= 95 then
			-- defense
			select into temp perso_pa
				from perso
				where perso_cod = receveur;
			if temp < 4 then
				update perso
					set perso_pa= perso_pa + 4
					where perso_cod = receveur;
				code_retour := nv_magie_defense(receveur,personnage,1);
			else
				code_retour := nv_magie_defense(receveur,personnage,1);
				update perso
					set perso_pa= perso_pa + 4
					where perso_cod = receveur;
			end if;
			code_retour := 'Vos bonbons disparaissent immédiatement, et comme par magie, vous vous sentez soudain plus résistant !';
		else
			-- rune
			temp := 26 + lancer_des(1,5);
			code_retour := cree_objet_perso_nombre(temp,personnage,1);
			code_retour := 'Vos bonbons sont pris à peine vous les tendez. ';
			if v_gmon_cod = 331 then
				code_retour := code_retour||'La sorcière ';
			else
				code_retour := code_retour||'Le monstre ';
			end if;
			code_retour := code_retour||' regarde autour, vérifie que personne ne regarde, et met rapidement dans votre inventaire un objet';
		end if;
	-- insertion d'un évènement
	texte_evt := '[attaquant] a donné des bonbons à [cible] ';

	end if;
			values(76,now(),1,personnage,texte_evt,'O','O',personnage,receveur);
			values(76,now(),1,receveur,texte_evt,'N','O',personnage,receveur);
		return code_retour;
end;


$_$;


ALTER FUNCTION public.donne_bonbon(integer, integer) OWNER TO delain;

--
-- Name: donne_contrat(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.donne_contrat(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/***********************************************/
/* donne_contrat : permet de savoir si on donne*/
/* un contrat à la cible                       */
/*  $1 = perso_cod                             */
/*  code_retour = 'N' -> pas de contrat        */
/*  code_retour = 'O' -> contrat               */
/***********************************************/
declare
	code_retour text;
	v_perso alias for $1;
        dernier_resultat text;
        tirage_des integer;
        chance_contrat integer;
        v_pp integer;

begin
	code_retour := 'O';
        -- on regarde si le test n a pas déjà été fait pour la journée présente

        select into dernier_resultat ptctr_resultat from perso_tentative_contrat
        where ptctr_perso_cod = v_perso
        and ptctr_date = current_date;

        if found then
             return dernier_resultat;
        end if;

        -- premiere tentative de la journée

        -- calcul de la chance
        select into v_pp perso_prestige from perso
        where perso_cod = v_perso;

        chance_contrat := min((20 + v_pp), 50);
        tirage_des := lancer_des(1,100);

        if (tirage_des > chance_contrat) then
            code_retour = 'N';
        end if;


        -- on insère dans la table des tentatives

	return code_retour;
end;$_$;


ALTER FUNCTION public.donne_contrat(integer) OWNER TO delain;

--
-- Name: donne_noir(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.donne_noir(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************/
/* donne_noir                                     */
/**************************************************/
declare
	code_retour text;
	personnage alias for $1;
	v_objet integer;
	v_pa integer;
	temp integer;
	temp2 integer;
	v_pv integer;
	v_pos integer;
	texte_evt text;
begin
----------------------------------------------------
-- DEBUT CONTROLES AVANT ACTION
----------------------------------------------------
--
----------------------------------------------------
-- DEBUT vérification de la possession du cadeau
----------------------------------------------------
	select into v_objet
		obj_cod
		from objets,perso_objets
		where perobj_perso_cod = personnage
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = 327;
	if not found then
		code_retour := 'Erreur ! Vous n''avez pas de cadeau dans votre inventaire !';
		return code_retour;
	end if;
----------------------------------------------------
-- FIN   vérification de la possession du cadeau
----------------------------------------------------
--
----------------------------------------------------
-- DEBUT vérification des PA
----------------------------------------------------
	select into v_pa
		perso_pa
		from perso
		where perso_cod = personnage;
	if v_pa < getparm_n(99) then
		code_retour := 'Erreur ! Vous n''avez pas assez de PA pour cette action !';
		return code_retour;
	end if;
----------------------------------------------------
-- FIN   vérification des PA
----------------------------------------------------
--
----------------------------------------------------
-- DEBUT vérification de la présence de lutin
----------------------------------------------------
	select into v_pos
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	select into temp
		perso_cod
		from perso,perso_position
		where ppos_pos_cod = v_pos
		and ppos_perso_cod = perso_cod
		and perso_race_cod = 54;
	if not found then
		code_retour := 'Erreur ! il n''y a pas de lutin sur votre case !';
		return code_retour;
	end if;
----------------------------------------------------
-- FIN   vérification de la présence de lutin
----------------------------------------------------
--
----------------------------------------------------
-- FIN   CONTROLES AVANT ACTION
----------------------------------------------------
--
----------------------------------------------------
-- DEBUT don, fonction principale
----------------------------------------------------
--
----------------------------------------------------
-- DEBUT destruction cadeau
----------------------------------------------------
	v_pa := f_del_objet(v_objet);
----------------------------------------------------
-- FIN   destruction cadeau
----------------------------------------------------
--
	code_retour := 'Le lutin tourne la tête vers vous ce qui fait sonner le grelot de son bonnet. Il ronchonne :<br>
<br>
« - Mais quel costume de naze Vivement que tout ça finisse pour que je puisse me saper correctement »<br>
<br>
Puis il daigne faire attention à votre présence, vous prend le cadeau des mains en précisant dune voix peu amène :<br>
<br>
« - Merci pour le cadeau. Monsieur Jacques va pouvoir le transformer à sa guise » Un sourire sadique ponctue la fin de sa phrase.<br>';
	update perso
		set perso_pa = perso_pa - getparm_n(99)
		where perso_cod = personnage;
	select into temp2 cn_perso_cod
		from compt_noel
		where cn_perso_cod = personnage;
	if not found then
	else
		update compt_noel
			set cn_compteur = cn_compteur - 1
			where cn_perso_cod = personnage;
	end if;
	texte_evt := '[attaquant] a donné un cadeau à [cible].';
		values(61,now(),personnage,texte_evt,'O','O',personnage,temp);
		values(61,now(),temp,texte_evt,'N','O',personnage,temp);
	return code_retour;

----------------------------------------------------
-- FIN   don, fonction principale
----------------------------------------------------
end;$_$;


ALTER FUNCTION public.donne_noir(integer) OWNER TO delain;

--
-- Name: donne_poisson(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.donne_poisson(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/********************************************************/
/* fonction donne_poisson                               */
/*   $1 = donneur                                       */
/*   $2 = receveur                                      */
/*   $3 = num_objet                                     */
/********************************************************/
declare
    code_retour text;
    donneur alias for $1;
    receveur alias for $2;
    num_objet alias for $3;
    nom_cible text;
    nb_poiss integer;
    v_type_receveur integer;
    v_race_receveur integer;
    v_pa integer;
    v_compte_donneur integer;
    v_compte_receveur integer;
    v_code_message integer;
    v_temp integer;
    texte_evt text;
    ligne record;
    des integer;                    -- lancer de dés
    temp_var text;
    v_niveau integer;
begin
code_retour := '';
/*********************************************************/
/* C O N T R O L E S                                     */
/*********************************************************/
-- type de perso
    select into v_type_receveur,v_race_receveur,nom_cible perso_type_perso,perso_race_cod,perso_nom
        from perso
        where perso_cod = receveur;
    if not found then
        code_retour := 'Erreur ! Receveur non trouvé !';
        return code_retour;
    end if;
    if v_type_receveur != 1 and v_race_receveur != 45 then
        code_retour := 'Erreur ! Vous ne pouvez pas donner les poissons aux monstres ou aux familiers !';
        return code_retour;
    end if;
-- PA
    select into v_pa,v_niveau perso_pa,perso_niveau from perso where perso_cod = donneur;
    if not found then
        code_retour := 'Erreur ! Donneur non trouvé !';
        return code_retour;
    end if;
    if v_pa < 1 then
        code_retour := 'Erreur ! Vous n''avez pas assez de PA pour donner ce poisson !';
        return code_retour;
    end if;
-- comptes
    select into v_compte_donneur pcompt_compt_cod from perso_compte
        where pcompt_perso_cod = donneur;
    if not found then
        code_retour := 'Erreur ! Compte donneur non trouvé !';
        return code_retour;
    end if;
    if v_race_receveur != 45 then
        select into v_compte_receveur pcompt_compt_cod from perso_compte
            where pcompt_perso_cod = receveur;
        if not found then
            code_retour := 'Erreur ! Compte receveur non trouvé !';
            return code_retour;
        end if;
        if v_compte_donneur = v_compte_receveur then
            code_retour := 'Erreur ! Vous ne pouvez pas donner les poissons à un autre personnage de votre compte !';
            return code_retour;
        end if;
    end if;
-- objet dans l'inventaire ?
    select into v_temp perobj_obj_cod from perso_objets
            where perobj_perso_cod = donneur
            and perobj_obj_cod = num_objet;
    if not found then
        code_retour := 'Erreur ! L''objet n''est pas dans l''inventaire !';
        return code_retour;
    end if;
/*********************************************************/
/* C O N T R O L E S  O K --> S U I T E                  */
/*********************************************************/
-- enlevage de PA
    update perso
        set perso_pa = perso_pa - 1
        where perso_cod = donneur;
-- Transfert de propriété
    update perso_objets
        set perobj_perso_cod = receveur
        where perobj_obj_cod = num_objet;
-- Evènement
    texte_evt := '[attaquant] a généreusement offert un poisson à [cible]';
        values(49,now(),donneur,texte_evt,'O','O',donneur,receveur);
        values(49,now(),receveur,texte_evt,'N','O',donneur,receveur);
-- Si le reveceveur est un snorkys
    if v_race_receveur = 45 then
        des := lancer_des(1,100);
        des := des + v_niveau;
        if des < 5 then -- don de rune
        		if lancer_des(1,10) = 1 then
        			des := lancer_des(1,14) + 26;
        			v_temp := cree_objet_perso_nombre(des,donneur,1);
       			code_retour := code_retour||'Le Snorky apprécie énormément votre geste, et vous offre une rune en échange !';
        		else
        			-- Renvoi de 2 poissons
            	v_temp := f_del_objet(num_objet);
            	v_temp := cree_objet_perso_nombre(226,donneur,2);
            	-- EVENEMENT
            	texte_evt := '[attaquant] a généreusement offert deux poissons à [cible]';
                	values(49,now(),donneur,texte_evt,'O','O',receveur,donneur);
                	values(49,now(),receveur,texte_evt,'N','O',receveur,donneur);
            	code_retour := code_retour||'Deux tu l''as vaut mieux qu''un tu l''avais !';
        		end if;
        elsif des < 25 then
                -- On s'assure que le Snorky a assez de PAs
                select into v_pa perso_pa from perso where perso_cod = receveur;
                if v_pa < 4 then
                   update perso
                   set perso_pa = 4
                   where perso_cod = receveur;
                end if;
                delete from perso_nb_sorts where pnbs_perso_cod = receveur;
            temp_var := nv_magie_bipbip(receveur,donneur,1);
                code_retour := code_retour||' Celui-ci vous lance Bip-Bip, étrange ce poisson';
        elsif des < 45 then
                -- On s'assure que le Snorky a assez de PAs
                select into v_pa perso_pa from perso where perso_cod = receveur;
                if v_pa < 8 then
                   update perso
                   set perso_pa = 8
                   where perso_cod = receveur;
                end if;
             	delete from perso_nb_sorts where pnbs_perso_cod = receveur;
            	temp_var := nv_magie_morsure_soleil(receveur,donneur,1);
            	delete from perso_sorts where psort_perso_cod = receveur and psort_sort_cod = 35;
                code_retour := code_retour||'Le Snorky semble ne pas apprécier votre cadeau. Il vous lance le sort <b>morsure du soleil</b>.';
        elsif des < 55 then
                -- On s'assure que le Snorky a assez de PAs
                select into v_pa perso_pa from perso where perso_cod = receveur;
                if v_pa < 8 then
                   update perso
                   set perso_pa = 8
                   where perso_cod = receveur;
                end if;
             	delete from perso_nb_sorts where pnbs_perso_cod = receveur;
            	temp_var := nv_magie_melasse(receveur,donneur,1);
            	delete from perso_sorts where psort_perso_cod = receveur and psort_sort_cod = 12;
                code_retour := code_retour||'Le Snorky semble ne pas apprécier votre cadeau. Il vous lance le sort <b>mélasse</b>.';
        elsif des < 65 then
            v_code_message := nextval('seq_msg_cod');
                values(v_code_message,now(),'Oh OoooOooh','Poisson ?<BR /> Huh ?<BR /> Mmmmm...<BR />Gloup...<BR /> Miam, meci!<BR />',now());
                values(v_code_message,donneur);
                values(v_code_message,receveur);
        elsif des < 85 then
            -- Renvoi de 2 poissons
            v_temp := f_del_objet(num_objet);
            v_temp := cree_objet_perso_nombre(226,donneur,2);
            -- EVENEMENT
            texte_evt := '[attaquant] a généreusement offert deux poissons à [cible]';
                values(49,now(),donneur,texte_evt,'O','O',receveur,donneur);
                values(49,now(),receveur,texte_evt,'N','O',receveur,donneur);
            code_retour := code_retour||'Deux tu l''as vaut mieux qu''un tu l''avais !';
        elsif des < 110 then
            -- don de 10 Br
            update perso
            set perso_po = perso_po + 10
            where perso_cod = donneur;
            code_retour := code_retour||' Celui-ci est super content, il vous donne 10 Br: Pas grand chose. Les snorkies sont un peu radins.';
        else
            -- don de 500 Br
            update perso
            set perso_po = perso_po + 500
            where perso_cod = donneur;
            code_retour := code_retour||' Celui-ci est super content, il vous donne 500 Br: Ca doit cacher quelque chose...';
        end if;
    end if;
-- on vérifie qu'on ne puisse pas faire un gros poisson chez le receveur
    select into nb_poiss count(obj_cod)
        from objets,perso_objets
        where perobj_perso_cod = receveur
        and perobj_obj_cod = obj_cod
        and obj_gobj_cod = 226;
    if nb_poiss >= 5 then
    -- on retire 5 petits poissons
        for ligne in
            select perobj_obj_cod
                from objets,perso_objets
                where perobj_perso_cod = receveur
                and perobj_obj_cod = obj_cod
                and obj_gobj_cod = 226
                limit 5 loop
            v_temp := f_del_objet(ligne.perobj_obj_cod);
        end loop;
    -- on ajoute un gros poisson
        v_temp := cree_objet_perso_nombre(227,receveur,1);
    end if;
-- code retour
    code_retour  := '<br>'||nom_cible||' a bien reçu votre poisson.<br>'||code_retour;
    return code_retour;
end;$_$;


ALTER FUNCTION public.donne_poisson(integer, integer, integer) OWNER TO delain;

--
-- Name: donne_rouge(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.donne_rouge(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************/
/* donne_rouge                                    */
/**************************************************/
declare
	code_retour text;
	personnage alias for $1;
	v_objet integer;
	v_pa integer;
	temp integer;
temp2 integer;
	v_pv integer;
	v_pos integer;
	texte_evt text;
begin
----------------------------------------------------
-- DEBUT CONTROLES AVANT ACTION
----------------------------------------------------
--
----------------------------------------------------
-- DEBUT vérification de la possession du cadeau
----------------------------------------------------
	select into v_objet
		obj_cod
		from objets,perso_objets
		where perobj_perso_cod = personnage
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = 327;
	if not found then
		code_retour := 'Erreur ! Vous n’avez pas de cadeau dans votre inventaire !<br />';
		return code_retour;
	end if;
----------------------------------------------------
-- FIN   vérification de la possession du cadeau
----------------------------------------------------
--
----------------------------------------------------
-- DEBUT vérification des PA
----------------------------------------------------
	select into v_pa
		perso_pa
		from perso
		where perso_cod = personnage;
	if v_pa < getparm_n(99) then
		code_retour := 'Erreur ! Vous n’avez pas assez de PA pour cette action !<br />';
		return code_retour;
	end if;
----------------------------------------------------
-- FIN   vérification des PA
----------------------------------------------------
--
----------------------------------------------------
-- DEBUT vérification de la présence de lutin
----------------------------------------------------
	select into v_pos
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	select into temp
		perso_cod
		from perso,perso_position
		where ppos_pos_cod = v_pos
		and ppos_perso_cod = perso_cod
		and perso_race_cod = 53;
	if not found then
		code_retour := 'Erreur ! il n’y a pas de lutin sur votre case !<br />';
		return code_retour;
	end if;
----------------------------------------------------
-- FIN   vérification de la présence de lutin
----------------------------------------------------
--
----------------------------------------------------
-- FIN   CONTROLES AVANT ACTION
----------------------------------------------------
--
----------------------------------------------------
-- DEBUT don, fonction principale
----------------------------------------------------
--
----------------------------------------------------
-- DEBUT destruction cadeau
----------------------------------------------------
	v_pa := f_del_objet(v_objet);
----------------------------------------------------
-- FIN   destruction cadeau
----------------------------------------------------
--
	code_retour := 'Le lutin rouge agite sa tête pour faire sonner le grelot de son bonnet, attitude qui ne le rend absolument pas ridicule. Un immense sourire jaillit sur son visage poupin. Il dit dune petite voix nasillarde et enjouée :<br />
« - Je te remercie pour ton présent. Le Père Léno sera très heureux de pouvoir offrir un cadeau à un petit enfant ».<br /><br />';
	update perso
	set perso_pa = perso_pa - getparm_n(99),
		perso_po = perso_po + 200
	where perso_cod = personnage;

	select into temp2 cn_perso_cod
		from compt_noel
		where cn_perso_cod = personnage;
	if not found then
	else
		update compt_noel
			set cn_compteur = cn_compteur + 1
			where cn_perso_cod = personnage;
	end if;
	texte_evt := '[attaquant] a donné un cadeau à [cible].';
		values(61,now(),personnage,texte_evt,'O','O',personnage,temp);
		values(61,now(),temp,texte_evt,'N','O',personnage,temp);
	return code_retour;

----------------------------------------------------
-- FIN   don, fonction principale
----------------------------------------------------
end;$_$;


ALTER FUNCTION public.donne_rouge(integer) OWNER TO delain;

