CREATE FUNCTION public.donne_xp(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*******************************************/
/* fonction donne_xp                       */
/*  actions lorsqu un joueur donne des xp  */
/*  à un autre joueur                      */
/* on passe en paramètres :                */
/*  $1 = donneur                           */
/*  $2 = recevuer                          */
/*  $3 = nombre de px donnés               */
/* on a en sortie une chaine séparée par ; */
/*  0 = code sortie (0 OK, -1 BAD)         */
/*  1 = motif erreur si BAD                */
/*******************************************/
/* Créé le 22/05/2003                      */
/*******************************************/
declare
	code_retour text;
	donneur alias for $1;
	receveur alias for $2;
	nb_px alias for $3;
-- variables donneur
	px_dispo integer;
-- variables de calcul
	nb_receveur integer;
	texte_evt text;
begin
	code_retour := '0';

	return code_retour;
end;



$_$;


ALTER FUNCTION public.donne_xp(integer, integer, integer) OWNER TO delain;

--
-- Name: drop_rune(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.drop_rune(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/**************************************************/
/* fonction drop_rune : fait tomber les runes en  */
/*   cas de sort                                  */
/* on passe en params :                           */
/*   $1 = gobj_cod de la rune                     */
/*   $2 = perso_cod                               */
/**************************************************/
/* on a en retour un entier                       */
/**************************************************/
/* créé le 25/07/2003                             */
/* modifié le 05/07/2006 :                        */
/*  on remet la chance de drop et l'objet         */
/*  déposable pour les runes utilisées en sort    */
/**************************************************/
declare
	code_retour integer;
	code_rune alias for $1;
	code_perso alias for $2;
	v_perobj_cod perso_objets.perobj_cod%type;
	v_etage integer;
	num_objet integer;
	etage_ref integer;
	v_etage_retour_rune_monstre integer;
	v_des integer;
	compt_mag integer;
	v_magasin integer;
	v_monstre_porteur integer;

begin
	code_retour := 0;
	select into v_perobj_cod,num_objet perobj_cod,perobj_obj_cod
		from perso_objets,objets
		where perobj_perso_cod = code_perso
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = code_rune
		limit 1;
	--
	-- on remet la rune en l'état
	--
	update objets
		set obj_deposable = 'O',obj_chance_drop = 15
		where obj_cod = num_objet;

	delete from transaction where tran_obj_cod = v_perobj_cod; -- On retire la rune utilisée des transactions.
	delete from perso_objets where perobj_cod = v_perobj_cod;
	v_des := lancer_des(1,100);
	if v_des < getparm_n(72) then
		select into compt_mag count(*)
			from lieu
			where lieu_tlieu_cod in (14);
		v_des := lancer_des(1,compt_mag);
		v_des := v_des - 1;
		select into v_magasin
			lieu_cod
			from lieu
			where lieu_tlieu_cod in (14)
			offset v_des
			limit 1;
	else
		-- Au sol ou dans l'inventaire d'un monstre ?
		v_des := lancer_des(1,100);
		select into v_etage pos_etage
			from perso_position,positions
			where ppos_perso_cod = code_perso
			and ppos_pos_cod = pos_cod;
		select into etage_ref, v_etage_retour_rune_monstre
			etage_reference, etage_retour_rune_monstre from etage
			where etage_numero = v_etage;
		select into v_monstre_porteur perso_cod
			from perso,perso_position, positions, etage
			where ppos_pos_cod = pos_cod and ppos_perso_cod = perso_cod
			and pos_etage = etage_numero and etage_reference = etage_ref
			and perso_type_perso = 2 and perso_actif = 'O'
			order by random() limit 1;
		if found and v_des < v_etage_retour_rune_monstre then
				values (v_monstre_porteur, num_objet);
		else
				values (num_objet,pos_aleatoire_ref(etage_ref));
		end if;
	end if;
	return code_retour;
end;$_$;


ALTER FUNCTION public.drop_rune(integer, integer) OWNER TO delain;

--
-- Name: duplique_perso(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.duplique_perso(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* Clonage		                                  */
/*  $1 = perso_cloné                            */
/************************************************/
declare
	code_retour text;
	v_attaquant alias for $1;
	v_des integer;
	v_pos integer;
	v_monstre integer;
	texte_evt text;
	ligne record;
	chance_chute integer;
	v_objet_deposable text;
	v_type_objet integer;
  v_objet_identifie text;
	v_num_perso integer;
	tmp numeric;
	v_compte integer;
	temp integer;
	temp1 integer;
	temp2 integer;
	temp3 integer;
	temp4 integer;
	temp5 integer;
begin
	select into v_pos
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = v_attaquant;
		-- on créé un clone !
		v_num_perso := nextval('seq_perso');
		-- les objets
		for ligne in select * from perso_objets
			where perobj_perso_cod = v_attaquant
			and perobj_equipe = 'O' loop
			select into chance_chute,v_objet_deposable,v_type_objet tobj_chute,gobj_deposable,gobj_tobj_cod
				from type_objet,objet_generique,objets
				where ligne.perobj_obj_cod = obj_cod
				and obj_gobj_cod = gobj_cod
				and gobj_tobj_cod = tobj_cod;
			if v_objet_deposable = 'O' then
					select into v_objet_identifie perobj_identifie from perso_objets
						where perobj_cod = ligne.perobj_cod;
					if v_objet_identifie = 'O' then
							values (nextval('seq_pio_cod'),v_attaquant,ligne.perobj_obj_cod,getparm_n(22));
					end if;
					update perso_objets
						set perobj_equipe = 'N'
						where perobj_perso_cod = v_attaquant
						and perobj_obj_cod in
							(select obj_cod
								from objets,objet_generique
								where obj_gobj_cod = gobj_cod
								and gobj_tobj_cod = v_type_objet);
					update perso_objets
						set perobj_perso_cod = v_attaquant
						where perobj_cod = ligne.perobj_cod;
			end if;
		end loop;
		-- les caracs de base
												perso_for,
												perso_dex,
												perso_int,
												perso_con,
												perso_for_init,
												perso_dex_init,
												perso_int_init,
												perso_con_init,
												perso_sex,
												perso_race_cod,
												perso_pv,
												perso_pv_max,
												perso_dlt,
												perso_temps_tour,
												perso_email,
												perso_dcreat,
												perso_validation,
												perso_actif,
												perso_pa,
												perso_der_connex,
												perso_des_regen,
												perso_valeur_regen,
												perso_vue,
												perso_po,
												perso_nb_esquive,
												perso_niveau,
												perso_type_perso,
												perso_amelioration_vue,
												perso_amelioration_regen,
												perso_amelioration_degats,
												perso_amelioration_armure,
												perso_nb_des_degats,
												perso_val_des_degats,
												perso_cible,
												perso_enc_max,
												perso_description,
												perso_nb_mort,
												perso_nb_monstre_tue,
												perso_nb_joueur_tue,
												perso_reputation,
												perso_avatar,
												perso_kharma,
												perso_amel_deg_dex,
												perso_nom,
												perso_gmon_cod,
												perso_renommee,
												perso_dirige_admin,
												perso_lower_perso_nom,
												perso_sta_combat,
												perso_sta_hors_combat,
												perso_utl_pa_rest,
												perso_tangible,
												perso_nb_tour_intangible,
												perso_capa_repar,
												perso_nb_amel_repar,
												perso_amelioration_nb_sort,
												perso_renommee_magie,
												perso_vampirisme,
												perso_niveau_vampire,
												perso_admin_echoppe,
												perso_nb_amel_comp,
												perso_nb_receptacle,
												perso_nb_amel_chance_memo,
												perso_priere,
												perso_dfin,
												perso_px,
												perso_taille,
												perso_admin_echoppe_noir,
												perso_use_repart_auto,
												perso_pnj,
												perso_redispatch,
												perso_nb_redist,
												perso_mcom_cod,
												perso_nb_ch_mcom,
												perso_piq_rap_env,
												perso_ancien_avatar,
												perso_nb_crap,
												perso_nb_embr,
												perso_crapaud,
												perso_dchange_mcom,
												perso_prestige,
												perso_av_mod,
												perso_mail_inactif_envoye,
												perso_test,
												perso_nb_spe,
												perso_compt_pvp,
												perso_dmodif_compt_pvp,
												perso_effets_auto,
												perso_quete
												)
								select 	v_num_perso,
												perso_for,
												perso_dex,
												perso_int,
												perso_con,
												perso_for_init,
												perso_dex_init,
												perso_int_init,
												perso_con_init,
												perso_sex,
												perso_race_cod,
												perso_pv,
												perso_pv_max,
												perso_dlt,
												perso_temps_tour,
												perso_email,
												perso_dcreat,
												perso_validation,
												perso_actif,
												perso_pa,
												perso_der_connex,
												perso_des_regen,
												perso_valeur_regen,
												perso_vue,
												perso_po,
												perso_nb_esquive,
												perso_niveau,
												perso_type_perso,
												perso_amelioration_vue,
												perso_amelioration_regen,
												perso_amelioration_degats,
												perso_amelioration_armure,
												perso_nb_des_degats,
												perso_val_des_degats,
												perso_cible,
												perso_enc_max,
												perso_description,
												perso_nb_mort,
												perso_nb_monstre_tue,
												perso_nb_joueur_tue,
												perso_reputation,
												perso_avatar,
												perso_kharma,
												perso_amel_deg_dex,
												'Copie de '||perso_nom,
												perso_gmon_cod,
												perso_renommee,
												perso_dirige_admin,
												'copie de '||perso_lower_perso_nom,
												perso_sta_combat,
												perso_sta_hors_combat,
												perso_utl_pa_rest,
												perso_tangible,
												perso_nb_tour_intangible,
												perso_capa_repar,
												perso_nb_amel_repar,
												perso_amelioration_nb_sort,
												perso_renommee_magie,
												perso_vampirisme,
												perso_niveau_vampire,
												perso_admin_echoppe,
												perso_nb_amel_comp,
												perso_nb_receptacle,
												perso_nb_amel_chance_memo,
												perso_priere,
												perso_dfin,
												perso_px,
												perso_taille,
												perso_admin_echoppe_noir,
												perso_use_repart_auto,
												perso_pnj,
												perso_redispatch,
												perso_nb_redist,
												perso_mcom_cod,
												perso_nb_ch_mcom,
												perso_piq_rap_env,
												perso_ancien_avatar,
												perso_nb_crap,
												perso_nb_embr,
												perso_crapaud,
												perso_dchange_mcom,
												perso_prestige,
												perso_av_mod,
												perso_mail_inactif_envoye,
												perso_test,
												perso_nb_spe,
												perso_compt_pvp,
												perso_dmodif_compt_pvp,
												perso_effets_auto,
												perso_quete
  			from perso where perso_cod = v_attaquant;
		-- competences
			select
			v_num_perso,pcomp_pcomp_cod,pcomp_modificateur
			from perso_competences
			where pcomp_perso_cod = v_attaquant;
		-- sorts
			select
			v_num_perso,psort_sort_cod
			from perso_sorts
			where psort_perso_cod = v_attaquant;
			-- compte
			select into v_compte pcompt_compt_cod from perso_compte where pcompt_perso_cod = v_attaquant;
			values (v_compte,v_num_perso);
			--temple
			/*Mise en commentaire, ça ne marche pas pour une obscure raison
			select into temp,temp1,temp2,temp3,temp4,temp5
				ptemple_perso_cod,ptemple_cod,ptemple_pos_cod,ptemple_nombre,ptemple_anc_pos_cod,ptemple_anc_nombre
				from perso_temple
				where ptemple_perso_cod = v_attaquant;
			if found then
					values (v_num_perso,temp1,temp2,temp3,temp4,temp5);
			end if;*/
		code_retour := trim(to_char(v_num_perso,'999999999'));

	return code_retour;

end;$_$;


