--
-- Name: effectue_degats_test(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.effectue_degats_test() RETURNS text
    LANGUAGE plpgsql
    AS $$declare
  code_retour text;
  v_pv integer;
  v_pv_max numeric;
  v_ratio numeric;
  v_marge_pv integer;

begin
  code_retour := '';
  for v_pv_max in 1 .. 150 loop
    for v_pv in 1 .. v_pv_max loop
      v_ratio := (v_pv - 1) / cast(v_pv_max as numeric);
      v_marge_pv := 1 + floor(v_pv_max * (v_ratio - floor(3*v_ratio) / cast(3 as numeric)
			- 0.20 * cast(v_ratio < 0.33 and v_ratio > 0.20 as integer)
			- 0.13 * cast(v_ratio > 0.80 as integer)));
      code_retour := code_retour || v_pv::text || '/' || v_pv_max::text || '=>' || v_marge_pv::text;
    end loop;
  end loop;
  return code_retour;
end;$$;


ALTER FUNCTION public.effectue_degats_test() OWNER TO delain;

--
-- Name: effet_auto_ajout_titre(integer, text, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.effet_auto_ajout_titre(integer, text, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*************************************************************/
/* fonction effet_auto_ajout_titre                           */
/*   Ajoute automatiquement un titre au personnage donné     */
/*   on passe en paramètres :                                */
/*   $1 = perso_cod : le perso_cod à qui ajouter le titre    */
/*   $2 = texte     : le texte du titre à ajouter            */
/*   $3 = source    : le code du monstre dont émane le titre */
/* on a en sortie un texte résumé                            */
/*************************************************************/
/* Créé le 17/06/2014                                        */
/*************************************************************/
declare
	v_perso_cod alias for $1;  -- Le code de la source
	v_texte alias for $2;      -- Le texte du titre
	v_source alias for $3;     -- Le code du monstre ayant généré le titre

	code_retour text;          -- Le retour de la fonction
	nom_monstre text;          -- Le nom du monstre qui déclenche le titre

begin
	code_retour := '';
	select into nom_monstre perso_nom from perso where perso_cod = v_source;

	values (
		v_perso_cod,
		replace (v_texte, '[monstre]', nom_monstre),
		now()
	);

	return 'Nouveau titre ! ' || replace (v_texte, '[monstre]', nom_monstre);
end;$_$;


