--
-- Name: f_del_objet_generique(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.f_del_objet_generique(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/**************************************************/
/* fonction f_del_objet_generique : détruit un    */
/*   objet générique d'un perso sans numéro       */
/* particulier																		*/
/* on passe en params :                           */
/*   $1 = gobj_cod de l'objet                     */
/*   $2 = perso_cod                               */
/**************************************************/
/* on a en retour un entier                       */
/**************************************************/
/* créé le 07/12/2009                             */
/* modifié le 05/07/2006 :                        */

/**************************************************/
declare
	code_retour integer;
	code_objet alias for $1;
	code_perso alias for $2;
	v_perobj_cod perso_objets.perobj_cod%type;
	num_objet integer;


begin
	code_retour := 0;
	select into v_perobj_cod,num_objet perobj_cod,perobj_obj_cod
		from perso_objets,objets
		where perobj_perso_cod = code_perso
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = code_objet
		limit 1;
	delete from transaction where tran_obj_cod = v_perobj_cod; -- On retire l'objet utilisée des transactions.
	delete from perso_objets where perobj_cod = v_perobj_cod;
	delete from perso_identifie_objet where pio_obj_cod = v_perobj_cod;
	delete from objet_position where pobj_obj_cod = v_perobj_cod;
	delete from objets where obj_cod = v_perobj_cod;
	return code_retour;
end;$_$;


ALTER FUNCTION public.f_del_objet_generique(integer, integer) OWNER TO delain;

--
-- Name: f_deplace_aleatoire(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.f_deplace_aleatoire(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/***********************************************************/
/* procédure deplace_aleatoire : deplace un monstre sur    */
/*   une case à coté de lui                                */
/* on passe en params :                                    */
/*   $1 = perso_cod du monstre                             */
/*   $2 = pos_actuelle du monstre                          */
/***********************************************************/
declare
	code_retour integer;
	v_monstre alias for $1;
	pos_monstre alias for $2;
	compt_pos integer;
	v_etage integer;
	nouvelle_pos integer;
	deplace text;
	sens integer;
	v_x integer;
	v_y integer;
	x_min integer;
	x_max integer;
	y_min integer;
	y_max integer;

begin
	select into v_etage,v_x,v_y pos_etage,pos_x,pos_y from positions
		where pos_cod = pos_monstre;
	x_min = v_x - 1;
	x_max = v_x + 1;
	y_min = v_y - 1;
	y_max = v_y + 1;

	select into nouvelle_pos pos_cod
		from positions
		where pos_etage = v_etage
		and pos_x between x_min and x_max
		and pos_y between y_min and y_max
		and not exists (select 1 from murs where mur_pos_cod = pos_cod)
		and not exists (select 1 from lieu,lieu_position where lpos_pos_cod = pos_cod and lpos_lieu_cod = lieu_cod and lieu_refuge = 'O')
		order by random()
		limit 1;

/*	select into compt_pos count(pos_cod)
		from positions
		where pos_etage = v_etage
		and pos_x between x_min and x_max
		and pos_y between y_min and y_max
		and not exists (select 1 from murs where mur_pos_cod = pos_cod)
		and not exists (select 1 from lieu,lieu_position where lpos_pos_cod = pos_cod and lpos_lieu_cod = lieu_cod and lieu_refuge = 'O');

	if compt_pos = 0 then
		code_retour := 0;

	end if;
	compt_pos := lancer_des(1,compt_pos);
	compt_pos := compt_pos - 1;
	sens := lancer_des(1,10);
	if sens <=5 then
		select into nouvelle_pos pos_cod
			from positions
			where pos_etage = v_etage
			and pos_x between x_min and x_max
		and pos_y between y_min and y_max
			and not exists (select 1 from murs where mur_pos_cod = pos_cod)
			and not exists (select 1 from lieu,lieu_position where lpos_pos_cod = pos_cod and lpos_lieu_cod = lieu_cod and lieu_refuge = 'O')
			order by pos_cod asc
			offset compt_pos
			limit 1;
	else
		select into nouvelle_pos pos_cod
			from positions
			where pos_etage = v_etage
			and pos_x between x_min and x_max
		and pos_y between y_min and y_max
			and not exists (select 1 from murs where mur_pos_cod = pos_cod)
			and not exists (select 1 from lieu,lieu_position where lpos_pos_cod = pos_cod and lpos_lieu_cod = lieu_cod and lieu_refuge = 'O')
			order by pos_cod desc
			offset compt_pos
			limit 1;
	end if;*/
	deplace = deplace_code(v_monstre,nouvelle_pos);
	code_retour := nouvelle_pos;
	return 0;
end;$_$;


