ALTER FUNCTION public.f_prix_obj_perso_a(integer, integer, integer) OWNER TO delain;

--
-- Name: f_prix_obj_perso_a_generique(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.f_prix_obj_perso_a_generique(integer, integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/**********************************************************/
/* fonction f_prix_obj_perso_a_generique                  */
/* : donne le prix d'un objet generique                   */
/*  pour un perso X dans une échoppe Y à l'achat          */
/* on passe en paramètres :                               */
/*  $1 = perso_cod du perso                               */
/*  $2 = lieu_cod du magasin                              */
/*  $3 = gobj_cod de l'objet                               */
/* on a en retour un entier correspondant au prix         */
/**********************************************************/
declare
	code_retour integer;
	personnage alias for $1;
	v_lieu_cod alias for $2;
	v_obj_cod alias for $3;
	v_bonus integer;
	v_prix integer;
	v_modif_guilde integer;
begin
	v_prix := f_prix_objet_generique(v_lieu_cod,v_obj_cod);
--
-- MODIFICATEUR DE PERSO
--
	v_prix := floor(v_prix * (mod_vente(personnage,v_lieu_cod)));
--
-- MODIFICATEUR DE GUILDE
--
	if ((select lieu_tlieu_cod from lieu where lieu_cod = v_lieu_cod) = 21) then
		select into v_modif_guilde
			guilde_modif_noir
			from guilde,guilde_perso
			where pguilde_perso_cod = personnage
			and pguilde_valide = 'O'
			and pguilde_guilde_cod = guilde_cod;
		if found then
			v_prix := round(v_prix*(100+v_modif_guilde)*0.01*1);
		else
			v_prix := v_prix * 1;
		end if;
	else
		if ((select lieu_tlieu_cod from lieu where lieu_cod = v_lieu_cod) != 14) then
			select into v_modif_guilde
				guilde_modif
				from guilde,guilde_perso
				where pguilde_perso_cod = personnage
				and pguilde_valide = 'O'
				and pguilde_guilde_cod = guilde_cod;
			if found then
				v_prix := round(v_prix*(100+v_modif_guilde)*0.01);
			end if;
		end if;
	end if;
	return v_prix;
end;
$_$;


ALTER FUNCTION public.f_prix_obj_perso_a_generique(integer, integer, integer) OWNER TO delain;

--
-- Name: f_prix_obj_perso_v(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.f_prix_obj_perso_v(integer, integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/**********************************************************/
/* fonction f_prix_obj_perso_v : donne le prix d'un objet */
/*  pour un perso X dans une échoppe Y à la vente         */
/* on passe en paramètres :                               */
/*  $1 = perso_cod du perso                               */
/*  $2 = lieu_cod du magasin                              */
/*  $3 = obj_cod de l'objet                               */
/* on a en retour un entier correspondant au prix         */
/**********************************************************/
declare
	code_retour integer;
	personnage alias for $1;
	v_lieu_cod alias for $2;
	v_obj_cod alias for $3;
	v_bonus integer;
	v_prix integer;
	v_modif_guilde integer;
	v_etat numeric;
	type_mag integer;
begin
	v_prix := f_prix_objet(v_lieu_cod,v_obj_cod);
--
-- BONUS
--
	select into v_bonus
		obon_prix
		from bonus_objets,objets
		where obj_cod = v_obj_cod
		and obj_obon_cod = obon_cod;
	if found then
		v_prix := v_prix + v_bonus;
	end if;
--
-- MODIFICATEUR DE PERSO
--
	v_prix := floor(v_prix / (mod_vente(personnage,v_lieu_cod)));
--
-- ETAT
--
	select into v_etat
		obj_etat from objets where obj_cod = v_obj_cod;
	v_prix := round(v_prix*v_etat/100);
	select into type_mag
		lieu_tlieu_cod
		from lieu
		where lieu_cod = v_lieu_cod;
	if type_mag = 11 then
		v_prix := round(v_prix*getparm_n(46)*0.01);
	end if;
if type_mag = 21 then
		v_prix := round(v_prix*getparm_n(46)*0.01);
	end if;
	if type_mag = 14 then
		v_prix := round(v_prix*getparm_n(47)*0.01);
	end if;
	return v_prix;
end;
$_$;


ALTER FUNCTION public.f_prix_obj_perso_v(integer, integer, integer) OWNER TO delain;

--
-- Name: f_prix_obj_perso_v_generique(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.f_prix_obj_perso_v_generique(integer, integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/**********************************************************/
/* fonction f_prix_obj_perso_v :                          */
/* donne le prix d'un objet générique                     */
/*  pour un perso X dans une échoppe Y à la vente         */
/* on passe en paramètres :                               */
/*  $1 = perso_cod du perso                               */
/*  $2 = lieu_cod du magasin                              */
/*  $3 = obj_cod de l'objet générique                     */
/* on a en retour un entier correspondant au prix         */
/**********************************************************/
declare
	code_retour integer;
	personnage alias for $1;
	v_lieu_cod alias for $2;
	v_gobj_cod alias for $3;
	v_bonus integer;
	v_prix integer;
	v_modif_guilde integer;
	v_etat numeric;
	type_mag integer;
begin
	v_prix := f_prix_objet_generique(v_lieu_cod,v_gobj_cod);
--
-- BONUS
--
	select into v_bonus
		obon_prix
		from bonus_objets,objet_generique
		where gobj_cod = v_gobj_cod
		and gobj_bonus_cod = obon_cod;
	if found then
		v_prix := v_prix + v_bonus;
	end if;
--
-- MODIFICATEUR DE PERSO
--
	v_prix := floor(v_prix / (mod_vente(personnage,v_lieu_cod)));

	select into type_mag
		lieu_tlieu_cod
		from lieu
		where lieu_cod = v_lieu_cod;
	if type_mag = 11 then
		v_prix := round(v_prix*getparm_n(46)*0.01);
	end if;
        if type_mag = 21 then
		v_prix := round(v_prix*getparm_n(46)*0.01);
	end if;
	if type_mag = 14 then
		v_prix := round(v_prix*getparm_n(47)*0.01);
	end if;
	return v_prix;
end;
$_$;


ALTER FUNCTION public.f_prix_obj_perso_v_generique(integer, integer, integer) OWNER TO delain;

--
-- Name: f_prix_objet(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.f_prix_objet(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*************************************************************/
/* fonction prix_objet : donne le prix par défaut d'un objet */
/*  dans un magasin                                          */
/* on passe en paramètres :                                  */
/*  $1 = lieu_cod du magasin                                 */
/*  $2 = obj_cod de l'objet                                  */
/* on a un entier en retour                                  */
/*************************************************************/
declare
	code_retour integer;					-- prix par défaut
	num_magasin alias for $1;			-- lieu_cod du magasin
	num_objet alias for $2;				-- gobj_cod de l'objet
	temp integer;							-- fourre tout
	marge integer;							-- marge du magasin
	v_prix_obj integer;
	v_prix_gobj integer;
begin
	select into temp mtar_prix
		from magasin_tarif
		where mtar_lieu_cod = num_magasin
		and mtar_gobj_cod = (select obj_gobj_cod from objets where obj_cod = num_objet);
	if found then
		code_retour := temp;
	else
		select into code_retour gobj_valeur
			from objet_generique,objets
			where obj_cod = num_objet
			and obj_gobj_cod = gobj_cod;
	end if;
	select into v_prix_obj,v_prix_gobj obj_valeur,gobj_valeur
		from objets,objet_generique
		where obj_cod = num_objet
		and obj_gobj_cod = gobj_cod;
	code_retour := code_retour - v_prix_gobj + v_prix_obj;
-- on rajoute la marge du magasin
	select into marge lieu_marge from lieu
		where lieu_cod = num_magasin;
	code_retour := ceil(code_retour + ((marge * code_retour)/100));
	return code_retour;
end;$_$;


ALTER FUNCTION public.f_prix_objet(integer, integer) OWNER TO delain;

