	num_objet alias for $2;				-- gobj_cod de l'objet
	temp integer;							-- fourre tout
	marge integer;							-- marge du magasin
	v_prix_obj integer;
	v_prix_gobj integer;
begin
	select into temp mtar_prix
		from magasin_tarif
