/* trigger f_trg_mod_perso_objet   */
/*   transaction d'un objet        */
/***********************************/
declare
	v_perso_cod integer;
	v_obj_cod integer;
	v_dest integer;
begin
/******************************************************/
/* partie 1 : les valeurs de base                     */
/******************************************************/
	select into
		v_perso_cod,
		v_obj_cod
		perobj_perso_cod,
		perobj_obj_cod
		from perso_objets
		where perobj_cod = OLD.perobj_cod;
	select into v_dest
		perobj_perso_cod
		from perso_objets
		where perobj_cod = NEW.perobj_cod;
	if v_dest != v_perso_cod then
	end if;
	return NEW;
end;
 $$;


