--
-- Name: f_use_armure(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.f_use_armure(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*************************************************************/
/* fonction f_use_armure : use l'armure du perso passé en $1 */
/*  en fonction du parametre de dégats passés en $2          */
/*************************************************************/
/* on a en retour :                                          */
/*   1 = OK                                                  */
/*   2 = armure brisée                                       */
/*************************************************************/
declare
	code_retour integer;
	v_armure integer;					-- valeur armure physique
	num_objet integer;				-- obj_cod de l'armure
	personnage alias for $1;
	degats alias for $2;
	v_usure numeric;					-- usure de l'arme
	temp integer;
	v_etat numeric;					-- etat de l'objet après coup
	texte_evt text;
begin
	select into v_armure,num_objet,v_usure
		obj_armure,obj_cod,obj_usure
		from perso_objets,objets,objet_generique,objets_caracs
		where perobj_perso_cod = personnage
		and perobj_equipe = 'O'
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = gobj_cod
		and gobj_tobj_cod = 2
		and gobj_obcar_cod = obcar_cod;
	if not found then
		return 1;
	end if;
	if degats <= v_armure then
		return 1;
	end if;
-- on commence à abimer
	update objets
		set obj_etat = obj_etat - v_usure
		where obj_cod = num_objet;
	if degats > (v_armure * 2) then
		update objets
			set obj_etat = obj_etat - v_usure
			where obj_cod = num_objet;
	end if;
	if degats > (v_armure * 3) then
		update objets
			set obj_etat = obj_etat - v_usure
			where obj_cod = num_objet;
	end if;
	select into v_etat obj_etat
		from objets
		where obj_cod = num_objet;
	if v_etat <= 0 then
		temp := f_del_objet(num_objet);
		return 2;
		texte_evt := 'L''armure de [perso_cod1] s''est brisée !';
	else
		return 1;
	end if;
end;$_$;


ALTER FUNCTION public.f_use_armure(integer, integer) OWNER TO delain;

--
-- Name: f_vue_renommee(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.f_vue_renommee(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/******************************************/
/* fonction f_vue_renommee                */
/*   retourne la renommee du perso        */
/*   passé en $1                          */
/******************************************/
declare
	code_retour text;
	personnage alias for $1;
	v_renom numeric;
	v_renom_magie numeric;
	v_renom_art numeric;
	v_renommee numeric;
begin
	select into v_renom, v_renom_magie, v_renom_art
		perso_renommee, perso_renommee_magie, perso_renommee_artisanat
	from perso
	where perso_cod = personnage;

	if v_renom > v_renom_magie AND v_renom > v_renom_art then
		code_retour := get_renommee(v_renom);
	elsif v_renom_magie > v_renom AND v_renom_magie > v_renom_art then
		code_retour := get_renommee_magie(v_renom_magie);
	else
		code_retour := get_renommee_artisanat(v_renom_art);
	end if;

	return code_retour;
end;
$_$;


ALTER FUNCTION public.f_vue_renommee(integer) OWNER TO delain;

--
-- Name: FUNCTION f_vue_renommee(integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.f_vue_renommee(integer) IS 'Gère la renommée à afficher pour un perso (la meilleure entre magie, classique et artisanale)';


--
-- Name: fin_hibernation(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.fin_hibernation(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*************************************************/
/* fonction fin_hibernation                        */
/*************************************************/
declare
	code_retour text;
	v_compte alias for $1;
	v_compte_nom text;
	v_commentaire text;
	v_numero integer;
begin
	update compte set compt_hibernation =null, compt_dfin_hiber = null
		where compt_cod = v_compte;
	update perso set perso_actif = 'O',perso_der_connex = now() where perso_actif = 'H'
		and perso_type_perso = 3
		and perso_cod in
		(select pfam_familier_cod from perso_compte, perso_familier
		where pcompt_compt_cod = v_compte
		and pcompt_perso_cod = pfam_perso_cod) ;
	update perso set perso_actif = 'O',perso_der_connex = now() where perso_actif = 'H'
		and perso_type_perso = 1
		and perso_cod in
		(select pcompt_perso_cod from perso_compte
		where pcompt_compt_cod = v_compte) ;
	select into v_compte_nom , v_commentaire compt_nom , compt_confiance from compte where compt_cod = v_compte and compt_confiance = 'S';
	if found then
		select into v_numero nextval('seq_msg_cod');
	end if;
	code_retour = 'OK';
	return code_retour;
end;$_$;


ALTER FUNCTION public.fin_hibernation(integer) OWNER TO delain;

