--
-- Name: ia_include_ramasse_objet(public.ia_donnees, integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.ia_include_ramasse_objet(public.ia_donnees, integer, integer, integer, integer) RETURNS public.ia_donnees
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function ia_include_ramasse_objet :                           */
/*      Procédure utilisée par les différentes IA pour gérer les */
/*      ramassages d’un type d’objet                             */
/* On passe en paramètres                                        */
/*    $1 = les données d’IA (de type ia_donnees)                 */
/*    $2 = la limite de vue du monstre                           */
/*    $3 = le type d’objets à ramasser                           */
/*    $4 = le nombre max à porter en inventaire                  */
/*    $5 = le nombre max à ramasser à chaque appel               */
/*****************************************************************/
/* Créé le 12/12/2012                                            */
/*****************************************************************/
declare
	donnees alias for $1;           -- l’ensemble des données d’IA à transmettre entre fonctions
	v_vue alias for $2;             -- la limite de vue du monstre
	v_tobj_cod alias for $3;        -- le type d’objets à ramasser
	v_inventaire_max alias for $4;  -- le nombre max à porter en inventaire
	v_ramassage_max alias for $5;   -- le nombre max à ramasser à chaque appel

	resultat ia_donnees; -- le résultat de la fonction

	pos_rune integer;             -- position de la rune à ramasser
	cod_rune integer;             -- code de la rune à ramasser
	v_nombre_portes integer;      -- Le nombre d’objets du type voulu actuellement portés par le perso

	compt_loop integer;           -- un compteur de boucle, permettant d’arrêter la boucle en cas de problème

	temp_txt text;                -- fourre-tout
begin
	resultat := donnees;
	resultat.code_retour := E'Ramassage d’objets ?<br />\n';

	compt_loop := 0;
	temp_txt := '';
	pos_rune := 0;

	-- on regarde si on n’a pas suffisamment d’objets de ce type en inventaire.
	select into v_nombre_portes count(*) from perso_objets
	inner join objets on obj_cod = perobj_obj_cod
	inner join objet_generique on gobj_cod = obj_gobj_cod
	where gobj_tobj_cod = v_tobj_cod and perobj_perso_cod = donnees.monstre_cod;

	if v_nombre_portes >= v_inventaire_max then
		resultat.code_retour := resultat.code_retour || E'Trop en inventaire !<br />\n';
		return resultat;
	end if;

	-- on récupère la position la plus proche en contenant
	select into pos_rune pobj_pos_cod
	from objet_position
	inner join objets on obj_cod = pobj_obj_cod
	inner join objet_generique on gobj_cod = obj_gobj_cod
	inner join positions on pos_cod = pobj_pos_cod
	where pos_x between (resultat.pos_x - v_vue) and (resultat.pos_x + v_vue)
		and pos_y between (resultat.pos_y - v_vue) and (resultat.pos_y + v_vue)
		and pos_etage = resultat.pos_etage
		and gobj_tobj_cod = v_tobj_cod
		and trajectoire_vue_murs(resultat.pos_cod, pos_cod) = 1
	order by max(abs(pos_x - resultat.pos_x), abs(pos_y - resultat.pos_y)), random()
	limit 1;

	if pos_rune > 0 then
		-- on se déplace vers cette position
		resultat.code_retour := resultat.code_retour || 'Objet repéré en ' || pos_rune::text || ' ! ';
		resultat := ia_include_deplacement(resultat, 1, v_vue, pos_rune, 0);
	end if;

	-- on ramasse jusqu’à X runes...
	compt_loop := 0;
	cod_rune := 0;
	while (resultat.perso_pa > 0) loop
		compt_loop := compt_loop + 1;
		exit when compt_loop > v_ramassage_max OR cod_rune = -1 OR v_nombre_portes + compt_loop > v_inventaire_max;

		select into cod_rune pobj_obj_cod
		from objet_position
		inner join objets on obj_cod = pobj_obj_cod
		inner join objet_generique on gobj_cod = obj_gobj_cod
		where pobj_pos_cod = resultat.pos_cod
			and gobj_tobj_cod = v_tobj_cod
		limit 1;
		if found then -- on ramasse !
			temp_txt := ramasse_objet(donnees.monstre_cod, cod_rune);
			resultat.code_retour := resultat.code_retour || temp_txt || E'<br />\n';
		else
			cod_rune := -1;
		end if;
		-- mise à jour des PA
		select into resultat.perso_pa perso_pa from perso where perso_cod = donnees.monstre_cod;
	end loop;
	return resultat;
end;$_$;


ALTER FUNCTION public.ia_include_ramasse_objet(public.ia_donnees, integer, integer, integer, integer) OWNER TO delain;

--
-- Name: FUNCTION ia_include_ramasse_objet(public.ia_donnees, integer, integer, integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.ia_include_ramasse_objet(public.ia_donnees, integer, integer, integer, integer) IS 'Gère le ramassage d’objets par l’IA';


--
-- Name: ia_lache(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.ia_lache(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************/
/* fonction ia_lache                                 */
/*    reçoit en arguments :                          */
/* $1 = perso_cod du monstre                         */
/*    retourne en sortie en entier non lu            */
/*    les évènements importants seront mis dans la   */
/*    table des evenemts admins                      */
/* Cette fonction effectue les actions automatiques  */
/*  des monstres pour éviter que le MJ qui a autre   */
/*  à faire jouer tout à la mimine....               */
/*****************************************************/
/* 25/01/2004 : changement pour adaptation à la      */
/*  nouvelle fonction attaque(int4,int4)             */
/* 20/02/2004 : ajout des sorts aggressifs           */
/* 05/07/2004 : IA non obligatoirement jouée         */
/* 17/07/2006 : rajout de l'utilisation des          */
/*              compétences de combat                */
/*****************************************************/
declare
-------------------------------------------------------
-- variables E/S
-------------------------------------------------------
	code_retour text;				-- code sortie
-------------------------------------------------------
-- variables de renseignements du monstre
-------------------------------------------------------
	v_monstre alias for $1;		-- perso_cod du monstre
	v_niveau integer;				-- niveau du monstre
	v_exp numeric;					-- xp du monstre
	v_pa integer;					-- pa du monstre
	v_vue integer;					-- distance de vue
	v_cible integer;				-- cible
	temp_cible integer;			-- cible temporaire
	v_etage integer;				-- etage
	pos_actuelle integer;		-- position
	v_x integer;					-- X
	v_y integer;					-- Y
	actif varchar(2);				-- actif ?
	distance_limite integer;	-- distance max attaque (min vue-dist attaque)
	distance_attaque integer;	-- portee attaque
	nb_lock integer;				-- nombre de locks combat
	v_int integer;					-- intelligence du monstre
	nb_sort_aggressif integer;	-- nombre de sorts aggressifs du monstre
	chance_sort integer;			-- chance de lancer un sort
	num_sort integer;				-- numéro du sort à lancer
	fonction_sort text;			-- fonction à lancer
	v_pv integer;					-- pv du monstre
	v_pv_max integer;				-- pv_max du monstre
	v_soutien text;				-- peut il soutenir d'autres monstres ?
	cible_soutien integer;		-- perso_cod a soutenir
	chance_mercu integer;	   -- chance de lancer mercu
	statique_combat text;		-- statique en combat ?
	statique_hors_combat text;	-- statique hors combat ?
	doit_jouer integer;			-- 0 pour non, 1 pour oui
	v_dlt timestamp;				-- dlt du monstre
	v_temps_tour integer;		-- temps du tour
	i_temps_tour interval;		-- temps du tour en intervalle
	temp_niveau integer;			-- random pour passage niveau
	limite_surcharge integer;
-------------------------------------------------------
-- variables temporaires ou de calcul
-------------------------------------------------------
	temp integer;					-- fourre tout
	temp_txt text;					-- texte temporaire
	compt_loop integer;			-- comptage de boucle pour sortie
	dep_aleatoire integer;		-- variable de calcul de dep aleatoire
	distance_cible integer;		-- distance de la cible
-------------------------------------------------------
-- variables pour cible
-------------------------------------------------------
	nb_joueur_en_vue integer;	-- nombre de joueurs en vue
	nb_cible_en_vue integer;	-- nombre de cibles en vue
	pos_cible integer;			-- position de la cible
	pos_dest integer;				-- destination
	ligne record;
	nv_pos integer;
	nb_cible_case integer;

begin
	doit_jouer := 0;
	code_retour := 'IA lache<br>Monstre '||trim(to_char(v_monstre,'999999999999'))||'<br>';
	limite_surcharge := 1;
/***********************************/
/* Etape 1 : on récupère les infos */
/* du monstre                      */
/***********************************/
	select into 	v_niveau,
						v_exp,
						v_pa,
						v_vue,
						pos_actuelle,
						v_cible,
						v_etage,
						actif,
						v_x,
						v_y,
						v_int,
						v_pv,
						v_pv_max,
						statique_combat,
						statique_hors_combat,
						v_dlt,
						v_temps_tour,
						nv_pos
					limite_niveau(v_monstre),
					perso_px,
					perso_pa,
					distance_vue(v_monstre),
					ppos_pos_cod,
					perso_cible,
					pos_etage,
					perso_actif,
					pos_x,
					pos_y,
					perso_int,
					perso_pv,
					perso_pv_max,
					perso_sta_combat,
					perso_sta_hors_combat,
					perso_dlt,
					perso_temps_tour,
					pos_cod
		from perso,perso_position,positions
		where perso_cod = v_monstre
		and ppos_perso_cod = v_monstre
		and ppos_pos_cod = pos_cod;
	nv_pos := 0;
	if v_cible is null then
		v_cible := 0;
	end if;
	if actif != 'O' then
		return 'inactif !';
	end if;
	i_temps_tour := trim(to_char(v_temps_tour,'9999999999'))||' minutes';
	if v_dlt + i_temps_tour - '10 minutes'::interval >= now() then
		doit_jouer := 1;
	end if;
	temp := lancer_des(1,100);
	if temp > 50 then
		if doit_jouer = 0 then
			code_retour := code_retour||'Perso non joué.';
			return code_retour;
		end if;
	end if;
/***************************************/
/* On sait qu'on doit jouer le monstre */
/***************************************/
	temp_txt := calcul_dlt2(v_monstre);
	distance_limite := portee_attaque(v_monstre);
	if distance_limite > v_vue then
		distance_limite := v_vue;
	end if;

/***********************************/
/* Etape 2 : on regarde si passage */
/*  de niveau                      */
/***********************************/
-- on lance la procédure de passage de niveau
	if (v_exp >= v_niveau and v_pa >= getparm_n(8)) then
		temp_niveau := lancer_des(1,6);
		temp_txt := f_passe_niveau(v_monstre,temp_niveau);
		select into v_pa perso_pa from perso where perso_cod = v_monstre;

		code_retour := code_retour||'Passage niveau.<br>';
	end if;
/************************************/
/* Etape 3 : on regarde si il y a   */
/*  des joueurs en vue              */
/************************************/
	select into nb_joueur_en_vue count(perso_cod)
		from perso,perso_position,positions
		where pos_x between (v_x - v_vue) and (v_x + v_vue)
		and pos_y between (v_y - v_vue) and (v_y + v_vue)
		and pos_etage = v_etage
		and ppos_perso_cod = perso_cod
		and perso_type_perso = 1
		and perso_actif = 'O'
		and perso_tangible = 'O'
		and ppos_pos_cod = pos_cod
		and not exists
			(select 1 from lieu,lieu_position
			where lpos_pos_cod = ppos_pos_cod
			and lpos_lieu_cod = lieu_cod
			and lieu_refuge = 'O')
		and is_surcharge(perso_cod,v_monstre) < limite_surcharge
		and trajectoire_vue(pos_actuelle,pos_cod) = 1;

	code_retour := code_retour||'Nombre de persos en vue : '||trim(to_char(nb_joueur_en_vue,'9999999999'))||'<br>';
/**************************************************/
/* Personne en vue, on se balade puis on sort     */
/**************************************************/
	if nb_joueur_en_vue = 0 then
		update perso set perso_cible = null where perso_cod = v_monstre;
		if statique_hors_combat = 'N' then
			compt_loop := 0;
			while (v_pa >= getparm_n(9)) loop
				compt_loop := compt_loop + 1;
				exit when compt_loop >= 5;
				dep_aleatoire := f_deplace_aleatoire(v_monstre,pos_actuelle);
				select into pos_actuelle ppos_pos_cod
					from perso_position
					where ppos_perso_cod = v_monstre;
				select into v_pa perso_pa from perso
					where perso_cod = v_monstre;
			end loop;
		end if;
		code_retour := code_retour||'Aucun joueur en vue, déplacement aléatoire.<br>';
		return code_retour;
	end if;
/*******************************/
/* On a des persos en vue      */
/*******************************/
-- on se soigne
	if v_pv != v_pv_max then
		select into temp psort_cod
			from perso_sorts
			where psort_perso_cod = v_monstre
			and psort_sort_cod = 5;
		if found then
			chance_mercu := round((v_pv_max - v_pv)/v_pv_max);
			if lancer_des(1,100) > chance_mercu then
				fonction_sort := 'select nv_magie_mercurochrome('||trim(to_char(v_monstre,'9999999999'))||','||trim(to_char(v_monstre,'999999999999999'))||',1)';
				code_retour := code_retour||'Lancement mercurochrome.<br>';
				execute fonction_sort;
			end if;
		end if;
	end if;
	if v_cible is null then
		code_retour := code_retour||'Pas de cible départ.<br>';
	else
		code_retour := code_retour||'Cible départ : '||trim(to_char(v_cible,'9999999999999'))||'<br>';
	end if;
/*************************************/
/* Etape 4 : on regarde si la cible  */
/*  est sur la même case             */
/*************************************/
-- on change de cible si lockage
	select into temp_cible count(lock_cod) from lock_combat
		where lock_cible = v_monstre;
	if temp_cible != 0 then
		if v_cible not in
			(select lock_attaquant from lock_combat where lock_cible = v_monstre
				union
			select lock_cible from lock_combat where lock_attaquant = v_monstre) then
		select into temp_cible count(distinct(perso_cod))
			from perso,lock_combat
			where (lock_cible = v_monstre and lock_attaquant = perso_cod)
			or (lock_cible = perso_cod and lock_attaquant = v_monstre);
		temp_cible := lancer_des(1,temp_cible);
		temp_cible := temp_cible - 1;
		select into v_cible
			distinct perso_cod
			from perso,lock_combat
			where (lock_cible = v_monstre and lock_attaquant = perso_cod)
			or (lock_cible = perso_cod and lock_attaquant = v_monstre)
			offset temp_cible
			limit 1;
		code_retour := code_retour||'Changement de cible suite à lock, nouvelle cible : '||trim(to_char(v_cible,'9999999999999'))||'<br>';
		end if;
	end if;
/*****************************************************/
/* A partir de maintenant, on a la bonne cible       */
/*****************************************************/
	select into	nb_cible_en_vue count(perso_cod)
		from perso_position,perso,positions
		where ppos_perso_cod = v_cible
		and pos_x between (v_x - distance_limite) and (v_x + distance_limite)
		and pos_y between (v_y - distance_limite) and (v_y + distance_limite)
		and pos_etage = v_etage
		and perso_cod = v_cible
		and perso_actif = 'O'
		and perso_tangible = 'O'
		and perso_type_perso in (1,3)
			and not exists
			(select 1 from lieu,lieu_position
			where lpos_pos_cod = ppos_pos_cod
			and lpos_lieu_cod = lieu_cod
			and lieu_refuge = 'O')
		and ppos_pos_cod = pos_cod;
	if nb_cible_en_vue != 0 then
		if (trajectoire_vue(pos_actuelle,(select ppos_pos_cod from perso_position
			where ppos_perso_cod = v_cible))) != 1 then
		nb_cible_en_vue := 0;
	end if;
	end if;
-- si cible pas sur la case, on en choisit une autre
	if nb_cible_en_vue = 0 then
/***************************************************/
/* Pas de bol, notre cible n'est pas visible       */
/***************************************************/
	code_retour := code_retour||'La cible choisie n''est pas en vue.<br>';
		v_cible := 0;
		nb_cible_case := 99;
		for ligne in select pos_cod,
			(select count(perso_cod)
			from perso,perso_position
			where ppos_pos_cod = pos_cod
			and ppos_perso_cod = perso_cod
			and perso_type_perso in (1,3)
			and perso_actif = 'O'
			and perso_tangible = 'O') as nbperso
		from positions
		where pos_x >= (v_x - v_vue) and pos_x <= (v_x + v_vue)
		and pos_y >= (v_y - v_vue) and pos_y <= (v_y + v_vue)
		and pos_etage = v_etage
		and not exists
			(select 1 from lieu,lieu_position
			where lpos_pos_cod = pos_cod
			and lpos_lieu_cod = lieu_cod
			and lieu_refuge = 'O')
		and trajectoire_vue(pos_actuelle,pos_cod) = 1 loop
				if ligne.nbperso != 0 then
				if ligne.nbperso < nb_cible_case then
					nb_cible_case := ligne.nbperso;
					nv_pos := ligne.pos_cod;
				end if;
			end if;
		end loop;
		code_retour := code_retour||'Nouvelle destination : '||trim(to_char(nv_pos,'9999999999999'))||'<br>';
	else
/***************************************************/
/* Notre cible est visible                         */
/***************************************************/
		code_retour := code_retour||'La cible choisie est en vue.<br>';
		if (v_pv/v_pv_max::numeric) < 0.3 then
/***************************************************/
/* On est blessé, on fuit !                        */
/***************************************************/
			code_retour := code_retour||'Points de vie faibles, on cherche une autre cible pour fuir.<br>';
			v_cible := 0;
				nb_cible_case := 99;
			for ligne in select pos_cod,
				(select count(perso_cod)
				from perso,perso_position
				where ppos_pos_cod = pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso in (1,3)
				and perso_actif = 'O'
				and perso_tangible = 'O') as nbperso
			from positions
			where pos_x >= (v_x - v_vue) and pos_x <= (v_x + v_vue)
			and pos_y >= (v_y - v_vue) and pos_y <= (v_y + v_vue)
			and pos_etage = v_etage
			and not exists
				(select 1 from lieu,lieu_position
				where lpos_pos_cod = pos_cod
				and lpos_lieu_cod = lieu_cod
				and lieu_refuge = 'O')
			and trajectoire_vue(pos_actuelle,pos_cod) = 1 loop
					if ligne.nbperso != 0 then
					if ligne.nbperso < nb_cible_case then
						nb_cible_case := ligne.nbperso;
						nv_pos := ligne.pos_cod;
					end if;
				end if;
			end loop;
			code_retour := code_retour||'Nouvelle destination : '||trim(to_char(nv_pos,'9999999999999'))||'<br>';
			else
			-- comportement normal
			select into nb_lock lock_cible
				from lock_combat
				where lock_cible = v_monstre;
			if found then
				-- on est locké, on prend la cible la plus faible
				v_cible := choix_cible_case_lache(v_monstre,pos_actuelle,v_etage,nb_joueur_en_vue);
			else
				select into nv_pos
					ppos_pos_cod
					from perso_position
					where ppos_perso_cod = v_cible;
			end if;
			code_retour := code_retour||'Nouvelle destination : '||trim(to_char(nv_pos,'9999999999999'))||'<br>';
			end if;
	end if;
/*****************************************************/
/* Etape 5 : on se déplace vers la nouvelle position */
/*****************************************************/
	if (distance(pos_actuelle,nv_pos) >= distance_limite) then
		if statique_combat = 'N' then
		code_retour := code_retour||'Déplacement vers la cible.<br>';
			compt_loop := 0;
			while (distance(pos_actuelle,nv_pos) >= distance_limite) and (v_pa >= getparm_n(9)) loop
				compt_loop := compt_loop + 1;
				exit when compt_loop >= 10;
				-- on récupère la case vers laquelle on se déplace
				pos_dest := dep_vers_cible(pos_actuelle,nv_pos);
				-- on va sur cette nouvelle case
				temp_txt := deplace_code(v_monstre,pos_dest);
				-- on récupère les nouvelles infos
				select into v_pa,pos_actuelle
					perso_pa,ppos_pos_cod
					from perso,perso_position
					where perso_cod = v_monstre
					and ppos_perso_cod = perso_cod;
			end loop;
		end if;
		if v_cible = 0 then
			v_cible := choix_cible_case_lache(v_monstre,nv_pos,0,0);
		end if;
	end if;
	-- on y choisit une cible

	select into pos_cible
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = v_cible;
	code_retour := code_retour||'Nouvelle cible : '||trim(to_char(v_cible,'9999999999999'))||'<br>';

/*****************************************/
/* Etape 6 : on regarde si on est sur la */
/*  même case que la cible               */
/*****************************************/
	if (distance(pos_actuelle,pos_cible) <= distance_limite) then
-- on regarde si on peut lancer un sort aggressif
	distance_cible := distance(pos_actuelle,pos_cible);
	select into nb_sort_aggressif count(psort_cod)
		from perso_sorts,sorts
		where psort_perso_cod = v_monstre
		and psort_sort_cod = sort_cod
		and sort_aggressif = 'O'
		and sort_distance >= distance_cible;
	if nb_sort_aggressif != 0 then
-- on tente le lancer de sort
		chance_sort := v_int * 4;
		if chance_sort > 80 then
			chance_sort := 80;
		end if;
		if (lancer_des(1,100) <= chance_sort) then
-- là on est bien parti pour lancer un sort quand même
-- on commence par choisir le sort qu'on va lancer
			temp := lancer_des(1,nb_sort_aggressif);
			temp := temp - 1;
			select into num_sort,fonction_sort
				sort_cod,sort_fonction
				from perso_sorts,sorts
				where psort_perso_cod = v_monstre
				and psort_sort_cod = sort_cod
				and sort_aggressif = 'O'
				and sort_distance >= distance_cible
				offset temp
				limit 1;
-- on construit la chaine de lancement du sort
			fonction_sort := 'select nv_'||fonction_sort||'('||trim(to_char(v_monstre,'999999'))||','||trim(to_char(v_cible,'999999'))||',1)';
-- on lance le sort proprement dit
			execute fonction_sort;
			code_retour := code_retour||'Lancement de sort offensif.<br>';
			end if;
	end if;
-- on regarde pour les sorts de soutien
	select into nb_lock lock_cible
		from lock_combat
		where lock_cible = v_monstre;
	if not found then
-- on choisit la cible du sort de soutien
		select into v_soutien gmon_soutien
			from monstre_generique,perso
			where perso_cod = v_monstre
			and perso_gmon_cod = gmon_cod;
		if not found then
			cible_soutien := v_monstre;
		else
			if v_soutien = 'N' then
				cible_soutien := v_monstre;
			else
				select into nb_joueur_en_vue count(perso_cod)
					from perso,perso_position,positions
					where pos_x between (v_x - v_vue) and (v_x + v_vue)
					and pos_y between (v_y - v_vue) and (v_y + v_vue)
					and pos_etage = v_etage
					and ppos_perso_cod = perso_cod
					and perso_type_perso = 2
					and perso_actif = 'O'
					and perso_tangible = 'O'
					and ppos_pos_cod = pos_cod;
				if nb_joueur_en_vue = 0 then
					cible_soutien := v_monstre;
				else
					nb_joueur_en_vue := lancer_des(1,nb_joueur_en_vue);
					nb_joueur_en_vue := nb_joueur_en_vue - 1;
					select into cible_soutien perso_cod
						from perso,perso_position,positions
						where pos_x between (v_x - v_vue) and (v_x + v_vue)
						and pos_y between (v_y - v_vue) and (v_y + v_vue)
						and pos_etage = v_etage
						and ppos_perso_cod = perso_cod
						and perso_type_perso = 2
						and perso_actif = 'O'
						and perso_tangible = 'O'
						and ppos_pos_cod = pos_cod
						limit 1
						offset nb_joueur_en_vue;
					if cible_soutien is null then
						cible_soutien := v_monstre;
					end if;
				end if;
			end if;
		end if;
		select into nb_sort_aggressif count(psort_cod)
			from perso_sorts,sorts
			where psort_perso_cod = v_monstre
			and psort_sort_cod = sort_cod
			and sort_soutien = 'O'
			and sort_distance >= distance_cible;
		if nb_sort_aggressif != 0 then
	-- on tente le lancer de sort
			chance_sort := v_int * 3;
			if chance_sort > 80 then
				chance_sort := 80;
			end if;
			if (lancer_des(1,100) <= chance_sort) then
	-- là on est bien parti pour lancer un sort quand même
	-- on commence par choisir le sort qu'on va lancer
				temp := lancer_des(1,nb_sort_aggressif);
				temp := temp - 1;
				select into num_sort,fonction_sort
					sort_cod,sort_fonction
					from perso_sorts,sorts
					where psort_perso_cod = v_monstre
					and psort_sort_cod = sort_cod
					and sort_soutien = 'O'
					and sort_distance >= distance_cible
					offset temp
					limit 1;
	-- on construit la chaine de lancement du sort
				fonction_sort := 'select nv_'||fonction_sort||'('||trim(to_char(v_monstre,'999999'))||','||trim(to_char(cible_soutien,'999999'))||',1)';
	-- on lance le sort proprement dit
				execute fonction_sort;
				code_retour := code_retour||'Lancement de sort de soutien sur '||trim(to_char(cible_soutien,'9999999999999'))||'.<br>';
			end if;
		end if;
	end if;
-- on attaque avec les compétences spéciales
	perform comp_spe_monstre(v_monstre,v_cible);
-- on attaque en boucle
		compt_loop := 0;
		while (distance(pos_actuelle,pos_cible) <= distance_limite) and (v_pa >= nb_pa_attaque(v_monstre)) loop
			distance_attaque := distance(pos_actuelle,pos_cible);
			compt_loop := compt_loop + 1;
			exit when compt_loop >= 15;
			temp_txt := attaque(v_monstre,v_cible,0);
			--on récupère les infos pour voir si on boucle encore
			select into v_pa perso_pa from perso where perso_cod = v_monstre;
			select into pos_cible ppos_pos_cod from perso_position
				where ppos_perso_cod = v_cible;
		end loop;
		code_retour := code_retour||'Attaque cible.<br>';
	end if;
/*************************************************/
/* Etape 7 : on regarde si on peut se concentrer */
/*************************************************/

/*************************************************/
/* Etape 8 : tout semble fini                    */
/*************************************************/
	return code_retour;
end;
$_$;


ALTER FUNCTION public.ia_lache(integer) OWNER TO delain;

--
-- Name: ia_soutien_aventuriers(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.ia_soutien_aventuriers(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************/
/* fonction ia_soutien_aventuriers                              */
/*    reçoit en arguments :                          */
/* $1 = perso_cod du monstre                         */
/*    retourne en sortie en entier non lu            */
/*    les évènements importants seront mis dans la   */
/*    table des evenemts admins                      */
/* Cette fonction effectue les actions automatiques  */
/*des monstres ou PNJ qui soutiennent les aventuriers*/
/*****************************************************/
/* 29/10/2012 : Création                             */
/*****************************************************/
declare
-------------------------------------------------------
-- variables E/S
-------------------------------------------------------
	code_retour text;				-- code sortie
-------------------------------------------------------
-- variables de renseignements du monstre
-------------------------------------------------------
	v_monstre alias for $1;		-- perso_cod du monstre
	v_niveau integer;				-- niveau du monstre
	v_exp numeric;					-- xp du monstre
	v_pa integer;					-- pa du monstre
	v_vue integer;					-- distance de vue
	v_cible integer;				-- cible
	v_etage integer;				-- etage
	pos_actuelle integer;		-- position
	v_x integer;					-- X
	v_y integer;					-- Y
	actif varchar(2);				-- actif ?
	distance_limite integer;	-- distance max des sorts connus
	v_int integer;					-- intelligence du monstre
	num_sort integer;				-- numéro du sort à lancer
	fonction_sort text;			-- fonction à lancer
	v_pv integer;					-- pv du monstre
	v_pv_max integer;				-- pv_max du monstre
	soigneur boolean;	   -- est-il soigneur exclusivement ?
	statique_combat text;		-- statique en combat ?
	statique_hors_combat text;	-- statique hors combat ?
	doit_jouer integer;			-- 0 pour non, 1 pour oui
	v_dlt timestamp;				-- dlt du monstre
	v_temps_tour integer;		-- temps du tour
	i_temps_tour interval;		-- temps du tour en intervalle
	temp_niveau integer;			-- random pour passage niveau
	v_portee_max integer;		-- Si la vue est trop grande, on majore.
-------------------------------------------------------
-- variables temporaires ou de calcul
-------------------------------------------------------
	temp integer;					-- fourre tout
	temp_txt text;					-- texte temporaire
	compt_loop integer;			-- comptage de boucle pour sortie
	dep_aleatoire integer;		-- variable de calcul de dep aleatoire
	distance_cible integer;		-- distance de la cible
-------------------------------------------------------
-- variables pour cible
-------------------------------------------------------
	nb_joueur_en_vue integer;	-- nombre de joueurs en vue
	pos_cible integer;			-- position de la cible
	pos_dest integer;				-- destination

begin
	compt_loop := 0;
	doit_jouer := 0;
	code_retour := E'IA soutien\nMonstre '||trim(to_char(v_monstre,'999999999999'))||E'\n';
/***********************************/
/* Etape 1 : on récupère les infos */
/* du monstre                      */
/***********************************/
	temp_txt := calcul_dlt2(v_monstre);
	select into 	v_niveau,
						v_exp,
						v_pa,
						v_vue,
						pos_actuelle,
						v_cible,
						v_etage,
						actif,
						v_x,
						v_y,
						v_int,
						v_pv,
						v_pv_max,
						statique_combat,
						statique_hors_combat,
						v_dlt,
						v_temps_tour
					limite_niveau(v_monstre),
					perso_px,
					perso_pa,
					distance_vue(v_monstre),
					ppos_pos_cod,
					perso_cible,
					pos_etage,
					perso_actif,
					pos_x,
					pos_y,
					perso_int,
					perso_pv,
					perso_pv_max,
					perso_sta_combat,
					perso_sta_hors_combat,
					perso_dlt,
					perso_temps_tour
		from perso,perso_position,positions
		where perso_cod = v_monstre
		and ppos_perso_cod = v_monstre
		and ppos_pos_cod = pos_cod;
	if actif != 'O' then
		return 'inactif !';
	end if;
	i_temps_tour := trim(to_char(v_temps_tour,'9999999'))||' minutes';
	if v_dlt + i_temps_tour - '10 minutes'::interval >= now() then
		doit_jouer := 1;
	end if;
	temp := lancer_des(1,100);
	if temp > 50 then
		if doit_jouer = 0 then
			code_retour := code_retour||'Perso non joué.';
			return code_retour;
		end if;
	end if;


/***********************************/
/* passage de niveau si possible   */
/***********************************/
-- on lance la procédure de passage de niveau
	if (v_exp >= v_niveau and v_pa >= getparm_n(8)) then
		temp_niveau := lancer_des(1,6);
		temp_txt := f_passe_niveau(v_monstre,temp_niveau);
		select into v_pa perso_pa from perso where perso_cod = v_monstre;
		code_retour := code_retour||E'Passage niveau.\n';
	end if;

/************************************/
/* On regarde si il y a             */
/*  des joueurs en vue              */
/************************************/

	select into soigneur
		count(*) = 0
	from perso_sorts
	inner join sorts on sort_cod = psort_sort_cod
	where psort_perso_cod = v_monstre
		and (sort_cod not in (5, 10, 129));

	select into nb_joueur_en_vue count(perso_cod)
	from perso
	inner join perso_position on ppos_perso_cod = perso_cod
	inner join positions on pos_cod = ppos_pos_cod
	where pos_x between (v_x - v_vue) and (v_x + v_vue)
		and pos_y between (v_y - v_vue) and (v_y + v_vue)
		and pos_etage = v_etage
		and perso_type_perso = 1
		and perso_actif = 'O'
		and perso_tangible = 'O'
		-- pour un perso soigneur, seuls les perso blessés sont comptés
		and (not soigneur OR perso_pv * 100 / perso_pv_max <= 75)
		and not exists
			(select 1 from lieu,lieu_position
			where lpos_pos_cod = ppos_pos_cod
				and lpos_lieu_cod = lieu_cod
				and lieu_refuge = 'O')
		and trajectoire_vue_murs(pos_actuelle, pos_cod) = 1;

	code_retour := code_retour||'Nombre de persos en vue : '||trim(to_char(nb_joueur_en_vue,'9999999999'))||E'\n';

	/* si personne, on sort..... ==> le monstre bouge */
	if nb_joueur_en_vue = 0 then
		update perso set perso_cible = null where perso_cod = v_monstre;
		if statique_hors_combat = 'N' then
			compt_loop := 0;
			while (v_pa >= getparm_n(9)) loop
				compt_loop := compt_loop + 1;
				exit when compt_loop >= 10;
				dep_aleatoire := f_deplace_aleatoire(v_monstre,pos_actuelle);

				select into pos_actuelle, v_x, v_y ppos_pos_cod, pos_x, pos_y
				from perso_position
				inner join positions on pos_cod = ppos_pos_cod
				where ppos_perso_cod = v_monstre;

				select into v_pa perso_pa from perso
				where perso_cod = v_monstre;
			end loop;
		end if;
		code_retour := code_retour||'Aucun joueur en vue, déplacement aléatoire - boucle arrêtée a '||trim(to_char(compt_loop,'9999999'))||E'\n';
		return code_retour;
	end if;

	/* Le monstre en a marre de s’occuper des mêmes personnes, il va voir ailleurs s’il y est*/
	if random() < 0.2 then
		update perso set perso_cible = null where perso_cod = v_monstre;

		code_retour := code_retour||'Changement d’air !\n';

		-- On choisit une cible le plus loin possible
		select into pos_cible
			pos_cod
		from positions
		where pos_x between (v_x - v_vue) and (v_x + v_vue)
			and pos_y between (v_y - v_vue) and (v_y + v_vue)
			and pos_etage = v_etage
			and trajectoire_vue_murs(pos_actuelle, pos_cod) = 1
		order by max(abs(pos_x - v_x), abs(pos_y - v_y)) desc, random()
		limit 1;

		if statique_hors_combat = 'N' then
			compt_loop := 0;
			while (v_pa >= getparm_n(9)) loop
				compt_loop := compt_loop + 1;
				exit when compt_loop >= 10;
				-- on récupère la case vers laquelle on se déplace
				-- on va sur cette nouvelle case
				-- on récupère les nouvelles infos
				pos_dest := dep_vers_cible(pos_actuelle, pos_cible);
				temp_txt := deplace_code(v_monstre, pos_dest);

				select into pos_actuelle, v_x, v_y ppos_pos_cod, pos_x, pos_y
				from perso_position
				inner join positions on pos_cod = ppos_pos_cod
				where ppos_perso_cod = v_monstre;

				select into v_pa perso_pa from perso
				where perso_cod = v_monstre;
			end loop;
		end if;
		code_retour := code_retour||'Aucun joueur en vue, déplacement aléatoire - boucle arrêtée a '||trim(to_char(compt_loop,'9999999'))||E'\n';
		return code_retour;
	end if;

	/*************************************************************/
	/* 1 Boucle sur les PA                                       */
	/* 2 Sort de soutien                                         */
	/*    Détermination de la distance maximale d’action         */
	/*    Choix d’une cible aléatoire dans ce rayon              */
	/*    Si aucune cible : on bouge vers le perso le plus près  */
	/*    Choix d’un sort aléatoire à lancer sur cette cible     */
	/*    Si aucun sort : on se rapproche de la cible            */
	/*    Si aucun sort : on se rapproche de la cible            */
	/* 3 Fin de boucle si plus de PA, sinon boucle fois 12       */
	/*************************************************************/
	/* Début de boucle */
	compt_loop := 0;

	while (v_pa >= 3) loop
		compt_loop := compt_loop + 1;
		exit when compt_loop >= 12;

		/* on tente de lancer un sort de soutien */

		-- Calcul de la distance limite max par rapport aux sorts de soutien
		-- Attention : ne prend pas en compte les bonus / malus aux PA, en déplacement ou magie...
		-- => améliorable.
		-- initialisation de la variable
		distance_limite := 0;
		select into distance_limite
			min(max(sort_distance + ((v_pa - sort_cout) / getparm_n(9))), v_vue)
		from perso_sorts
		inner join sorts on sort_cod = psort_sort_cod
		where psort_perso_cod = v_monstre
			and sort_soutien = 'O';

		-- On choisit une cible
		/* On sélectionne d’abord une cible qui est à distance de sort */
		select into v_cible, distance_cible, v_pv, pos_cible
			perso_cod, max(abs(pos_x - v_x), abs(pos_y - v_y)), perso_pv * 100 / perso_pv_max, ppos_pos_cod
		from perso
		inner join perso_position on ppos_perso_cod = perso_cod
		inner join positions on pos_cod = ppos_pos_cod
		where pos_x between (v_x - distance_limite) and (v_x + distance_limite)
			and pos_y between (v_y - distance_limite) and (v_y + distance_limite)
			and pos_etage = v_etage
			and perso_type_perso = 1
			and perso_actif = 'O'
			and perso_tangible = 'O'
			and trajectoire_vue_murs(pos_actuelle, pos_cod) = 1
			and (not soigneur OR perso_pv * 100 / perso_pv_max <= 75)
			and not exists
				(select 1 from lieu
				inner join lieu_position on lpos_pos_cod = pos_cod
				where lpos_pos_cod = ppos_pos_cod
					and lieu_refuge = 'O')
		order by random()
		limit 1;

		if not found then	-- Pas de cibles à distance : on se rapproche d’une cible aléatoire
			select into v_cible, distance_cible, v_pv, pos_cible
				perso_cod, max(abs(pos_x - v_x), abs(pos_y - v_y)), perso_pv * 100 / perso_pv_max, ppos_pos_cod
			from perso
			inner join perso_position on ppos_perso_cod = perso_cod
			inner join positions on pos_cod = ppos_pos_cod
			where pos_x between (v_x - v_vue) and (v_x + v_vue)
				and pos_y between (v_y - v_vue) and (v_y + v_vue)
				and pos_etage = v_etage
				and perso_type_perso = 1
				and perso_actif = 'O'
				and perso_tangible = 'O'
				and trajectoire_vue_murs(pos_actuelle, pos_cod) = 1
				and not exists
					(select 1 from lieu
					inner join lieu_position on lpos_pos_cod = pos_cod
					where lpos_pos_cod = ppos_pos_cod
						and lieu_refuge = 'O')
			order by max(abs(pos_x - v_x), abs(pos_y - v_y))
			limit 1;
			code_retour := code_retour||'Pas de cible à distance pour soutien. Déplacement...\n';
		end if;

		code_retour := code_retour || 'Cible localisée : ' || v_cible::text || ' à distance ' || distance_cible::text || '\n';

		-- Choix du sort à lancer
		select into num_sort, fonction_sort psort_cod, sort_fonction
		from perso_sorts
		inner join sorts on sort_cod = psort_sort_cod
		where psort_perso_cod = v_monstre
			and sort_soutien = 'O'
			and (sort_cod not in (5, 10, 129) or v_pv <= 75)	-- Si la cible n’est pas blessée on exclut les soins
			and sort_distance >= distance_cible
			and sort_cout <= v_pa
		order by random()
		limit 1;

		if found then	-- on a un sort, on a une cible
			code_retour := code_retour||E'Lancement de sort de soutien.\n';
			update perso set perso_cible = v_cible where perso_cod = v_monstre;

			-- on construit la chaine de lancement du sort
			-- puis on lance le sort proprement dit
			fonction_sort := 'select nv_' || fonction_sort || '(' || trim(to_char(v_monstre, '9999999999')) || ', ' || trim(to_char(v_cible, '9999999999')) || ', 1)';
			execute fonction_sort;
			code_retour := code_retour||'Lancement de ' || fonction_sort ||E'.\n';
		else	-- déplacement...
			if statique_combat = 'N' then
				-- on récupère la case vers laquelle on se déplace
				-- on va sur cette nouvelle case
				-- on récupère les nouvelles infos
				pos_dest := dep_vers_cible(pos_actuelle, pos_cible);
				temp_txt := deplace_code(v_monstre, pos_dest);
			end if;
		end if;

		-- On finit la boucle, en relançant la procédure, si PA suffisants
		select into v_pa, pos_actuelle, v_x, v_y
			perso_pa, ppos_pos_cod, pos_x, pos_y
		from perso
		inner join perso_position on ppos_perso_cod = perso_cod
		inner join positions on pos_cod = ppos_pos_cod
		where perso_cod = v_monstre;

	end loop;
	return code_retour;
end;$_$;


ALTER FUNCTION public.ia_soutien_aventuriers(integer) OWNER TO delain;

--
-- Name: FUNCTION ia_soutien_aventuriers(integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.ia_soutien_aventuriers(integer) IS 'Gère l’IA des monstres aidant les aventuriers';


--
-- Name: identifie_perso_objet(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.identifie_perso_objet(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$declare
	v_perso alias for $1;
	v_obj_cod integer;
	ligne record;
begin
	for ligne in
		select perobj_cod
		from perso_objets,objets,objet_generique,type_objet
		where perobj_identifie != 'O'
		and perobj_obj_cod = obj_cod
		and perobj_perso_cod = v_perso
		and obj_gobj_cod = gobj_cod
		and gobj_tobj_cod = tobj_cod
		and tobj_identifie_auto = 1 loop
		update perso_objets
			set perobj_identifie = 'O'
			where perobj_cod = ligne.perobj_cod;
	end loop;
	return 0;
end;


	$_$;


ALTER FUNCTION public.identifie_perso_objet(integer) OWNER TO delain;

--
-- Name: FUNCTION identifie_perso_objet(integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.identifie_perso_objet(integer) IS 'Permet d''identifier automatiquement tous les objets d''un perso (se lance à chaque affichage d''inventaire)';


--
-- Name: identifier_objet(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.identifier_objet(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function identifier_objet : identifie un objet de l’inventaire*/
/* On passe en paramètres                                        */
/*    $1 = perso_cod                                             */
/*    $2 = obj_cod                                               */
/* Le code sortie est une chaine séparée par ;                   */
/*    Caractère 1 =>                                             */
/*       0 = tout est OK                                         */
/*      -1 = anomalie + description                              */
/* Ensuite, dans l ordre                                         */
/*      comp_cod                                                 */
/*      libelle de la competence                                 */
/*      pourcentage dans la competence                           */
/*      lancer des                                               */
/*      0 si comp ratée, 1 si réussie , -1 si echec auto         */
/* (si 0 ou -1, on arrête ici )                                  */
/*      num objet pour rappel                                    */
/*      nombre de px gagnés                                      */
/*      lancer des pour amelioration competence                  */
/*      1 si amélioration, 0 sinon                               */
/* (si 0, on arrête ici)                                         */
/*      nouvelle valeur compétence                               */
/*****************************************************************/
/* Créé le 19/03/2003                                            */
/* Liste des modifications :                                     */
/* 19/04/2006 : changement de l’amélioration pour rajouter       */
/*              les Pxs en cas de réussite                       */
/* 28/05/2012 : Rajout renommée artisanale                       */
/*****************************************************************/
declare
	code_retour text;
	limite_exp integer;
	personnage alias for $1;
	num_objet alias for $2;
-- variables de vérification
	compt integer;
	code_perobj perso_objets.perobj_cod%type;
	obj_identifie perso_objets.perobj_identifie%type;
	pa perso.perso_pa%type;
-- variables liées à la compétence
	comp_ident competences.comp_cod%type;
	nom_comp competences.comp_libelle%type;
	valeur_comp perso_competences.pcomp_modificateur%type;
	valeur_comp_modifie integer;
	des integer;
	amelioration integer;
	nouvelle_valeur_comp integer;
	temp_ameliore_competence text;
	gain_renommee numeric;		-- gain (ou perte) de renommée artisanale
-- variables liées aux évènements
	texte_evt text;
	nom_perso perso.perso_nom%type;
begin
	limite_exp := getparm_n(1);
	code_retour := '0'; -- par défaut, tout est OK
	gain_renommee := 0.1;
/********************************************/
/* Etape 1 : on vérifie que le perso existe */
/********************************************/
	select into pa perso_pa from perso where perso_cod = personnage;
	if not found then
		code_retour := '-1;Perso non trouvé !!';
		return code_retour;
	end if;
/********************************************/
/* Etape 2 : on vérifie que l’objet existe  */
/********************************************/
	select into compt obj_cod from objets
		where obj_cod = num_objet;
	if not found then
		code_retour := '-1;Objet inexistant';
		return code_retour;
	end if;
/***********************************************************/
/* Etape 3 : on vérifie que l’objet est dans l’inventaire  */
/***********************************************************/
	select into code_perobj perobj_cod
			from perso_objets
			where perobj_perso_cod = personnage
			and perobj_obj_cod = num_objet;
	if not found then
		code_retour := '-1;L’objet n’est pas dans l’inventaire';
		return code_retour;
	end if;
/********************************************************/
/* Etape 4 : on vérifie que l objet n est pas identifie */
/********************************************************/
	select into obj_identifie perobj_identifie
		from perso_objets
		where perobj_cod = code_perobj;
	if obj_identifie = 'O' then
		code_retour := '-1;L’objet est déjà identifié';
		return code_retour;
	end if;
/****************************************/
/* Etape 5 : on vérifie les PA du perso */
/****************************************/
	if pa < 2 then
		code_retour:= '-1;Pas assez de PA pour cette action';
		return code_retour;
	end if;
/****************************************/
/* Etape 6 : tout est vérifié, on passe */
/*   à la suite                         */
/****************************************/
-- 6.1 on retire les pa au joueur
	update perso
		set perso_pa = pa - 2
		where perso_cod = personnage;
-- 6.2 on recherche le type d objet pour déterminer la compétence à utiliser
	select into comp_ident tobj_ident_comp_cod
		from type_objet,objets,objet_generique
		where obj_cod = num_objet
		and obj_gobj_cod = gobj_cod
		and gobj_tobj_cod = tobj_cod;
	code_retour := code_retour || ';' || trim(to_char(comp_ident, '99999'));	-- retour pos 1

-- 6.3 on recherche le libellé de la compétence et son pourcentage
	select into nom_comp,valeur_comp comp_libelle,pcomp_modificateur
		from competences,perso_competences
		where comp_cod = comp_ident
		and pcomp_pcomp_cod = comp_cod
		and pcomp_perso_cod = personnage;
-- 6.3 bis : concentration
	select into compt concentration_perso_cod from concentrations
		where concentration_perso_cod = personnage;
	if found then
		valeur_comp_modifie := valeur_comp + 20;
		delete from concentrations where concentration_perso_cod = personnage;
	else
		valeur_comp_modifie := valeur_comp;
	end if;
	code_retour := code_retour || ';' || nom_comp || ';' || trim(to_char(valeur_comp_modifie, '999')); -- retour pos 2 et 3

-- 6.4 on fait un jet de dés et on regarde si on réussit la compétence
	des := lancer_des(1,100);
	code_retour := code_retour||';'||trim(to_char(des,'999')); -- retour pos 4
	if des > 96 then -- echec automatique
		gain_renommee := gain_renommee * (-2);
		code_retour := code_retour||';-1'; --retour pos 5
		return code_retour;
	end if;
	if des > valeur_comp_modifie then
		gain_renommee := gain_renommee * (-1);
		if valeur_comp <= limite_exp then
			temp_ameliore_competence := ameliore_competence_px(personnage, comp_ident, valeur_comp);
			code_retour := code_retour||';0;'||temp_ameliore_competence||';'; -- retour pos 5,6,7,8
		end if;
		code_retour := code_retour||';0;'; -- retour pos 5,6,7,8
		return code_retour;
	end if;
/****************************************/
/* Etape 7 : la compétence est réussie  */
/****************************************/
	code_retour := code_retour||';1;'||trim(to_char(num_objet,'99999999')); -- retour pos 5,6
-- 7.1 on met le marqueur identifié
	update perso_objets
		set perobj_identifie = 'O'
		where perobj_cod = code_perobj;
-- 7.2 on attribue des PX au joueur
	update perso
		set perso_px = perso_px + 1,
		perso_renommee_artisanat = perso_renommee_artisanat + gain_renommee
		where perso_cod = personnage;
-- 7.3 on met une ligne d evenement
	select into nom_perso perso_nom from perso
		where perso_cod = personnage;
	texte_evt := '[perso_cod1] a identifié l’objet n°' || trim(to_char(num_objet, '999999999'));
		values(nextval('seq_levt_cod'), 5, now(), 1, personnage, texte_evt, 'O', 'N');
	code_retour := code_retour||';1;'; -- retour pos 7
/**************************************************/
/* Etape 8 : on essaie d ameliorer la competence  */
/**************************************************/
	temp_ameliore_competence := ameliore_competence_px(personnage, comp_ident, valeur_comp);
	code_retour := code_retour||temp_ameliore_competence;
	return code_retour;
end;
$_$;


ALTER FUNCTION public.identifier_objet(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION identifier_objet(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.identifier_objet(integer, integer) IS 'Gère l’identification d’un objet.';


--
-- Name: if(boolean, character varying, character varying); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.if(boolean, character varying, character varying) RETURNS character varying
    LANGUAGE sql
    AS $_$SELECT CASE WHEN $1 THEN $2 ELSE $3 END$_$;


ALTER FUNCTION public.if(boolean, character varying, character varying) OWNER TO delain;

--
-- Name: indice_lieu(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.indice_lieu(integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$/********************************************************/
/* function indice_lieu                                       */
/* Donne une phrase d’indice sur la localisation d’un lieu    */
/* proche de la position donnée en paramètre (étage adjacent) */
/* parametres :                                               */
/*  $1 = pos_cod                                              */
/* Sortie :                                                   */
/*  code_retour = table contenant la liste des étages         */
/**************************************************************/
/**************************************************************/
/* Création - 09/10/2012 - Reivax                             */
/**************************************************************/
declare
	code_position alias for $1;
	code_etage integer;
	position_du_lieu integer;
	resultat character varying;

begin
	select into code_etage pos_etage
	from positions
	where pos_cod = code_position;

	select into resultat, position_du_lieu
		'Vous trouverez ' ||
			case when tlieu_cod in (1, 4) then 'une ' else 'un ' end ||
			lower(tlieu_libelle) ||
			' du nom de « ' ||
			lieu_nom ||
			' » à l’étage nommé « ' ||
			etage_libelle ||
			' »',
		lpos_pos_cod
	from lieu
	inner join lieu_type on tlieu_cod = lieu_tlieu_cod
	inner join lieu_position on lpos_lieu_cod = lieu_cod
	inner join positions on pos_cod = lpos_pos_cod
	inner join etage on etage_numero = pos_etage
	inner join etages_adjacents(code_etage) as ea ON ea = etage_numero
	where tlieu_cod in (1, 2, 4, 6, 9, 11, 13, 14, 17, 21, 22, 33)
	order by random()
	limit 1;

	select into resultat
		resultat || ', plutôt vers ' || indice_localisation(position_du_lieu) || '.';

	return resultat;
end;		$_$;


ALTER FUNCTION public.indice_lieu(integer) OWNER TO delain;

