COMMENT ON FUNCTION public.indice_lieu(integer) IS 'Donne un indice sur la localisation d’un lieu, choisi aléatoirement parmi ceux des étages proches de la position passée en paramètre.';


--
-- Name: indice_localisation(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.indice_localisation(integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$/***********************************************************/
/* function indice_localisation                                  */
/* Donne une information textuelle sur la position géographique  */
/* de la case donnée au sein de son étage                        */
/* L’étage est quadrillé en 9 zones                              */
/*  ----------                                                   */
/*  |NO| N|NE| Nord-ouest, Nord, Nord-est                        */
/*  |--|--|--|                                                   */
/*  | O| C| E| Ouest, centre, est                                */
/*  |--|--|--|                                                   */
/*  |SO| S|SE| sud-ouest, sud, sud-est                           */
/*  ----------                                                   */
/* parametres :                                                  */
/*  $1 = pos_cod                                                 */
/* Sortie :                                                      */
/*  code_retour = texte informatif (est, nord-est, centre, etc.) */
/*****************************************************************/
/*****************************************************************/
/* Création - 09/10/2012 - Reivax                                */
/*****************************************************************/
declare
	code_position alias for $1;  -- code de la position
	code_etage integer;          -- code de l’étage
	posX integer;                -- valeur X de la position fournie en paramètre
	posY integer;                -- valeur Y de la position fournie en paramètre
	minX integer;                -- valeur X minimale de l’étage
	maxX integer;                -- valeur X maximale de l’étage
	minY integer;                -- valeur Y minimale de l’étage
	maxY integer;                -- valeur Y maximale de l’étage
	centreX integer;             -- valeur X du centre de l’étage
	centreY integer;             -- valeur Y du centre de l’étage
	distanceX integer;           -- distance sur les X de la case donnée au centre de l’étage
	distanceY integer;           -- distance sur les Y de la case donnée au centre de l’étage
	rayonX integer;              -- distance sur les X du centre de l’étage vers le bord de la zone centrale
	rayonY integer;              -- distance sur les Y du centre de l’étage vers le bord de la zone centrale
	resultat character varying;

begin
	select into code_etage, posX, posY
		pos_etage, pos_x, pos_y
	from positions
	where pos_cod = code_position;

	select into minX, maxX, minY, maxY
		min(pos_x), max(pos_x), min(pos_y), max(pos_y)
	from positions
	where pos_etage = code_etage;

	centreX := ((maxX + minX) / 2)::integer;
	centreY := ((maxY + minY) / 2)::integer;

	distanceX := abs(posX - centreX);
	distanceY := abs(posY - centreY);

	rayonX := (abs(maxX - centreX) / 3)::integer;
	rayonY := (abs(maxY - centreY) / 3)::integer;

	select into resultat
		case
			when distanceX <= rayonX AND distanceY <= rayonY then 'le centre'
			when distanceX <= rayonX AND distanceY > rayonY AND posY > centreY then 'le nord'
			when distanceX <= rayonX AND distanceY > rayonY AND posY < centreY then 'le sud'
			when distanceX > rayonX AND distanceY <= rayonY AND posX > centreX then 'l’est'
			when distanceX > rayonX AND distanceY <= rayonY AND posX < centreX then 'l’ouest'
			when distanceX > rayonX AND distanceY > rayonY AND posX < centreX AND posY > centreY then 'le nord-ouest'
			when distanceX > rayonX AND distanceY > rayonY AND posX < centreX AND posY < centreY then 'le sud-ouest'
			when distanceX > rayonX AND distanceY > rayonY AND posX > centreX AND posY > centreY then 'le nord-est'
			when distanceX > rayonX AND distanceY > rayonY AND posX > centreX AND posY < centreY then 'le sud-est'
			else 'une position indéterminée...'
		end;

	return resultat;
end;		$_$;


ALTER FUNCTION public.indice_localisation(integer) OWNER TO delain;

--
-- Name: FUNCTION indice_localisation(integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.indice_localisation(integer) IS 'Donne une information textuelle sur la position géographique de la case donnée au sein de son étage.';


--
-- Name: init_1_avril(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.init_1_avril() RETURNS text
    LANGUAGE plpgsql
    AS $$/****************************************/
/* init 1er avril                       */
/****************************************/
declare
	code_retour text;
	ligne record;
	v_pos integer;
	v_compt integer;
	v_temp integer;
	v_texte text;
begin
	v_compt := 0;
	for ligne in
		select * from perso
		where perso_type_perso = 2
		and perso_actif = 'O'
		and perso_dirige_admin = 'O' loop
	-- sauvegarde des positions des persos hors IA
		select into v_pos ppos_pos_cod
			from perso_position
			where ppos_perso_cod = ligne.perso_cod;
	-- on le déplace :
	-- 1 on vire les locks
		delete from lock_combat where lock_cible = ligne.perso_cod;
		delete from lock_combat where lock_attaquant = ligne.perso_cod;
	-- 2 on vire dans l'ile aux enfants
		update perso_position set ppos_pos_cod = pos_aleatoire(4)
			where ppos_perso_cod = ligne.perso_cod;
	-- 3 on remplace
		v_temp := cree_monstre_pos(236,v_pos);
		v_compt := v_compt + 1;
	end loop;
	code_retour := trim(to_char(v_compt,'9999999999'))||' monstres hors IA déplacés et remplacés, ';
	v_compt := 0;
	for ligne in
		select perso_cod,ppos_pos_cod from perso,perso_position
		where perso_type_perso = 2
		and perso_actif = 'O'
		and (perso_dirige_admin = 'N' or perso_dirige_admin is null) and ppos_perso_cod = perso_cod loop
	-- 1 on vire les locks
		delete from lock_combat where lock_cible = ligne.perso_cod;
		delete from lock_combat where lock_attaquant = ligne.perso_cod;
	-- 2 on supprime cette fois le perso
		update perso set perso_actif = 'N' where perso_cod = ligne.perso_cod;
	-- 3 on remplace
		v_temp := cree_monstre_pos(236,ligne.ppos_pos_cod);
		v_compt := v_compt + 1;
	end loop;
	code_retour := code_retour||trim(to_char(v_compt,'9999999999'))||' monstres IA remplacés, ';
	v_compt := 0;
	for ligne in
		select * from perso
		where perso_type_perso = 1
		and perso_actif = 'O'
		loop
		v_texte := cree_objet_perso_nombre(226,ligne.perso_cod,1);
		v_compt := v_compt + 1;
	end loop;
	code_retour := code_retour||trim(to_char(v_compt,'9999999999'))||' poissons ditribués.';
	return code_retour;
end;$$;


