--
-- Name: init_rune(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.init_rune() RETURNS text
    LANGUAGE plpgsql
    AS $$/*******************************************************/
/* fonction init_rune                                  */
/*******************************************************/
declare
	code_retour text;
	ligne record;
	v_pos integer;
	v_rune integer;
	v_objet integer;
begin
	code_retour := '';
	delete from sort_rune;
	for ligne in select * from sorts loop
		for v_pos in 1..6 loop
			v_rune := to_number(substr(ligne.sort_combinaison,v_pos,1),'9');
			if ((v_rune != 0) and (v_rune != 9) and (v_rune != 8)) then
				select into v_objet gobj_cod from objet_generique
					where gobj_rune_position = v_rune
					and gobj_frune_cod = v_pos;
				if not found then
					code_retour := 'Sort '||trim(to_char(ligne.sort_cod,'9999'))||' pos '||trim(to_char(v_pos,'999'))||' rune '||trim(to_char(v_rune,'9999'));
					return code_retour;
				end if;
				code_retour := code_retour||trim(to_char(v_objet,'9999'))||';';
			end if;
		end loop;
	end loop;
	return code_retour;
end;$$;


ALTER FUNCTION public.init_rune() OWNER TO delain;

--
-- Name: init_stock(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.init_stock() RETURNS integer
    LANGUAGE plpgsql
    AS $$/*********************************************************/
/* fonction init_stock : remplit les magasins            */
/*********************************************************/
declare
	l_mag record;
	l_objet record;
	qte integer;
	num_objet integer;
	num_gobj integer;
	temp integer;

begin
	for l_mag in select * from lieu where lieu_tlieu_cod in (11,14,21) loop
		for l_objet in select * from stock_magasin_defaut where dmstock_lieu_cod = l_mag.lieu_cod loop
			temp := 0;
			while temp <= l_objet.dmstock_qte loop
				num_objet := nextval('seq_obj_cod');
				temp := temp + 1;
			end loop;
		end loop;
	end loop;
	return 0;
end;$$;


