--

CREATE FUNCTION public.is_riposte(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/**********************************************/
/* fonction is_riposte : dit si une riposte   */
/*  est en cours                              */
/* on passe en paramètres :                   */
/*  $1 = cible                                */
/*  $2 = attaquant                            */
/* on a en retour un entier :                 */
/*   0 = pas de riposte                       */
/*   1 = riposte                              */
/**********************************************/
declare
	code_retour integer;
	v_cible alias for $1;
	v_attaquant alias for $2;
	v_riposte integer;
	type_attaquant integer;
begin
	select into v_riposte riposte_cod
		from riposte
		where riposte_cible = v_cible
		and riposte_attaquant = v_attaquant;
	if not found then
	-- aucune riposte
		code_retour := 0;
	else
	-- riposte
		code_retour := 1;
	end if;
	/*select into type_attaquant perso_type_perso from perso where perso_cod = v_attaquant;
	if type_attaquant = 2 then
		code_retour := 0;
	end if;*/
	return code_retour;
end;
$_$;


ALTER FUNCTION public.is_riposte(integer, integer) OWNER TO delain;

--
-- Name: is_surcharge(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.is_surcharge(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*********************************************/
/* fonction is_surcharge                     */
/*  on passe en params :                     */
/*     $1 = perso_cod cible                  */
/*     $21 = perso_cod attaquant             */
/*  on a en retour un entier :               */
/*     0 = pas surchargé                     */
/*     1 = partiellement                     */
/*     2 = totalement                        */
/*********************************************/
declare
	code_retour integer;
	attaquant alias for $2;
	cible alias for $1;
	taille_cible numeric;
	nb_lock integer;

begin
	code_retour := 0;
	select into taille_cible perso_taille
		from perso where perso_cod = cible;
	select into nb_lock
		count(lock_cod)
		from lock_combat
		where lock_cible = cible
		and lock_attaquant != attaquant;
	if nb_lock <= taille_cible then
		code_retour := 0;
		return code_retour;
	end if;
	if nb_lock >= (2*taille_cible) then
		code_retour := 2;
		return code_retour;
	end if;
	if nb_lock > taille_cible then
		code_retour := 1;
		return code_retour;
	end if;
end;
	$_$;


ALTER FUNCTION public.is_surcharge(integer, integer) OWNER TO delain;

--
-- Name: is_visible_groupe(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.is_visible_groupe(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*********************************************/
/* is_visible_groupe                         */
/*  $1 = groupe_cod                          */
/*  $2 = perso_cod                           */
/* retourne 1 si le perso est visible par    */
/*  le groupe                                */
/*********************************************/
declare
	code_retour integer;
	v_groupe alias for $1;
	v_perso alias for $2;
	v_chef integer;
	v_pos_chef integer;
	v_pos_perso integer;
	v_etage_chef integer;
	v_etage_perso integer;
begin
	select into v_chef
		groupe_chef
		from groupe,groupe_perso
		where pgroupe_perso_cod = v_perso
		and pgroupe_statut = 1
		and pgroupe_groupe_cod = groupe_cod;
	if not found then
		return 0; -- pas de groupe associé au perso
	end if;
	if v_chef = v_perso then
		return 1; -- le perso est le chef
	end if;
	select into v_pos_chef,v_etage_chef
		pos_cod,pos_etage
		from perso_position,positions
		where ppos_perso_cod = v_chef
		and ppos_pos_cod = pos_cod;
	if not found then
		return 0;
	end if;
	select into v_pos_perso,v_etage_perso
		pos_cod,pos_etage
		from perso_position,positions
		where ppos_perso_cod = v_perso
		and ppos_pos_cod = pos_cod;
	if v_etage_perso != v_etage_chef then
		return 0;
	end if;
	if distance(v_pos_perso,v_pos_chef) <= 10 then
		return 1;
	end if;
	return 0;
end;$_$;


ALTER FUNCTION public.is_visible_groupe(integer, integer) OWNER TO delain;

--
-- Name: joueur_inactif(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.joueur_inactif(integer) RETURNS text
    LANGUAGE plpgsql
    AS $$/********************************************/
/* Fonction joueur_inactif                  */
/*   transforme les joueurs inactifs en     */
/*   monstres                               */
/********************************************/
/* On passe en paramètre un entier          */
/********************************************/
/* le code retour est un texte              */
/********************************************/
declare
	code_retour text;
	ligne record;
	ligne2 record;
	compt integer;
	delai interval;
	texte_admin text;
	temp integer;
	v_etage integer;
begin
	compt := 0;
	code_retour := '';
	delai := trim(to_char(getparm_n(14),'9999'))||' days';
	-- 1 : persos inactifs
	for ligne in select * from perso
		where perso_type_perso = 1
		and perso_actif = 'O'
		and perso_der_connex + delai < now()
		and perso_pnj != 1
		loop
		temp := monstrifie_perso(ligne.perso_cod);
	end loop;
	code_retour := trim(to_char(compt,'999999'))||' persos transformés en monstres';
	compt := 0;
	-- 2 : perso inactifs hibernés
	for ligne in select * from perso
		where perso_type_perso = 1
		and perso_actif = 'H'
		and perso_der_connex + '360 days'::interval < now()
		loop
		temp := monstrifie_perso(ligne.perso_cod);
	end loop;
	-- 3 : on supprime l'impalpabilité
	for ligne in
		select * from perso
		where perso_dfin_tangible <= now()
		and perso_type_perso = 2 loop
		-- on prend l'étage
		select pos_etage into v_etage
			from perso_position,positions
			where ppos_perso_cod = ligne.perso_cod
			and ppos_pos_cod = pos_cod;
		-- on les réactive
		update perso set perso_tangible = 'O', perso_dfin_tangible = null
			where perso_cod = ligne.perso_cod;
		-- on dispatche l'inventaire
		for ligne2 in
			select * from objets,perso_objets,objet_generique
			where perobj_perso_cod = v_perso
			and perobj_obj_cod = obj_cod
			and obj_gobj_cod = gobj_cod
			loop
			-- on supprime l'objet de l'inventaire
			delete from perso_objets
				where perobj_cod = ligne2.perobj_cod;
			-- on le met quelque part dans l'étage
		end loop;
	end loop;
	code_retour := 0;
	return code_retour;

end;
$$;


ALTER FUNCTION public.joueur_inactif(integer) OWNER TO delain;

--
-- Name: lance_fonction(integer, integer, numeric, numeric, numeric, integer, integer, integer, integer, text, text); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.lance_fonction(integer, integer, numeric, numeric, numeric, integer, integer, integer, integer, text, text) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function lance_fonction : à partir d'un code et de paramètre, */
/* lance le résultat soit par fonction, soit par code						 */
/* On passe en paramètres                                        */
/*   $1 = fonction à lancer                                      */
/*   $2 = param1                                                 */
/*   $3 = param2                                                 */
/*   $4 = param3                                                 */
/*   $5 = param4                                                 */
/*   $6 = param5                                                 */
/*   $7 = param6                                                 */
/*   $8 = param7                                                 */
/*   $9 = param8                                                 */
/*   $10 = param9                                                */
/*   $11 = param10                                                */
/*****************************************************************/
/* Créé le 10/05/2010                                            */
/*****************************************************************/
declare
-------------------------------------------------------------
-- variables servant pour la sortie
-------------------------------------------------------------
	code_retour text;				-- chaine html de sortie
-------------------------------------------------------------
-- variables concernant le lanceur
-------------------------------------------------------------
	fonction alias for $1;		--
	param1 alias for $2;		--
	param2 alias for $3;		--
	param3 alias for $4;		--
	param4 alias for $5;		--
	param5 alias for $6;		--
	param6 alias for $7;		--
	param7 alias for $8;		--
	param8 alias for $9;		--
	param9 alias for $10;		--
	param10 alias for $11;		--
	temp integer;
	desc text;
	v_num_mes integer;
	v_desc text;
	v_nom text;
	v_mobile text;
	v_refuge text;
	ligne_perso record;
/******************************************************/
/*1	Création de monstres en nombre sur une position
2	Création de GB
3	Création d'objets sur une position
4	Création d'objets pour un perso
5	Création de murs
6	Rajout d'une fonction_dessus pour une position (par exemple ajout bonus malus ou autre)
7	Envoi d'un message à tout le groupe
8	Envoi d'un message à tous les persos de l'étage
9	Modification de lieu existant
10 Création de cachette ==>Pas opérationnel
11 Création de piège (nécessite de connaître la bonne syntaxe des pièges)
12 destruction de murs
13 Création ou destruction de lieu
14 Destruction de monstres sur une position
15 Destruction de monstres dans un étage complet
16 Changement de paramètre d'un objectif
17 Envoi d'une rumeur
18 Téléportation de persos vers un point B. Attention, risque de concerner tous les persos d'un groupe, sauf si l'objectif doit être pris par un groupe
19 Modification paramètre mission
*/
/******************************************************/

begin
	code_retour := '';
	--On lance les différents cas
	if fonction = 1 then --param1 = gmon_cod, param2 = pos_cod, param3 = nombre
		select into code_retour cree_monstre_pos_nombre(param1,cast(param2 as integer),cast(param3 as integer));
		return code_retour;
	elseif fonction = 2 then -- param1 = gmon_cod, param2 = pos_cod, param3 = facteur Carac, param4 = facteur PV, param5 = variation DLT (nombre), param6 = bonus dégâts, , param7 = bonus armure, param8 = bonus Régèn, param9 = Nom, param10 = Description
		select into code_retour cree_monstre_pos_nombre(param1,cast(param2 as integer),1);
		code_retour := trim (both ';' from code_retour);
		update perso set perso_int = floor(perso_int * param3),
						perso_for = floor(perso_for * param3),
						perso_dex = floor(perso_dex * param3),
						perso_con = floor(perso_con * param3),
						perso_pv_max = floor(perso_pv_max * param4),
						perso_pv = floor(perso_pv * param4),
						perso_temps_tour = perso_temps_tour - param5,
						perso_amelioration_degats = perso_amelioration_degats + param6,
						perso_amel_deg_dex = perso_amel_deg_dex+ param6,
						perso_amelioration_armure = perso_amelioration_armure + param7,
						perso_amelioration_regen = perso_amelioration_regen +param8,
						perso_lower_perso_nom = lower(param9),
						perso_nom = param9,
						perso_niveau = floor(param3 * perso_niveau),
						perso_description = param10
						where perso_cod = code_retour;
		return code_retour;
	elsif fonction = 3 then --param1 = gobj_cod, param2 = pos_cod
		select into code_retour cree_objet_pos(param1,cast(param2 as integer));
		code_retour := '';
	elsif fonction = 4 then --param1 = gobj_cod, param2 = perso_cod, param3 = nombre
		select into code_retour cree_objet_perso_nombre(param1,cast(param2 as integer),cast(param3 as integer));
		code_retour := '';
	elsif fonction = 5 then --param1 = mur_pos_cod, param2 = mur_usure, param3 = mur_richesse, param9 = mur_tangible, param10 = mur_creusable
		select into temp mur_pos_cod from murs where mur_pos_cod = param1;
		if found then
			code_retour := 'mur déjà existant';
		else
								values (param1,param2,param3,param9,param10);
			perform init_automap_pos (param1);
			code_retour := cast(param1 as text);
		end if;
	elsif fonction = 6 then --param1 = pos_cod, param9 = fonction_arrivee
		select into temp pos_cod from positions where pos_cod = param1 and pos_fonction_dessus not in (null,'');
		if found then
			code_retour := 'Fonction déjà existante !';
		else
			update positions set pos_fonction_dessus = param9 where pos_cod = param1;
			code_retour := cast(param1 as text);
		end if;
	elsif fonction = 7 then --param1 = group_cod, param9 = Titre, param10 = corps
		v_num_mes := nextval('seq_msg_cod');
			values (v_num_mes,209808);
			for ligne_perso in select mgroupe_perso_cod from quetes.mission_groupe where mgroupe_groupe_cod = param1 loop
													values (v_num_mes,ligne_perso.mgroupe_perso_cod,'N','N');
			end loop;
	elsif fonction = 8 then --param1 = etage_cod, param9 = Titre, param10 = corps
		v_num_mes := nextval('seq_msg_cod');
			values (v_num_mes,209808);
			for ligne_perso in select ppos_perso_cod from perso_position,positions,perso
													where ppos_pos_cod = pos_cod
													and pos_etage = param1
													and perso_actif = 'O'
													and perso_type_perso = 1
													and ppos_perso_cod = perso_cod loop
													values (v_num_mes,ligne_perso.ppos_perso_cod,'N','N');
			end loop;
	elsif fonction = 9 then --param1 = lieu_cod, param2 = lieu_dest, param3 = lieu_refuge (attention, passage par numérique), param9 = lieu_url, param10 = lieu_description
		if param2 = 999999 then --On annule le lieu de destination
			update lieu set lieu_dest = null where lieu_cod = param1;
		elsif param2 != 0 then --On change le lieu si c'est différent de 0 sinon on le garde
			update lieu set lieu_dest = param2 where lieu_cod = param1;
		end if;
		if param3 = 1 then
			update lieu set lieu_refuge = 'O' where lieu_cod = param1;
		elsif param3 = 2 then
			update lieu set lieu_refuge = 'N' where lieu_cod = param1;
		end if;
		if param9 = ' ' then
			--On ne change rien
		elsif param9 = 0  then --On supprime l'url
			update lieu set lieu_url = '' where lieu_cod = param1;
		else
			update lieu set lieu_url = param9 where lieu_cod = param1;
		end if;
		v_desc := split_part(param10 , '#', 1);
		v_nom := split_part(param10 , '#', 2);
		if v_desc = 0 or v_desc = ' ' or v_desc = '' then
			--On ne change rien
		else
			update lieu set lieu_description = v_desc where lieu_cod = param1;
		end if;
		if v_nom = 0 or v_nom = ' ' or v_nom = '' then
			--On ne change rien
		else
			update lieu set lieu_nom = v_nom where lieu_cod = param1;
		end if;
	elsif fonction = 11 then --param1 = pos_cod, param9 = pos_fonction_arrivee
		select into temp pos_cod from positions where pos_cod = param1 and pos_fonction_arrivee not in (null,'');
		if found then
			code_retour := 'Fonction déjà existante !';
		else
			update positions set pos_fonction_arrivee = param9 where pos_cod = param1;
			code_retour := cast(param1 as text);
		end if;
	elsif fonction = 12 then --param1 = mur_pos_cod
		select into temp mur_pos_cod from murs where mur_pos_cod = param1;
		if not found then
			code_retour := 'pas de mur existant';
		else
			delete from murs where mur_pos_cod = param1;
			perform init_automap_pos (param1);
			code_retour := cast(param1 as text);
		end if;
	elsif fonction = 13 then --param1 = lieu_pos_cod, param2 = lieu_dest, param3 = lieu_refuge (attention, passage par numérique),param4 = création ou destruction,param5 = type de lieu,param6 = lieu_mobile (attention, passage par numérique), param9 = lieu_url, param10 = nom et lieu_description séparé par #  !!!
		if param4 = 1 then -- alors création
			if param3 = 0 then
				v_refuge = 'N';
			elsif param3 = 1 then
				v_refuge = 'O';
			end if;
			if param6 = 0 then
				v_mobile = 'N';
			elsif param6 = 1 then
				v_mobile = 'O';
			end if;
			v_num_mes := nextval('seq_lieu_cod');
			v_desc := split_part(param10 , '#', 1);
			v_nom := split_part(param10 , '#', 2);
								values (v_num_mes,param2,v_refuge,param5,v_mobile,param9,v_nom,v_desc);
												values (param1,v_num_mes);
		elsif param4 = 0 then -- alors destruction de lieu
			select into v_num_mes lpos_lieu_cod from lieu_position where lpos_pos_cod = param1;
			delete from lieu where lieu_cod = v_num_mes;
			delete from lieu_position where lpos_lieu_cod = v_num_mes;
		end if;
	elsif fonction = 14 then --param1 = pos_cod
		update perso set perso_actif = 'N'
			where perso_cod in ((select ppos_perso_cod from perso_position where ppos_pos_cod = param1)) and perso_type_perso = 2;

	elsif fonction = 15 then --param1 = etage_numero
		update perso set perso_actif = 'N'
			where perso_cod in ((select ppos_perso_cod from perso_position,positions where ppos_pos_cod = pos_cod and pos_etage = param1))
			and perso_type_perso = 2;

	elsif fonction = 16 then --param1 = mobject_cod,param2 = mobject_perso_cod,param3 =	mobject_pos_cod,param4 = mobject_temps,param9 = mobject_param_text,param10 = mobject_date_deb
		if param2 = 0 then --On ne fait rien
		elsif param2 = 1 then --On annule le perso_cod
			update quetes.mission_objectif set mobject_perso_cod = 'null' where mobject_object_cod = param1;
		else
			update quetes.mission_objectif set mobject_perso_cod = param2 where mobject_object_cod = param1;
		end if;
		if param3 = 0 then --On ne fait rien
		elsif param3 = 1 then --On annule le pos_cod
			update quetes.mission_objectif set mobject_pos_cod = 'null' where mobject_object_cod = param1;
		else
			update quetes.mission_objectif set mobject_pos_cod = param3 where mobject_object_cod = param1;
		end if;
		if param4 = 0 then --On ne fait rien
		elsif param4 = 1 then --On annule le mobject_temps
			update quetes.mission_objectif set mobject_temps = 'null' where mobject_object_cod = param1;
		else
			update quetes.mission_objectif set mobject_temps = param4 where mobject_object_cod = param1;
		end if;
		if param9 = ' ' or param9 = ''  then
			--On ne change rien
		elsif param9 = 0 then -- supprime les valeurs dans cet objectif
			update quetes.mission_objectif set mobject_param_text = '' where mobject_object_cod = param1;
		else
			update quetes.mission_objectif set mobject_param_text = param9 where mobject_object_cod = param1;
		end if;
	/*Non fonctionnel !!!!! Pas de cross database ...
			v_num_mes := nextval('z_forum.public.phpbb_posts_id_seq');
			temp := nextval('phpbb_topics_id_seq');
																				values(v_num_mes,temp,55,4);
																			values (temp,55,'Je suis un titre',4);
																					values (temp,'Je suis le contenu');*/
	elsif fonction = 17 then --param1 = rum_poids, param9 = rum_texte
	elsif fonction = 18 then --param1 = [groupe], param2 = ppos_cod
			for ligne_perso in select mgroupe_perso_cod from quetes.mission_groupe where mgroupe_groupe_cod = param1 loop
				update perso_position set ppos_pos_cod = param2 where ppos_perso_cod = ligne_perso.mgroupe_perso_cod;
			end loop;
	elsif fonction = 19 then --param1 = mission, param2 = mission_date_deb (si 0 on ne fait rien, si 1 réinitialisation,param3 = mission_delai
		if param2 = 1 then --On réinitialise
			update quetes.mission set mission_date_deb = now() where mission_cod = param1;
		end if;
		if param3 > 0 then --On réinitialise
			update quetes.mission set mission_delai = param3 where mission_cod = param1;
		end if;
	else
		code_retour := '';
	end if;
	return code_retour;
end;
$_$;


ALTER FUNCTION public.lance_fonction(integer, integer, numeric, numeric, numeric, integer, integer, integer, integer, text, text) OWNER TO delain;

--
-- Name: lancer_des(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.lancer_des(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function lancer_des : Procédure de lancer de dés              */
/* On passe en paramètres  :                                     */
/*    1 le nombre de dés                                         */
/*    2 la valeur des dés                                        */
/* En sortie, on a le résultat du lancer                         */
/* Ex : select lancer_des(3,6) donnera en sortie 3D6             */
/*****************************************************************/
declare
	resultat integer;
	nb_des alias for $1;
	val_des alias for $2;
	val_des_moins integer;
	resultat_intermediaire integer;
	avril integer;
	i integer;
begin
	avril := 0;
	i := 1;
	-- ajout par Merrick, on arrête tout si le nombre de dés est supérieur à 100 000
	-- ca va provoquer un plantage de la fonction appelante, et on va aller voir à l'intérieur ce qu'il y a
	-- car ce n'est pas normal
	-- on provoque donc un plantage pour division par zéro
	if (nb_des > 100000) then
		resultat := i/avril;
		return resultat;
	end if;
	resultat := 0;
	val_des_moins := val_des - 1;
	/*Mise en commentaire du précédent premier avril Blade remplacé par nouveau
	if to_char(now(),'DD/MM/YYYY') = '01/04/2009' then
		if val_des = 100 then
			avril := 1;
				while i <= nb_des loop
					resultat_intermediaire := trunc(5*random()) + 97;
					resultat := resultat + resultat_intermediaire;
					i := i + 1;
				end loop;
		end if;
	end if;*/
	if avril = 0 then
		while i <= nb_des loop
			resultat_intermediaire := trunc(val_des*random()) + 1;
			resultat := resultat + resultat_intermediaire;
			i := i + 1;
		end loop;
	end if;
	return resultat;
end;$_$;


ALTER FUNCTION public.lancer_des(integer, integer) OWNER TO delain;

