--

CREATE FUNCTION public.lieu_arrive() RETURNS integer
    LANGUAGE plpgsql
    AS $$/*************************************************************/
/* fonction lieu_arrive : donne un pos_cod au lvl 0 pour les */
/*   lieux d’arrivée                                         */
/*************************************************************/
declare
	code_retour integer;
	cp_lieu integer;
	temp integer;
begin
	select into cp_lieu
		count(lieu_cod)
		from lieu,lieu_position,positions
		where lieu_tlieu_cod in (15,23)
		and lieu_cod = lpos_lieu_cod
		and lpos_pos_cod = pos_cod
		and pos_etage = 0;
	temp := lancer_des(1,cp_lieu);
	temp := temp - 1;
	select into temp
		pos_cod
 		from lieu,lieu_position,positions
		where lieu_tlieu_cod in (15,23)
		and lieu_cod = lpos_lieu_cod
		and lpos_pos_cod = pos_cod
		and pos_etage = 0
		offset temp
		limit 1;
	return temp;
end;
		$$;


