--
-- Name: limite_niveau(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.limite_niveau(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
/*****************************************************************/
/* function limite_niveau : calcule le nombre d XP pour lequel   */
/*   un joueur peut passer au niveau suivant                     */
/* On passe en paramètres  :                                     */
/*    1 le perso cod                                             */
/* En sortie, on a le nombre d XP                                */
/*****************************************************************/
declare
	resultat integer;
	personnage alias for $1;
	niveau perso.perso_niveau%type;
	n_1 integer;
begin
	select into niveau perso_niveau from perso
		where perso_cod = personnage;
	n_1 := niveau - 1;
	resultat := 5*((n_1*n_1)+(3*n_1)+2);
	return resultat;
end;
$_$;


ALTER FUNCTION public.limite_niveau(integer) OWNER TO delain;

--
-- Name: limite_niveau_actuel(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.limite_niveau_actuel(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function limite_niveau_actuel : calcule le nombre d XP du     */
/*   niveau actuel                                               */
/* On passe en paramètres  :                                     */
/*    1 le perso cod                                             */
/* En sortie, on a le nombre d XP                                */
/*****************************************************************/
declare
	resultat integer;
	personnage alias for $1;
	niveau perso.perso_niveau%type;
	n_1 integer;
begin
	select into niveau perso_niveau from perso
		where perso_cod = personnage;
	n_1 := niveau - 2;
	resultat := 5*((n_1*n_1)+(3*n_1)+2);
	return resultat;
end;
$_$;


