--
-- Name: magasin_destocker(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.magasin_destocker(integer, integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************************************/
/* fonction magasin_destockage : Un gérant retire des objets dans son stock */
/* On passe en paramètres :                                               */
/*   $1 = perso_cod du gérant                                             */
/*   $2 = lieu_cod du magasin                                             */
/*   $3 = obj_cod de l'objet acheté                                       */
/*   $3 = nombre_obj nombre d'objets                                      */
/* On a retour une chaine HTML exploitable par action.php                 */
/**************************************************************************/
/* Créé le 08/03/2004                                                     */
/* ATTENTION ! NE CONCERNE QUE LES OBJETS MODIFIES                        */
/**************************************************************************/
declare
----------------------------------------------------------------------------
-- variable de retour
----------------------------------------------------------------------------
	code_retour text;					-- texte formatté
----------------------------------------------------------------------------
-- variable concernant le joueur
----------------------------------------------------------------------------
	personnage alias for $1;		-- perso_cod du joueur
----------------------------------------------------------------------------
-- variable concernant le magasin
----------------------------------------------------------------------------
	v_magasin alias for $2;			-- lieu_cod du magasin
	v_mag_caisse integer;
	pos_magasin integer;				-- position du magasin
	montant_marge integer;			-- marge encaissée par le magasin
	montant_prelev integer;			-- montant reversé à l'administration
	prix_origine integer;			-- prix sans marge
	marge integer;						-- marge du magasin
	prelev integer;					-- % de reversement
----------------------------------------------------------------------------
-- variable concernant l'objet
----------------------------------------------------------------------------
	num_objet alias for $3;			-- obj_cod de l'objet acheté
	nombre_obj alias for $4;			-- obj_cod de l'objet acheté
	prix_total integer;				-- prix total de la transaction
	prix_init integer;				-- prix de l'objet hors modificateur
	num_init integer;				-- nombre d'objets deja en stock
	nom_objet text;					-- nom de l'objet
----------------------------------------------------------------------------
-- variable de calcul
----------------------------------------------------------------------------
	temp integer;						-- fourre tout
	modificateur numeric;			-- modif du prix de vente
	bonus_prix integer;
begin
----------------------------------------------------------------------------
-- Etape 1 : vérification
----------------------------------------------------------------------------

	select into temp,marge,prelev ,v_mag_caisse
			lieu_cod,lieu_marge,lieu_prelev,lieu_compte
		from lieu
		where lieu_cod = v_magasin;
	if not found then
		code_retour := '<p>Erreur ! Magasin non trouvé !';
		return code_retour;
	end if;

	select into nom_objet,prix_init
		gobj_nom,gobj_valeur from objet_generique
		where gobj_cod = num_objet;
	prix_total := prix_init * nombre_obj;


	select into num_init
		mgstock_nombre
	from stock_magasin_generique
	where mgstock_gobj_cod = num_objet and mgstock_lieu_cod = v_magasin;

	if not found then
		code_retour := '<p> Erreur ! Vous n''avez pas assez d''objets de ce type en stock !';
		return code_retour;
	else
		if nombre_obj > num_init then
			code_retour := '<p> Erreur ! Vous n''avez pas assez d''objets de ce type en stock !';
			return code_retour;
		end if;
		-- On RETIRE les BRs

		update lieu set lieu_compte = lieu_compte + prix_total where lieu_cod = v_magasin;

		-- MAJ DU STOCK

		update stock_magasin_generique
			set mgstock_nombre = mgstock_nombre - nombre_obj
			where mgstock_gobj_cod = num_objet
			and mgstock_lieu_cod = v_magasin;
  -- AJOUT DANS LE LOG

	end if;

	code_retour := '<p>Vous avez vendu <b>'||CAST(nombre_obj AS text)||' '||nom_objet||'</b> pour une somme totale de <b>'||CAST(prix_total AS text)||'Br</b></p>';

	return code_retour;
end;
$_$;


ALTER FUNCTION public.magasin_destocker(integer, integer, integer, integer) OWNER TO delain;

--
-- Name: magasin_identifie(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.magasin_identifie(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************************************/
/* fonction magasin_identifie : gère l'identification d'un objet dans un  */
/*   magasin                                                              */
/* On passe en paramètres :                                               */
/*   $1 = perso_cod du joueur                                             */
/*   $2 = lieu_cod du magasin                                             */
/*   $3 = obj_cod de l'objet acheté                                       */
/* On a retour une chaine HTML exploitable par action.php                 */
/**************************************************************************/
/* Créé le 08/03/2004                                                     */
/**************************************************************************/
declare
----------------------------------------------------------------------------
-- variable de retour
----------------------------------------------------------------------------
	code_retour text;					-- texte formatté
----------------------------------------------------------------------------
-- variable concernant le joueur
----------------------------------------------------------------------------
	personnage alias for $1;		-- perso_cod du joueur
	qte_or integer;					-- nb de brouzoufs du joueur
	pos_joueur integer;
	karma_perso numeric;			-- karma du joueur

----------------------------------------------------------------------------
-- variable concernant le magasin
----------------------------------------------------------------------------
	magasin alias for $2;			-- lieu_cod du magasin
	pos_magasin integer;
		montant_marge integer;			-- marge encaissée par le magasin
	montant_prelev integer;			-- montant reversé à l'administration
	prix_origine integer;			-- prix sans marge
	marge integer;						-- marge du magasin
	prelev integer;					-- % de reversement
----------------------------------------------------------------------------
-- variable concernant l'objet
----------------------------------------------------------------------------
	num_objet alias for $3;			-- obj_cod de l'objet acheté
	prix_objet integer;				-- prix de l'objet
	prix_init integer;				-- prix de l'objet hors modificateur
	nom_objet text;					-- nom de l'objet
----------------------------------------------------------------------------
-- variable de calcul
----------------------------------------------------------------------------
	temp integer;						-- fourre tout
	modificateur numeric;			-- modif du prix de vente
	cout integer;
begin
----------------------------------------------------------------------------
-- Etape 1 : vérification
----------------------------------------------------------------------------
	select into qte_or,karma_perso perso_po,perso_kharma
		from perso
		where perso_cod = personnage;
	if not found then
		code_retour := '<p>Erreur ! Acheteur non trouvé !';
		return code_retour;
	end if;
	select into pos_joueur
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	if not found then
		code_retour := '<p>Erreur ! Position acheteur non trouvé !';
		return code_retour;
	end if;

	select into temp,marge,prelev lieu_cod,lieu_marge,lieu_prelev
		from lieu
		where lieu_cod = magasin;
	if not found then
		code_retour := '<p>Erreur ! Magasin non trouvé !';
		return code_retour;
	end if;
	select into temp
		perobj_cod
		from perso_objets
		where perobj_perso_cod = personnage
		and perobj_obj_cod = num_objet;
	if not found then
		code_retour := '<p>Erreur ! L''objet n''est pas dans votre inventaire !';
		return code_retour;
	end if;
	if qte_or < (100 + marge) then
		code_retour := '<p>Erreur ! Vous n''avez pas assez de brouzoufs pour faire identifier cet objet !';
		return code_retour;
	end if;
	select into prix_init,nom_objet obj_valeur,obj_nom
		from objets
		where obj_cod = num_objet;
----------------------------------------------------------------------------
-- Etape 2 : on passe à l'identification
----------------------------------------------------------------------------
-- on ajoute les brouzoufs
	update perso
		set perso_po = perso_po - 100 - marge
		where perso_cod = personnage;
	update lieu set lieu_compte = lieu_compte + marge - prelev where lieu_cod = magasin;
	update parametres set parm_valeur = parm_valeur + prelev where parm_cod = 39;

-- on update dans l'inventaire
	update perso_objets
		set perobj_identifie = 'O'
		where perobj_obj_cod = num_objet;
-- on rajoute une transaction dans le total
	select into temp pvmag_cod
		from perso_visite_magasin
		where pvmag_perso_cod = personnage
		and pvmag_lieu_cod = magasin;
	if not found then
	else
		update perso_visite_magasin
			set pvmag_nombre = (pvmag_nombre + 0.02)::numeric
			where pvmag_perso_cod = personnage
			and pvmag_lieu_cod = magasin;
	end if;
-- on modifie l'alignement
	if karma_perso < 0 then
		update lieu
		set lieu_alignement = lieu_alignement - 1
		where lieu_cod = magasin;
	else
		update lieu
		set lieu_alignement = lieu_alignement + 1
		where lieu_cod = magasin;
	end if;
	cout := 100 + marge;
	code_retour := '<p>Vous avez fait identifier l''objet '||nom_objet||' pour la somme de '||trim(to_char(cout,'9999'))||' brouzoufs.';
	return code_retour;
end;



	$_$;


ALTER FUNCTION public.magasin_identifie(integer, integer, integer) OWNER TO delain;

--
-- Name: magasin_realiser_formule(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.magasin_realiser_formule(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************************************/
/* fonction magasin_realiser_formule                                      */
/* On passe en paramètres :                                               */
/*   $1 = perso_cod du gérant                                             */
/*   $2 = lieu_cod du magasin                                             */
/*   $3 = le code de la formule                                           */
/**************************************************************************/
declare
----------------------------------------------------------------------------
-- variable de retour
----------------------------------------------------------------------------
	code_retour text;					-- texte formatté
----------------------------------------------------------------------------
-- variable concernant le joueur
----------------------------------------------------------------------------
	personnage alias for $1;		-- perso_cod du joueur
----------------------------------------------------------------------------
-- variable concernant le magasin
----------------------------------------------------------------------------
	v_magasin alias for $2;			-- lieu_cod du magasin
	v_mag_caisse integer;
----------------------------------------------------------------------------
-- variable concernant la formule
----------------------------------------------------------------------------
	v_formule_cod alias for $3;
  v_formule_cout integer;
  v_formule_resultat integer;
  ligne record;					-- enregistrements
----------------------------------------------------------------------------
-- divers
----------------------------------------------------------------------------
  temp integer;

begin
----------------------------------------------------------------------------
-- Etape 1 : vérification
----------------------------------------------------------------------------

  -- verification magasin
	select into temp,v_mag_caisse
			lieu_cod,lieu_compte
		from lieu
		where lieu_cod = v_magasin;
	if not found then
		code_retour := '<p>Erreur ! Magasin non trouvé !</p>';
		return code_retour;
	end if;
  -- verification formule
  select into v_formule_cout,v_formule_resultat
   frm_cout,frm_resultat
		from formule
		where frm_cod = v_formule_cod;
	if not found then
  code_retour := '<p>Erreur ! Formule non trouvée !</p>';
		return code_retour;
	end if;
  -- verification de la caisse
  if v_formule_cout > v_mag_caisse then
    code_retour := '<p>Pas assez en caisse pour financer cette réalisation !</p>';
		return code_retour;
	end if;


  -- verification stock du magasin
  for ligne in select gobj_nom,frmco_num,COALESCE(mgstock_nombre,0) as stock
      from  	formule_composant,objet_generique
      LEFT OUTER JOIN stock_magasin_generique ON
      (gobj_cod = mgstock_gobj_cod  and mgstock_lieu_cod = v_magasin)
      where frmco_frm_cod = v_formule_cod
      and frmco_gobj_cod = gobj_cod
   loop
    if ligne.stock < ligne.frmco_num then
      code_retour := '<p>Quantité insuffisante ! '||trim(to_char(ligne.frmco_num,'99999999999'))||' '||ligne.gobj_nom||' requis pour cette formule, '||trim(to_char(ligne.stock,'99999999999'))||' en stock</p>';
		  return code_retour;
		end if;
	end loop;

	 code_retour := '<p>Tous les composants sont disponibles, la fabrication commence.<br />';
  -- MAJ Caisse
   update lieu set lieu_compte = lieu_compte + v_formule_resultat - v_formule_cout	where lieu_cod = v_magasin;
  -- Retrait des composants.

  for ligne in select gobj_nom,gobj_cod,frmco_num,COALESCE(mgstock_nombre,0) as stock
      from formule_composant,objet_generique
      LEFT OUTER JOIN stock_magasin_generique ON
      (gobj_cod = mgstock_gobj_cod  and mgstock_lieu_cod = v_magasin)
      where frmco_frm_cod = v_formule_cod
      and frmco_gobj_cod = gobj_cod
   loop
      if ligne.stock > ligne.frmco_num then
        update stock_magasin_generique
			  set mgstock_nombre = mgstock_nombre - ligne.frmco_num
			  where mgstock_gobj_cod = ligne.gobj_cod
			  and mgstock_lieu_cod = v_magasin;
      else
        delete from stock_magasin_generique
        where mgstock_gobj_cod = ligne.gobj_cod
			  and mgstock_lieu_cod = v_magasin;
      end if;
      code_retour := code_retour||'<b>'||trim(to_char(ligne.frmco_num,'99999999999'))||' '||ligne.gobj_nom||'</b>  Utilisé(s)<br />';

	end loop;


  -- Ajout des produits.
    for ligne in select gobj_nom,frmpr_gobj_cod,frmpr_num,COALESCE(mgstock_nombre,0) as stock
      from  	formule_produit,objet_generique
      LEFT OUTER JOIN stock_magasin_generique ON
      (gobj_cod = mgstock_gobj_cod  and mgstock_lieu_cod = v_magasin)
      where frmpr_frm_cod = v_formule_cod
      and frmpr_gobj_cod = gobj_cod
   loop
   if ligne.stock <1 then
    delete from stock_magasin_generique
        where mgstock_gobj_cod = ligne.frmpr_gobj_cod
			  and mgstock_lieu_cod = v_magasin;
      values (v_magasin,ligne.frmpr_gobj_cod,ligne.frmpr_num);
   else
      update stock_magasin_generique
			set mgstock_nombre = mgstock_nombre + ligne.frmpr_num
			where mgstock_gobj_cod = ligne.frmpr_gobj_cod
			and mgstock_lieu_cod = v_magasin;
   end if;
   code_retour := code_retour||'<b>'||trim(to_char(ligne.frmpr_num,'99999999999'))||' '||ligne.gobj_nom||'</b>  Produits(s)<br />';
	end loop;




	code_retour := code_retour||'Réalisation Terminée</p>';

	return code_retour;
end;
$_$;


ALTER FUNCTION public.magasin_realiser_formule(integer, integer, integer) OWNER TO delain;

--
-- Name: magasin_repare(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.magasin_repare(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************************************/
/* fonction magasin_repare : gère la réparation dans un magasin           */
/* On passe en paramètres :                                               */
/*   $1 = perso_cod du joueur                                             */
/*   $2 = lieu_cod du magasin                                             */
/*   $3 = obj_cod de l’objet acheté                                       */
/* On a retour une chaine HTML exploitable par action.php                 */
/**************************************************************************/
/* Créé le 08/03/2004                                                     */
/**************************************************************************/
declare
----------------------------------------------------------------------------
-- variable de retour
----------------------------------------------------------------------------
	code_retour text;          -- texte formatté
----------------------------------------------------------------------------
-- variable concernant le joueur
----------------------------------------------------------------------------
	personnage alias for $1;   -- perso_cod du joueur
	qte_or integer;            -- nb de brouzoufs du joueur
	pos_joueur integer;        -- position du joueur
	karma_perso numeric;       -- karma du joueur
----------------------------------------------------------------------------
-- variable concernant le magasin
----------------------------------------------------------------------------
	magasin alias for $2;      -- lieu_cod du magasin
	pos_magasin integer;       -- position du magasin
	montant_marge integer;     -- marge encaissée par le magasin
	montant_prelev integer;    -- montant reversé à l'administration
	prix_origine integer;      -- prix sans marge
	marge integer;             -- marge du magasin
	prelev integer;            -- % de reversement
----------------------------------------------------------------------------
-- variable concernant l'objet
----------------------------------------------------------------------------
	num_objet alias for $3;    -- obj_cod de l'objet acheté
	prix_objet integer;        -- prix de l'objet
	prix_init integer;         -- prix de l'objet hors modificateur
	nom_objet text;            -- nom de l'objet
	v_etat numeric;            -- etat de l'objet
----------------------------------------------------------------------------
-- variable de calcul
----------------------------------------------------------------------------
	temp integer;              -- fourre tout
	modificateur numeric;      -- modif du prix de vente
	bonus_prix integer;
begin
----------------------------------------------------------------------------
-- Etape 1 : vérification
----------------------------------------------------------------------------
	select into qte_or, karma_perso perso_po, perso_kharma
		from perso
		where perso_cod = personnage;
	if not found then
		code_retour := '<p>Erreur ! Acheteur non trouvé !</p>';
		return code_retour;
	end if;
	select into pos_joueur
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	if not found then
		code_retour := '<p>Erreur ! Position acheteur non trouvée !</p>';
		return code_retour;
	end if;

	select into temp, marge, prelev lieu_cod, lieu_marge, lieu_prelev
		from lieu
		where lieu_cod = magasin;
	if not found then
		code_retour := '<p>Erreur ! Magasin non trouvé !</p>';
		return code_retour;
	end if;
	select into pos_magasin
		lpos_pos_cod
		from lieu_position
		where lpos_lieu_cod = magasin;
	if not found then
		code_retour := '<p>Erreur ! Position magasin non trouvée !</p>';
		return code_retour;
	end if;
	if pos_joueur != pos_magasin then
		code_retour := '<p>Erreur ! Position magasin et joueur non concordantes !</p>';
		return code_retour;
	end if;
	select into temp, v_etat
		perobj_cod, obj_etat
		from perso_objets, objets
		where perobj_perso_cod = personnage
		and obj_cod = num_objet
		and perobj_obj_cod = num_objet;
	if not found then
		code_retour := '<p>Erreur ! L’objet n’est pas dans votre inventaire !</p>';
		return code_retour;
	end if;
	prix_init := f_prix_objet(magasin, num_objet);
	select into bonus_prix obon_prix from objets, bonus_objets
		where obj_cod = num_objet
		and obj_obon_cod = obon_cod;
	if found then
		prix_init := prix_init + bonus_prix;
	end if;
	select into nom_objet obj_nom
		from objets
		where obj_cod = num_objet;
	modificateur := mod_vente(personnage, magasin);
	prix_objet := floor(prix_init * 0.2 * (100 - v_etat) * modificateur / 100);
	if prix_objet > qte_or then
		code_retour := '<p>Erreur ! Vous n’avez pas assez de brouzoufs pour réparer cet objet !</p>';
		return code_retour;
	end if;
----------------------------------------------------------------------------
-- Etape 2 : on passe à la réparation
----------------------------------------------------------------------------
-- on enlève les brouzoufs
	update perso
		set perso_po = perso_po - prix_objet
		where perso_cod = personnage;
-- on passe aux marges
	prix_origine = (prix_init * 100) / (100 + marge);
	montant_marge = round((prix_origine * marge) / 100);
	montant_prelev = round((prix_origine * prelev) / 100);
-- on met la marge au magasin
	update lieu set lieu_compte = lieu_compte + montant_marge where lieu_cod = magasin;
	update lieu set lieu_compte = lieu_compte - montant_prelev where lieu_cod = magasin;
	update parametres set parm_valeur = parm_valeur + montant_prelev where parm_cod = 39;
-- on répare l’objet
	update objets
		set obj_etat = 100
		where obj_cod = num_objet;
-- on rajoute une transaction dans le total
	select into temp pvmag_cod
		from perso_visite_magasin
		where pvmag_perso_cod = personnage
		and pvmag_lieu_cod = magasin;
	if not found then
	else
		update perso_visite_magasin
			set pvmag_nombre = pvmag_nombre + (prix_objet::numeric / 5000)
			where pvmag_perso_cod = personnage
			and pvmag_lieu_cod = magasin;
	end if;
-- on modifie l’alignement
	if karma_perso < 0 then
		update lieu
		set lieu_alignement = lieu_alignement - 1
		where lieu_cod = magasin;
	else
		update lieu
		set lieu_alignement = lieu_alignement + 1
		where lieu_cod = magasin;
	end if;
	code_retour := '<p>Vous avez réparé l’objet '||nom_objet||' pour la somme de '||trim(to_char(prix_objet,'99999999999'))||' brouzoufs.';
	return code_retour;
end;
$_$;


