--
-- Name: magasin_stocker(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.magasin_stocker(integer, integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************************************/
/* fonction magasin_stockage : Un gérant ajoute des objets dans son stock */
/* On passe en paramètres :                                               */
/*   $1 = perso_cod du gérant                                             */
/*   $2 = lieu_cod du magasin                                             */
/*   $3 = obj_cod de l'objet acheté                                       */
/*   $3 = nombre_obj nombre d'objets                                      */
/* On a retour une chaine HTML exploitable par action.php                 */
/**************************************************************************/
/* Créé le 08/03/2004                                                     */
/* ATTENTION ! NE CONCERNE QUE LES OBJETS MODIFIES                        */
/**************************************************************************/
declare
----------------------------------------------------------------------------
-- variable de retour
----------------------------------------------------------------------------
	code_retour text;					-- texte formatté
----------------------------------------------------------------------------
-- variable concernant le joueur
----------------------------------------------------------------------------
	personnage alias for $1;		-- perso_cod du joueur
----------------------------------------------------------------------------
-- variable concernant le magasin
----------------------------------------------------------------------------
	v_magasin alias for $2;			-- lieu_cod du magasin
	v_mag_caisse integer;
	pos_magasin integer;				-- position du magasin
	montant_marge integer;			-- marge encaissée par le magasin
	montant_prelev integer;			-- montant reversé à l'administration
	prix_origine integer;			-- prix sans marge
	marge integer;						-- marge du magasin
	prelev integer;					-- % de reversement
----------------------------------------------------------------------------
-- variable concernant l'objet
----------------------------------------------------------------------------
	num_objet alias for $3;			-- obj_cod de l'objet acheté
	nombre_obj alias for $4;			-- obj_cod de l'objet acheté
	prix_total integer;				-- prix total de la transaction
	prix_init integer;				-- prix de l'objet hors modificateur
	num_init integer;				-- nombre d'objets deja en stock
	nom_objet text;					-- nom de l'objet
----------------------------------------------------------------------------
-- variable de calcul
----------------------------------------------------------------------------
	temp integer;						-- fourre tout
	modificateur numeric;			-- modif du prix de vente
	bonus_prix integer;
begin
----------------------------------------------------------------------------
-- Etape 1 : vérification
----------------------------------------------------------------------------

	select into temp,marge,prelev ,v_mag_caisse
			lieu_cod,lieu_marge,lieu_prelev,lieu_compte
		from lieu
		where lieu_cod = v_magasin;
	if not found then
		code_retour := '<p>Erreur ! Magasin non trouvé !';
		return code_retour;
	end if;

	select into nom_objet,prix_init,num_init
		gobj_nom,gobj_valeur,mgstock_nombre from objet_generique
		LEFT OUTER JOIN stock_magasin_generique ON (gobj_cod = mgstock_gobj_cod and mgstock_lieu_cod = v_magasin)
		where gobj_cod = num_objet;
	prix_total := prix_init * nombre_obj;

	if prix_total > v_mag_caisse then
		code_retour := '<p>Erreur ! Vous n''avez pas assez de brouzoufs en caisse pour acheter ces objets !';
		return code_retour;
	end if;

	-- On RETIRE les BRs

	update lieu set lieu_compte = lieu_compte - prix_total where lieu_cod = v_magasin;

	-- MAJ DU STOCK

	select into num_init
		mgstock_nombre
	from stock_magasin_generique
	where mgstock_gobj_cod = num_objet and mgstock_lieu_cod = v_magasin;
	if not found then
	else
		update stock_magasin_generique
			set mgstock_nombre = mgstock_nombre + nombre_obj
			where mgstock_gobj_cod = num_objet
			and mgstock_lieu_cod = v_magasin;
	end if;

  -- AJOUT DANS LE LOG


	code_retour := '<p>Vous avez acheté <b>'||CAST(nombre_obj AS text)||' '||nom_objet||'</b> pour une somme totale de <b>'||CAST(prix_total AS text)||'Br</b></p>';

	return code_retour;
end;
$_$;


ALTER FUNCTION public.magasin_stocker(integer, integer, integer, integer) OWNER TO delain;

--
-- Name: magasin_valider_transaction(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.magasin_valider_transaction(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************************************/
/* fonction magasin_destockage : Un gérant retire des objets dans son stock */
/* On passe en paramètres :                                               */
/*   $1 = numero de la transaction                                             */
/* On a retour une chaine HTML exploitable par action.php                 */
/**************************************************************************/
declare

v_transaction_cod alias for $1;		-- perso_cod du joueur
----------------------------------------------------------------------------
-- variable de retour
----------------------------------------------------------------------------
	code_retour text;					-- texte formatté
----------------------------------------------------------------------------
-- variable concernant le joueur
----------------------------------------------------------------------------
	personnage integer;		-- perso_cod du joueur
	qte_or integer;
----------------------------------------------------------------------------
-- variable concernant le magasin
----------------------------------------------------------------------------
	v_magasin integer;			-- lieu_cod du magasin
	v_mag_caisse integer;
	pos_magasin integer;				-- position du magasin
	montant_marge integer;			-- marge encaissée par le magasin
	montant_prelev integer;			-- montant reversé à l'administration
	prix_origine integer;			-- prix sans marge
	marge integer;						-- marge du magasin
	prelev integer;					-- % de reversement
----------------------------------------------------------------------------
-- variable concernant l'objet
----------------------------------------------------------------------------
	num_objet integer;		-- obj_cod de l'objet acheté
	nombre_obj integer;			-- obj_cod de l'objet acheté
	prix_total integer;				-- prix total de la transaction
	prix_init integer;				-- prix de l'objet hors modificateur
	num_init integer;				-- nombre d'objets deja en stock
	nom_objet text;					-- nom de l'objet
----------------------------------------------------------------------------
-- variable de calcul
----------------------------------------------------------------------------
	temp integer;						-- fourre tout
	tmp_txt text;
	modificateur numeric;			-- modif du prix de vente
	bonus_prix integer;
	v_transaction_prix integer;
begin
----------------------------------------------------------------------------
-- Etape 1 : vérification
----------------------------------------------------------------------------

  select into num_objet,v_magasin,personnage,v_transaction_prix,nombre_obj
   tran_gobj_cod,tran_vendeur,tran_acheteur,tran_prix,tran_quantite from transaction_echoppe
   where tran_cod = v_transaction_cod;


	select into temp,marge,prelev ,v_mag_caisse
			lieu_cod,lieu_marge,lieu_prelev,lieu_compte
		from lieu
		where lieu_cod = v_magasin;
	if not found then
		code_retour := '<p>Erreur ! Magasin non trouvé !';
		return code_retour;
	end if;

  select into qte_or perso_po
		from perso
		where perso_cod = personnage;
	if not found then
		code_retour := '<p>Erreur ! Acheteur non trouvé !';
		return code_retour;
	end if;

  if v_transaction_prix > qte_or then
		code_retour := '<p>Erreur ! Vous n''avez pas assez de brouzoufs pour acheter cet objet !';
		return code_retour;
	end if;

	select into num_init
		mgstock_nombre
	from stock_magasin_generique
	where mgstock_gobj_cod = num_objet and mgstock_lieu_cod = v_magasin;

	if not found then
		code_retour := '<p> Erreur ! Il n''y a pas assez d''objets de ce type en stock !';
		return code_retour;
	else
		if nombre_obj > num_init then
			code_retour := '<p> Erreur ! Il n''y a pas assez d''objets de ce type en stock !';
			return code_retour;
		end if;
	end if;
  -- CONTROLES OK

  -- MAJ ECHOPPE
  -- On RETIRE les BRs
	update lieu set lieu_compte = lieu_compte + v_transaction_prix where lieu_cod = v_magasin;
	-- MAJ DU STOCK
 -- on retire de l'inventaire du magasin
	update stock_magasin_generique
		set mgstock_nombre = mgstock_nombre - nombre_obj
		where mgstock_lieu_cod = v_magasin
		and mgstock_gobj_cod = num_objet;
-- on vérifie que le stock soit pas égal à 0
	select into temp
		mgstock_nombre
		from stock_magasin_generique
		where mgstock_lieu_cod = v_magasin
		and mgstock_gobj_cod = num_objet;
	if temp = 0 then
		delete from stock_magasin_generique
			where mgstock_lieu_cod = v_magasin
			and mgstock_gobj_cod = num_objet;
	end if;

  -- MAJ PERSO
  update perso
		set perso_po = perso_po - v_transaction_prix
		where perso_cod = personnage;
  tmp_txt := cree_objet_perso_nombre(num_objet,personnage,nombre_obj);
  -- AJOUT DANS LE LOG

  --SUPRESSION DE LA TRANSACTION
  delete from transaction_echoppe where tran_cod = v_transaction_cod;
  select into nom_objet gobj_nom from objet_generique where gobj_cod = num_objet;
	code_retour := '<p>Vous avez acheté <b>'||trim(to_char(nombre_obj,'9999999'))||' '||nom_objet||'</b> pour une somme totale de <b>'||trim(to_char(v_transaction_prix,'9999999999'))||'Br</b></p>';

	return code_retour;
end;
$_$;


ALTER FUNCTION public.magasin_valider_transaction(integer) OWNER TO delain;
--
-- Name: magasin_vente_generique2(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.magasin_vente_generique2(integer, integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/**************************************************************************/
/* fonction magasin_vente : gère la vente dans un magasin par un joueur   */
/* On passe en paramètres :                                               */
/*   $1 = perso_cod du joueur                                             */
/*   $2 = lieu_cod du magasin                                             */
/*   $3 = obj_cod de l'objet acheté                                       */
/**************************************************************************/
/* Créé le 08/03/2004                                                     */
/* Modifié le 10/09/2004 par SD : prise en compte d'un paramètre pour     */
/*   le taux de rachat.                                                   */
/**************************************************************************/
declare
----------------------------------------------------------------------------
-- variable de retour
----------------------------------------------------------------------------
	code_retour text;					-- texte formatté
----------------------------------------------------------------------------
-- variable concernant le joueur
----------------------------------------------------------------------------
	personnage alias for $1;		-- perso_cod du joueur
	qte_or integer;					-- nb de brouzoufs du joueur
	pos_joueur integer;
	karma_perso integer;			-- karma du joueur

----------------------------------------------------------------------------
-- variable concernant le magasin
----------------------------------------------------------------------------
	magasin alias for $2;			-- lieu_cod du magasin
	pos_magasin integer;
	montant_marge integer;			-- marge encaissée par le magasin
	montant_prelev integer;			-- montant reversé à l'administration
	prix_origine integer;			-- prix sans marge
	marge integer;						-- marge du magasin
	prelev integer;					-- % de reversement
	type_magasin integer;			-- type de magasin (runique ou normal)
	taux_rachat numeric;				-- taux de rachat
----------------------------------------------------------------------------
-- variable concernant l'objet
----------------------------------------------------------------------------
	num_objet alias for $3;			-- obj_cod de l'objet acheté
	prix_objet integer;				-- prix de l'objet
	prix_init integer;				-- prix de l'objet hors modificateur
	nom_objet text;					-- nom de l'objet
	v_etat numeric;					-- etat de l'objet
----------------------------------------------------------------------------
-- variable de calcul
----------------------------------------------------------------------------
	temp integer;						-- fourre tout
	modificateur numeric;			-- modif du prix de vente
	bonus_prix integer;
        v_obj_modifie integer;      -- indique si l'objet a été modifie
        v_obj_type integer;
begin
----------------------------------------------------------------------------
-- Etape 1 : vérification
----------------------------------------------------------------------------
	select into qte_or,karma_perso perso_po,perso_kharma
		from perso
		where perso_cod = personnage;
	if not found then
		code_retour := '<p>Erreur ! Acheteur non trouvé !';
		return code_retour;
	end if;
	select into pos_joueur
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = personnage;
	if not found then
		code_retour := '<p>Erreur ! Position acheteur non trouvé !';
		return code_retour;
	end if;

	select into temp,marge,prelev,type_magasin lieu_cod,lieu_marge,lieu_prelev,lieu_tlieu_cod
		from lieu
		where lieu_cod = magasin;
	if not found then
		code_retour := '<p>Erreur ! Magasin non trouvé !';
		return code_retour;
	end if;
	select into temp,v_etat,v_obj_modifie,v_obj_type
		perobj_cod,obj_etat,obj_modifie,obj_gobj_cod
		from perso_objets,objets
		where perobj_perso_cod = personnage
		and obj_cod = num_objet
		and perobj_obj_cod = num_objet;
	if not found then
		code_retour := '<p>Erreur ! L''objet n''est pas dans votre inventaire !';
		return code_retour;
	end if;

	select into nom_objet obj_nom
		from objets
		where obj_cod = num_objet;

	prix_objet := f_prix_obj_perso_v(personnage,magasin,num_objet);
----------------------------------------------------------------------------
-- Etape 2 : on passe à la vente
----------------------------------------------------------------------------
-- on stocke
-- on ajoute les brouzoufs
	update perso
		set perso_po = perso_po + prix_objet
		where perso_cod = personnage;
-- on passe aux marges
	prix_origine = (prix_objet*100)/(100 + marge);
	montant_marge = round((prix_objet * marge)/100);
	montant_prelev = round((prix_objet * prelev) / 100);
-- on met la marge au magasin
	update lieu set lieu_compte = lieu_compte + montant_marge where lieu_cod = magasin;
	update lieu set lieu_compte = lieu_compte - montant_prelev where lieu_cod = magasin;
	update parametres set parm_valeur = parm_valeur + montant_prelev where parm_cod = 39;
     -- SI L OBJET EST MODIFIE ON GARDE L'ANCIENNE VERSION
if v_obj_modifie != 0 then
-- on ajoute dans l'incentaire du magasin
-- on enlève dans l'inventaire
	delete from perso_objets
		where perobj_obj_cod = num_objet;
-- on remet l'objet à neuf
	update objets set obj_etat = 100
		where obj_cod = num_objet;
else
    select into temp f_del_objet(num_objet);
    select into temp
		mgstock_nombre
		from stock_magasin_generique
		where mgstock_lieu_cod = magasin
		and mgstock_gobj_cod = v_obj_type;
    if not found then
	else
		update stock_magasin_generique
			set mgstock_nombre = mgstock_nombre + 1
			where mgstock_gobj_cod = v_obj_type
			and mgstock_lieu_cod = magasin;
	end if;
end if;
-- on rajoute une transaction dans le total
	select into temp pvmag_cod
		from perso_visite_magasin
		where pvmag_perso_cod = personnage
		and pvmag_lieu_cod = magasin;

	if not found then
	else
		update perso_visite_magasin
			set pvmag_nombre = pvmag_nombre + (prix_objet/5000)::numeric
			where pvmag_perso_cod = personnage
			and pvmag_lieu_cod = magasin;
	end if;
-- on modifie l'alignement
	if karma_perso < 0 then
		update lieu
		set lieu_alignement = lieu_alignement - 1
		where lieu_cod = magasin;
	else
		update lieu
		set lieu_alignement = lieu_alignement + 1
		where lieu_cod = magasin;
	end if;
	code_retour := '<p>Vous avez vendu l''objet '||nom_objet||' pour la somme de '||trim(to_char(prix_objet,'99999999999'))||' brouzoufs.';
	return code_retour;
end;



	$_$;


ALTER FUNCTION public.magasin_vente_generique2(integer, integer, integer) OWNER TO delain;


