COMMENT ON FUNCTION public.missions_verifie(integer) IS 'Vérifie si les missions du perso peuvent être validées.';


--
-- Name: mod_vente(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.mod_vente(integer, integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$/****************************************************************/
/* fonction mod_vente : donne un modificateur de vente pour les */
/*  magasins. Calculé en fonction de l'alignement et du nombre  */
/*  de transactions passées par un perso dans un magasin donné. */
/* On passe en paramètres :                                     */
/*  $1 = perso_cod                                              */
/*  $2 = lieu_cod                                               */
/* on a en retour un numeric correspondant au bonus de prix :   */
/*  ex : 0.95 signifie qu'on ne paierai que 95% du prix d'achat */
/*  et que le magasin achetera à 105% du prix de vente.         */
/****************************************************************/
/* créé le 08/03/2004                                           */
/* 03/04/2009: Suppression de l'influence du karma sur les prix */
/****************************************************************/
declare
------------------------------------------------------------------
-- variables de retour
------------------------------------------------------------------
	code_retour numeric;					-- multiplicateur
------------------------------------------------------------------
-- variables du perso
------------------------------------------------------------------
	personnage alias for $1;			-- perso_cod
	karma_perso numeric;				-- karma du perso
	nb_visite_magasin numeric;			-- nombre de transactions dans magasin
------------------------------------------------------------------
-- variables du magasin
------------------------------------------------------------------
	magasin alias for $2;				-- lieu_cod du magasin
	align_magasin integer;				-- aligenement du magasin1
	v_neutre integer;						-- neutralité du magasin
------------------------------------------------------------------
-- variables de calcul
------------------------------------------------------------------
	temp_numeric numeric;
begin
	code_retour := 1;
------------------------------------------------------------------
-- Etape 1 : on calcule en fonction du la réput
------------------------------------------------------------------
--	select into align_magasin,v_neutre lieu_alignement,lieu_neutre
--		from lieu
--		where lieu_cod = magasin;
--	select into karma_perso perso_kharma
--		from perso
--		where perso_cod = personnage;
--	if v_neutre = 0 then
--		if (@(align_magasin)) > 100 then
--			if (@(align_magasin)) > 200 then
--				if ((align_magasin*karma_perso) < 0) then
--					code_retour := code_retour + 0.15;
--				else
--					code_retour := code_retour - 0.15;
--				end if;
--			else
--				if ((align_magasin*karma_perso) > 0) then
--					code_retour := code_retour - 0.15;
--				end if;
--			end if;
--		end if;
--	end if;
------------------------------------------------------------------
-- Etape 2 : en fonction du nombre de visites
------------------------------------------------------------------
	select into nb_visite_magasin pvmag_nombre
		from perso_visite_magasin
		where pvmag_perso_cod = personnage
		and pvmag_lieu_cod = magasin;
	if not found then
		nb_visite_magasin := 0;
	end if;
	temp_numeric := nb_visite_magasin::numeric/100;
	code_retour := code_retour - temp_numeric;
	if code_retour > 1.15 then
		code_retour := 1.15;
	end if;
	if code_retour < 0.85 then
		code_retour := 0.85;
	end if;
	return code_retour;
end;$_$;


ALTER FUNCTION public.mod_vente(integer, integer) OWNER TO delain;
--
-- Name: modif_change_cible(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.modif_change_cible(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/**********************************************************/
/* fonction modif_change_cible : donne le modificateur    */
/*   pour un projectile de changer de cible               */
/* on passe en paramètres :                               */
/*   $1 = perso_cod                                       */
/* on a en retour un entier                               */
/**********************************************************/
declare
	code_retour integer;
	personnage alias for $1;
	dext integer;
begin
	select into dext perso_dex from perso
		where perso_cod = personnage;
	code_retour := (dext - 11)*2;
	return code_retour;
end;
$_$;


ALTER FUNCTION public.modif_change_cible(integer) OWNER TO delain;

--
-- Name: modif_type_arme(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.modif_type_arme(integer, integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $_$declare
	v_attaquant alias for $1;
	v_cible alias for $2;
	m_def numeric;
	v_type_arme integer;
	v_type_arme_cible integer;
	v_main_cible integer;
	v_main_attaquant integer;
begin
	v_type_arme := type_arme(v_attaquant);
	v_type_arme_cible := type_arme(v_cible);
	select into v_main_cible gobj_nb_mains
					from perso_objets,objets,objet_generique
					where perobj_perso_cod = v_cible
					and perobj_equipe = 'O'
					and perobj_obj_cod = obj_cod
					and obj_gobj_cod = gobj_cod
					and gobj_tobj_cod = 1;
	select into v_main_attaquant gobj_nb_mains
					from perso_objets,objets,objet_generique
					where perobj_perso_cod = v_attaquant
					and perobj_equipe = 'O'
					and perobj_obj_cod = obj_cod
					and obj_gobj_cod = gobj_cod
					and gobj_tobj_cod = 1;
	--
	-- attaquant mains nues
	--
	if v_type_arme = 0 then 				-- attaquant mains nues
		if v_type_arme_cible = 0 then			-- cible mains nues
			m_def := 0.8;
		elsif v_type_arme_cible = 1 then		-- cible contact
			if v_main_cible = 1 then -- arme 1 main
				m_def := 1.2;
			else
				m_def := 1.4;
			end if;
		elsif v_type_arme_cible = 2 then		-- cible distance
			m_def := 0.5;
		end if;
	--
	-- attaquant contact
	--
	elsif v_type_arme = 1 then
		if v_main_attaquant = 1 then -- arme 1 main
			if v_type_arme_cible = 0 then			-- cible mains nues
				m_def := 0.7;
			elsif v_type_arme_cible = 1 then		-- cible contact
				if v_main_cible = 1 then -- arme 1 main
					m_def := 0.9;
				else
					m_def := 1.4;
				end if;
			elsif v_type_arme_cible = 2 then		-- cible distance
				m_def := 0.4;
			end if;
		else
			if v_type_arme_cible = 0 then			-- cible mains nues
				m_def := 0.7;
			elsif v_type_arme_cible = 1 then		-- cible contact
				if v_main_cible = 1 then -- arme 1 main
					m_def := 1.1;
				else
					m_def := 1.2;
				end if;
			elsif v_type_arme_cible = 2 then		-- cible distance
				m_def := 0.4;
			end if;
		end if;
	--
	-- attaquant distance
	--
	elsif v_type_arme = 2 then				-- attaquant distance
		if v_type_arme_cible = 0 then			-- cible mains nues
			m_def := 0.6;
		elsif v_type_arme_cible = 1 then		-- cible contact
			if v_main_cible = 1 then -- arme 1 main
				m_def := 0.7;
			else
				m_def := 0.7;
			end if;
		elsif v_type_arme_cible = 2 then		-- cible distance
			m_def := 0.5;
		end if;
	end if;
	return m_def;
end;


$_$;


ALTER FUNCTION public.modif_type_arme(integer, integer) OWNER TO delain;

