--
-- Name: nb_pa_attaque(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.nb_pa_attaque(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*********************************************/
/* fonction nb_pa_attaque                    */
/*   retourne le nombre de pa nécessaires    */
/*   pour porter une attaque en fonction     */
/*   de l'arme équipée par le perso à ce     */
/*   moment                                  */
/* on passe en paramètre :                   */
/*   $1 = perso_cod                          */
/*********************************************/
/* Créé le 21/05/2003                        */
/*********************************************/
declare
	code_retour integer;
	v_perso alias for $1;
	pa_temp integer;
	v_bonus integer;
	att_temp integer;

begin
	select into pa_temp gobj_pa_normal
		from objet_generique,perso_objets,objets
		where perobj_perso_cod = v_perso
		and perobj_equipe = 'O'
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = gobj_cod
		and gobj_tobj_cod = 1;
	if pa_temp is null then
		att_temp := getparm_n(2);
	else
		att_temp := pa_temp;
	end if;
	code_retour := att_temp + valeur_bonus(v_perso, 'PAA') + valeur_bonus(v_perso, 'PPA');
if code_retour < 2 then
code_retour := 2;
end if;
	return code_retour;
end;

$_$;


ALTER FUNCTION public.nb_pa_attaque(integer) OWNER TO delain;

--
-- Name: nb_pa_foudre(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.nb_pa_foudre(integer) RETURNS integer
    LANGUAGE plpgsql STRICT SECURITY DEFINER
    AS $_$/*********************************************/
/* fonction nb_pa_foudre                     */
/*   retourne le nombre de pa nécessaires    */
/*   pour porter une attaque foudroyante     */
/*   en fonction de l'arme équipée par le    */
/*   perso à ce moment                       */

/* on passe en paramètre :                   */
/*   $1 = perso_cod                          */
/*********************************************/
/* Créé le 21/05/2003                        */
/*********************************************/
declare
	code_retour integer;
	v_perso alias for $1;
	pa_temp integer;
	v_bonus integer;
	att_temp integer;

begin
	select into pa_temp gobj_pa_eclair
		from objet_generique,perso_objets,objets
		where perobj_perso_cod = v_perso
		and perobj_equipe = 'O'
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = gobj_cod
		and gobj_tobj_cod = 1;
	if pa_temp is null then
		att_temp := getparm_n(5);
	else
		att_temp := pa_temp;
	end if;
	code_retour := att_temp + valeur_bonus(v_perso, 'PAA') + valeur_bonus(v_perso, 'PPA');
if code_retour < 1 then
code_retour := 1;
end if;
	return code_retour;
end;

$_$;


ALTER FUNCTION public.nb_pa_foudre(integer) OWNER TO delain;

--
-- Name: nb_sort_memorisable(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.nb_sort_memorisable(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*******************************************************/
/* fonction nb_sort_memorisable                        */
/*  donne le nombre de sorts mémorisables              */
/* on passe en paramètres le num de perso              */
/*******************************************************/
/* créé le 18/06/2004                                  */
/*******************************************************/
declare
	code_retour integer;
	personnage alias for $1;
	v_race integer;
	v_nb_amel integer;
	temp integer;
	v_int integer;
begin
	select into v_race,v_nb_amel,v_int
		perso_race_cod,perso_amelioration_nb_sort,perso_int
		from perso
		where perso_cod = personnage;
	if v_race = 2 then
		temp := floor(v_int/2);
	else
		temp := v_int;
	end if;
	code_retour := temp + v_nb_amel;
	return code_retour;
end;$_$;


ALTER FUNCTION public.nb_sort_memorisable(integer) OWNER TO delain;

--
-- Name: necromancie(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.necromancie(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* Nécromancie                                  */
/*  $1 = tueur                                  */
/*  $2 = cible                                  */
/************************************************/
declare
	code_retour text;
	v_attaquant alias for $1;
	v_cible alias for $2;
	v_des integer;
	v_pos integer;
	v_monstre integer;
	texte_evt text;
	ligne record;
	chance_chute integer;
	v_objet_deposable text;
	v_type_objet integer;
        v_objet_identifie text;
	v_num_perso integer;
	tmp numeric;
begin
	select into v_pos
		ppos_pos_cod
		from perso_position
		where ppos_perso_cod = v_cible;
	v_des := lancer_des(1,100);
	if v_des < 20 then
		v_monstre := cree_monstre_pos(19,v_pos);
	elsif v_des < 50 then
		v_monstre := cree_monstre_pos(207,v_pos);
	elsif v_des < 60 then
		v_monstre := cree_monstre_pos(210,v_pos);
	elsif v_des < 70 then
		v_monstre := cree_monstre_pos(28,v_pos);
	elsif v_des < 73 then
		v_monstre := cree_monstre_pos(170,v_pos);
	elsif v_des < 76 then
		v_monstre := cree_monstre_pos(175,v_pos);
	elsif v_des < 80 then
		v_monstre := cree_monstre_pos(181,v_pos);
	elsif v_des < 85 then
		v_monstre := cree_monstre_pos(253,v_pos);
	else
		-- on créé un clone !
		v_num_perso := nextval('seq_perso');
		-- les objets
		for ligne in select * from perso_objets
			where perobj_perso_cod = v_cible
			and perobj_equipe = 'O' loop
			select into chance_chute,v_objet_deposable,v_type_objet tobj_chute,gobj_deposable,gobj_tobj_cod
				from type_objet,objet_generique,objets
				where ligne.perobj_obj_cod = obj_cod
				and obj_gobj_cod = gobj_cod
				and gobj_tobj_cod = tobj_cod;
			if v_objet_deposable = 'O' then
				if lancer_des(1,100) <= chance_chute then
					select into v_objet_identifie perobj_identifie from perso_objets
						where perobj_cod = ligne.perobj_cod;
					if v_objet_identifie = 'O' then
							values (nextval('seq_pio_cod'),v_cible,ligne.perobj_obj_cod,getparm_n(22));
					end if;
					update perso_objets
						set perobj_equipe = 'N'
						where perobj_perso_cod = v_attaquant
						and perobj_obj_cod in
							(select obj_cod
								from objets,objet_generique
								where obj_gobj_cod = gobj_cod
								and gobj_tobj_cod = v_type_objet);
					update perso_objets
						set perobj_perso_cod = v_attaquant
						where perobj_cod = ligne.perobj_cod;
				end if;
			end if;
		end loop;
		-- les caracs de base
									perso_nom,
									perso_for,
									perso_dex,
									perso_int,
									perso_con,
									perso_race_cod,
									perso_pv,
									perso_pv_max,
									perso_dcreat,
									perso_actif,
									perso_des_regen,
									perso_valeur_regen,
									perso_vue,
									perso_niveau,
									perso_type_perso,
									perso_amelioration_vue,
 									perso_amelioration_regen,
  									perso_amelioration_degats,
  									perso_amelioration_armure,
  									perso_nb_des_degats,
  									perso_val_des_degats,
  									perso_enc_max,
  									perso_amel_deg_dex,
  									perso_tangible,
  									perso_capa_repar,
  									perso_nb_amel_repar,
  									perso_amelioration_nb_sort,
  									perso_px,
  									perso_dlt,
  									perso_temps_tour)
			select 	v_num_perso,
						'Squelette de '||perso_nom,
						perso_for,
						perso_dex,
						perso_int,
						perso_con,
						17,
						round(perso_pv_max*0.5),
						perso_pv_max,
						now(),
						'O',
						perso_des_regen,
						perso_valeur_regen,
						perso_vue,
						perso_niveau,
						2,
						perso_amelioration_vue,
 						perso_amelioration_regen,
  						perso_amelioration_degats,
  						perso_amelioration_armure,
  						perso_nb_des_degats,
  						perso_val_des_degats,
  						perso_enc_max,
  						perso_amel_deg_dex,
  						'O',
  						perso_capa_repar,
  						perso_nb_amel_repar,
  						perso_amelioration_nb_sort,
  						perso_px,
  						perso_dlt,
  						perso_temps_tour
  			from perso where perso_cod = v_cible;
		-- competences
			select
			v_num_perso,pcomp_pcomp_cod,pcomp_modificateur
			from perso_competences
			where pcomp_perso_cod = v_cible;
		-- sorts
			select
			v_num_perso,psort_sort_cod
			from perso_sorts
			where psort_perso_cod = v_cible;
		code_retour := trim(to_char(v_num_perso,'999999999'));
	--end if;
	end if;
	texte_evt := '[perso_cod1] a invoqué un mort vivant.';


	return code_retour;

end;$_$;


ALTER FUNCTION public.necromancie(integer, integer) OWNER TO delain;

--
-- Name: nettoie(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.nettoie(integer) RETURNS text
    LANGUAGE plpgsql
    AS $$/*****************************************************/
/* fonction nettoie : nettoie les souterrains        */
/* on passe en params 0                              */
/* on a en retour un texte explicatif                */
/*****************************************************/
declare
	code_retour text;
	ligne record;
	ligne_objet record;
	temps interval;
	cpt integer;
begin
	cpt := 0;
	code_retour := '';
-- on efface les objets en trop
	for ligne in select tobj_cod,tobj_nettoyage,tobj_libelle
		from type_objet
		where tobj_nettoyage is not null loop
		temps := ligne.tobj_nettoyage::text||' days';
		for ligne_objet in select pobj_obj_cod
			from objet_position,objets,objet_generique
			where pobj_obj_cod = obj_cod
			and obj_gobj_cod = gobj_cod
			and gobj_tobj_cod = ligne.tobj_cod
			and pobj_dlache < now() - temps loop
			delete from objet_position
				where pobj_obj_cod = ligne_objet.pobj_obj_cod;
			delete from perso_identifie_objet
				where pio_obj_cod = ligne_objet.pobj_obj_cod;
			delete from objets
				where obj_cod = ligne_objet.pobj_obj_cod;
			cpt := cpt + 1;
		end loop;
		code_retour := code_retour||ligne.tobj_libelle||' : '||trim(to_char(cpt,'9999999'))||' nettoyés.<br>';
		cpt := 0;
	end loop;

	return code_retour;
end;$$;


ALTER FUNCTION public.nettoie(integer) OWNER TO delain;

