--
-- Name: nettoie_automap(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.nettoie_automap() RETURNS integer
    LANGUAGE plpgsql
    AS $$declare
	ligne record;
	nb_efface integer;
	v_query text;
	v_nb_query integer;
begin
	nb_efface := 0;
	for ligne in select tablename from pg_tables
		where tableowner = 'sdewitte'
		and tablename like 'perso_vue_pos_%' loop
		v_query = 'delete from '||ligne.tablename||'
			where not exists
			(select 1 from perso where perso_cod = pvue_perso_cod);';
			execute v_query;
			get diagnostics v_nb_query = ROW_COUNT;
			nb_efface := nb_efface + v_nb_query;
	end loop;
	return nb_efface;
end;$$;


