--

CREATE FUNCTION public.nettoyage_etage("1" integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$declare
	code_retour integer;
	etage alias for $1;
	dobj RECORD;
begin
	FOR dobj IN Select * from objets inner join objet_position on objet_position.pobj_obj_cod = objets.obj_cod inner join positions on objet_position.pobj_pos_cod = positions.pos_cod where positions.pos_etage = etage LOOP

	Perform f_del_objet(dobj.obj_cod);

        END LOOP;

	Delete from or_position using positions where positions.pos_cod = or_position.por_pos_cod and positions.pos_etage = etage;

        RETURN 0;

end;$_$;


