--
-- Name: obj_enchantement(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.obj_enchantement(integer, integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/******************************************************/
/* fonction obj_enchantement                          */
/* Params :                                           */
/*  $1 = perso_cod                                    */
/*  $2 = enc_cod                                      */
/*  $3 = obj_cod à enchanter                          */
/* Détermine si un perso donné possède bien tous les  */
/* objets nécessaires pour enchanter un objet         */
/* Retours :                                          */
/*   0 = ne possède pas les objets                    */
/*   1 = possède les objets                           */
/******************************************************/
/* Créé le 04/05/2006 par Merrick                     */
/******************************************************/
declare
	code_retour integer;
	personnage alias for $1;
	v_enc_cod alias for $2;
	v_obj_cod alias for $3;
	v_nb_obj_perso integer;
	ligne record;
begin
	-- On boucle sur les objets nécessaires.
	-- si on n'a pas le bon nombre, alors on retourne un 0
	for ligne in select * from enc_objets where oenc_enc_cod = v_enc_cod loop
		select into v_nb_obj_perso count(obj_cod)
			from objets,perso_objets
			where perobj_perso_cod = personnage
			and perobj_identifie = 'O'
			and perobj_obj_cod = obj_cod
			and obj_cod != v_obj_cod
			and obj_gobj_cod = ligne.oenc_gobj_cod;
		if v_nb_obj_perso < ligne.oenc_nombre then
			return 0;
		end if;
	end loop;
	-- fin de la boucle. A priori, tout le monde est ok, on peut dire qu'il a tout
	return 1;
end;$_$;


ALTER FUNCTION public.obj_enchantement(integer, integer, integer) OWNER TO delain;

--
-- Name: offre_boire(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.offre_boire(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$declare
	donneur alias for $1;
	cible alias for $2;
	code_retour text;
	v_pa integer;
	v_brouzouf integer;
	v_pos_donneur integer;
	v_pos_cible integer;
	v_nom_cible text;
	temp integer;
	texte_evt text;
begin
	select into v_pa,v_brouzouf,v_pos_donneur
		perso_pa,perso_po,ppos_pos_cod
		from perso,perso_position
		where perso_cod = donneur
		and ppos_perso_cod = perso_cod;
	if not found then
		code_retour := 'Erreur ! Donneur non trouvé !';
		return code_retour;
	end if;
	if v_pa < 4 then
		code_retour := 'Erreur ! Pas assez de Pa !';
		return code_retour;
	end if;
	if v_brouzouf < 10 then
		code_retour := 'Erreur ! Pas assez de brouzoufs !';
		return code_retour;
	end if;
	select into v_pos_cible,v_nom_cible
		ppos_pos_cod,perso_nom
		from perso,perso_position
		where perso_cod = cible
		and ppos_perso_cod = perso_cod;
	if not found then
		code_retour := 'Erreur ! Cible non trouvée !';
		return code_retour;
	end if;
	if v_pos_cible != v_pos_donneur then
		code_retour := 'Erreur ! le donneur et la cible ne sont pas sur la même position !';
		return code_retour;
	end if;
	select into temp
		lieu_tlieu_cod
		from lieu,lieu_position
		where lpos_pos_cod = v_pos_donneur
		and lpos_lieu_cod = lieu_cod;
	if not found then
		code_retour := 'Erreur ! Le donneur n''est pas sur un lieu !';
		return code_retour;
	end if;
	if temp != 4 then
		code_retour := 'Erreur ! Le donneur n''est pas sur une auberge !';
		return code_retour;
	end if;
-- actions
	update perso
		set perso_pa = perso_pa - 4, perso_po = perso_po - 10
		where perso_cod = donneur;
	texte_evt := '[attaquant] a offert à boire à [cible]';
	code_retour := 'Vous avez offert un coup à boire à <b>'||v_nom_cible||'</b><br>';
	return code_retour;
end;$_$;


ALTER FUNCTION public.offre_boire(integer, integer) OWNER TO delain;


--
-- Name: ouvrir_prison(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.ouvrir_prison(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*************************************************/
/* ouvrir prison                                 */
/*   $1 = perso à qui on ouvre                   */
/*   $2 = perso_ouvrant                          */
/*************************************************/
declare
	code_retour text;
	personnage alias for $1;
	geolier alias for $2;
	nom_personnage text;
	num_message integer;
	anc_temple integer;
begin
	select into nom_personnage
		perso_nom
		from perso
		where perso_cod = personnage;
	if not found then
		code_retour := 'Erreur ! Personnage non trouvé !';
		return code_retour;
	end if;
		values (personnage,2139);
	num_message := nextval('seq_msg_cod');
		values (nextval('seq_emsg_cod'),num_message,geolier,'N');
		values (num_message, personnage, 'N', 'N');
	select into anc_temple ptemple_anc_pos_cod
		from perso_temple
		where ptemple_perso_cod = personnage;
	if anc_temple = 0 then
		delete from perso_temple where ptemple_perso_cod = personnage;
	else
		update perso_temple
			set ptemple_pos_cod = ptemple_anc_pos_cod,
			ptemple_nombre = ptemple_anc_nombre
			where ptemple_perso_cod = personnage;
	end if;
	code_retour := '<p>Vous avez ouvert la porte pour ce prisonnier, il est maintenant libre de sortir.';
	return code_retour;
end;
	$_$;


ALTER FUNCTION public.ouvrir_prison(integer, integer) OWNER TO delain;

--
-- Name: perso_erreur(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.perso_erreur() RETURNS text
    LANGUAGE plpgsql
    AS $$/******************************************/
/* persos anomalies                       */
/******************************************/
declare
	code_retour text;
	ligne record;
	v_niveau integer;
	v_calcul integer;
begin
	code_retour := e'Debut<br>\r\n';
	for ligne in
		select perso_cod, perso_nom,perso_temps_tour,perso_niveau,compt_cod,compt_nom,coalesce(perso_redispatch,'NR') as perso_redispatch
			from perso,perso_compte,compte
			where perso_actif != 'N'
			and perso_type_perso = 1
			and perso_pnj != 1
			and perso_cod = pcompt_perso_cod
			and pcompt_compt_cod = compt_cod
			order by compt_cod loop
		v_calcul := compter_perso_amelioration(ligne.perso_cod);
		if v_calcul = -1 then
			code_retour := code_retour||'Compte '||trim(to_char(ligne.compt_cod,'99999999'))||' ('||ligne.compt_nom||') - perso '||ligne.perso_nom||'  ('||trim(to_char(ligne.perso_cod,'9999999'))||') - ANOMALIE : temps incorrect ('||trim(to_char(ligne.perso_temps_tour,'99999999'))||e')<br>\r\n';
		else
			select into v_niveau perso_niveau from perso where perso_cod = ligne.perso_cod;
			if v_niveau != v_calcul then
				code_retour := code_retour||'Compte '||trim(to_char(ligne.compt_cod,'99999999'))||' ('||ligne.compt_nom||') perso '||ligne.perso_nom||'  ('||trim(to_char(ligne.perso_cod,'9999999'))||') - ANOMALIE : niveau actuel : '||trim(to_char(v_niveau,'99999999'))||' - niveau calculé :' ||trim(to_char(v_calcul,'99999999'))||' - redispatch : '||ligne.perso_redispatch||e'<br>\r\n';
			end if;
		end if;
		if trim(code_retour) is null then
			return trim(to_char(ligne.perso_cod,'999999999'));
		end if;
	end loop;
	return code_retour;
end;
	$$;


ALTER FUNCTION public.perso_erreur() OWNER TO delain;

--
-- Name: piege_param(integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, text); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.piege_param(integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, text) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* Piège multi résultat                         */
/* les monstres ne sont pas affectés            */
/* 12/04/2006                                   */
/* perso : $1                                   */
/* malus de dlt : $2                            */
/* malus poison : $3                            */
/* malus déplacement : $4                       */
/* malus Esquive : $5                           */
/* malus dégâts : $6                            */
/* malus de vue : $7                            */
/* malus pour toucher : $8                      */
/* malus pour entendre : $9 comme ultrason,     */
/*                          mettre une valeur   */
/*                          positive            */
/* malus de PA par attaque : $10                */
/* dés de dégâts pour le piege : $11            */
/* chance de déclencher le piège : $12          */
/* Texte de code retour : $13                    */
/************************************************/

declare
-------------------------------------------------------------
-- variables servant pour la sortie
-------------------------------------------------------------
	code_retour text;			-- texte pour action
	texte_evt text;				-- texte pour évènements
-------------------------------------------------------------
-- variables concernant le perso
-------------------------------------------------------------
	personnage alias for $1;        -- perso_cod du perso
	type_perso integer;             -- perso_type_perso du perso ou monstre
	pv_perso integer;               -- PV du perso
	pos_perso integer;		-- position du perso
-------------------------------------------------------------
-- variables de calcul
-------------------------------------------------------------
	malus_dlt alias for $2;			-- temps de décalage de la prochaine dlt
	int_malus_dlt interval;			-- variable interne de concatenation de chaine
	mal_poison alias for $3;
	mal_deplacement alias for $4;
	mal_esquive alias for $5;
	mal_deg alias for $6;
	mal_vue alias for $7;
	mal_touche alias for $8;
	mal_son alias for $9;
	mal_attaque alias for $10;
	mal_blessure alias for $11;
	declenchement alias for $12;
	texte alias for $13;
	texte2 text;
	v_degats integer;
	des integer; 				-- correspond à l'aléatoire
	texte_mort text;

begin


                code_retour := '';
                select into type_perso,pv_perso
			perso_type_perso,perso_pv
			from perso
			where perso_cod = personnage;
	if not found then
		return 'soucis sur la sélection de type de perso !';
	end if;
	if type_perso = 2             --On teste si il s'agit d'un monstre
			then return 'Sans conséquence';
	else
                       --un perso est entré sur la case
            des := lancer_des(1,100);
	    if des < declenchement then
	        if texte = ''
			then
		code_retour := 'Vos pieds ne vous ont pas porté dans un endroit hospitalier. Lors de l''un de vos pas, une flèchette empoisonnée provenant d''un piège est venue se planter dans votre jambe. Une douleur aiguë commence à se faire sentir. Vos mouvements sont plus lents, et vos réactions beaucoup moins aiguisées ... De drôles de sensations se font sentir. Les effets sont immédiats, et certains vous échappent pour le moment. Y survivrez vous ? ';
			else
		texte2 := replace(texte,'%','''');
		texte2 := replace(texte2,'#',',');
		code_retour := texte2;
		end if;
-------------------------------------------------------------
-- Dégâts directs, non paramétrables
-------------------------------------------------------------
		v_degats := lancer_des(mal_blessure,10);
		if pv_perso < v_degats then
		-- personnage tué
			code_retour := code_retour||'Vous venez de mourir dans d''attroces souffrances. Prenez garde la prochaine fois où vous mettez les pieds !';
			texte_mort := tue_perso_final(personnage,personnage);
			code_retour := code_retour||split_part(texte_mort,';',2);
			texte_evt := '[perso_cod1] ayant été trop négligeant n''a pu échapper à un piège.';
     			values(54,now(),1,personnage,texte_evt,'O','O');
			return code_retour;
		else
		-- personnage survit
			update perso set perso_pv = pv_perso - v_degats where perso_cod = personnage;
		end if;

-------------------------------------------------------------
-- Malus pour la dlt
-------------------------------------------------------------
		if malus_dlt != 0
		then
			int_malus_dlt := trim(to_char(malus_dlt,'999999999'))||' minutes';
			update perso
			set perso_dlt = perso_dlt + int_malus_dlt::interval
			where perso_cod = personnage;
		end if;
-------------------------------------------------------------
-- Malus pour le poison
-------------------------------------------------------------
		if mal_poison != 0
		then
			perform ajoute_bonus(personnage, 'POI', 4, mal_poison);
		end if;
-------------------------------------------------------------
-- Malus pour le déplacement
-------------------------------------------------------------
		if mal_deplacement != 0
		then
			perform ajoute_bonus(personnage, 'DEP', 2, 1);
		end if;
-------------------------------------------------------------
-- Malus pour l'esquive
-------------------------------------------------------------
		if mal_esquive != 0
		then
			perform ajoute_bonus(personnage, 'MAE', 2, mal_esquive);
		end if;
-------------------------------------------------------------
-- Malus pour les dégâts
-------------------------------------------------------------
		if mal_deg != 0
		then
			perform ajoute_bonus(personnage, 'DEG', 2, mal_deg);
		end if;
-------------------------------------------------------------
-- Malus pour la vue
-------------------------------------------------------------
		if mal_vue != 0
		then
			perform ajoute_bonus(personnage, 'VUE', 2, mal_vue);
		end if;
-------------------------------------------------------------
-- Malus pour les chances de toucher
-------------------------------------------------------------
		if mal_touche != 0
		then
			perform ajoute_bonus(personnage, 'TOU', 2, mal_touche);
		end if;
-------------------------------------------------------------
-- Malus pour entendre les messages (ultrasons)
-------------------------------------------------------------
		if mal_son != 0
		then
			perform ajoute_bonus(personnage, 'UTL', 5, mal_son);
		end if;
-------------------------------------------------------------
-- Malus pour le nombre de PA par attaque
-------------------------------------------------------------
		if mal_attaque != 0
		then
			perform ajoute_bonus(personnage, 'PAA', 2, mal_attaque);
		end if;
-------------------------------------------------------------
-- Code retour des évènements et du texte
-------------------------------------------------------------

		texte_evt := '[perso_cod1] ayant été trop négligeant n''a pu échapper à un piège.';
     		values(54,now(),1,personnage,texte_evt,'O','O');
/* disparition du piege */
		des := lancer_des(1,100);
		if des < 5 then
/* On sélectionne l'endroit où l'on est pour mettre à jour la fontion d'arrivée */
			select into pos_perso
				ppos_pos_cod
				from perso_position
				where ppos_perso_cod = personnage;
/* on fait la mise à jour pour la supprimer */
			update positions Set pos_fonction_arrivee = null where pos_cod = pos_perso;
			code_retour := code_retour||'<br><br> Le piège semble s''être désactivé. Cela évitera que d''autres ne se fassent avoir aussi bêtement ...';
		end if;
	end if;
	return code_retour;
end if;
end;$_$;


ALTER FUNCTION public.piege_param(integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, integer, text) OWNER TO delain;

--
-- Name: piqure_rappel(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.piqure_rappel() RETURNS text
    LANGUAGE plpgsql
    AS $$/****************************************/
/* piqure_rappel                        */
/****************************************/
declare
	code_retour text;
	v_sexe text;
	ligne record;
	v_corps text;
	v_mes integer;
begin
	for ligne in select perso_cod,perso_sex from perso
		where perso_piq_rap_env = 0
		and perso_type_perso = 1
		and perso_dcreat + '5 days'::interval < now() loop
		if ligne.perso_sex = 'M' then
			v_corps := 'Alors que vous marchez laborieusement à travers les fourrés des Extérieurs, vous vous remémorez la conversation que vous avez surprise entre Hernin et Gildwen, au poste de garde. Votre esprit commence à s''égarer sur les courbes évocatrices de la gracieuse elfette... Puis, vous essayez de vous reconcentrer sur les paroles.<br>
				<br>
				Apparemment, il faut se méfier des <b>Voyous</b> et des <b>monstres</b>. Parmi les monstres, les <b>morbelins</b> sont intéressants car ils permettent de se procurer une épée. Les <b>queues de rat</b> peuvent être échangées dans les <b>Centres Administratifs</b> contre des brouzoufs, la monnaie locale.<br>
				<br>
				Lorsqu''on a un problème avec un autre aventurier, on peut faire appel à la <b>Milice</b>.<br>
				<br>
				Gildwen aime bien les Miliciens, peut-être que si vous en devenez un, elle succombera à votre charme.... Vous reconcentrez à nouveau votre pensée sur les paroles de Gildwen...<br>
				<br>
				Il vaut mieux parler avec les aventuriers pour composer un <b>groupe</b> au plus vite... et peut-être que parmi eux, il y aura un visage aussi ravissant que celui de...<br>
				<br>
				<br>
				Bref, fort de tous ces beaux conseils, vous les mettez en pratique sans plus tarder ! ';
		else
			v_corps := 'Alors que vous marchez laborieusement à travers les fourrés des Extérieurs, vous vous remémorez la conversation que vous avez surprise entre Hernin et Gildwen, au poste de garde. L''elfette avait l''air bien délurée, pensez-vous avec répprobation... Puis, vous essayez de vous reconcentrer sur les paroles.<br>
				<br>
				Apparemment, il faut se méfier des <b>Voyous</b> et des <b>monstres</b>. Parmi les monstres, les <b>morbelins</b> sont intéressants car ils permettent de se procurer une épée. Les <b>queues de rat</b> peuvent être échangées dans les <b>Centres Administratifs</b> contre des brouzoufs, la monnaie locale.<br>
				<br>
				Lorsqu''on a un problème avec un autre aventurier, on peut faire appel à la <b>Milice</b>.<br>
				<br>
				Gildwen aime bien les Miliciens... Tsss, Encore une Marie-Couche-Toi-Là que cela ne vous étonnerait guère, elle avait un genre si vulgaire ! Vous reconcentrez à nouveau votre pensée sur les paroles de Gildwen...<br>
				<br>
				Il vaut mieux parler avec les aventuriers pour composer un <b>groupe</b> au plus vite... En tout cas, une chose est sure, pas question que vous vous associiez à une nénette écervelée comme cette Gildwen, elle pourrait vous faire de l''ombre en plus...<br>
				<br>
				<br>
				Bref, fort de tous ces beaux conseils, vous les mettez en pratique sans plus tarder !';
		end if;
	v_mes := nextval('seq_msg_cod');
		values (v_mes,1773905,'N');
		values (v_mes,ligne.perso_cod,'N','N');
	update perso set perso_piq_rap_env = 1 where perso_cod = ligne.perso_cod;
	end loop;
/*Message pour la contrebande en parallèle */
/* Désactivé pour cause de dissolution. */
	for ligne in select perso_cod,perso_sex from perso
		where perso_piq_rap_env = 1
		and perso_type_perso = 1
		and perso_dcreat + '8 days'::interval < now() loop

		v_corps := 'Hep, l''ami !
<br><br>
Oui toi qui viens d''arriver dans ce monde peuplé de créatures étranges
et d''aventuriers en soif de gloire et de richesses. N''aie pas peur, je
n''en veux pas à ta bourse...
<br><br>
Peut-être as tu quelques minutes à me consacrer ?
<br><br>
Ce bon roi Hormandre veut annexer ce royaume pour le rattacher à son
domaine, vois tu. Mais il se moque éperdument de ceux qui foulent le sol de
Delain. Regarde ton équipement, tu n''aimerais pas toi aussi pouvoir
t''équiper correctement comme ces fanfarons de Miliciens ? Tu n''aimerais
pas pouvoir planter quelques coudes d''acier dans tous ces monstres ou ces
aventuriers qui en veulent à tes maigres richesses ?
<br><br>
Mais tu n''as pas envie de reconnaitre la souveraineté de ce roi qui se
moque des sujets de son royaume ou de ceux qui oeuvrent à libérer les
souterrains des créatures de Malkiar ? Tu n''as pas envie d''enrichir la
cour qui se roule dans la luxure par l''argent durement ramassé par les
honnêtes aventuriers que nous sommes, n''est ce pas ?
<br><br>
Tu m''as l''air sympathique, aussi, je vais te confier un petit secret,
mais il faut que tu le gardes pour toi, l''ami. Si tu n''as pas envie
d''avoir à faire avec les échoppes du roi Hormandre et que tu veux faire de
vraies affaires, contacte les Contrebandiers, adresse toi à eux et nul
doute qu''ils sauront trouver quelque chose pour te satisfaire.
<br><br>
N''oublie pas mon conseil l''ami, sombrer dans la facilité du commerce
avec la Caravane c''est enrichir un roi qui n''a que faire de ton sort.';
--	v_mes := nextval('seq_msg_cod');
--	insert into messages (msg_cod,msg_date2,msg_date,msg_titre,msg_corps) values
--		(v_mes,now(),now(),'Dans un recoin ...',v_corps);
--	insert into messages_exp (emsg_msg_cod,emsg_perso_cod,emsg_archive)
--		values (v_mes,858361,'N');
--	insert into messages_dest (dmsg_msg_cod,dmsg_perso_cod,dmsg_lu,dmsg_archive)
--		values (v_mes,ligne.perso_cod,'N','N');
	update perso set perso_piq_rap_env = 2 where perso_cod = ligne.perso_cod;
	end loop;
	return 'OK';
end;$$;


