--
-- Name: poison_araignee(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.poison_araignee(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$declare
	v_monstre alias for $1;
	v_pos integer;
	v_poison integer;
	v_for integer;
	cpt_perso integer;
	v_perso integer;
	c_perso integer;
	v_pv_cible integer;
	texte_evt text;
begin
	select into v_pos,v_for
		ppos_pos_cod,perso_for
		from perso_position,perso
		where ppos_perso_cod = v_monstre
		and perso_cod = ppos_perso_cod;
	v_poison := floor(v_for / 3);
	select into cpt_perso
		count(perso_cod)
		from perso,perso_position
		where perso_type_perso in (1,3)
		and perso_actif = 'O'
		and perso_cod = ppos_perso_cod
		and ppos_pos_cod = v_pos
		and perso_tangible = 'O';
	if cpt_perso != 0 then
		c_perso := lancer_des(1,cpt_perso) - 1;
		select into v_perso,v_pv_cible
			perso_cod,perso_pv_max
			from perso,perso_position
			where perso_type_perso in (1,3)
			and perso_actif = 'O'
			and perso_tangible = 'O'
			and perso_cod = ppos_perso_cod
			and ppos_pos_cod = v_pos
			limit 1
			offset c_perso;
		perform ajoute_bonus(v_perso, 'POI', 5, v_poison);
		texte_evt := '[attaquant] a empoisonné [cible] ';
     		values(nextval('seq_levt_cod'),14,now(),1,v_monstre,texte_evt,'O','O',v_monstre,v_perso);
	     	values(nextval('seq_levt_cod'),14,now(),1,v_perso,texte_evt,'N','O',v_monstre,v_perso);
		return v_perso;
	else
		return 0;
	end if;
end;	$_$;


ALTER FUNCTION public.poison_araignee(integer) OWNER TO delain;

--
-- Name: poissons(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.poissons(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*********************************/
/* poissons                      */
/*********************************/
declare
	code_retour text;
	personnage alias for $1;
	nb_pois 	alias for $2;
	duree integer;
	num_mes integer;
	texte_mes text;
	temp integer;
begin
	select into temp perso_cod
	from perso
	where perso_cod = personnage;
	if found then
	-- titre
	-- malus
	delete from bonus
		where bonus_perso_cod = personnage
		and bonus_tbonus_libc in ('POI','PAA','VUE');
	duree := nb_pois + 2;
	num_mes := nextval('seq_msg_cod');
	texte_mes := 'Vous avedz accumulé des poissons dans votre inventaire.<br>L''odeur vous monte à la tête, vous tombez malade....';

	return 'OK';
else
	return 'KKKOOOO';
end if;
end;

		$_$;


