--
-- Name: portee_attaque(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.portee_attaque(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function portee_attaque : donne la portée de l arme equipee   */
/* On passe en paramètres                                        */
/*    $1 = perso                                                 */
/* En sortie, on a un entier (portee)                            */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications :                                     */
/*   15/09/2003 : prise en compte des armes de jet               */
/*****************************************************************/
declare
	code_retour integer; -- sert de code retour
	personnage alias for $1;
	type_arme varchar(2);
	code_objet integer;
	distance integer;

begin
	-- etape 1 : on regarde si une arme est équipée
	select into code_objet,type_arme obj_cod,gobj_distance
		from perso_objets,objets,objet_generique
		where perobj_perso_cod = personnage
		and perobj_equipe = 'O'
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = gobj_cod
		and gobj_tobj_cod = 1;
	if code_objet is null then
		code_retour := 0;
		return code_retour;
	else
		if type_arme = 'N' then
			code_retour := 0;
			return code_retour;
		else
			select into distance obj_portee
				from objets
				where obj_cod = code_objet;
			code_retour := distance;
			return code_retour;
		end if;
	end if;
end;
$_$;


ALTER FUNCTION public.portee_attaque(integer) OWNER TO delain;

--
-- Name: pos_aleatoire(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.pos_aleatoire(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function pos_aleatoire : retourne un pos_cod aléatoire en     */
/*    fonction de l etage passé en paramètre                     */
/* On passe en paramètres                                        */
/*    $1 = etage                                                 */
/* Le code sortie est un entier (pos_cod)                        */
/*****************************************************************/
/* Créé le 02/04/2003                                            */
/* Liste des modifications :                                     */
/*   06/05/2003 : ajout du contrôle pour les murs                */
/*   31/01/2013 : ajout du contrôle pour le zéro                 */
/*****************************************************************/
declare
	code_retour integer;
	v_etage alias for $1;
begin
	select into code_retour
		pos_cod
	from positions
	where pos_etage = v_etage
		and (pos_etage <> 0
			or pos_x between -20 and 20
				and pos_y between -20 and 20)
		and not exists
			(select 1 from murs
			where mur_pos_cod = pos_cod)
		and not exists
			(select 1 from lieu_position
			where lpos_pos_cod = pos_cod)
	order by random()
	limit 1;

	return code_retour;
end;
$_$;


ALTER FUNCTION public.pos_aleatoire(integer) OWNER TO delain;

--
-- Name: FUNCTION pos_aleatoire(integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.pos_aleatoire(integer) IS 'Retourne un pos_cod aléatoire dans l’étage donné';



--
-- Name: pos_par_etage(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.pos_par_etage(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$declare
	code_retour text;
	v_etage alias for $1;
	ligne record;
begin
	code_retour := '0';
	for ligne in select pos_cod from positions where pos_etage = v_etage loop
		code_retour := code_retour||'|'||trim(to_char(ligne.pos_cod,'99999999'));
	end loop;
	return code_retour;
end;$_$;


ALTER FUNCTION public.pos_par_etage(integer) OWNER TO delain;

--
-- Name: possede_4e_perso(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.possede_4e_perso(integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$/********************************************************/
/* function  possede_4e_perso                                 */
/* Indique si le compte donné possède un quatrième perso      */
/* parametres :                                               */
/*  $1 = compt_cod du compte à tester                         */
/* Sortie :                                                   */
/*  code_retour = True ou False                               */
/**************************************************************/
/**************************************************************/
/* Création - 27/09/2012 - Reivax                             */
/**************************************************************/
declare
	num_compte alias for $1;      -- compt_cod
	resultat boolean;             -- le résultat

begin
/*********************************************************/
/*             E X É C U T I O N                         */
/*********************************************************/

	-- On recherche si le compte n’aurait pas un 4e perso de type aventurier
	select into resultat (count(*) > 0)
	from perso_compte
	inner join perso on perso_cod = pcompt_perso_cod
	where pcompt_compt_cod = num_compte
		and perso_actif = 'O'
		and perso_pnj = 2;

	-- On recherche si le compte n’aurait pas un 4e perso de type monstre
	if not resultat then
		select into resultat (count(*) > 0)
		from perso_compte
		inner join perso on perso_cod = pcompt_perso_cod
		where pcompt_compt_cod = num_compte
			and perso_actif = 'O'
			and perso_type_perso = 2;
	end if;
	return resultat;
end;		$_$;


ALTER FUNCTION public.possede_4e_perso(integer) OWNER TO delain;

--
-- Name: FUNCTION possede_4e_perso(integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.possede_4e_perso(integer) IS 'Détermine si un compte possède un 4e perso';


--
-- Name: prepare_hibernation(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.prepare_hibernation(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/***************************************/
/* prepare hibernation                 */
/***************************************/
declare
	d_hiber date;
	v_compte alias for $1;
begin
	select into d_hiber compt_ddeb_hiber
		from compte where compt_cod = v_compte;
	if d_hiber is null then
		return 0;
	else
		return 1;
	end if;
end;$_$;


ALTER FUNCTION public.prepare_hibernation(integer) OWNER TO delain;

--
-- Name: prie_dieu(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.prie_dieu(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*******************************************************/
/* fonction prie_dieu                                  */
/*  on passe en params                                 */
/*  $1 = perso_cod                                     */
/*  $2 = dieu_cod                                      */
/* on a en retour une chaine html exploitable          */
/*******************************************************/
declare
	code_retour text;             -- code_html de retour
-- personnage
	personnage alias for $1;      -- perso_cod du prieur
	v_pa integer;                 -- pa du perso
	v_nom_dieu text;              -- nom éventuel de l’ancien dieu
	v_dieu_cod integer;           -- dieu_cod éventuel de l’ancien dieu
	v_dieu_niveau integer;        -- niveau éventuel de l’ancien dieu
	v_grade text;                 -- nom du grade éventuel de l’ancien dieu
	v_duree_renegat interval;     -- durée de "rénégation"
	v_type_perso integer;
	v_perso_pos integer;          -- position du perso
	v_familier_divin integer;     -- perso_cod du familier divin (s’il existe)
	v_priere_familier integer;    -- points de prière du familier divin
	v_ferveur integer;            -- valeur calculée entre le rang et les PP du prêtre (rang * 2 + PP / 1000)
	v_avancement integer;         -- avancement du prêtre dans son niveau
	v_gain_familier integer;      -- gain en PP pour le familier
-- dieu
	v_dieu alias for $2;          -- dieu_cod
	texte_evt text;
	dieu_lieu integer;            -- Déterminer si on est sur un temple
	v_tlieu integer;            -- Type de lieu (temple, autel, etc)

begin
	code_retour := '';
	--if to_char(now(),'DD/MM/YYYY') in ('22/04/2011', '23/04/2011') then
	--	return 'Un silence pesant fait écho à votre prière...';
	--end if;
	-- on commence par faire les vérifs d’usage
	select into
		v_pa, v_type_perso
		perso_pa, perso_type_perso
		from perso
		where perso_cod = personnage;
	if not found then
		code_retour := '<p>Anomalie ! Personnage non trouvé !</p>';
		return code_retour;
	end if;
	if v_pa < getparm_n(48) then
		code_retour := '<p>Anomalie ! Pas assez de PA pour prier ce dieu !</p>';
		return code_retour;
	end if;
	if v_type_perso = 3 then
		code_retour := '<p>Le dieu regarde d’un air méprisant la créature qui tente de le prier. Un familier est indigne de s’adresser directement à son dieu !</p>';
		return code_retour;
	end if;
	-- Vérification que le perso est bien sur un lieu sacré
	-- Temple = 17 / Autel = 33 / Auberge (Tonto) = 4
	select into dieu_lieu, v_tlieu lieu_dieu_cod, lieu_tlieu_cod from perso_position,lieu_position,lieu
		where lieu_cod = lpos_lieu_cod
		and lpos_pos_cod = ppos_pos_cod
		and ppos_perso_cod = personnage
		and lieu_tlieu_cod in (17,33,4);
	if not found or dieu_lieu = NULL then
		return '<p>Vous ne pouvez pas faire ce type de prière ici, vous n’êtes pas dans un temple ni devant un autel !</p>';
	end if;
	-- Si on tente de prier un autre dieu que celui correspondant au lieu
	if v_dieu != dieu_lieu then
		return '<p>Vous ne pouvez pas faire ce type de prière ici.</p>';
	end if;
	-- on regarde s’il avait déjà prié ici ou ailleurs
	select into
		v_dieu_cod,
		v_dieu_niveau,
		v_nom_dieu,
		v_ferveur

		dper_dieu_cod,
		dper_niveau,
		dieu_nom,
		dper_niveau * 2 + floor(sqrt(dper_points) / 20)

		from dieu_perso,dieu
		where dper_perso_cod = personnage
		and dper_dieu_cod = dieu_cod;
	if found then
		if v_dieu_cod != v_dieu then
			-- attention, il fait une infidélité
			if v_dieu_niveau = 0 then
				-- pas trop grave, aucun grade pour l'ancien dieu
				code_retour := '<p>Vous aviez déjà prié pour le dieu <b>'||v_nom_dieu||'</b> auparavant. Toutes vos prières pour ce dieu sont maintenant passées dans l’oubli.<br>';
				delete from dieu_perso where dper_perso_cod = personnage;
			else
				-- un grade chez l'ancien dieu, pas bon, on passe en renégat
				select into v_grade dniv_libelle from dieu_niveau
					where dniv_dieu_cod = v_dieu_cod
					and dniv_niveau = v_dieu_niveau;
				code_retour := '<p>Vous étiez '||v_grade||' pour le dieu <b>'||v_nom_dieu||'</b><br>';
				code_retour := code_retour||'Celui-ci vous considère maintenant comme un renégat, il vous est impossible de faire partie de ses fidèles pendant un certain temps.<br>';
				delete from dieu_perso where dper_perso_cod = personnage;
				if v_dieu_niveau = 1 then
					v_duree_renegat := '1 month';
				end if;
				if v_dieu_niveau = 2 then
					v_duree_renegat := '3 month';
				end if;
				if v_dieu_niveau = 3 then
					v_duree_renegat := '6 month';
				end if;
				if v_dieu_niveau = 4 then
					v_duree_renegat := '9 month';
				end if;
				if v_dieu_niveau = 5 then
					v_duree_renegat := '1 year';
				end if;
					values (v_dieu_cod,personnage,now()+v_duree_renegat);
			end if;
		else
			-- on a déjà un fidèle, on peut "augmenter" son compteur
			update dieu_perso
				set dper_points = dper_points + 10
				where dper_perso_cod = personnage;

			-- on ajoute des points au familier divin
			select into v_familier_divin, v_priere_familier perso_cod, dper_points
				from perso_familier
				inner join perso on perso_cod = pfam_familier_cod
				inner join dieu_perso on dper_perso_cod = pfam_familier_cod
				where pfam_perso_cod = personnage
					and perso_gmon_cod = 441
					and dper_dieu_cod = v_dieu
					and perso_actif='O';

			if found then
				v_gain_familier := v_ferveur + 10;
				v_priere_familier := max(v_priere_familier, min(v_priere_familier + v_gain_familier, 200));
				update dieu_perso set dper_points = v_priere_familier where dper_perso_cod = v_familier_divin;
				if v_priere_familier = 200 then
					code_retour := code_retour||'Votre familier a bénéficié de cette action ; il ne pourra pas accumuler plus d’énergie divine par vos prières.<br />';
				elseif v_priere_familier > 200 then
					code_retour := code_retour||'Votre familier a trop d’énergie divine pour avoir pu bénéficier de cette action.<br />';
				else
					code_retour := code_retour||'Votre familier a bénéficié de cette action.<br />';
				end if;
			end if;
		end if;
	else
	end if;
	-- maintenant, on rajoute du pouvoir au dieu en question
         -- pour remonter les points de pouvoir des dieux on profite de la période haloween 2009 pour passer le gain à 3
	update dieu set dieu_pouvoir = dieu_pouvoir + 2 + coalesce(v_dieu_niveau, 0)
		where dieu_cod = v_dieu;

	-- on enlève les PA au perso
	update perso set perso_pa = perso_pa - getparm_n(48),perso_priere = 1,perso_px = perso_px + 0.25
		where perso_cod = personnage;

	-- on regarde où en est le perso de son avancement
	select into v_avancement dieu_avancement(dper_niveau, dper_points)
	from dieu_perso
	where dper_perso_cod = personnage
		and dper_dieu_cod = v_dieu;

	-- événements
	texte_evt := '[perso_cod1] a prié';
		values(nextval('seq_levt_cod'),29,now(),1,personnage,texte_evt,'O','O',personnage);

	-- on génère un code retour
	if v_avancement <= 50 then
		code_retour := code_retour || 'Votre prière a été entendue par votre dieu ; ';
	elsif v_avancement <= 80 then
		code_retour := code_retour || 'Votre dieu vous a écouté avec bienveillance ; ';
	else
		code_retour := code_retour || 'Vous sentez que votre dieu a été particulièrement intéressé par votre prière ; ';
	end if;

	code_retour := code_retour || ' il a gagné en puissance.<br>Vous gagnez 0,25 PX.';
	return code_retour;
end;$_$;


ALTER FUNCTION public.prie_dieu(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION prie_dieu(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.prie_dieu(integer, integer) IS 'Le personnage donné effectue une prière, en temple, à l’adresse du dieu donné.';


--
-- Name: prie_dieu_ext(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.prie_dieu_ext(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*******************************************************/
/* fonction prie_dieu_ext                              */
/*  on passe en params                                 */
/*  $1 = perso_cod                                     */
/*  $2 = dieu_cod                                      */
/* on a en retour une chaine html exploitable          */
/*******************************************************/
declare
	code_retour text;          -- code_html de retour
-- personnage
	personnage alias for $1;   -- perso_cod du prieur
	v_pa integer;              -- pa du perso
	v_nom_dieu text;           -- nom éventuel de l’ancien dieu
	v_dieu_cod integer;        -- dieu_cod éventuel de l’ancien dieu
	v_dieu_niveau integer;     -- niveau éventuel de l’ancien dieu
	v_grade text;              -- nom du grade éventuel de l’ancien dieu
	v_duree_renegat interval;  -- durée de "rénégation"
	v_type_perso integer;
	v_familier_divin integer;  -- perso_cod du familier divin (s’il existe)
	v_priere_familier integer; -- points de prière du familier divin
	v_ferveur integer;         -- valeur calculée entre le rang et les PP du prêtre (rang * 2 + racine(PP) / 20)
	v_gain_familier integer;   -- gain en PP pour le familier
	v_avancement integer;      -- avancement du prêtre dans son niveau
-- dieu
	v_dieu alias for $2;       -- dieu_cod
	texte_evt text;

begin
	code_retour := '';
	--if to_char(now(),'DD/MM/YYYY') in ('22/04/2011', '23/04/2011') then
	--	return 'Un silence pesant fait écho à votre prière...';
	--end if;
	-- on commence par faire les vérifs d’usage
	select into
		v_pa,v_type_perso
		perso_pa,perso_type_perso
		from perso
		where perso_cod = personnage;
	if not found then
		code_retour := '<p>Anomalie ! Personnage non trouvé !</p>';
		return code_retour;
	end if;
	if v_pa < getparm_n(48) then
		code_retour := '<p>Anomalie ! Pas assez de PA pour prier ce dieu !</p>';
		return code_retour;
	end if;
	if v_type_perso = 3 then
		code_retour := '<p>Le dieu regarde d’un air méprisant la créature qui tente de le prier. Un familier est indigne de s’adresser directement à son dieu !</p>';
		return code_retour;
	end if;
	-- on regarde s’il avait déjà prié ici ou ailleurs
	select into
		v_dieu_cod,
		v_dieu_niveau,
		v_nom_dieu,
		v_ferveur

		dper_dieu_cod,
		dper_niveau,
		dieu_nom,
		dper_niveau * 2 + floor(sqrt(dper_points) / 20)

		from dieu_perso,dieu
		where dper_perso_cod = personnage
		and dper_dieu_cod = dieu_cod
		and dper_niveau >= 2;
	if found then
		if v_dieu_cod != v_dieu then
			code_retour := '<p>Anomalie sur le numéro de Dieu !</p>';
			return code_retour;
		else
			-- on a déjà un fidèle, on peut "augmenter" son compteur
			update dieu_perso
				set dper_points = dper_points + 10
				where dper_perso_cod = personnage;

			-- on ajoute des points au familier divin
			select into v_familier_divin, v_priere_familier perso_cod, dper_points
				from perso_familier
				inner join perso on perso_cod = pfam_familier_cod
				inner join dieu_perso on dper_perso_cod = pfam_familier_cod
				where pfam_perso_cod = personnage
					and perso_gmon_cod = 441
					and dper_dieu_cod = v_dieu
					and perso_actif='O';

			if found then
				v_gain_familier := v_ferveur + 10;
				v_priere_familier := max(v_priere_familier, min(v_priere_familier + v_gain_familier, 200));
				update dieu_perso set dper_points = v_priere_familier where dper_perso_cod = v_familier_divin;
				if v_priere_familier = 200 then
					code_retour := code_retour||'Votre familier a bénéficié de cette action ; il ne pourra pas accumuler plus d’énergie divine par vos prières.<br />';
				elseif v_priere_familier > 200 then
					code_retour := code_retour||'Votre familier a trop d’énergie divine pour avoir pu bénéficier de cette action.<br />';
				else
					code_retour := code_retour||'Votre familier a bénéficié de cette action.<br />';
				end if;
			end if;
		end if;
	else
		code_retour := '<p>Anomalie ! Vous ne pouvez pas prier ce dieu en extérieur !</p>';
		return code_retour;
	end if;
	-- maintenant, on rajoute du pouvoir au dieu en question
         -- pour remonter les points de pouvoir des dieux on profite de la période haloween 2009 pour passer le gain à 3

	update dieu set dieu_pouvoir = dieu_pouvoir + 2 + coalesce(v_dieu_niveau, 0)
		where dieu_cod = v_dieu;

	-- on enlève les PA au perso
	update perso set perso_pa = perso_pa - getparm_n(48),perso_priere = 1,perso_px = perso_px + 0.25
		where perso_cod = personnage;

	-- on regarde où en est le perso de son avancement
	select into v_avancement dieu_avancement(dper_niveau, dper_points)
	from dieu_perso
	where dper_perso_cod = personnage
		and dper_dieu_cod = v_dieu;

	-- événements
	texte_evt := '[perso_cod1] a prié';
		values(nextval('seq_levt_cod'),29,now(),1,personnage,texte_evt,'O','O',personnage);

	-- on génère un code retour
	if v_avancement <= 50 then
		code_retour := code_retour || 'Votre prière a été entendue par votre dieu ; ';
	elsif v_avancement <= 80 then
		code_retour := code_retour || 'Votre dieu vous a écouté avec bienveillance ; ';
	else
		code_retour := code_retour || 'Vous sentez que votre dieu a été particulièrement intéressé par votre prière ; ';
	end if;

	code_retour := code_retour || ' il a gagné en puissance.<br>Vous gagnez 0,25 PX.';

	if (v_pa >= 2 * getparm_n(48)) then
		code_retour := code_retour||'<br><br><a href="action.php?methode=prie_ext&dieu='||cast(v_dieu as varchar(2))||'">Continuer les prières ('|| cast(getparm_n(48) as varchar(2)) ||' PA)</a>';
	end if;
	return code_retour;
end;$_$;


