--
-- Name: prochaine_dlt(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.prochaine_dlt(integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    AS $_$declare
    v_perso alias for $1;
    v_temps_tour integer;
    v_pv integer;
    v_pv_max integer;
    v_min_pv_manquants integer;
    v_poids numeric;
    v_poids_max integer;
    v_pa integer;
    v_util_pa_restants integer;
    v_dlt timestamp;
    v_variation integer; -- Variation en minutes

    v_ignore_malus_blessures integer;

begin
    select into v_temps_tour,
        v_pv,
        v_pv_max,
        v_poids,
        v_poids_max,
        v_pa,
        v_util_pa_restants,
        v_dlt

        perso_temps_tour,
        perso_pv,
        perso_pv_max,
        get_poids(v_perso),
        perso_enc_max,
        perso_pa,
        perso_utl_pa_rest,
        perso_dlt
    from perso
    where perso_cod = v_perso;

    v_variation := 0;
    if ( v_util_pa_restants = 1 ) then
        v_variation := v_variation - round(v_temps_tour*v_pa/24);
    end if;

    v_min_pv_manquants := max(0, v_pv_max - v_pv - calcul_regen_max(v_perso));
    if ( valeur_bonus(v_perso, 'PDL') = 0 and v_min_pv_manquants != 0 ) then
        v_variation := v_variation + round(v_temps_tour*(v_min_pv_manquants)/(v_pv_max*4));
    end if;

    -- Bleda 6/2/11 Distortion temporelle
    v_variation := v_variation + valeur_bonus(v_perso, 'DIS');
    v_variation := v_variation - valeur_bonus(v_perso, 'DIT');

    if ( v_poids > v_poids_max) then
        v_variation := v_variation + round((v_temps_tour*v_poids/v_poids_max - v_temps_tour)/2);
    end if;

    return v_dlt::timestamp + (to_char(v_temps_tour + v_variation,'999999') || ' minutes')::interval;

end;
$_$;


ALTER FUNCTION public.prochaine_dlt(integer) OWNER TO delain;

--
-- Name: purge_mes(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.purge_mes(integer) RETURNS text
    LANGUAGE plpgsql
    AS $$/*************************************/
/* fonction purge_mes                */
/*   purge les messages non archivés */
/*************************************/
declare
	code_retour text;
	temp interval;
	test integer;
	test2 integer;
begin
	temp := trim(to_char(getparm_n(10), '99999999999')) || ' days';

	delete from messages_dest
	where dmsg_archive = 'N'
		and exists
		(
			select 1 from messages
			where dmsg_msg_cod = msg_cod
			and msg_date2 <= now() - temp
		)
		and not exists
		(
			select 1 from perso_compte
			inner join compte on compt_cod = pcompt_compt_cod
			where compt_monstre = 'O'
				and pcompt_perso_cod = dmsg_perso_cod
		);
	get diagnostics test = row_count;

	temp :=  trim(to_char(getparm_n(23), '99999999999')) || ' days';

-- On ne supprime plus du tout les messages archivés.
/*
	delete from messages_dest
	where dmsg_archive = 'O'
		and exists
		(
			select 1 from messages
			where dmsg_msg_cod = msg_cod
			and msg_date2 <= now() - temp
		);
	get diagnostics test2 = row_count;
	test := test + test2;
*/
	code_retour := 'Fonction purge_mes : ' || trim(to_char(test, '99999')) || ' lignes effacées dans dest, ';

	-- On supprime les messages émis, s’ils ne sont pas archivés, et si aucun des destinataires ne l’a gardé.
	delete from messages_exp
	where emsg_archive = 'N'
		and not exists
		(
			select 1 from messages_dest
			where emsg_msg_cod = dmsg_msg_cod
		)
		and not exists
		(
			select 1 from perso_compte
			inner join compte on compt_cod = pcompt_compt_cod
			where compt_monstre = 'O'
				and pcompt_perso_cod = emsg_perso_cod
		);
	get diagnostics test = row_count;
	code_retour := code_retour ||trim(to_char(test, '99999')) || ' lignes effacées dans exp, ';

	-- On supprime les messages qui n’ont plus ni expéditeur ni destinataire
	delete from messages
	where not exists
		(
			select 1 from messages_exp
			where emsg_msg_cod = msg_cod
		)
		and not exists
		(
			select 1 from messages_dest
			where dmsg_msg_cod = msg_cod
		);
	get diagnostics test = row_count;
	code_retour := code_retour ||trim(to_char(test, '99999')) || ' messages effacés, ';
	temp := trim(to_char(getparm_n(44), '99999999999')) || ' days';

	-- On supprime les rumeurs
	delete from rumeurs
	where rum_poids <= 0;
	get diagnostics test = row_count;
	code_retour := code_retour ||trim(to_char(test, '99999')) || ' rumeurs effacées.';

	-- Et on diminue le poids des rumeurs existantes
	update rumeurs set rum_poids = (rum_poids / 1.2)::integer - 1;

	return code_retour;
end;$$;


ALTER FUNCTION public.purge_mes(integer) OWNER TO delain;

--
-- Name: FUNCTION purge_mes(integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.purge_mes(integer) IS 'Gère la purge des messages et des rumeurs';


