		and t2.act_tact_cod = 3
		and t2.act_tact_cod = ta2.tact_cod
		and t2.act_perso1 != t2.act_perso2
		group by libelle,joueur
		loop
			select into nom_perso perso_nom from perso where perso_cod = ligne.joueur;
		px_perso := round(((ligne.donnee+1)/(total_points::numeric)) * v_px);
		total_distrib := total_distrib + px_perso;
		code_retour := code_retour||nom_perso||'('||trim(to_char(ligne.joueur,'99999999999'))||') a gagne '||trim(to_char(px_perso,'9999999999999'))||' PX pour l''action : <b>'||ligne.libelle||'</b><br>';
	end loop;
	code_retour := code_retour||trim(to_char(total_distrib,'99999999999'))||' ont été distribués.';
	--
	--
	total_distrib := 0;
	total_distrib_n := 0;
	code_retour := code_retour||'<p class="titre">Methode 7 : global avec PX en numérique</p>';
	total_points := 0;
	for ligne in select tact_libelle as libelle,sum(act_donnee + 1) as donnee,act_perso1 as joueur from action,action_type
		where act_perso2 = cible and act_tact_cod = tact_cod
		and act_tact_cod in (1,2)
		group by libelle,joueur
		union all
		select ta2.tact_libelle as libelle,sum(t2.act_donnee+1) as donnee,t2.act_perso1 as joueur from action t2,action_type ta2
		where t2.act_perso2 in
		(select t1.act_perso1 from action t1
		where t1.act_perso2 = cible and act_tact_cod in (1,2))
		and t2.act_tact_cod = 3
		and t2.act_tact_cod = ta2.tact_cod
		and t2.act_perso1 != t2.act_perso2
		group by libelle,joueur
		loop
		total_points := total_points + ligne.donnee;
	end loop;
	for ligne in select tact_libelle as libelle,sum(act_donnee+1) as donnee,act_perso1 as joueur from action,action_type
		where act_perso2 = cible and act_tact_cod = tact_cod
		and act_tact_cod in (1,2)
		group by libelle,joueur
		union all
		select ta2.tact_libelle as libelle,sum(t2.act_donnee+1) as donnee,t2.act_perso1 as joueur from action t2,action_type ta2
		where t2.act_perso2 in
		(select t1.act_perso1 from action t1
		where t1.act_perso2 = cible and act_tact_cod in (1,2))
		and t2.act_tact_cod = 3
		and t2.act_tact_cod = ta2.tact_cod
		and t2.act_perso1 != t2.act_perso2
		group by libelle,joueur
		loop
			select into nom_perso perso_nom from perso where perso_cod = ligne.joueur;
		px_perso_n := ((ligne.donnee+1)/(total_points::numeric)) * v_px;
		total_distrib_n := total_distrib_n + px_perso_n;
		code_retour := code_retour||nom_perso||'('||trim(to_char(ligne.joueur,'99999999999'))||') a gagne '||trim(to_char(px_perso_n,'99999999999D99'))||' PX pour l''action : <b>'||ligne.libelle||'</b><br>';
	end loop;
	code_retour := code_retour||trim(to_char(total_distrib_n,'99999999999D99'))||' ont été distribués.';

	--
	--
	total_distrib := 0;
	total_distrib_n := 0;
	code_retour := code_retour||'<p class="titre">Methode 8 : global avec PX en numérique, calul en niveau téhorique par participant</p>';
	total_points := 0;
	for ligne in select tact_libelle as libelle,sum(act_donnee + 1) as donnee,act_perso1 as joueur from action,action_type
		where act_perso2 = cible and act_tact_cod = tact_cod
		and act_tact_cod in (1,2)
		group by libelle,joueur
		union all
		select ta2.tact_libelle as libelle,sum(t2.act_donnee+1) as donnee,t2.act_perso1 as joueur from action t2,action_type ta2
		where t2.act_perso2 in
		(select t1.act_perso1 from action t1
		where t1.act_perso2 = cible and act_tact_cod in (1,2))
		and t2.act_tact_cod = 3
		and t2.act_tact_cod = ta2.tact_cod
		and t2.act_perso1 != t2.act_perso2
		group by libelle,joueur
		loop
		total_points := total_points + ligne.donnee;
	end loop;
	for ligne in select tact_libelle as libelle,sum(act_donnee+1) as donnee,act_perso1 as joueur from action,action_type
		where act_perso2 = cible and act_tact_cod = tact_cod
		and act_tact_cod in (1,2)
		group by libelle,joueur
		union all
		select ta2.tact_libelle as libelle,sum(t2.act_donnee+1) as donnee,t2.act_perso1 as joueur from action t2,action_type ta2
		where t2.act_perso2 in
		(select t1.act_perso1 from action t1
		where t1.act_perso2 = cible and act_tact_cod in (1,2))
		and t2.act_tact_cod = 3
		and t2.act_tact_cod = ta2.tact_cod
		and t2.act_perso1 != t2.act_perso2
		group by libelle,joueur
		loop
			select into nom_perso perso_nom from perso where perso_cod = ligne.joueur;
		select into n1,px1 perso_niveau,perso_px from perso where perso_cod = ligne.joueur;
		n1_r := niveau_relatif(px1);
		if n1_r > n1
			then n1 := n1_r;
		end if;
		select into n2,px2 perso_niveau,perso_px from perso where perso_cod = cible;
		n2_r := niveau_relatif(px2);
		if n2_r > n2
			then n2 := n2_r;
		end if;
		px_theo := 10 + 2*(n2 - n1) + n2;
		if px_theo < 0 then
			px_theo := 0;
		end if;
		px_perso_n := ((ligne.donnee+1)/(total_points::numeric)) * px_theo;
		total_distrib_n := total_distrib_n + px_perso_n;
		code_retour := code_retour||nom_perso||'('||trim(to_char(ligne.joueur,'99999999999'))||') a gagne '||trim(to_char(px_perso_n,'99999999999D99'))||' PX pour l''action : <b>'||ligne.libelle||'</b><br>';
	end loop;
	code_retour := code_retour||trim(to_char(total_distrib_n,'99999999999D99'))||' ont été distribués.';
		--
	--
	total_distrib := 0;
	total_distrib_n := 0;
	code_retour := code_retour||'<p class="titre">Methode 9 : global avec PX en numérique, calul en niveau téhorique par participant, en tenant compte des dégats reçus</p>';
	total_points := 0;
	for ligne in select tact_libelle as libelle,sum(act_donnee + 1) as donnee,act_perso1 as joueur from action,action_type
		where act_perso2 = cible and act_tact_cod = tact_cod
		and act_tact_cod in (1,2)
		group by libelle,joueur
		union all
		select ta2.tact_libelle as libelle,sum(t2.act_donnee+1) as donnee,t2.act_perso1 as joueur from action t2,action_type ta2
		where t2.act_perso2 in
		(select t1.act_perso1 from action t1
		where t1.act_perso2 = cible and act_tact_cod in (1,2))
		and t2.act_tact_cod = 3
		and t2.act_tact_cod = ta2.tact_cod
		and t2.act_perso1 != t2.act_perso2
		group by libelle,joueur
		union all
		select tact_libelle as libelle,sum(act_donnee + 1) as donnee,act_perso2 as joueur from action,action_type
		where act_perso1 = cible and act_tact_cod = tact_cod
		and act_tact_cod = 4
		and act_donnee >= 0
		group by libelle,joueur
		loop
		total_points := total_points + ligne.donnee;
	end loop;
	for ligne in select tact_libelle as libelle,sum(act_donnee+1) as donnee,act_perso1 as joueur from action,action_type
		where act_perso2 = cible and act_tact_cod = tact_cod
		and act_tact_cod in (1,2)
		group by libelle,joueur
		union all
		select ta2.tact_libelle as libelle,sum(t2.act_donnee+1) as donnee,t2.act_perso1 as joueur from action t2,action_type ta2
		where t2.act_perso2 in
		(select t1.act_perso1 from action t1
		where t1.act_perso2 = cible and act_tact_cod in (1,2))
		and t2.act_tact_cod = 3
		and t2.act_tact_cod = ta2.tact_cod
		and t2.act_perso1 != t2.act_perso2
		group by libelle,joueur
		union all
		select tact_libelle as libelle,sum(act_donnee + 1) as donnee,act_perso2 as joueur from action,action_type
		where act_perso1 = cible and act_tact_cod = tact_cod
		and act_tact_cod = 4
		and act_donnee >= 0
		group by libelle,joueur
		loop
			select into nom_perso perso_nom from perso where perso_cod = ligne.joueur;
		select into n1,px1 perso_niveau,perso_px from perso where perso_cod = ligne.joueur;
		n1_r := niveau_relatif(px1);
		if n1_r > n1
			then n1 := n1_r;
		end if;
		select into n2,px2 perso_niveau,perso_px from perso where perso_cod = cible;
		n2_r := niveau_relatif(px2);
		if n2_r > n2
			then n2 := n2_r;
		end if;
		px_theo := 10 + 2*(n2 - n1) + n2;
		if px_theo < 0 then
			px_theo := 0;
		end if;
		px_perso_n := ((ligne.donnee+1)/(total_points::numeric)) * px_theo;
		total_distrib_n := total_distrib_n + px_perso_n;
		code_retour := code_retour||nom_perso||'('||trim(to_char(ligne.joueur,'99999999999'))||') a gagne '||trim(to_char(px_perso_n,'99999999999D99'))||' PX pour l''action : <b>'||ligne.libelle||'</b><br>';
	end loop;
	code_retour := code_retour||trim(to_char(total_distrib_n,'99999999999D99'))||' ont été distribués.';
	return code_retour;
end;

$_$;


ALTER FUNCTION public.px_auto(integer, integer) OWNER TO delain;

--
-- Name: quete(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.quete(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function quete : permet de lancer des requêtes relatives aux  */
/*          quêtes automatisees                                  */
/* On passe en paramètres                                        */
/*    $1 = quete_cod numéro de quête concernée                    */
/*    $2 = perso_cod numéro du perso concerné                    */
/* Le code sortie est texte utilisable                           */
/*****************************************************************/
/* Créé le 07/06/2006                                            */
/* Liste des modifications :                                     */
/*****************************************************************/
declare
/*******************************/
		 code_retour text;
		 code_quete alias for $1;
		 quete_nombre integer;
		 personnage alias for $2;
		 des integer;
		 image text;
		 dieu integer;
/*******************************/

begin

code_retour := '';

--------------------------------------------
-- Quête des Dieux, Falis, Elian, Balgur
--------------------------------------------
/*Etape 1 Falis et Balgur, même code quête, dieux différents*/
if (code_quete = 7) then
select into dieu dper_dieu_cod
	from dieu_perso
	where dper_perso_cod = personnage;
		 		 /*Traitement du cas de Falis*/
		 		 if dieu = 7 then

			 		 		select into quete_nombre pquete_nombre
							 		 		from quete_perso
							 		 		where pquete_quete_cod = code_quete
							 		 		and pquete_perso_cod = personnage;
							/*On regarde à quelle étape de la quête on se trouve */

						 if not found then
								des := lancer_des(1,2);
		 		 		 		 if des = 1 then
		 		 		 		 		 image := 'quete.png';
		 		 		 		 else
		 		 		 		 		 image := 'quete1.png';
		 		 		 		 end if;

		 		 		 		 /*validation de l'étape, possibilité de passer à la suivante*/
		 		 		 		 update perso set perso_px = perso_px + 10, perso_prestige = perso_prestige + 2 where perso_cod = personnage;

		 		 		 		 code_retour := code_retour||'<br> En vous approchant de la paroi, vous avez vu cet interstice. La curiosité aidant, vous vous êtes pris au jeu, et vous avez voulu en savoir plus.
		 		 		 		 		 		 		 		 <br>Mais la curiosité vous a fait un drôle de cadeau. Non pas celui dont on vous avait parlé, pas celui dun trésor enfoui. Dailleurs qui croit encore aux trésors ?
		 		 		 		 		 		 		 		 <br>Non, le résultat en est encore plus étrange.
		 		 		 		 		 		 		 		 <br>Vous êtes arrivé dans une sorte de petite grotte, assez petite pour quun groupe ne puisse pas sy introduire en même temps. Vous avez à 		 		 		 		 		 		 		 		 peine la place de tourner sur vous même.
		 		 		 		 		 		 		 		 <br>Il vous faut alors un peu de temps pour comprendre que les sigles qui se trouvent autour de vous sont en fait des lettres.
		 		 		 		 		 		 		 		 <br>En utilisant votre source de lumière, et en tournant sur vous même, vous pouvez alors apercevoir une sorte de poème, n''ayant que peu de sens à 		 		 		 		 		 		 vos yeux.
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br><img src="http://www.jdr-delain.net/avatars/'||image||'">
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>A sa lecture, une douleur se fait ressentir dans votre tête, et une voix semble vous parler intérieurement :
		 		 		 		 		 		 		 		 <br><i>Tu es initié maintenant. A toi de trouver le chemin
		 		 		 		 		 		 		 		 <br>Peu pourront t''aider pour cela, choisi bien tes amis</i>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>Un courant d''air éteint alors votre flamme, et l''obscurité vous oblige à battre en retraite ...';

		 		 		 		 return code_retour;
		 		 		elsif (quete_nombre = 1) then
						 		 code_retour := code_retour||'<br>Un sentiment de déjà vu remonte en vous. Mais vous ne savez plus si il s''agit de cette même petite salle déjà visitée ... Une salle portant des marques sur le mur, une salle avec une sorte de poème. Rien n''est pareil. Pourtant, il vous semble vous rappeler les évènements, la voix, l''obscurité ...
						 		 <br>Vos souvenirs vous joueraient-ils des tours ? Vous seriez vous trompé ?';
						 		 return code_retour;
						else return code_retour;
		 			 	end if;

		 		 /*Traitement du cas de Balgur, dans les mêmes cachettes*/
		 		 elsif dieu = 2 then

		 					 select into quete_nombre pquete_nombre
					 					 from quete_perso
					 					 where pquete_quete_cod = code_quete
					 					 and pquete_perso_cod = personnage;
							/*On regarde à quelle étape de la quête on se trouve */
						 if quete_nombre = 1 then

		 		 		 		 /*validation de l'étape, possibilité de passer à la suivante*/
		 		 		 		 update quete_perso set pquete_nombre = 2 where pquete_perso_cod = personnage and pquete_quete_cod = 7;
		 		 		 		 update perso set perso_px = perso_px + 10, perso_prestige = perso_prestige + 2 where perso_cod = personnage;

		 		 		 		 code_retour := code_retour||'<br> En vous approchant de la paroi, vous avez vu cet interstice. La curiosité aidant, vous vous êtes pris au jeu, et vous avez voulu en savoir plus.
		 		 		 		 		 		 		 		 <br>Mais la curiosité vous a fait un drôle de cadeau. Non pas celui dont on vous avait parlé, pas celui dun trésor enfoui. Dailleurs qui croit encore aux trésors ?
		 		 		 		 		 		 		 		 <br>Non, le résultat en est encore plus étrange.
		 		 		 		 		 		 		 		 <br>Vous êtes arrivé dans une sorte de petite grotte, assez petite pour quun groupe ne puisse pas sy introduire en même temps. Vous avez à 		 		 		 		 		 		 		 		 peine la place de tourner sur vous même.
		 		 		 		 		 		 		 		 <br>Il vous faut alors un peu de temps pour comprendre que les sigles qui se trouvent autour de vous sont en fait des lettres.
		 		 		 		 		 		 		 		 <br>En utilisant votre source de lumière, et en tournant sur vous même, vous pouvez alors apercevoir une sorte de poème, n''ayant que peu de sens à 		 		 		 		 		 		 vos yeux.
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br><img src="http://www.jdr-delain.net/avatars/quete_2165balg1ur.png">
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>A sa lecture, une douleur se fait ressentir dans votre tête, et une voix semble vous parler intérieurement :
		 		 		 		 		 		 		 		 <br><i>Tu es initié maintenant. A toi de trouver le chemin
		 		 		 		 		 		 		 		 <br>Peu pourront t''aider pour cela, choisi bien tes amis</i>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>Un courant d''air éteint alors votre flamme, et l''obscurité vous oblige à battre en retraite ...';

		 		 		 		 return code_retour;
		 		 		 elsif (quete_nombre > 1) then
						 		 code_retour := code_retour||'<br>Un sentiment de déjà vu remonte en vous. Mais vous ne savez plus si il s''agit de cette même petite salle déjà visitée ... Une salle portant des marques sur le mur, une salle avec une sorte de poème. Rien n''est pareil. Pourtant, il vous semble vous rappeler les évènements, la voix, l''obscurité ...
						 		 <br>Vos souvenirs vous joueraient-ils des tours ? Vous seriez vous trompé ?';
						 		 return code_retour;
		 			 	else return code_retour;
		 			 	end if;
		 			else return code_retour;
				 end if;

-- Fin du cas de la quête 7, concernant Balgur et Falis

-- On gère le cas des adeptes d'Elian qui ont validé la première étape dans un temple, donc code quête 8, étape 1
/*Etape 1 Elian*/
elsif (code_quete = 8) then
		 select into quete_nombre pquete_nombre
						 from quete_perso
						 where pquete_quete_cod = code_quete
						 and pquete_perso_cod = personnage;
/*On regarde à quelle étape de la quête on se trouve */
		 if quete_nombre = 1 then

		 		 		 		 /*validation de l'étape, possibilité de passer à la suivante*/
		 		 		 		 update quete_perso set pquete_nombre = 2 where pquete_perso_cod = personnage and pquete_quete_cod = 8;
		 		 		 		 update perso set perso_px = perso_px + 10, perso_prestige = perso_prestige + 2 where perso_cod = personnage;

		 		 		 		 code_retour := code_retour||'<br> Votre vision ne vous avait pas trahi.
		 		 		 		 		 		 		 		 <br>Il y a bien ici un message qui vous était destiné
		 		 		 		 		 		 		 		 <br>Mais le plus étrange, c''est que ce message n''est pas gravé, il semble flotter sur les murs, comme si sa présence était irréelle.
		 		 		 		 		 		 		 		 <br>sa lecture ne peut que vous laisser perplexe ...
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br><img src="http://www.jdr-delain.net/avatars/quete1_00el1an.png">
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>A sa lecture, une douleur se fait ressentir dans votre tête, et une voix semble vous parler intérieurement :
		 		 		 		 		 		 		 		 <br><b><i>Tu es initié maintenant. A toi de trouver le chemin
		 		 		 		 		 		 		 		 <br>Peu pourront t''aider pour cela, choisi bien tes amis
		 		 		 		 		 		 		 		 <br>Que la foi en Moi te guide vers la suite de ta destinée</i></b>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>Un courant d''air éteint alors votre flamme, votre tête bourdonne, et toute réalité semble s''évanouir ...';

		 		 		 		 return code_retour;
		 end if;
		 if (quete_nombre = 2) then

		 		 code_retour := code_retour||'<br>Un sentiment de déjà vu remonte en vous. Mais vous ne savez plus si il s''agit de cette même petite salle déjà visitée ... Une salle portant des marques sur le mur, une salle avec une sorte de poème. Rien n''est pareil. Pourtant, il vous semble vous rappeler les évènements, la voix, l''obscurité ...
		 		 <br>Vos souvenirs vous joueraient-ils des tours ? Vous seriez vous trompé ?';
		 		 return code_retour;
		 end if;

/* On gère le cas des adeptes d'Elian qui ont validé la deuxième étape dans la cachette 1 ainsi que retour dans un temple, donc code de quête 9, étape 1 de la quête*/
elsif (code_quete = 9) then
		 select into quete_nombre pquete_nombre
						 from quete_perso
						 where pquete_quete_cod = code_quete
						 and pquete_perso_cod = personnage;
/*On regarde à quelle étape de la quête on se trouve */
		 if quete_nombre = 1 then

		 		 		 		 /*validation de l'étape, possibilité de passer à la suivante*/
		 		 		 		 update quete_perso set pquete_nombre = 2 where pquete_perso_cod = personnage and pquete_quete_cod = 9;

		 		 		 		 code_retour := code_retour||'<br> A nouveau, une vision en entrant dans cet endroit vous submerge
		 		 		 		 		 		 		 		 <br>Cette sensation, vous la reconnaissez, elle ne peut vous laisser de marbre.
		 		 		 		 		 		 		 		 <br>A nouveau, un message danse devant vos yeux
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br><img src="http://www.jdr-delain.net/avatars/quete_15el1an2.png">
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>Comme la première fois, une douleur se fait ressentir dans votre tête, et une voix semble vous parler intérieurement :
		 		 		 		 		 		 		 		 <br><i><b>Tu as eu le courage de poursuivre.
		 		 		 		 		 		 		 		 <br>Tout est maintenant dit
		 		 		 		 		 		 		 		 <br>Prends garde à l''épée qui pourrait se trouver en travers de ta route</i></b>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>Un courant d''air éteint alors votre flamme, et l''obscurité vous oblige à battre en retraite ...';

		 		 		 		 return code_retour;
		 end if;
		 if (quete_nombre = 2) then
		 		 code_retour := code_retour||'<br>Un sentiment de déjà vu remonte en vous. Mais vous ne savez plus si il s''agit de cette même petite salle déjà visitée ... Une salle portant des marques sur le mur, une salle avec une sorte de poème. Rien n''est pareil. Pourtant, il vous semble vous rappeler les évènements, la voix, l''obscurité ...
		 		 <br>Vos souvenirs vous joueraient-ils des tours ? Vous seriez vous trompé ?';
		 		 return code_retour;
		 end if;


/*Etape 1 Io*/
elsif (code_quete = 10) then
		 select into quete_nombre pquete_nombre
						 from quete_perso
						 where pquete_quete_cod = code_quete
						 and pquete_perso_cod = personnage;
/*On regarde à quelle étape de la quête on se trouve */
		 if quete_nombre = 1 then
		 		 /*Traitement du cas de Io*/
		 		 		 		 /*validation de l'étape, possibilité de passer à la suivante*/
		 		 		 		 update quete_perso set pquete_nombre = 2 where pquete_perso_cod = personnage and pquete_quete_cod = 10;
		 		 		 		 update perso set perso_px = perso_px + 10, perso_prestige = perso_prestige + 2 where perso_cod = personnage;

		 		 		 		 code_retour := code_retour||'<br> Votre vision ne vous avait pas trahi.
		 		 		 		 		 		 		 		 <br>Il y a bien ici un message qui vous était destiné
		 		 		 		 		 		 		 		 <br>Mais le plus étrange, c''est que ce message n''est pas gravé, il semble flotter sur les murs, comme si sa présence était irréelle.
		 		 		 		 		 		 		 		 <br>Sa lecture ne peut que vous laisser perplexe ...
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br><img src="http://www.jdr-delain.net/avatars/quete_I1io6o.png">
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>A sa lecture, une douleur se fait ressentir dans votre tête, et une voix semble vous parler intérieurement :
		 		 		 		 		 		 		 		 <br><b><i>L''Aveugle te guide
		 		 		 		 		 		 		 		 <br>Il est la Balance qui doit guider le monde
		 		 		 		 		 		 		 		 <br>En Moi tu dois voir, pour le futur établir.</i>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>
		 		 		 		 		 		 		 		 <br>Un courant d''air éteint alors votre flamme, votre tête bourdonne, et toute réalité semble s''évanouir ...';

		 		 		 		 return code_retour;
		 end if;
		 if (quete_nombre = 2) then

		 		 code_retour := code_retour||'<br>Un sentiment de déjà vu remonte en vous. Mais vous ne savez plus si il s''agit de cette même petite salle déjà visitée ... Une salle portant des marques sur le mur, une salle avec une sorte de poème. Rien n''est pareil. Pourtant, il vous semble vous rappeler les évènements, la voix, l''obscurité ...
		 		 <br>Vos souvenirs vous joueraient-ils des tours ? Vous seriez vous trompé ?';
		 		 return code_retour;
		 end if;
end if;
return code_retour;
-------------------------------------------------
-- Fin Quête des Dieux, Falis, Elian, Balgur
-------------------------------------------------
end;$_$;


ALTER FUNCTION public.quete(integer, integer) OWNER TO delain;

--
-- Name: ramasse_objet(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.ramasse_objet(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function ramasse_arme : ramasse une arme posée au sol et la   */
/*          dans l’inventaire du perso                           */
/* On passe en paramètres                                        */
/*    $1 = perso_cod                                             */
/*    $2 = arm_cod                                               */
/* Le code sortie est un entier                                  */
/*    0 = tout s est bien passé                                  */
/*    1 = le perso et l’arme ne sont pas sur la même position    */
/*    2 = le perso n a pas assez de pa                           */
/*    3 = perso non trouvé                                       */
/*    4 = arme non trouvée                                       */
/*    5 = position perso non trouvée                             */
/*    6 = position arme non trouvée                              */
/*****************************************************************/
/* Créé le 11/03/2003                                            */
/* Liste des modifications :                                     */
/*  18/12/2003 : Retour en texte pour intégrer les mimiques      */
/*  26/06/2012 : Ajout du nom de l’objet dans les événements     */
/*  26/06/2012 : Rationalisation des requêtes                    */
/*****************************************************************/
declare
	code_retour text;
	personnage alias for $1;
	num_objet alias for $2;
	pos_perso positions.pos_cod%type;
	pos_objet positions.pos_cod%type;
	pa integer;
	objet_position_cod objet_position.pobj_cod%type;
	nom_objet objets.obj_nom_generique%type;
	texte_evt text;
	tobjet type_objet.tobj_libelle%type;
	gobj integer;
	code_monstre integer;
	code_ia text;
	tangibilite text;
	cout_pa integer;
	v_poids_max integer;
	v_poids_actu numeric;
	v_poids_objet numeric;
	v_temp integer;
begin
	/**************************************/
	/* Etape 1                            */
	/* On cherche le perso                */
	/**************************************/
	select into tangibilite, v_poids_max, pos_perso, v_poids_actu, pa
		perso_tangible, perso_enc_max, ppos_pos_cod, get_poids(perso_cod), perso_pa
	from perso
	inner join perso_position on ppos_perso_cod = perso_cod
	where perso_cod = personnage;
	if not found then
		code_retour := '<p>Anomalie : personnage ou position non trouvés !</p>';
		return code_retour;
	end if;

	/**************************************/
	/* Etape 2                            */
	/* On cherche l’objet                 */
	/**************************************/
	select into nom_objet, tobjet, gobj, v_poids_objet, pos_objet, objet_position_cod
		obj_nom_generique, tobj_libelle, gobj_cod, obj_poids, pobj_pos_cod, pobj_cod
	from objets
	inner join objet_generique on gobj_cod = obj_gobj_cod
	inner join type_objet on tobj_cod = gobj_tobj_cod
	inner join objet_position on pobj_obj_cod = obj_cod
	where obj_cod = num_objet;
	if not found then
		code_retour := '<p>Anomalie : objet ou position non trouvés !</p>';
		return code_retour;
	end if;

	-- Interdit de ramasser pendant un défi
	if exists(select 1 from defi where defi_statut = 1 and personnage in (defi_lanceur_cod, defi_cible_cod)
		UNION ALL select 1 from defi
			inner join perso_familier on pfam_perso_cod in (defi_lanceur_cod, defi_cible_cod)
			where defi_statut = 1 and pfam_familier_cod = personnage)
	then
		code_retour := '<p>Anomalie : il est interdit de ramasser un objet pendant un défi !</p>';
		return code_retour;
	end if;

	-- on regarde le poids
	if ((v_poids_actu + v_poids_objet) > (v_poids_max * 3))	then
		v_poids_max := v_poids_max * 3;
		code_retour := '<p>Vous ne pouvez ramasser un objet qui vous fait dépasser '||trim(to_char(v_poids_max,'99999999'))||' d’encombrement.</p>';
		return code_retour;
	end if;

	/********************************************/
	/* Etape 3                                  */
	/* On verifie la correspondance des pos_cod */
	/********************************************/
	if pos_perso != pos_objet then
		code_retour := '<p>Anomalie : le perso et l’objet ne sont pas sur la même position !</p>';
		return code_retour;
	end if;

	/********************************/
	/* Etape 4                      */
	/* On verifie les PA du perso   */
	/********************************/
	if tangibilite = 'O' then
		cout_pa := getparm_n(41);
	else
		cout_pa := getparm_n(42);
	end if;
	if pa < cout_pa then
		code_retour := '<p>Anomalie : pas assez de PA pour ramasser cet objet !</p>';
		return code_retour;
	end if;

	/********************************/
	/* Etape 5                    */
	/* Modif Bleda 30/01/11         */
	/* Glyphe de résurrection ?     */
	/********************************/
	if gobj = 859 then
		select into v_temp 1 from perso_glyphes
		where pglyphe_perso_cod = personnage
		--and pglyphe_resurrection is not NULL
		and pglyphe_obj_cod = num_objet;

		if found then
			code_retour := '<p>Erreur : vous ne pouvez ramasser votre propre glyphe de résurrection !</p>';
			return code_retour;
		end if;
	end if;

	/********************************/
	/* Etape 6                      */
	/* on valide les changements    */
	/********************************/
	-- 6.1 : on supprime le objet_position
	delete from objet_position where pobj_cod = objet_position_cod;

	-- 6.2 : on regarde à tout hasard si ce n’est pas une mimique
	if gobj = 84 then
		code_monstre := cree_monstre_pos(38, pos_objet);

		update perso set perso_cible = personnage
		where perso_cod = code_monstre;

		code_ia := ia_monstre(code_monstre);
		code_retour := '<p>L’objet que vous essayez de ramasser est en fait une mimique, qui vous attaque en se réveillant !</p>';
		return code_retour;
	end if;
	if gobj = 85 then
		code_monstre := cree_monstre_pos(39, pos_objet);

		update perso set perso_cible = personnage
		where perso_cod = code_monstre;

		code_ia := ia_monstre(code_monstre);
		code_retour := '<p>L’objet que vous essayez de ramasser est en fait une mimique, qui vous attaque en se réveillant !</p>';
		return code_retour;
	end if;

	-- 6.3 : on rajoute l’objet dans l’inventaire du perso
	-- 6.3.1 : on regarde si l’objet est identifié
	if exists (select 1 from perso_identifie_objet
		where pio_perso_cod = personnage
		and pio_obj_cod = num_objet)
	then
		values (nextval('seq_perobj_cod'), personnage, num_objet, 'O', 'N');
	else
		values (nextval('seq_perobj_cod'), personnage, num_objet, 'N', 'N');
	end if;

	-- 6.4 : on enlève les pa au perso
	update perso set perso_pa = (pa - cout_pa) where perso_cod = personnage;

	-- 6.5 : on rajoute un événement
	texte_evt := '[perso_cod1] a ramassé un objet « ' || nom_objet || ' » (' || tobjet || ' ' || to_char(num_objet, '99999999999') || ')';
	values (nextval('seq_levt_cod'), 3, now(), 1, personnage, texte_evt, 'O', 'O');

	code_retour := '<p>L’objet « ' || nom_objet || ' » a été ramassé. Il est maintenant dans votre inventaire.</p>';
	return code_retour;
end;$_$;


ALTER FUNCTION public.ramasse_objet(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION ramasse_objet(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.ramasse_objet(integer, integer) IS 'Gère le ramassage d’un objet par un perso.';


--
-- Name: ramasse_objet_cachette(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.ramasse_objet_cachette(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function ramasse_objet_cachette : récupère un objet qui se    */
/*          trouve dans une cachette. Copie de la fonction       */
/*          ramasse_objet                                        */
/*          dans l inventaire du perso                           */
/* On passe en paramètres                                        */
/*    $1 = perso_cod                                             */
/*    $2 = obj_cod                                               */
/* Le code sortie est un entier                                  */
/*    0 = tout s est bien passé                                  */
/*    1 = le perso et l arme ne sont pas sur la même position    */
/*    2 = le perso n a pas assez de pa                           */
/*    3 = perso non trouvé                                       */
/*    4 = arme non trouvée                                       */
/*    5 = position perso non trouvée                             */
/*    6 = position arme non trouvée                              */
/*****************************************************************/
/* Créé le 15/05/2006 : copie de ramasse_objet                   */
/* Liste des modifications :                                     */
/*****************************************************************/
declare
	code_retour text;
	personnage alias for $1;
	num_objet alias for $2;
	pos_perso positions.pos_cod%type;
	pos_objet positions.pos_cod%type;
	compt integer;
	pa integer;
	objet_position_cod objet_position.pobj_cod%type;
	nom_objet objet_generique.gobj_nom_generique%type;
	nom_perso perso.perso_nom%type;
	texte_evt text;
	tobjet type_objet.tobj_libelle%type;
	gobj integer;
	code_monstre integer;
	code_ia text;
	tangibilite text;
	cout_pa integer;
	v_poids_max integer;
	v_poids_actu numeric;
	v_poids_objet numeric;

begin
/**************************************/
/* Etape 1                            */
/* On cherche le perso                */
/**************************************/
	select into compt,tangibilite,v_poids_max
		perso_cod,perso_tangible,perso_enc_max
		from perso where perso_cod = personnage;
	v_poids_actu := get_poids(personnage);
	if not found then
		code_retour := '<p>Anomalie : Personnage non trouvé !';
		return code_retour;
	end if;							-- if compt = 0
/**************************************/
/* Etape 2                            */
/* On cherche l objet                 */
/**************************************/
	select into 	nom_objet,
						tobjet,
						v_poids_objet
					obj_nom_generique,
					tobj_libelle,
					obj_poids
		from objets,objet_generique,type_objet
			where obj_cod = num_objet
			and obj_gobj_cod = gobj_cod
			and gobj_tobj_cod = tobj_cod;
	if not found then
		code_retour := '<p>Anomalie : objet non trouvé !';
		return code_retour;
	end if;
-- on regarde le poids
	if ((v_poids_actu + v_poids_objet) > (v_poids_max * 3))	then
		v_poids_max := v_poids_max * 3;
		code_retour := '<p>Vous ne pouvez pas récupérer un objet qui vous fait dépasser '||trim(to_char(v_poids_max,'99999999'))||' d''encombrement.';
		return code_retour;
	end if;
/**************************************/
/* Etape 3                            */
/* On cherche le pos_cod du perso     */
/**************************************/
	select into pos_perso,nom_perso ppos_pos_cod,perso_nom from perso_position,perso
			where ppos_perso_cod = personnage
			and perso_cod = personnage;
	if not found then
		code_retour := '<p>Anomalie : position perso incohérente !';
		return code_retour;
	end if;							-- if compt_pos != 0
/**************************************/
/* Etape 5 inutile pour les cachettes */
/*          													*/
/**************************************/
/********************************************/
/* Etape 6   inutile pour les cachettes	    */
/* 																					*/
/********************************************/
/********************************/
/* Etape 7                      */
/* On verifie les PA du perso   */
/********************************/
	if tangibilite = 'O' then
		cout_pa := getparm_n(41);
	else
		cout_pa := getparm_n(42);
	end if;
	select into pa perso_pa from perso where perso_cod = personnage;
	if pa < cout_pa then
		code_retour := '<p>Anomalie : Pas assez de PA pour ramasser cet objet !';
		return code_retour;
	end if; 							-- if pa < 1
/********************************/
/* Etape 8                      */
/* on valide les changements    */
/********************************/
-- 8.1 : on supprime le arme_position
	delete from objet_position where pobj_cod = objet_position_cod;
--8.1 bis : on supprime l'arme de la cachette
	delete from cachettes_objets where objcache_obj_cod = num_objet;
	select into tobjet,gobj gobj_tobj_cod,gobj_cod from objets,objet_generique
		where obj_cod = num_objet
		and obj_gobj_cod = gobj_cod;
-- 8.1.1 : on regarde à tout hasard si ce n est pas une mimique
	if gobj = 84 then
		code_monstre := cree_monstre_pos(38,pos_objet);
		update perso set perso_cible = personnage
			where perso_cod = code_monstre;
		code_ia := ia_monstre(code_monstre);
		code_retour := '<p>L''objet que vous essayez de récupérer est en fait une mimique, qui vous attaque en se réveillant !';
		return code_retour;
	end if;
	if gobj = 85 then
		code_monstre := cree_monstre_pos(39,pos_objet);
		update perso set perso_cible = personnage
			where perso_cod = code_monstre;
		code_ia := ia_monstre(code_monstre);
		code_retour := '<p>L''objet que vous essayez de récupérer est en fait une mimique, qui vous attaque en se réveillant !';
		return code_retour;
	end if;

-- 8.2 : on rajoute l arme dans l inventaire du perso
-- 8.2.1 : on regarde si l objet est identifie
	if exists (select 1 from perso_identifie_objet
		where pio_perso_cod = personnage
		and pio_obj_cod = num_objet) then
				values (nextval('seq_perobj_cod'),personnage,num_objet,'O','N');
	else
			values (nextval('seq_perobj_cod'),personnage,num_objet,'N','N');
	end if;
-- 8.2.2 : si c est une rune, on l identifie

	if tobjet = 5 then
		update perso_objets
			set perobj_identifie = 'O'
			where perobj_perso_cod = personnage
			and perobj_obj_cod = num_objet;
	end if;
	-- 8.3 : on enlève les pa au perso
	update perso set perso_pa = (pa - cout_pa) where perso_cod = personnage;
	-- 8.4 : on rajoute un évènement
	texte_evt := '[perso_cod1] a récupéré un objet ('||tobjet||' '||to_char(num_objet,'99999999999')||')';
		values (nextval('seq_levt_cod'),3,now(),1,personnage,texte_evt,'O','O');
	code_retour := '<p>L''objet a été récupérer de la cachette. Il est maintenant dans votre inventaire.';
	return code_retour;
end;$_$;


ALTER FUNCTION public.ramasse_objet_cachette(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION ramasse_objet_cachette(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.ramasse_objet_cachette(integer, integer) IS 'Déclinaison de la fonction ramasse_objet, pour tenir compte du cas des cachettes';


--
-- Name: ramasse_or(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.ramasse_or(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function ramasse_arme : ramasse de l or posé au sol et        */
/*          l ajoute dans l inventaire du perso                  */
/* On passe en paramètres                                        */
/*    $1 = perso_cod                                             */
/*    $2 = or_cod                                                */
/* Le code sortie est un entier                                  */
/*    0 = tout s est bien passé                                  */
/*    1 = le perso et l ore ne sont pas sur la même position     */
/*    2 = le perso n a pas assez de pa                           */
/*    3 = perso non trouvé                                       */
/*    4 = or non trouvée                                         */
/*    5 = position perso non trouvée                             */
/*    6 = position or non trouvée                                */
/*****************************************************************/
/* Créé le 11/03/2003                                            */
/* Liste des modifications :                                     */
/*****************************************************************/
declare
	code_retour text;
	personnage alias for $1;
	num_or alias for $2;
	qte_or or_position.por_qte%type;
	compt integer;
	pos_perso positions.pos_cod%type;
	pos_or positions.pos_cod%type;
	pa perso.perso_pa%type;
	texte_evt text;
	nom_perso perso.perso_nom%type;
	tangibilite text;
	cout_pa integer;
	or_palpable text;

begin
/**************************************/
/* Etape 1                            */
/* On cherche le perso                */
/**************************************/
	select into compt,tangibilite perso_cod,perso_tangible from perso where perso_cod = personnage;
	if not found then
		code_retour := '<p>Erreur ! Perso non trouvé !';
		return code_retour;
	end if;
/**************************************/
/* Etape 2                            */
/* On cherche l or                    */
/**************************************/
	select into compt por_cod from or_position where por_cod = num_or;
	if not found then
		code_retour := '<p>Erreur ! Brouzoufs non trouvés !';
		return code_retour;
	end if;
/**************************************/
/* Etape 3                            */
/* On cherche le pos_cod du perso     */
/**************************************/
	select into pos_perso,nom_perso ppos_pos_cod,perso_nom from perso_position,perso
			where ppos_perso_cod = personnage
			and perso_cod = personnage;
	if not found then								-- if compt_pos != 0
		code_retour := '<p>Erreur ! Position du ramasseur non trouvée !';
		return code_retour;
	end if;							-- if compt_pos != 0

/**************************************/
/* Etape 4                            */
/* Interdit de ramasser pendant un défi*/
/**************************************/
	if exists(select 1 from defi where defi_statut = 1 and personnage in (defi_lanceur_cod, defi_cible_cod)
		UNION ALL select 1 from defi
			inner join perso_familier on pfam_perso_cod in (defi_lanceur_cod, defi_cible_cod)
			where defi_statut = 1 and pfam_familier_cod = personnage)
	then
		code_retour := '<p>Anomalie : il est interdit de ramasser des brouzoufs pendant un défi !</p>';
		return code_retour;
	end if;
/**************************************/
/* Etape 5                            */
/* On cherche le pos_cod de l or      */
/**************************************/
	if tangibilite = 'O' then
		cout_pa := getparm_n(41);
	else
		cout_pa := getparm_n(42);
	end if;
/********************************/
/* Etape 7                      */
/* On verifie les PA du perso   */
/********************************/
	select into pa perso_pa from perso where perso_cod = personnage;
	if pa < cout_pa then
		code_retour := '<p>Erreur ! Vous n''avez pas assez de PA pour ramasser ces brouzoufs !';
		return code_retour;
	end if;
	select into pos_or,qte_or,or_palpable por_pos_cod,por_qte,por_palpable from or_position
		where por_cod = num_or;
	if or_palpable = 'N' then
		update perso set perso_pa = perso_pa - cout_pa where perso_cod = personnage;
		delete from or_position where por_cod = num_or;
		code_retour := '<p>A peine vous approchez vous du tas de brouzoufs que celui-ci disparait. Vous comprenez qu''il s''agissait de brouzoufs de farfadets....';
		return code_retour;
	end if;
/********************************************/
/* Etape 6                                  */
/* On verifie la correspondance des pos_cod */
/********************************************/
	if pos_perso != pos_or then
		code_retour := '<p>Erreur ! Distance trop éloignée !';
		return code_retour;
	end if; 							-- if pos_perso != pos_arme
/********************************/
/* Etape 7                      */
/* On verifie les PA du perso   */
/********************************/
	select into pa perso_pa from perso where perso_cod = personnage;
	if pa < cout_pa then
		code_retour := '<p>Erreur ! Vous n''avez pas assez de PA pour ramasser ces brouzoufs !';
		return code_retour;
	end if; 							-- if pa < 1
/********************************/
/* Etape 8                      */
/* on valide les changements    */
/********************************/
-- 8.1 : on supprime le or_position
	delete from or_position where por_cod = num_or;
-- 8.2 : on rajoute l or dans l inventaire du perso
	update perso set perso_po = (perso_po + qte_or) where perso_cod = personnage;
-- 8.3 : on enlève les pa au perso
	update perso set perso_pa = (pa - cout_pa) where perso_cod = personnage;
-- 8.4 : on rajoute un évènement
	texte_evt := '[perso_cod1] a ramassé '||to_char(qte_or,'99999999')||' brouzoufs.';
		values (nextval('seq_levt_cod'),4,now(),1,personnage,texte_evt,'O','O');
	code_retour := '<p>Vous avez ramassé '||trim(to_char(qte_or,'99999999'))||' brouzoufs.';
	return code_retour;
end;
$_$;


ALTER FUNCTION public.ramasse_or(integer, integer) OWNER TO delain;

--
-- Name: rappel_coterie(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.rappel_coterie(integer, integer) RETURNS integer
    LANGUAGE plpgsql STRICT
    AS $_$/*****************************************************************/
/* function rappel_coterie :                                     */
/*  Ramène un personnage au dernier de ses compagnons ayant      */
/*     essayé de le rappeler                                     */
/* On passe en paramètres                                        */
/*   $1 = perso appelé                                           */
/*   $2 = perso à rejoindre                                      */
/* Le code sortie est la nouvelle position après la mort, ou -1  */
/*****************************************************************/
/* Créé le 21/04/2012                                            */
/* Liste des modifications :                                     */
/*****************************************************************/
declare
-------------------------------------------------------------
-- variables servant pour la sortie
-------------------------------------------------------------
	code_retour integer;               -- nouvelle position
-------------------------------------------------------------
-- variables concernant le lanceur
-------------------------------------------------------------
	v_perso_cible 	alias for $1;	-- perso_cod du décédé
	v_perso_source 	alias for $2;	-- perso_cod du perso appeleur
	v_pos_cible		integer;		-- Position du perso cible
	v_pos_source	integer;		-- Position du perso source
	v_pos_source_x	integer;		-- Position X du perso source
	v_pos_source_y	integer;		-- Position Y du perso source
	v_distcarr_xy	integer;		-- distance horizontale (au carré)
	v_distcarr_n	integer;		-- distance verticale (au carré)
	v_distance		integer;		-- distance d’arrivée
	v_etage_source	integer;		-- etage de la case de destination
	etage_gm		integer;		-- Valeur de l’étage du garde manger

begin
	-- Initialisation
	etage_gm	:= 90;

	-- On récupère la position du perso source.
	select into v_pos_source, v_pos_source_x, v_pos_source_y, v_etage_source
			ppos_pos_cod, pos_x, pos_y, pos_etage
		from perso_position
		inner join positions on pos_cod = ppos_pos_cod
		where ppos_perso_cod = v_perso_source;

	-- Si le perso appelant est au garde-manger, il est inaccessible
	if v_etage_source = etage_gm then
		return -1;
	end if;

	-- On récupère la position du perso cible.
	select into v_pos_cible ppos_pos_cod from perso_position
		where ppos_perso_cod = v_perso_cible;

	-- On évalue leur distance (un étage compte pour 10).
	select into v_distcarr_xy, v_distcarr_n
			(p1.pos_x - p2.pos_x)*(p1.pos_x - p2.pos_x) + (p1.pos_y - p2.pos_y)*(p1.pos_y - p2.pos_y),
			(e1.etage_reference - e2.etage_reference) * (e1.etage_reference - e2.etage_reference) * 100
		from positions p1
		inner join etage e1 on e1.etage_numero = p1.pos_etage
		inner join positions p2 on p2.pos_cod = v_pos_cible
		inner join etage e2 on e2.etage_numero = p2.pos_etage
		where p1.pos_cod = v_pos_source;

	-- Choix de la case de téléportation, au hasard dans un rayon de v_distance / 5, mais toujours entre 2 et 10 cases.
	v_distance := min(max(cast(sqrt(v_distcarr_xy + v_distcarr_n) as integer) / 5, 2), 10);

	select into code_retour pos_cod from positions
		where pos_etage = v_etage_source
			and abs(pos_x - v_pos_source_x) <= v_distance and abs(pos_y - v_pos_source_y) <= v_distance
			and not exists (select 1 from murs where mur_pos_cod = pos_cod)
			and (pos_etage != 0 OR abs(pos_x) < 20 AND abs(pos_y) < 20)
		order by random()
		limit 1;
	if found then
		-- Trouvé une position
		return code_retour;
	else
		-- Pas de position libre trouvée.
		return -1;
	end if;
end;
$_$;


ALTER FUNCTION public.rappel_coterie(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION rappel_coterie(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.rappel_coterie(integer, integer) IS 'Trouve la case sur laquelle un perso va apparaître, une fois rappelé par sa coterie.';


--
-- Name: rappel_partiel_coterie(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.rappel_partiel_coterie(integer, integer) RETURNS text
    LANGUAGE plpgsql STRICT
    AS $_$/*****************************************************************/
/* function rappel_partiel_coterie :                             */
/*  Tente de ramener un personnage mort à sa coterie    	     */
/* On passe en paramètres                                        */
/*   $1 = perso appelé                                           */
/*   $2 = perso à rejoindre                                      */
/* Le code sortie du text HTML 									 */
/*****************************************************************/
/* Créé le 21/04/2012                                            */
/* Liste des modifications :                                     */
/* 21/06/2012 Reivax augmentation du nombre total de points en   */
/*   fonction de la taille de la coterie                         */
/*****************************************************************/
declare
-------------------------------------------------------------
-- variables servant pour la sortie
-------------------------------------------------------------
	code_retour text;               -- code html de retour
-------------------------------------------------------------
-- variables concernant le lanceur ou la cible
-------------------------------------------------------------
	v_perso_cible 		alias for $1;		-- perso_cod du décédé
	v_perso_source 		alias for $2;		-- perso_cod du perso appeleur
	v_coterie_source	integer;		-- groupe_cod de la coterie du perso rappelant
	v_taille_coterie	integer;		-- Taille de la coterie
	v_perso_pa		integer;		-- PA du lanceur
	v_dieu			integer;		-- Dieu_cod
	v_dieu_rang		integer;		-- Rang moyen des deux protagonistes dans la religion
	v_temp			integer;		-- variable multi-usage pour les vérifications
	v_temp_str		character varying(1);	-- variable multi-usage pour les vérifications
	etage_gm		integer;		-- Valeur de l’étage du garde manger
	v_compteur_rappel	integer;		-- Valeur du compteur de rappel
	v_total_necessaire	integer;		-- Nombre de points à accumuler pour effectuer le rappel
	v_increment_rappel	integer;		-- Valeur de l’incrément du rappel
	v_cout_PA		integer;		-- Coût en PA
	v_pos_retour		integer;		-- Position de retour
	v_arene			character(1);		-- Indique si l’étage de destination est une arène
	texte_evt		text;			-- Texte pour l’événement

begin
	--
	-- Initialisation
	--
	etage_gm		:= 90;
	v_cout_PA 		:= 6;
	v_increment_rappel	:= 6;	-- Est réévalué en fonction de la taille de la coterie, peut descendre jusqu’à 3.
	v_total_necessaire	:= 0;	-- cf plus bas : égal au niveau du perso cible
	code_retour		:= '';

	--
	-- Vérifications
	--

	-- PA
	select into v_perso_pa, v_temp
		perso_pa, perso_type_perso
		from perso where perso_cod = v_perso_source;
	if not found then
		code_retour := '<p><b>Erreur !</b> Lanceur inconnu.</p>';
		return code_retour;
	elseif v_temp <> 1 then
		code_retour := '<p><b>Erreur !</b> Les monstres et familiers ne peuvent pas rappeler leurs compagnons...</p>';
		return code_retour;
	elseif v_perso_pa < v_cout_PA then
		code_retour := '<p><b>Erreur !</b> Vous n’avez pas assez de PA pour réaliser cette action (6 PA nécessaires).</p>';
		return code_retour;
	end if;

	-- Coterie du perso source
	select into v_coterie_source
		pgroupe_groupe_cod
		from groupe_perso
		where pgroupe_perso_cod = v_perso_source and pgroupe_statut = 1;
	if not found then
		code_retour := '<p><b>Erreur !</b> Vous n’appartenez à aucune coterie.</p>';
		return code_retour;
	end if;

	-- Coterie active du perso cible
	select into v_temp
		pgroupe_groupe_cod
		from groupe_perso
		where pgroupe_perso_cod = v_perso_cible
			and pgroupe_statut = 1;
	if found then
		code_retour := '<p><b>Erreur !</b> La cible a déjà réintégré une coterie.</p>';
		return code_retour;
	end if;

	-- Coterie en suspend du perso cible
	select into v_compteur_rappel
		pgroupe_valeur_rappel
		from groupe_perso
		where pgroupe_perso_cod = v_perso_cible
			and pgroupe_statut = 2 and pgroupe_groupe_cod = v_coterie_source;
	if not found then
		code_retour := '<p><b>Erreur !</b> La cible ne peut plus être rappelée.</p>';
		return code_retour;
	end if;
        -- impalpabilité de la source
       	select into v_temp_str
		perso_tangible
		from perso
		where perso_cod = v_perso_source;
	if v_temp_str <> 'O' then
		code_retour := '<p><b>Erreur !</b> vous êtes impalpable, vous ne pouvez donc ramener votre compagnon.</p>';
		return code_retour;
	end if;

	-- impalpabilité de la cible
	select into v_temp_str, v_total_necessaire, v_temp
		perso_tangible, perso_niveau, perso_type_perso
		from perso
		where perso_cod = v_perso_cible;
	if v_temp_str <> 'N' then
		code_retour := '<p><b>Erreur !</b> La cible ne peut plus être rappelée.</p>';
		return code_retour;
	end if;
	if v_temp <> 1 then
		code_retour := '<p><b>Erreur !</b> Seul un aventurier peut être rappelé.</p>';
		return code_retour;
	end if;

	-- Garde manger, arènes.
	select into v_temp, v_arene
		pos_etage, etage_arene
		from perso_position
		inner join positions on pos_cod = ppos_pos_cod
		inner join etage on etage_numero = pos_etage
		where ppos_perso_cod = v_perso_source;
	if v_temp = etage_gm then
		code_retour := '<p><b>Erreur !</b> Vous êtes au garde-manger, et ne pouvez pas y rappeler de compagnons.</p>';
		return code_retour;
	end if;
	if v_arene = 'O' then
		code_retour := '<p><b>Erreur !</b> Vous êtes dans une arène, et ne pouvez pas y rappeler de compagnons.</p>';
		return code_retour;
	end if;

	--
	-- Exécution du rappel
	--

	-- Taille de la coterie, pour détermination de l’incrément
	select into v_taille_coterie
		count(*)
		from groupe_perso
		where pgroupe_groupe_cod = v_coterie_source and pgroupe_statut = 1;
	v_increment_rappel := v_increment_rappel - (min(4, v_taille_coterie / 15));

	-- Bonus supplémentaires en fonction de la religion
	select into v_dieu
		dper_dieu_cod
		from dieu_perso
		where dper_perso_cod = v_perso_source;
	if found then
		select into v_dieu
			dper_dieu_cod
			from dieu_perso
			where dper_perso_cod = v_perso_cible and dper_dieu_cod = v_dieu;
		if found then
			-- Les deux persos sont de la même religion, on leur octroie un petit bonus.
			select into v_dieu_rang
				floor(AVG(dper_niveau))
				from dieu_perso
				where dper_perso_cod IN (v_perso_cible, v_perso_source);
			v_increment_rappel := v_increment_rappel + v_dieu_rang;
			code_retour := code_retour || '<p>Votre dieu voyant vos prières pour votre compagnon mort vous donne un petit coup de pouce.</p>';
		end if;
	end if;

	-- événements de la prière
	texte_evt := '[attaquant] a prié pour ramener [cible] à ses côtés.';
	values(29, now(), 1, v_perso_cible, texte_evt, 'N', 'N', v_perso_source, v_perso_cible);
	values(29, now(), 1, v_perso_source, texte_evt, 'O', 'N', v_perso_source, v_perso_cible);

	-- Incrément du compteur
	v_compteur_rappel := v_compteur_rappel + v_increment_rappel;

	-- Résolution
	if v_compteur_rappel >= v_total_necessaire then
		v_pos_retour := rappel_coterie(v_perso_cible, v_perso_source);

		if v_pos_retour = -1 then
			code_retour := '<p><b>Erreur !</b> Aucune position n’a été trouvée pour rappeler votre compagnon...</p>';
			return code_retour;
		end if;

		-- position
		update perso_position set ppos_pos_cod = v_pos_retour where ppos_perso_cod = v_perso_cible;

		-- coterie
		update groupe_perso set pgroupe_valeur_rappel = 0, pgroupe_statut = 1
		where pgroupe_perso_cod = v_perso_cible
			and pgroupe_groupe_cod = v_coterie_source;

		-- malus : prolongation de l’impalpabilité, réduction des PV
		-- autres malus à envisager ?
		update perso set
			perso_nb_tour_intangible = perso_nb_tour_intangible + 5,
			perso_pv = perso_pv / 2
		where perso_cod = v_perso_cible;

		-- événements
		texte_evt := '[cible] a été téléporté vers [attaquant], et ramené à sa coterie.';
		values(38, now(), 1, v_perso_cible, texte_evt, 'N', 'O', v_perso_source, v_perso_cible);
		values(38, now(), 1, v_perso_source, texte_evt, 'O', 'N', v_perso_source, v_perso_cible);

		code_retour := code_retour || '<p>Enfin ! Votre compagnon décédé se matérialise à vos côtés. Il semble quelque peu sonné...</p>';
	else
		update groupe_perso set pgroupe_valeur_rappel = v_compteur_rappel
		where pgroupe_perso_cod = v_perso_cible
			and pgroupe_groupe_cod = v_coterie_source;

		code_retour := code_retour || '<p>Vous appelez votre compagnon, mais le lien est encore trop ténu pour le voir apparaître...</p>';
	end if;

	-- Décompte des PA
	update perso set perso_pa = perso_pa - v_cout_PA
	where perso_cod = v_perso_source;

	return code_retour;
end;
$_$;


ALTER FUNCTION public.rappel_partiel_coterie(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION rappel_partiel_coterie(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.rappel_partiel_coterie(integer, integer) IS 'Gère la tentative de rappel d’un compagnon de coterie mort au combat.';


--
-- Name: rattra_m(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.rattra_m() RETURNS integer
    LANGUAGE plpgsql
    AS $$declare
	ligne record;
	temp integer;
begin
for ligne in
	select obj_cod,gobj_nom from objets,objet_generique
where obj_gobj_cod = gobj_cod
and gobj_tobj_cod in (1,2)
and not exists
(select 1 from perso_objets where perobj_obj_cod = obj_cod)
and not exists
(select 1 from objet_position where pobj_obj_cod = obj_cod)
and not exists
(select 1 from stock_magasin where mstock_obj_cod = obj_cod)
and gobj_deposable = 'O' loop
	delete from perso_objets where perobj_obj_cod = ligne.obj_cod;
	temp := lancer_des(1,22);
	select into temp lieu_cod from lieu
		where lieu_tlieu_cod = 11
		offset temp limit 1;
	end loop;
	return 0;
end;

		$$;


ALTER FUNCTION public.rattra_m() OWNER TO delain;

--
-- Name: reduc_compt_pvp(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.reduc_compt_pvp() RETURNS text
    LANGUAGE plpgsql
    AS $$/********************************************************/
/* function reduc_compt_pvp                             */
/*   permet de réduire le compteur pvp si un temps      */
/*   égal à la dlt du perso est passé depuis la         */
/*   dernière modif du compteur                         */
/********************************************************/
declare
	ligne record;
	code_retour text;
	v_compt integer;
begin
	v_compt := 0;
	for ligne in select perso_cod
		from perso
		where perso_type_perso = 1
		and perso_actif = 'O'
		and perso_compt_pvp >= 1
		and perso_dmodif_compt_pvp + (to_char(perso_temps_tour,'99999999')||' minutes')::interval < now() loop
	--
	-- a priori, maintenant, on a les bons persos dont on doit baisser le compteur
	--
		update perso
			set perso_compt_pvp = perso_compt_pvp -1,
			perso_dmodif_compt_pvp = now()
			where perso_cod = ligne.perso_cod;
		v_compt := v_compt + 1;
	end loop;
	code_retour := trim(to_char(v_compt,'999999999999999'))||' compteurs baissés';
	return code_retour;
end;$$;


ALTER FUNCTION public.reduc_compt_pvp() OWNER TO delain;

--
-- Name: refuse_invitation(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.refuse_invitation(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/***********************************************/
/* refus_invitation                            */
/*  $1 = perso_cod                             */
/*  $2 = groupe_cod                            */
/***********************************************/
declare
	code_retour text;
	v_perso alias for $1;
	v_groupe_cod alias for $2;
	v_chef integer;
	v_num_mes integer;
	v_texte_mes text;
	v_nom_invite text;
	v_nom_groupe text;
begin
	-- on commence par virer l'invitation
	delete from groupe_perso
		where pgroupe_perso_cod = v_perso
		and pgroupe_groupe_cod = v_groupe_cod;
	-- on prépare un message
	select into v_chef groupe_chef
		from groupe
		where groupe_cod = v_groupe_cod;
	select into 	v_nom_invite
		perso_nom from perso
		where perso_cod = v_perso;




	v_num_mes := nextval('seq_msg_cod');
	--
		values (v_num_mes,v_perso);
		values (v_num_mes,v_chef,'N','N');
	return 'L''inscription a bien été refusée.';
end;$_$;


ALTER FUNCTION public.refuse_invitation(integer, integer) OWNER TO delain;

--
-- Name: rejoint_glyphe_resurrection(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.rejoint_glyphe_resurrection(integer) RETURNS integer
    LANGUAGE plpgsql STRICT
    AS $_$/*****************************************************************/
/* function rejoint_glyphe_resurrection :                        */
/*  si le perso a un glyphe de résurrection, on le supprime et   */
/*  retourne la position libre la plus proche du glyphe          */
/* On passe en paramètres                                        */
/*   $1 = perso                                                  */
/* Le code sortie est la nouvelle position après la mort, ou -1  */
/*****************************************************************/
/* Créé le 30/01/2011                                            */
/* Liste des modifications :                                     */
/*****************************************************************/
declare
-------------------------------------------------------------
-- variables servant pour la sortie
-------------------------------------------------------------
	code_retour integer;               -- nouvelle position
-------------------------------------------------------------
-- variables concernant le lanceur
-------------------------------------------------------------
	v_perso alias for $1;		-- perso_cod du décédé
	v_glyphe	integer;	-- obj_cod du glyphe
	v_distance	integer;	--distance au glyphe
	v_pos_glyphe	integer;	--Position du glyphe
	v_etage		integer;
	v_x		integer;
	v_y		integer;
	etage_gm	integer;	-- Valeur de l’étage du garde manger

begin
	-- Initialisation
	etage_gm	:= 90;

	select into v_glyphe pglyphe_obj_cod
	from perso_glyphes
	where pglyphe_perso_cod = v_perso
		and pglyphe_type = 'R';
	if not found then
 		return -1;
	end if;

	-- On récupère la position du glyphe au sol.
	select into v_pos_glyphe pobj_pos_cod from objet_position
		where v_glyphe = pobj_obj_cod;
	if not found then
		-- On cherche dans les inventaires
		select into v_pos_glyphe ppos_pos_cod
		from perso_position, perso_objets
		where ppos_perso_cod = perobj_perso_cod
			and perobj_obj_cod = v_glyphe;
		if not found then
			-- Impossible que l''objet soit perdu, mais on ne sait jamais
			return -1;
		end if;
	end if;

	-- On a la position du glyphe.
	-- On rejoint la position
	select into v_etage, v_x, v_y pos_etage, pos_x, pos_y from positions
	where pos_cod = v_pos_glyphe;

	-- Si le glyphe est au garde-manger, il est inaccessible
	if v_etage = etage_gm then
		return -1;
	end if;

	v_distance := 0;
	loop
		select into code_retour pos_cod from positions
		where pos_etage = v_etage
			and abs(pos_x - v_x) <= v_distance and abs(pos_y - v_y) <= v_distance
			and not exists (select 1 from murs where mur_pos_cod = pos_cod );
		if found then
			-- Trouvé une position
			return code_retour;
		end if;
		if v_distance < 10 then
			v_distance := v_distance + 1;
		else
			-- Pas de position libre à moins de 10 cases. Glyphe non atteignable.
			return -1;
		end if;
	end loop;

	-- On n''arrive jamais ici.
	return -1;
end;
$_$;


ALTER FUNCTION public.rejoint_glyphe_resurrection(integer) OWNER TO delain;

--
-- Name: relache_monstre_4e_perso(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.relache_monstre_4e_perso(integer) RETURNS character varying
    LANGUAGE plpgsql
    AS $_$/********************************************************/
/* function relache_monstre_4e_perso                          */
/* Relâche un monstre précédemment attribué à un compte en    */
/* guise de 4e perso.                                         */
/* parametres :                                               */
/*  $1 = perso_cod du monstre à relâcher                      */
/* Sortie :                                                   */
/*  code_retour = texte à afficher                            */
/**************************************************************/
/**************************************************************/
/* Création - 24/09/2012 - Reivax                             */
/**************************************************************/
declare
	code_perso alias for $1;       -- perso_cod
	v_trop_recent smallint;        -- vaut 1 si le monstre a été attribué trop récemment
	v_actif varchar(1);            -- Type choisi pour le 4e perso
	retour varchar(200);           -- code retour contenant le texte à afficher
begin
/*********************************************************/
/*        I N I T I A L I S A T I O N S                  */
/*********************************************************/
	retour := 'Le monstre n’est pas supprimé, mais son contrôle vous en est retiré.'; --par défaut

/*********************************************************/
/*                  C O N T R O L E S                    */
/*********************************************************/
	-- controle sur la possibilité d’ajouter un 4e perso
	select into v_trop_recent, v_actif
		case when (now() - pcompt_date_attachement) < '1 day'::interval then 1 else 0 end, perso_actif
	from perso
	inner join perso_compte on pcompt_perso_cod = perso_cod
	where perso_cod = code_perso;
	if not found then
		return 'Erreur ! Le monstre n’a pas été trouvé.';
	end if;
	if v_trop_recent = 1 AND v_actif = 'O' then
		return 'Ce monstre vous a été affecté trop récemment, gardez-le au moins 24 heures !';
	end if;

/*********************************************************/
/*             E X É C U T I O N                         */
/*********************************************************/
	-- Suppression du monstre du compte du joueur
	DELETE FROM perso_compte WHERE pcompt_perso_cod = code_perso;

	-- Réactivation de l’IA
	UPDATE perso SET perso_dirige_admin = 'N' WHERE perso_cod = code_perso;

	return retour;
end;		$_$;


