--
-- Name: sitting(integer, integer, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.sitting(integer, integer, timestamp with time zone, timestamp with time zone) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function sitting : Déclaration de sitting                     */
/* On passe en paramètres                                        */
/*   $1 = compte sitteur                                         */
/*   $2 = compte sitté                                           */
/*   $3 = Durée du sitting, convertit en heure                   */
/*   $4 = Date de debut du sitting                               */
/* Le code sortie est une chaine html utilisable directement     */
/*****************************************************************/
/* Créée le 07/12/2006                                           */
/* Liste des modifications :                                     */
/*****************************************************************/

declare
-------------------------------------------------------------
-- variables d'entrée
-------------------------------------------------------------
	compte_sitteur alias for $1;		-- Compte du sitteur ==> Compte_cod
	compte_sit alias for $2;				-- Compte du sitté ==> Compte_nom
	date_deb alias for $3;					-- Date de début du sitting
	date_fin alias for $4;					-- Date de fin du sitting
-------------------------------------------------------------
-- variables de calcul
-------------------------------------------------------------
	sitting_encours integer; 				-- si le compte est déjà sitté ou prévu de l'être
	sitteur_encours integer;				-- si le sitteur a déjà un sitting en cours
	compte_exist integer;						-- test d'existance du compte sitteur inscrit
	code_retour text;
begin

/*Prévoir interface pour connaitre les sittings déclarés*/
/*Prévoir une interface pour annuler un sitting programmé, mais pas un sitting en cours*/

/* Première étape : controle du temps annoncé de sitting.
Si supérieur à 5 jours, message d'anomalie */

/*calcul de la date de fin théorique*/
code_retour := '';

select into sitting_encours csit_compte_sitte from compte_sitting
			where date_deb >= csit_ddeb
			and date_deb <= csit_dfin
			and compte_sit = csit_compte_sitte;
select into sitteur_encours csit_compte_sitteur from compte_sitting,compte
			where date_deb < csit_ddeb
			and date_deb > csit_dfin
			and compte_sitteur = compt_nom
			and csit_compte_sitteur = compt_cod;
select into compte_exist compt_cod from compte
		where compt_cod = compte_sitteur;
/*Vérification que le compte sitteur existe :*/
if compte_exist is null then
		code_retour := code_retour||'********************************************<br><b>Le compte sitteur que vous indiquez n''existe pas</b><br>********************************************';
		return code_retour;
/* Vérification de la durée de sitting */
/*Elsif duree > 120 then
		code_retour := code_retour||'********************************************<br><b>Vous ne pouvez pas déclarer une durée de sitting supérieure à 5 jours</b><br>********************************************';
		return code_retour;*/
/* Deuxième étape : vérif que le compte ne doit pas déjà être sitté dans la période mentionnée*/
elsif sitting_encours is not null  then
		code_retour := code_retour||'********************************************<br><b>Ce compte doit déjà être sitté dans la période mentionnée.<br>Un seul sitting est autorisé par compte.</b><br>********************************************';
		return code_retour;
/*Quatrième étape : vérif que le sitteur n'a pas déjà un autre compte en sitting*/
elsif sitteur_encours is not null then
		code_retour := code_retour||'********************************************<br><b>Ce compte doit déjà sitter un autre compte que le votre, et il n''est pas autorisé de sitter plus d''un compte à la fois.</b><br>********************************************';
		return code_retour;
/* Cinquième étape : intégration dans la table de sitting */
else
		values (compte_sit,compte_sitteur,date_deb,date_fin,now());
		code_retour := code_retour||'Votre demande de sitting a bien été prise en compte<br>Un message a été envoyé à l''intention de votre sitteur.';
		return code_retour;
end if;
end;$_$;


ALTER FUNCTION public.sitting(integer, integer, timestamp with time zone, timestamp with time zone) OWNER TO delain;

--
-- Name: soin_compteur_pvp(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.soin_compteur_pvp(integer) RETURNS void
    LANGUAGE plpgsql
    AS $_$/*********************************************/
/* soin_compteur_pvp                         */
/*  $1 = perso sur lequel on fait les soins  */
/* Retour : void  			                     */
/*********************************************/
/* créé le 08/11/2009 par Blade              */
/*********************************************/
declare
	personnage alias for $1;
	v_compt_pvp integer;
  v_compt_pvp1 integer;    -- ajout azaghal pour garde fou
	v_pv integer;
	v_pv_max numeric;
	v_niveau integer;

begin
/*La fonction permet après des soins de recalculer le compteur pvp. A inclure dans toute fonction de soin */
	select into v_compt_pvp,v_pv,v_pv_max
		perso_compt_pvp,perso_pv,perso_pv_max
		from perso
		where perso_cod = personnage;
	if ((v_pv/v_pv_max) < 0.20) then
		v_niveau := 4;
	elsif ((v_pv/v_pv_max) < 0.33) then
		v_niveau := 3;
	elsif ((v_pv/v_pv_max) < 0.66) then
		v_niveau := 2;
	elsif  ((v_pv/v_pv_max) < 0.80) then
		v_niveau := 1;
	elsif  ((v_pv/v_pv_max) >= 0.80) then
		v_niveau := 0;
	end if;
	if v_compt_pvp < v_niveau then
		v_niveau = v_compt_pvp;
	end if;
	update perso
		set perso_compt_pvp = v_niveau
		where perso_cod = personnage;
end;$_$;


ALTER FUNCTION public.soin_compteur_pvp(integer) OWNER TO delain;

--
-- Name: FUNCTION soin_compteur_pvp(integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.soin_compteur_pvp(integer) IS 'Fonction qui permet de recalculer le compteur pvp en cas de soin : si le compteur est inférieur au niveau des blessures, il est conservé en l''état.
Cette fonction est à utiliser en perform soin_compteur_pvp(variable) pour tout élément permettant de réaliser des gains de pv autres que ceux de l''activation de dlt';


--
-- Name: start_redispatch(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.start_redispatch(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************************/
/* redispatch                                               */
/************************************************************/
declare
	code_retour text;
	personnage alias for $1;
	compt integer;
	redispatch text;
	compt_total integer;
begin
	compt_total := 0;
	select into redispatch
		perso_redispatch
		from perso
		where perso_cod = personnage;
	if redispatch != 'P' then
		code_retour := 'Vous n''êtes pas autorisé à faire une répartition des niveaux ! ';
		return code_retour;
	end if;
	-- generique
	update perso set perso_redispatch = 'E' where perso_cod = personnage;
	-- degats distance
	select into compt
		perso_amel_deg_dex
		from perso
		where perso_cod = personnage;
	if compt is null then
		compt := 0;
	end if;
	update perso set perso_amel_deg_dex = 0,perso_nb_redist = perso_nb_redist + compt
		where perso_cod = personnage;
	compt_total := compt_total + compt;
	-- regen
	select into compt
		perso_des_regen
		from perso
		where perso_cod = personnage;
	if compt is null then
		compt := 0;
	end if;
	update perso set perso_des_regen = 1,perso_nb_redist = perso_nb_redist + (compt - 1)
		where perso_cod = personnage;
	compt_total := compt_total + compt - 1;
	-- corps à corps
	select into compt
		perso_amelioration_degats
		from perso
		where perso_cod = personnage;
	if compt is null then
		compt := 0;
	end if;
	update perso set perso_amelioration_degats = 0,perso_nb_redist = perso_nb_redist + compt
		where perso_cod = personnage;
	compt_total := compt_total + compt;
	--armure
	select into compt
		perso_amelioration_armure
		from perso
		where perso_cod = personnage;
	if compt is null then
		compt := 0;
	end if;
	update perso set perso_amelioration_armure = 0,perso_nb_redist = perso_nb_redist + compt
		where perso_cod = personnage;
	compt_total := compt_total + compt;
	-- vue
	select into compt
		perso_amelioration_vue
		from perso
		where perso_cod = personnage;
	if compt is null then
		compt := 0;
	end if;
	update perso set perso_amelioration_vue = 0,perso_nb_redist = perso_nb_redist + compt
		where perso_cod = personnage;
	compt_total := compt_total + compt;
	-- reparation
	select into compt
		perso_nb_amel_repar
		from perso
		where perso_cod = personnage;
	if compt is null then
		compt := 0;
	end if;
	update perso set perso_nb_amel_repar = 0,perso_nb_redist = perso_nb_redist + compt
		where perso_cod = personnage;
	update perso set perso_capa_repar = ((perso_dex+perso_int)*3) where perso_cod = personnage;
	compt_total := compt_total + compt;
	-- nombre de sorts
	select into compt
		perso_amelioration_nb_sort
		from perso
		where perso_cod = personnage;
	if compt is null then
		compt := 0;
	end if;
	update perso set perso_amelioration_nb_sort = 0,perso_nb_redist = perso_nb_redist + compt
		where perso_cod = personnage;
	compt_total := compt_total + compt;
	-- receptacle
	select into compt
		perso_nb_receptacle
		from perso
		where perso_cod = personnage;
	delete from recsort
		where recsort_perso_cod = personnage;
	if compt is null then
		compt := 0;
	end if;
	update perso set perso_nb_receptacle = 0,perso_nb_redist = perso_nb_redist + compt
		where perso_cod = personnage;
	update perso set perso_nb_amel_comp = perso_nb_amel_comp - compt
		where perso_cod = personnage;
	compt_total := compt_total + compt;
	-- amé de mémo
	select into compt
		perso_nb_amel_chance_memo
		from perso
		where perso_cod = personnage;
	if compt is null then
		compt := 0;
	end if;
	update perso set perso_nb_amel_chance_memo = 0,perso_nb_redist = perso_nb_redist + compt
		where perso_cod = personnage;
	update perso set perso_nb_amel_comp = perso_nb_amel_comp - compt
		where perso_cod = personnage;
	compt_total := compt_total + compt;
	code_retour := 'Redistribution terminée. Vous avez '||trim(to_char(compt_total,'999999'))||' points à redistribuer.<br>';
	return code_retour;
end;$_$;


ALTER FUNCTION public.start_redispatch(integer) OWNER TO delain;

--
-- Name: supprimer_ameliorations_perso(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.supprimer_ameliorations_perso(integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function supprimer_ameliorations_perso :                      */
/*     Supprime toutes les amélio du perso                       */
/*    et le replace au niveau 1                                  */
/* On passe en paramètre le perso_cod                            */
/*****************************************************************/
/* Liste des modifications :                                     */
/*   le 23/01/2013 : création                                    */
/*****************************************************************/
declare
	personnage alias for $1;
	v_race integer;
begin
	-- réceptacles
	delete from recsort where recsort_perso_cod = personnage;

	update perso set
		perso_niveau = 1,
		perso_pv = (2 * perso_con_init),
		perso_pv_max = (2 * perso_con_init),
		perso_temps_tour = 720,
		perso_for = coalesce(perso_for_init, 0),
		perso_dex = coalesce(perso_dex_init, 0),
		perso_int = coalesce(perso_int_init, 0),
		perso_con = coalesce(perso_con_init, 0),
		perso_amelioration_vue = 0,
		perso_des_regen = 1,
		perso_amelioration_degats = 0,
		perso_amelioration_armure = 0,
		perso_amel_deg_dex = 0,
		perso_nb_amel_repar = 0,
		perso_nb_receptacle = 0,
		perso_amelioration_nb_sort = 0,
		perso_nb_amel_comp = 0
	where perso_cod = personnage;

	-- compétences
	select into v_race perso_race_cod
	from perso
	where perso_cod = personnage;
	if v_race in (1, 3) then
		delete from perso_competences where pcomp_perso_cod = personnage and pcomp_pcomp_cod IN (25,63,66,72,75,61,64,67,73,76,62,65,68,74,77);
	else
		delete from perso_competences where pcomp_perso_cod = personnage and pcomp_pcomp_cod IN (63,66,72,75,64,67,73,76,65,68,74,77);
		update perso_competences set pcomp_pcomp_cod = 25 where pcomp_perso_cod = personnage and pcomp_pcomp_cod IN (61, 62);
	end if;

	return 1;
end;$_$;


ALTER FUNCTION public.supprimer_ameliorations_perso(integer) OWNER TO delain;

--
-- Name: FUNCTION supprimer_ameliorations_perso(integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.supprimer_ameliorations_perso(integer) IS 'Supprime toutes les amélio du perso et le replace au niveau 1.
Il garde ses PX.';


--
-- Name: tannage(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.tannage(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*********************************************************/
/* function tannage                                      */
/* Création d’un parchemin à partie d’une peau de monstre*/
/* en cours                                              */
/* parametres :                                          */
/*  $1 = personnage qui tanne la peau                    */
/*  $2 = peau concernée                                  */
/*  $3 = parchemin                                       */
/* Sortie :                                              */
/*  code_retour = texte exploitable par php              */
/*********************************************************/
/**************************************************************/
/*	06/04/2012 - Reivax - Rajout d’une usure sur le tannage, histoire de
             permettre la réutilisation d’une grande peau pour une autre opération.*/
/**************************************************************/
declare
	personnage alias for $1;	-- perso_cod
	objet alias for $2;				-- gobj_cod du type de peau
	parchemin alias for $3;   -- parchemin qui est tenté (gobj_cod)
	code_retour text;				-- code retour
	v_compo integer;				-- Composant qui va être consommé
	v_compo_etat integer;				-- usure courante du composant
	pos_personnage integer;		--position du personnage
	des integer;
	v_pv integer;
	v_pa integer;					-- PA de l’utilisateur
	v_competence integer; --compétence de l’enlumineur
	v_niv_competence integer;	--pourcentage de la compétence3
	v_niv_competence_modif integer;
	v_gobj_cod integer;			-- code de l’objet générique
	v_usure integer;			-- l'usure infligée à l’objet
	v_obj_cod integer;			-- obj_cod de la potion
	v_nom text;			-- nom du parchemin (formule) produit
	v_temps integer; -- Temps de production
	v_heure integer; -- temps de production en heures
	v_nombre integer; --nombre de parchemin produit
	v_comp integer; -- compétence nécessaire pour produire ce type de parchemin
	v_niveau_parchemin integer;
	v_niveau_peau integer;
	chance integer;
	texte_evt text;
	texte_tannage text;
	px_gagne numeric;
	temp_ameliore_competence text;
	v_special integer;
	param_pa integer;
	v_temp_text text;
	v_temp integer;
	compt integer;
	cout_pa integer;
	v_code_formule integer;
	v_max integer;
	peau_tannee integer;
	i integer;
	temp_renommee numeric;		-- calcul pour renommee

begin
/*********************************************************/
/*        I N I T I A L I S A T I O N S                  */
/*********************************************************/
	code_retour := '0;'; --par défaut, tout va bien
	px_gagne := 0;
/*********************************************************/
/*                  C O N T R O L E S                    */
/*********************************************************/
	-- controle sur la possession d’un composant du type indiqué
	select into v_compo, v_compo_etat, v_niveau_peau
		obj_cod, obj_etat, gobj_niv_peau
	from objets, perso_objets, objet_generique
	where perobj_perso_cod = personnage
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = objet
		and gobj_cod = obj_gobj_cod
	order by obj_etat
	limit 1;
	if not found then
		return '1;1;Erreur ! Vous ne possédez pas de peau de monstre de ce type !';
	end if;
	--Controle des PA
	select into v_pa, param_pa, v_competence, v_niv_competence
		perso_pa, getparm_n(117), pcomp_pcomp_cod, pcomp_modificateur
	from perso, perso_competences
	where perso_cod = personnage
		and pcomp_perso_cod = perso_cod
		and pcomp_pcomp_cod in (91, 92, 93);
	if not found then
		return '1;1;Erreur ! Vous ne possédez pas la compétence nécessaire à cette action !';
	end if;
	if v_pa < param_pa then
		return '1;1;Erreur ! Vous ne possédez pas suffisamment de PA pour cette action !';
	end if;

	--Controler le niveau de l’enlumineur par rapport au parchemin à produire
	select into v_code_formule, v_nom, v_temps, v_nombre, v_comp, v_niveau_parchemin, v_usure
		frm_cod, frm_nom, frm_temps_travail, frmpr_num, frm_comp_cod, gobj_niv_parchemin, frmco_usure
	from formule_produit, formule_composant, formule, objet_generique, perso_competences
	where frmpr_frm_cod = frm_cod
		and frmco_gobj_cod = objet
		and frmco_frm_cod = frm_cod
		and frmpr_gobj_cod = parchemin
		and frm_type = 4
		and gobj_cod = frmpr_gobj_cod
		and pcomp_pcomp_cod in (91, 92, 93)
		and pcomp_pcomp_cod = frm_comp_cod
		and pcomp_perso_cod = personnage;
	if v_comp > v_competence then
		return '1;1;Erreur ! Vous ne possédez pas une compétence suffisamment élevée pour produire ce type de parchemin !';
	end if;

	-- Gestion de l’usure
	v_compo_etat := v_compo_etat - v_usure;
	if v_compo_etat <= 0 then
		v_temp := f_del_objet(v_compo);
		texte_tannage := '<br>Cette opération a requis l’intégralité du support.';
	else
		update objets set obj_etat = v_compo_etat where obj_cod = v_compo;
		texte_tannage := '<br>Vous arrivez à conserver une partie du support lors de l’opération.';
	end if;
	-- Fin gestion usure

	--On regarde maintenant si le perso y arrive
	temp_renommee := ((v_niveau_parchemin/10)*0.1)::numeric;
	des := lancer_des(1, 100);

	-- on regarde s il y a concentration
	v_niv_competence_modif := v_niv_competence;
	select into compt concentration_perso_cod from concentrations
	where concentration_perso_cod = personnage;
	if found then
		v_niv_competence_modif := v_niv_competence_modif + 20;
		delete from concentrations where concentration_perso_cod = personnage;
	end if;


	-- Modif Morgenese : le * 3.5 est bcp trop je remplace par 1.5
        -- sachant que les niveaux de parcho sont 40 - 60 - 80 et 100
        -- et les niveaux de peau 20 - 40 - 60 - 80 - 100 - 120
	chance := floor(1.5*v_niveau_parchemin) - v_niveau_peau;
	v_niv_competence_modif := (v_niv_competence_modif - chance);
	v_max := floor((v_niveau_peau * 2000 / v_niveau_parchemin)/100);
	v_niv_competence_modif := max(v_niv_competence_modif, v_max);
	code_retour := code_retour || '<br>Votre chance de réussite en tenant compte des modificateurs est de <b>' || trim(to_char(v_niv_competence_modif, '9999')) || '</b>.
		<br>Votre lancer de dés est de <b>' || trim(to_char(des, '9999')) || '</b>.<br>';
	v_special := floor(v_niv_competence_modif/4);
	if des > 96 then
		-- echec critique
		texte_evt := '[perso_cod1] a tenté de fabriquer un parchemin vierge et a lamentablement échoué.';

		values(nextval('seq_levt_cod'), 83, now(), 1, personnage, texte_evt, 'O', 'O', personnage, personnage);

		code_retour := code_retour || 'Il s’agit donc d’un échec automatique.<br><br>';
		code_retour := '0;' || code_retour || texte_tannage;
		update perso set perso_renommee_artisanat = perso_renommee_artisanat - (temp_renommee*2), perso_pa = perso_pa - param_pa where perso_cod = personnage;
		return code_retour;
	end if;
	if des > v_niv_competence_modif then
		code_retour := code_retour || 'Vous avez donc <b>échoué</b>.<br><br>';
		-- on regarde si on améliore la comp
		if v_niv_competence <= getparm_n(1) then
			code_retour := code_retour || 'Votre compétence est inférieure à ' || trim(to_char(getparm_n(1), '9999')) || ' %. Vous tentez une amélioration.<br>';
			temp_ameliore_competence := ameliore_competence_px(personnage, v_competence, v_niv_competence);
			code_retour := code_retour || 'Votre lancer de dés est de <b>' || split_part(temp_ameliore_competence, ';', 1) || '</b>, ';
			if split_part(temp_ameliore_competence, ';', 2) = '1' then
				code_retour := code_retour || 'Vous avez amélioré cette compétence. Sa nouvelle valeur est <b>' || split_part(temp_ameliore_competence, ';', 3) || '</b><br><br>.';
			else
				code_retour := code_retour || 'Vous n’avez pas réussi à améliorer cette compétence.<br><br>';
			end if;
		end if;
		texte_evt := '[perso_cod1] a tenté de fabriquer un parchemin vierge et a échoué.';

		values(nextval('seq_levt_cod'), 83, now(), 1, personnage, texte_evt, 'O', 'O', personnage, personnage);

		code_retour := '0;' || code_retour || texte_tannage;
		update perso set perso_renommee_artisanat = perso_renommee_artisanat - temp_renommee, perso_pa = perso_pa - param_pa where perso_cod = personnage;
		return code_retour;
	end if;

	texte_tannage := '<br>Vous réalisez votre opération de tannage, qui va prendre du temps, principalement pour le séchage.' || texte_tannage;

	if des <= 5 then
		code_retour := code_retour || 'il s’agit donc d’une <b>réussite critique</b>.<br><br>';
		px_gagne := px_gagne + 2;
		cout_pa := floor(param_pa/2);
	else
		if des <= v_special then
			code_retour := code_retour || 'il s’agit donc d’une <b>réussite spéciale</b>.<br><br>';
			px_gagne := px_gagne + 1;
		else
			code_retour := code_retour || 'Vous avez donc <b>réussi</b>.<br><br>';
		end if;
	end if;
	-- px
	px_gagne := px_gagne + (((v_niveau_parchemin/10) - 1)/3.0::numeric);
	-- on tente l amélioration
	temp_ameliore_competence := ameliore_competence_px(personnage, v_competence, v_niv_competence);
	code_retour := code_retour || 'Votre jet d’amélioration est de <b>' || split_part(temp_ameliore_competence, ';', 1) || '</b>, ';
	if split_part(temp_ameliore_competence, ';', 2) = '1' then
		code_retour := code_retour || 'Vous avez amélioré cette compétence. Sa nouvelle valeur est <b>' || split_part(temp_ameliore_competence, ';', 3) || '</b>.<br><br>';
	else
		code_retour := code_retour || 'Vous n’avez pas réussi à améliorer cette compétence.<br><br>';
	end if;
	if split_part(temp_ameliore_competence, ';', 2) = '1' then
		px_gagne := px_gagne + 1;
	end if;
	texte_evt := '[perso_cod1] est parvenu à fabriquer un parchemin vierge.';

	values(nextval('seq_levt_cod'), 83, now(), 1, personnage, texte_evt, 'O', 'O', personnage, personnage);

	--On introduit une peau tannée dans l’équipement du perso
	v_temp_text := cree_objet_perso_nombre(846, personnage, v_nombre);
	--On insère dans la table des formules objets inachevés cette nouvelle occurence
	for i in 1..v_nombre loop
		peau_tannee := split_part(v_temp_text, ';', i);
		if peau_tannee is null then
			exit;
		else
		end if;
	end loop;
	v_heure := floor(v_temps/60);
	code_retour := code_retour || 'Votre peau sera prête pour une enluminure dans approximativement ' || trim(to_char(v_heure, '99999999')) || ' heures.<br><br>';
	-- on attribue les PX
	update perso set perso_px = perso_px + px_gagne, perso_renommee_artisanat = perso_renommee_artisanat + temp_renommee, perso_pa = perso_pa - param_pa where perso_cod = personnage;
	code_retour := code_retour || '<br>Pour cette action, vous gagnez ' || to_char(px_gagne, '999999990D99') || ' PX.';
	code_retour := '1;' || code_retour || texte_tannage;
	return code_retour;
end;$_$;


ALTER FUNCTION public.tannage(integer, integer, integer) OWNER TO delain;

--
-- Name: FUNCTION tannage(integer, integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.tannage(integer, integer, integer) IS 'Tanne une peau pour en faire un parchemin vierge utilisable en enluminure';


--
-- Name: teleportation_divine(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.teleportation_divine(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$declare
	code_retour text;
	personnage alias for $1;
	destination alias for $2;
	-- variables de controle
	v_pa integer;				-- pa du perso
	v_dieu_cod integer; 		-- religion du perso
	v_dieu_niveau integer; 	-- niveau de religion
	v_pos_cod integer;		-- position de début
	-- variables de retour
	v_texte_evt text;			-- texte pour les évènements
begin
	/*********************/
	/* DEBUT : controles */
	/*********************/
	--
	/************************/
	/* DEBUT : controles PA */
	/************************/
	select into v_pa perso_pa
		from perso
		where perso_cod = personnage;
	if not found then
		code_retour := 'Anomalie ! Personnage non trouvé !';
		return code_retour;
	end if;
	if v_pa < getparm_n(100) then
		code_retour := 'Anomalie ! Pas assez de PA pour effectuer cette action !';
		return code_retour;
	end if;
	/************************/
	/* FIN   : controles PA */
	/************************/
	--
	/******************************/
	/* DEBUT : controles religion */
	/******************************/
	select into v_dieu_cod,v_dieu_niveau
		dper_dieu_cod,dper_niveau
		from dieu_perso
		where dper_perso_cod = personnage;
	if not found then
		code_retour := 'Anomalie ! Religion du personnage non trouvée !';
		return code_retour;
	end if;
	if v_dieu_niveau < 3 then
		code_retour := 'Anomalie ! Niveau dans la religion non correspondant !';
		return code_retour;
	end if;
	/******************************/
	/* FIN   : controles religion */
	/******************************/
	--
	/*******************************/
	/* DEBUT : controles positions */
	/*******************************/
	select into v_pos_cod
		ppos_pos_cod
		from perso_position,lieu_position,lieu
		where ppos_perso_cod = personnage
		and ppos_pos_cod = lpos_pos_cod
		and lpos_lieu_cod = lieu_cod
		and lieu_dieu_cod = v_dieu_cod;
	if not found then
		code_retour := 'Anomalie ! Le personnage n''est pas sur un temple !';
		return code_retour;
	end if;
	--
	select into v_pos_cod
		lpos_pos_cod
		from lieu,lieu_position
		where lpos_pos_cod = destination
		and lpos_lieu_cod = lieu_cod
		and lieu_dieu_cod = v_dieu_cod;
	if not found then
		code_retour := 'Anomalie ! La destination n''est pas un temple !';
		return code_retour;
	end if;
	select into v_pos_cod
		lpos_pos_cod
		from lieu,lieu_position
		where lpos_pos_cod = destination
		and lpos_lieu_cod = lieu_cod
		and lieu_dieu_cod = v_dieu_cod;
	if not found then
		code_retour := 'Anomalie ! La destination n''est pas un temple !';
		return code_retour;
	end if;
	perform *
 		from choix_temple_vus(personnage)
		where choix_temple_vus = destination;
	if not found then
		code_retour := 'Anomalie ! Vous désirez vous rendre dans un temple jamais visité !';
		return code_retour;
	end if;
	perform *
 		from perso_objets , objets
		where perobj_perso_cod = personnage and perobj_obj_cod = obj_cod and obj_gobj_cod between 86 and 88;
	if found then
		code_retour := 'Anomalie ! Vous ne pouvez vous téléporter en portant un médaillon !';
		return code_retour;
	end if;


	/*******************************/
	/* FIN   : controles positions */
	/*******************************/
	--
	/*********************/
	/* FIN   : controles */
	/*********************/
	--
	/*********************/
	/* DEBUT : actions   */
	/*********************/
	--
	update perso
		set perso_pa = perso_pa - getparm_n(100)
		where perso_cod = personnage;
	--
	update perso_position
		set ppos_pos_cod = destination
		where ppos_perso_cod = personnage;
	--
	v_texte_evt := '[perso_cod1] s''est téléporté.';
	--
	code_retour := 'Vous vous êtes téléporté avec succès.';
	return code_retour;
	--
	/*********************/
	/* FIN   : actions   */
	/*********************/
end;$_$;


