CREATE FUNCTION public.temp_init_esc() RETURNS integer
    LANGUAGE plpgsql
    AS $$declare
	l_lieu record;
	pos_lieu integer;
	v_x integer;
	v_y integer;
	v_etage integer;

begin
	for l_lieu in select * from lieu
		where lieu_url = 'escalier_m.php' loop
