--
-- Name: trajectoire(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.trajectoire(integer, integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************/
/* fonction trajectoire : calcule une trajectoire */
/*  pour une arme à distance                      */
/* on passe en paramètres :                       */
/*  $1 = pos_cod 1                                */
/*  $2 = pos_cod 2                                */
/*  $3 = perso_cod cible                          */
/*  $4 = perso_cod du lanceur                     */
/* on a en retour une chaine séparée par ;        */
/*  pos0 = 0 tout est OK, la cible est atteinte   */
/*  pos0 = 1 on atteint un mur (pos_cod en 1)     */
/*  pos0 = 2 on atteint un autre perso            */
/*      (perso_cod en 1)                          */
/**************************************************/
/* créé le 15/09/2003                             */
/* 15/12/2007 : modification totale de la fonction*/
/* Pas du tout en phase avec les ligne de vue     */
/**************************************************/
declare
	code_retour text;
	pos1 alias for $1;
	pos2 alias for $2;
	v_cible alias for $3;
	personnage alias for $4;
	toucher_intermediaire integer;
	v_modif_change_cible integer;
	ligne record;

begin
	-- On détermine si le projectile change de cible, à cause d’une mauvaise dext
	v_modif_change_cible := modif_change_cible(personnage);

	code_retour := '0;0;';

	for ligne in select nv_cible from trajectoire_perso_hors_lieu(pos1, pos2) as (nv_cible int, v_pos int, type_perso int)
	loop
		toucher_intermediaire := lancer_des(1, 100);
		if toucher_intermediaire < (getparm_n(24) - v_modif_change_cible)  then
			-- On teste si le projectile ne les touche pas, en fonction d’un % de chance, soit 40% - (dex-11 * 2)
			--  le test est fait pour chaque perso sur la route du projectile !
			-- Si un projectile atteint un des persos on arrête
			code_retour := '2;' || trim(to_char(ligne.nv_cible, '999999999')) || ';';
			return code_retour;
		else
			code_retour := '0;0;';
		end if;
	end loop;
	return code_retour;
end;$_$;


ALTER FUNCTION public.trajectoire(integer, integer, integer, integer) OWNER TO delain;

--
-- Name: FUNCTION trajectoire(integer, integer, integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.trajectoire(integer, integer, integer, integer) IS 'Correction pour que la trajectoire lors d’un tir soit conforme à l’algorithme de vue
Permet de déterminer si une flèche touche un perso en cours de route.';


--
-- Name: trajectoire_magie(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.trajectoire_magie(integer, integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************/
/* fonction trajectoire : calcule une trajectoire */
/*  pour une arme à distance                      */
/* on passe en paramètres :                       */
/*  $1 = pos_cod 1                                */
/*  $2 = pos_cod 2                                */
/*  $3 = perso_cod cible                          */
/*  $4 = perso_cod du lanceur                     */
/* on a en retour une chaine séparée par ;        */
/*  pos0 = 0 tout est OK, la cible est atteinte   */
/*  pos0 = 1 on atteint un mur (pos_cod en 1)     */
/*  pos0 = 2 on atteint un autre perso            */
/*      (perso_cod en 1)                          */
/**************************************************/
/* créé le 15/09/2003                             */
/**************************************************/
declare
	code_retour text;
	pos1 alias for $1;
	pos2 alias for $2;
	v_cible alias for $3;
	personnage alias for $4;
	temp_pos integer;
	diff_x integer;
	diff_y integer;
	temp_diff_x integer;
	temp_diff_y integer;
	ordre integer;
	etage1 integer;
	etage2 integer;
	distance_init integer;
	v_distance integer;
	temp_distance integer;
	r_pos record;
	compteur integer;
	nb_mur integer;
	nb_perso integer;
	toucher_intermediaire integer;
	temp_perso integer;
	nv_cible integer;
	compteur2 integer;
	v_modif_change_cible integer;
	v_x integer;
	v_y integer;
	v_etage integer;
	tangible text;

begin
	v_modif_change_cible := modif_change_cible(personnage);
	code_retour := '0;0;';
	distance_init := distance(pos1,pos2);
	v_distance := distance_init;
	temp_pos := pos1;
	diff_x := delta_x(pos1,pos2);
	diff_y := delta_y(pos1,pos2);
	select into etage1 pos_etage from positions
		where pos_cod = pos1;
	select into etage2 pos_etage from positions
		where pos_cod = pos2;
	if (etage1 != etage2) then
		code_retour := '9;0;';
		return code_retour;
	end if;
	compteur := 0;
	while (v_distance != 0) loop
		select into v_x,v_y,v_etage pos_x,pos_y,pos_etage
			from positions
			where pos_cod = temp_pos;
		compteur := compteur + 1;
		exit when compteur >= 30;
		for r_pos in select * from positions
			where pos_x >= (v_x - 1) and pos_x <= (v_x + 1)
			and pos_y >= (v_y - 1) and pos_y <= (v_y + 1)
			and pos_etage = etage1 loop
			temp_distance := distance(r_pos.pos_cod, pos2);
			if (temp_distance < v_distance) then -- on s approche
				temp_diff_x := delta_x(r_pos.pos_cod,pos2);
				temp_diff_y := delta_y(r_pos.pos_cod,pos2);
				if ((temp_diff_x <= diff_x) and (temp_diff_y <= diff_y)) then -- ok pour la position suivante
					-- maintenant, on fait les tests qui vont bien
					-- 1 => les murs
					select into tangible,nb_mur mur_tangible,mur_pos_cod from murs
						where mur_pos_cod = r_pos.pos_cod;
					if found then
						if tangible = 'O' then
							code_retour := '1;'||trim(to_char(nb_mur,'99999'))||';';
							return code_retour;
						end if;
					end if;
					temp_pos := r_pos.pos_cod;
					v_distance := temp_distance;
					diff_x := temp_diff_x;
					diff_y := temp_diff_y;
				end if;
			end if;
		end loop;
	end loop;
	if compteur >= 30 then
		code_retour := 'erreur';
	end if;
	return code_retour;
end;
$_$;


ALTER FUNCTION public.trajectoire_magie(integer, integer, integer, integer) OWNER TO delain;

--
-- Name: FUNCTION trajectoire_magie(integer, integer, integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.trajectoire_magie(integer, integer, integer, integer) IS 'Fonction pourrie car ne correspondant pas à l''algorithme de vue.
Mais comme le controle du perso cible se fait avant, ce n''est pas "trop" grave (juste que c''est incohérent et inutile)';


--
-- Name: trajectoire_old(integer, integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.trajectoire_old(integer, integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**************************************************/
/* fonction trajectoire : calcule une trajectoire */
/*  pour une arme à distance                      */
/* on passe en paramètres :                       */
/*  $1 = pos_cod 1                                */
/*  $2 = pos_cod 2                                */
/*  $3 = perso_cod cible                          */
/*  $4 = perso_cod du lanceur                     */
/* on a en retour une chaine séparée par ;        */
/*  pos0 = 0 tout est OK, la cible est atteinte   */
/*  pos0 = 1 on atteint un mur (pos_cod en 1)     */
/*  pos0 = 2 on atteint un autre perso            */
/*      (perso_cod en 1)                          */
/**************************************************/
/* créé le 15/09/2003                             */
/**************************************************/
declare
	code_retour text;
	pos1 alias for $1;
	pos2 alias for $2;
	v_cible alias for $3;
	personnage alias for $4;
	temp_pos integer;
	diff_x integer;
	diff_y integer;
	temp_diff_x integer;
	temp_diff_y integer;
	ordre integer;
	etage1 integer;
	etage2 integer;
	distance_init integer;
	v_distance integer;
	temp_distance integer;
	r_pos record;
	compteur integer;
	nb_mur integer;
	nb_perso integer;
	toucher_intermediaire integer;
	temp_perso integer;
	nv_cible integer;
	compteur2 integer;
	v_modif_change_cible integer;
	v_x integer;
	v_y integer;
	v_etage integer;
	tangible text;

begin
	v_modif_change_cible := modif_change_cible(personnage);
	code_retour := '0;0;';
	distance_init := distance(pos1,pos2);
	v_distance := distance_init;
	temp_pos := pos1;
	diff_x := delta_x(pos1,pos2);
	diff_y := delta_y(pos1,pos2);
	select into etage1 pos_etage from positions
		where pos_cod = pos1;
	select into etage2 pos_etage from positions
		where pos_cod = pos2;
	if (etage1 != etage2) then
		code_retour := '9;0;';
		return code_retour;
	end if;
	compteur := 0;
	while (v_distance != 0) loop
		select into v_x,v_y,v_etage pos_x,pos_y,pos_etage
			from positions
			where pos_cod = temp_pos;
		compteur := compteur + 1;
		exit when compteur >= 30;
		for r_pos in select * from positions
			where pos_x >= (v_x - 1) and pos_x <= (v_x + 1)
			and pos_y >= (v_y - 1) and pos_y <= (v_y + 1)
			and pos_etage = etage1 loop
			temp_distance := distance(r_pos.pos_cod, pos2);
			if (temp_distance < v_distance) then -- on s approche
				temp_diff_x := delta_x(r_pos.pos_cod,pos2);
				temp_diff_y := delta_y(r_pos.pos_cod,pos2);
				if ((temp_diff_x <= diff_x) and (temp_diff_y <= diff_y)) then -- ok pour la position suivante
					-- maintenant, on fait les tests qui vont bien
					-- 1 => les murs
					select into tangible,nb_mur mur_tangible,mur_pos_cod from murs
						where mur_pos_cod = r_pos.pos_cod;
					if found then
						if tangible = 'O' then
							code_retour := '1;'||trim(to_char(nb_mur,'9999999999'))||';';
							return code_retour;
						end if;
					end if;
					-- 2 => les autres persos
					select into nb_perso perso_cod
						from perso_position,perso,lieu,lieu_position
						where ppos_pos_cod = r_pos.pos_cod
						and ppos_perso_cod = perso_cod
						and perso_actif = 'O'
						and perso_cod != v_cible
						and lpos_pos_cod = r_pos.pos_cod
						and lpos_lieu_cod = lieu_cod
						and lieu_refuge = 'O';
					if found then
						toucher_intermediaire := lancer_des(1,100);
						if toucher_intermediaire < (getparm_n(24) - v_modif_change_cible)  then
							-- on touche en perso en route
							temp_perso := lancer_des(1,nb_perso);
							nv_cible := null;
							compteur2 := 0;
							temp_perso := temp_perso - 1;
							while nv_cible is null loop
								compteur2 := compteur2 + 1;
								exit when compteur2 >=30;
								select into nv_cible perso_cod from perso,perso_position,lieu,lieu_position
									where ppos_pos_cod = r_pos.pos_cod
									and ppos_perso_cod = perso_cod
									and perso_actif = 'O'
									and perso_cod != v_cible
									and lpos_pos_cod = r_pos.pos_cod
									and lpos_lieu_cod = lieu_cod
									and lieu_refuge = 'O'
									limit 1
									offset temp_perso;
							end loop;
							if compteur2 >= 30 then
								code_retour := '0;0;';
							else
								code_retour := '2;'||trim(to_char(nv_cible,'999999999'))||';';
							end if;
							return code_retour;
						end if;
					end if;
					temp_pos := r_pos.pos_cod;
					v_distance := temp_distance;
					diff_x := temp_diff_x;
					diff_y := temp_diff_y;
				end if;
			end if;
		end loop;
	end loop;
	if compteur >= 30 then
		code_retour := 'erreur';
	end if;
	return code_retour;
end;
$_$;


ALTER FUNCTION public.trajectoire_old(integer, integer, integer, integer) OWNER TO delain;

--
-- Name: trajectoire_perso(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.trajectoire_perso(integer, integer) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $_$/***************************************************/
/* fonction trajectoire_perso : calcule une        */
/* trajectoire et récupère les num de persos dessus*/
/*  pour une arme à distance                       */
/* on passe en paramètres :                        */
/*  $1 = pos_cod 1                                 */
/*  $2 = pos_cod 2                                 */
/* on a en retour :                                */
/* liste des perso_co                              */
/* pour appeler la fonction :                      */
/*select * from trajectoire_perso as (personnage int,*/
/*   v_pos int, type_perso int)                    */
/* On peut évidemment sélectionner les champs de   */
/* sortie                                          */
/***************************************************/
/* donné le 11/05/2005                             */
/* © mnibjb@free.fr - utilisation libre pour Delain*/
/***************************************************/

declare
	code_retour integer;
	pos1 alias for $1;
	pos2 alias for $2;
	d_x integer;
	d_y integer;
	signe_x integer;
	signe_y integer;
	x1 integer;
	x2 integer;
	y1 integer;
	y2 integer;
	etage1 integer;
	etage2 integer;
xx integer;
yy integer;
A integer;
v_Ax integer;
v_Ay integer;
v_Axy integer;
proc_pos integer;
	v_req text;
	curs2 refcursor;
	v_pos integer;
	personnage integer;
	type_perso integer;
	x_calcul integer;
	y_calcul integer;


ligne record;

begin
	xx := 0;
	yy := 0;
	if pos1 = pos2 then
		return;
	end if;
	select into etage1,x1,y1 pos_etage,pos_x,pos_y from positions
		where pos_cod = pos1;
if not found then
return;
end if;
	select into etage2,x2,y2 pos_etage,pos_x,pos_y from positions
		where pos_cod = pos2;
if not found then
return;
end if;
	if etage1 != etage2 then
		return;
	end if;
	d_x := x2 - x1;
	d_y := y2 - y1;
	if d_x > 0 then
		signe_x := 1;
	else
		signe_x := -1;
	end if;
	if d_y > 0 then
		signe_y := 1;
	else
		signe_y := -1;
	end if;
	d_x := abs(d_x);
	d_y := abs(d_y);

	A = d_x - d_y ;
	v_Ax := -2*d_y ;
	v_Ay := 2*d_x ;
	v_Axy := 2*A ;


loop
   if A>0 then
      xx := xx + 1 ;
      A=A+v_Ax ;
   elsif A<0 then
      yy := yy + 1;
      A=A+v_Ay ;
   else
      xx := xx + 1 ;
     	yy := yy + 1;
      A=A+v_Axy ;
   end if;

   /* while(xx!=d_x OR yy!=d_y) */
  if (xx=d_x AND yy=d_y) then
   	return;
	end if;
	x_calcul := x1+(xx*signe_x);
	y_calcul := y1+(yy*signe_y);
	select into proc_pos
	      mur_pos_cod
	      from positions,murs
	      where pos_x = x_calcul
	      and pos_y =   y_calcul
	      and pos_etage = etage1
	      and mur_pos_cod = pos_cod
	      and mur_tangible = 'O';
   if found then
      return;
   else
		   v_req = 'select ppos_perso_cod as personnage,ppos_pos_cod as v_pos,perso_type_perso as type_perso
					      from positions,perso_position,perso
					      where pos_x = '||trim(to_char(x_calcul,'99999999999'))||'
					      and pos_y =   '||trim(to_char(y_calcul,'99999999999'))||'
					      and pos_etage = '||trim(to_char(etage1,'99999999999'))||'
					      and ppos_pos_cod = pos_cod
					      and perso_actif = ''O''
					      and perso_tangible = ''O''
					      and perso_cod = ppos_perso_cod';
		    open curs2 for execute v_req;
				loop
					fetch curs2 into ligne;
					exit when NOT FOUND;
					return next ligne;
				end loop;
				close curs2;
		end if;
end loop;
return;
end;$_$;


ALTER FUNCTION public.trajectoire_perso(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION trajectoire_perso(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.trajectoire_perso(integer, integer) IS 'Permet de récupérer les numéros de persos sur une trajectoire entre deux positions, comme pour la vue, à savoir que si derrière un mur, les numéros de perso ne sont pas récupérés. Attention, cela ne récupère que persos sur la trajectoire, pas les persos sur les cases';


--
-- Name: trajectoire_perso2(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.trajectoire_perso2(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/***************************************************/
/* fonction trajectoire_perso : calcule une        */
/* trajectoire et récupère les num de persos dessus*/
/*  pour une arme à distance                       */
/* on passe en paramètres :                        */
/*  $1 = pos_cod 1                                 */
/*  $2 = pos_cod 2                                 */
/* on a en retour :                                */
/* liste des perso_co                              */
/* pour appeler la fonction :                      */
/*select * from trajectoire_perso as (personnage int,*/
/*   v_pos int, type_perso int)                    */
/* On peut évidemment sélectionner les champs de   */
/* sortie                                          */
/***************************************************/
/* donné le 11/05/2005                             */
/* © mnibjb@free.fr - utilisation libre pour Delain*/
/***************************************************/

declare
	code_retour integer;
	pos1 alias for $1;
	pos2 alias for $2;
	d_x integer;
	d_y integer;
	signe_x integer;
	signe_y integer;
	x1 integer;
	x2 integer;
	y1 integer;
	y2 integer;
	etage1 integer;
	etage2 integer;
xx integer;
yy integer;
A integer;
v_Ax integer;
v_Ay integer;
v_Axy integer;
proc_pos integer;
	v_req text;
	curs2 refcursor;
	v_pos integer;
	personnage integer;
	type_perso integer;
	x_calcul integer;
	y_calcul integer;
	compt_perso integer;
	v_compt_perso integer;
	v_refuge integer;


ligne record;

begin
	compt_perso := 0;
	xx := 0;
	yy := 0;
	if pos1 = pos2 then
		return 0;
	end if;
	select into etage1,x1,y1 pos_etage,pos_x,pos_y from positions
		where pos_cod = pos1;
if not found then
return 0;
end if;
	select into etage2,x2,y2 pos_etage,pos_x,pos_y from positions
		where pos_cod = pos2;
if not found then
return 0;
end if;
	if etage1 != etage2 then
		return 0;
	end if;
	d_x := x2 - x1;
	d_y := y2 - y1;
	if d_x > 0 then
		signe_x := 1;
	else
		signe_x := -1;
	end if;
	if d_y > 0 then
		signe_y := 1;
	else
		signe_y := -1;
	end if;
	d_x := abs(d_x);
	d_y := abs(d_y);

	A = d_x - d_y ;
	v_Ax := -2*d_y ;
	v_Ay := 2*d_x ;
	v_Axy := 2*A ;


loop
   if A>0 then
      xx := xx + 1 ;
      A=A+v_Ax ;
   elsif A<0 then
      yy := yy + 1;
      A=A+v_Ay ;
   else
      xx := xx + 1 ;
     	yy := yy + 1;
      A=A+v_Axy ;
   end if;

   /* while(xx!=d_x OR yy!=d_y) */
  if (xx=d_x AND yy=d_y) then
   	return compt_perso;
	end if;
	x_calcul := x1+(xx*signe_x);
	y_calcul := y1+(yy*signe_y);
	select into proc_pos
	      mur_pos_cod
	      from positions,murs
	      where pos_x = x_calcul
	      and pos_y =   y_calcul
	      and pos_etage = etage1
	      and mur_pos_cod = pos_cod
	      and mur_tangible = 'O';
   if found then
      return 0;
   else
		 select count(*) into v_compt_perso
		 	from positions,perso_position,perso
			where pos_x = x_calcul
			and pos_y =   y_calcul
			and pos_etage = etage1
			and ppos_pos_cod = pos_cod
			and perso_actif = 'O'
			and perso_tangible = 'O'
			and perso_cod = ppos_perso_cod;
		--
		-- on regarde si ce n'est pas un refuge
		--
		select lieu_cod into v_refuge
			from lieu,lieu_position,positions
			where pos_x = x_calcul
			and pos_y =   y_calcul
			and pos_etage = etage1
			and lpos_pos_cod = pos_cod
			and lpos_lieu_cod = lieu_cod
			and lieu_refuge = 'O';
		if found then
			v_compt_perso := 0;
		end if;
		 compt_perso := compt_perso + v_compt_perso;


		end if;
end loop;
return compt_perso;
end;$_$;


