--
-- Name: valide_quete_avatar(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.valide_quete_avatar(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*************************************************************/
/* fonction valide_quete_avatar                              */
/*   Exécute les fonctions spécifiques liées à la mort       */
/*    d’un avatar                                            */
/*   on passe en paramètres :                                */
/*   $1 = perso_cod : le perso_cod de l’avatar tué           */
/*   $2 = cible_cod : le code du perso qui a tué l’avatar    */
/* on a en sortie un message à afficher                      */
/*************************************************************/
/* Créé le 20/05/2014                                        */
/*************************************************************/
declare
	v_perso_cod alias for $1;  -- Le code de l’avatar tué
	v_tueur_cod alias for $2;  -- Le code du perso qui a tué l’avatar

	code_retour text;          -- Le retour de la fonction
	v_queteur_cod integer;     -- Le code de celui qui aurait dû tuer l’avatar
	v_quete_cod integer;       -- Le code de la quête correspondante
	v_mes integer;             -- L’id du message envoyé
	v_corps text;              -- Le corps du message envoyé

begin
	code_retour := '';
	select into v_quete_cod pquete_cod from quete_perso where pquete_perso_cod = v_tueur_cod and pquete_quete_cod = 16 and pquete_param = v_perso_cod;
	if found then
		update quete_perso set pquete_nombre = 2 where pquete_cod = v_quete_cod;
		code_retour := code_retour || '<br><br><b>Une sensation de plénitude vous envahit, vous avez vaincu vos propres peurs et angoisses. Retournez donc dans un centre de maîtrise magique ou magasin runique afin de faire valider cette nouvelle étape.</b><br><br>';
	end if;
	select into v_quete_cod, v_queteur_cod pquete_cod, pquete_perso_cod from quete_perso where pquete_perso_cod != v_tueur_cod and pquete_quete_cod = 16 and pquete_param = v_perso_cod;
	if found then
		code_retour := code_retour || '<br><br><b>Malheur à vous, vous avez tué un avatar qui était destiné à un autre...</b><br><br>';
		v_corps := 'Un autre que vous a achevé l’avatar qui vous était destiné. Vous devez donc recommencer cette quête depuis le départ';
		v_mes := nextval('seq_msg_cod');
			values (v_mes, v_perso_cod, 'N');
			values (v_mes, v_queteur_cod, 'N', 'N');
		delete from quete_perso where pquete_cod = v_quete_cod;
	end if;

	return code_retour;
end;$_$;


ALTER FUNCTION public.valide_quete_avatar(integer, integer) OWNER TO delain;

--
-- Name: FUNCTION valide_quete_avatar(integer, integer); Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON FUNCTION public.valide_quete_avatar(integer, integer) IS 'Exécute les fonctions spécifiques liées à la mort d’un avatar ';


--
-- Name: variation_aleatoire(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.variation_aleatoire(integer, integer) RETURNS integer
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function variation_aleatoire : Fait varier aléatoirement une valeur*/
/* On passe en paramètres  :                                     */
/*    1 valeur d'origine                                         */
/*    2 le pourcentage d'aléatoire                               */
/* En sortie, on a la valeur modifiée                            */
/*****************************************************************/
declare
	resultat integer;
	valeur_depart alias for $1;
	pourcentage_aleatoire alias for $2;
	variation integer;
begin
	variation := 100+lancer_des(1,2*pourcentage_aleatoire)-pourcentage_aleatoire;
	if valeur_depart <1 then
		-- CAS particulier ou valeurdepart = 0 ,+0 +1 +2 en fonction
		resultat := trunc(10 * variation/100)-10;
		resultat := max(resultat,0);
		resultat := min(resultat,2);
	else
		resultat := trunc(valeur_depart * variation/100);
	end if;
	return resultat;
end;$_$;


ALTER FUNCTION public.variation_aleatoire(integer, integer) OWNER TO delain;

--
-- Name: vend_objet(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vend_objet(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/************************************************/
/* fonction vend_objet                          */
/* cette fonction a pour but de vendre un objet */
/* venu des postes de garde                     */
/* on passe en paramètres :                     */
/*  $1 = le perso_cod qui achète                */
/*  $2 = l'objet acheté                         */
/*     1 = tonneau de bière                     */
/*     2 = opium                                */
/* on a en retour une zone texte exploitable    */
/*  dans action.php                             */
/************************************************/
/* Modifications :                              */
/* 21/04/2006 : Modification des prix pour les  */
/*              égouts                          */
/************************************************/



declare
	code_retour text;
	personnage alias for $1;
	v_objet alias for $2;
	v_type_lieu integer;
	v_objet_generique integer;
	v_prix integer;
	v_po integer;
	temp_txt text;
	v_etage integer;
	nb_objet integer;
	gain_po integer;
	temp_int integer;
	ligne record;
	v_comp integer;
	temp_ameliore_competence text;
	gain_px integer;

begin
	code_retour := '';
-- vérification de la position du perso
	select into v_type_lieu lieu_tlieu_cod
		from perso_position,lieu_position,lieu
		where ppos_perso_cod = personnage
		and lpos_pos_cod = ppos_pos_cod
		and lpos_lieu_cod = lieu_cod
		and lieu_tlieu_cod in (4);
	if not found then
		code_retour := 'Anomalie ! Vous ne pouvez pas vendre ces objets ici !';
		return code_retour;
	end if;
	if v_objet < 1 then
		code_retour := 'Anomalie ! paramètre objet incorrect !';
		return code_retour;
	end if;
	if v_objet > 2 then
		code_retour := 'Anomalie ! paramètre objet incorrect !';
		return code_retour;
	end if;
	select into v_etage
		etage_reference
		from perso_position,positions, etage
		where ppos_perso_cod = personnage
		and ppos_pos_cod = pos_cod
		and pos_etage = etage_numero;
	if not found then
		code_retour := 'Anomalie ! position perso non trouvée !';
		return code_retour;
	end if;


	if v_objet = 1 then
		v_prix := 1000 - (v_etage * 500);
		v_objet_generique := 196;
	end if;
	if v_objet = 2 then
		v_prix := 2500 - (v_etage * 500);
		v_objet_generique := 186;
	end if;
	if v_etage = 7 then
		if v_objet = 1 then
			v_prix := 2200;
		end if;
		if v_objet = 2 then
			v_prix := 2200;
		end if;
	end if;
if v_etage = 0 then
		if v_objet = 1 then
			v_prix := 200;
		end if;
		if v_objet = 2 then
			v_prix := 425;
		end if;
	end if;
	select into nb_objet count(perobj_cod) from perso_objets,objets
		where perobj_perso_cod = personnage
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = v_objet_generique;
	if nb_objet = 0 then
		code_retour := 'Anomalie ! Vous n''avez pas d''objets de ce type à vendre !';
		return code_retour;
	end if;
--
-- on s'attaque à la vente proprement dite
--
-- les brouzoufs
	gain_po := nb_objet * v_prix;
	update perso set perso_po = perso_po + gain_po
		where perso_cod = personnage;
-- les PX
	gain_px := round(nb_objet/2);
	if gain_px < 1 then
		gain_px := 1;
	end if;
	update perso set perso_px = perso_px + gain_px where perso_cod = personnage;
-- les objets
	for ligne in
		select obj_cod from perso_objets,objets
		where perobj_perso_cod = personnage
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = v_objet_generique loop
		temp_int := f_del_objet(ligne.obj_cod);
	end loop;
-- éventuellement les compétences
	if v_objet = 2 then
		-- s'il est louche, on le blanchit
		delete from perso_louche where plouche_perso_cod = personnage;
		-- compétence contrebande
		select into v_comp
			pcomp_modificateur
			from perso_competences
			where pcomp_perso_cod = personnage
			and pcomp_pcomp_cod = 78;
		if not found then
			-- il faut créer la compétence
				select
				perso_cod,78,(25+((10-perso_int)*2))
				from perso
				where perso_cod = personnage;
			code_retour := 'C''est votre premier dépot de matières prohibées. Vous apprenez à cette occasion la compétence <b>Contrebande</b> !<br>';
		else
			-- on va l'améliorer
			temp_ameliore_competence := ameliore_competence_px(personnage,78,v_comp);
			code_retour := 'Vous tentez d''améliorer cotre compétence <b>Contrebande</b>.<br>';
			code_retour := code_retour||'Votre jet d''amélioration est de '||split_part(temp_ameliore_competence,';',1)||', ';
			if split_part(temp_ameliore_competence,';',2) = '1' then
				code_retour := code_retour||'vous avez donc <b>amélioré</b> cette compétence. <br>';
				code_retour := code_retour||'Sa nouvelle valeur est '||split_part(temp_ameliore_competence,';',3)||'<br><br>';
				gain_px := gain_px + 1;
			else
				code_retour := code_retour||'vous n''avez pas amélioré cette compétence.<br><br> ';
			end if;
		end if;
	end if;
	code_retour := code_retour||'Vous venez de vendre l''objet. Vous gagnez '||trim(to_char(gain_px,'99999999999'))||' PX et '||trim(to_char(gain_po,'99999999999'))||' brouzoufs pour cette action.';
	if v_objet = 1 then
		update parametres set parm_valeur = parm_valeur + 1 where parm_cod in (78,79);
	end if;
	if v_objet = 2 then
		update parametres set parm_valeur = parm_valeur + 1 where parm_cod in (83,84);
	end if;
	return code_retour;
end;

	$_$;


