--
-- Name: vente_perso(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vente_perso(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/***********************************************************/
/* fonction vente_perso : vend des objets de quête aux     */
/*   PNJ                                                   */
/* on passe en paramètres :                                */
/*   $1 = perso_cod vendeur                                */
/*   $2 = le gobj_cod de l'objet vendu                     */
/* on a en retour une chaine html exploitable directement  */
/*   dans la page d'action                                 */
/***********************************************************/
/* créée le 04/03/2004                                     */
/***********************************************************/
declare
-------------------------------------------------------------
-- variables de retour
-------------------------------------------------------------
	code_retour text;					-- texte de retour formaté
-------------------------------------------------------------
-- variables concernant le vendeur
-------------------------------------------------------------
	personnage alias for $1;
	pa integer;							-- nombre de PA du vendeur
	pos_perso integer;				-- position du vendeur
	nb_quete_perso integer;			-- nombre de fois où le vendeur a fait cette quête
-------------------------------------------------------------
-- variables concernant l'objet vendu
-------------------------------------------------------------
	num_gobj alias for $2;			-- gobj_cod de l'objet à vendre
	nom_obj text;						-- nom de l'objet vendu
-------------------------------------------------------------
-- variables de contrôle
-------------------------------------------------------------
	temp integer;						-- fourre tout
	l_objet record;					-- record pour effacement de l'inventaire
	px_gagne integer;					-- px de base gagnés par le vendeur
	or_gagne integer;					-- brouzoufs gagnés par le vendeur
	num_quete integer;				-- numéro de la quête associée
begin
-------------------------------------------------------------
-- Etape 1 : contrôles
-------------------------------------------------------------
-- 1.1 : nombre de PA
	select into pa
		perso_pa
		from perso
		where perso_cod = personnage;
	if not found then
		code_retour := '<p>Erreur ! Vendeur non trouvé !';
		return code_retour;
	end if;
	if pa < getparm_n(36) then
		code_retour := 'Erreur ! Vous n''avez pas assez de PA pour effectuer cette action !';
		return code_retour;
	end if;
-- 1.5 existance du type d'objets
	select into nom_obj gobj_nom
		from objet_generique
		where gobj_cod = num_gobj;
	if not found then
		code_retour := '<p>Erreur ! Type d''objet non trouvé !';
		return code_retour;
	end if;
-- 1.4 quantité des objets à vendre
	select into temp
		count(perobj_cod) from perso_objets,objets
		where perobj_perso_cod = personnage
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = num_gobj;
	if temp < 10 then
		code_retour := '<p>Erreur ! Vous n''avez pas assez de '||nom_obj||' dans vote inventaire.<br>';
		code_retour := code_retour||'Le minimum pour une vente est de 10 unités.';
		return code_retour;
	end if;
-------------------------------------------------------------
-- Etape 2 : contrôles OK, on passe à la vente
-------------------------------------------------------------
-- 2.1 : on enlève les PA du vendeur
	update perso
		set perso_pa = perso_pa - getparm_n(36)
		where perso_cod = personnage;
-- 2.2 : on enlève ses objets de l'inventaire
	for l_objet in
		select perobj_obj_cod,perobj_cod
		from perso_objets,objets
		where perobj_perso_cod = personnage
		and perobj_obj_cod = obj_cod
		and obj_gobj_cod = num_gobj
		limit 10 loop
		delete from perso_objets
			where perobj_cod  = l_objet.perobj_cod;
		delete from perso_identifie_objet
			where pio_obj_cod = l_objet.perobj_obj_cod;
		delete from objets
			where obj_cod = l_objet.perobj_obj_cod;
	end loop;
-- 2.3 : on rajoute les brouzoufs
	if num_gobj = 91 then
		px_gagne := 10;
		or_gagne := 80;
		num_quete := 2;
	code_retour := '<i>"Le rat, c''est la vermine par excellence. J''vous l''dis moi, c''est maladie et compagnie ces bêtes là. Y''a des sacrés pièces en plus par ici, j''préfères n''en voir que l''arrière, croyez moi ! Enfin, ce que j''en dis moi ! C''est du bon boulot en tout qu''rat ! Uh uh, une bonne vieille feinte de ratier ça !".</i> L''individu s''éloigne alors en vous saluant, réprimant avec peine un fou-rire inexplicable. ';

	end if;
	if num_gobj = 92 then
		px_gagne := 12;
		or_gagne := 100;
		num_quete := 3;

code_retour := '<i>En plus, j''ai une sainte horreur des serpents, ça rampe et c''est gluant. J''suis bien content que vous en ayez fait passer plus d''un de vie à trépas ! Sinon, vous faites quoi des peaux ? Parce que j''ai un cousin qui a sa petite affaire de maroquinerie."</i> ricane le ratier en vous quittant non sans vous saluer cordialement.';

	end if;
	if num_gobj = 94 then
		px_gagne := 20;
		or_gagne := 350;
		num_quete := 4;
code_retour := '<i>"J''ai entendu dire que les Orlanthis faisaient des vêtements avec la soie d''araignée !? Z''avez déjà entendu quelque chose d''aussi absurde vous ? Toujours à vouloir se mettre en avant ceux-là. Notez bien, j''pourrais m''faire un sacré pactole en leur revendant tout ça. Mais non, rêvons pas, va bien falloir que j''aille bruler tout ça, faut que ça blinque : des souterrains propres pour des aventuriers épanouis comme on dit chez les ratiers"</i> lance l''homme en reprenant la route après vous avoir remercié avec gratitude. ';
	end if;
	update perso set perso_po = perso_po + or_gagne
		where perso_cod = personnage;
-- 2.4 XP gagné : pour cela on regarde si la quête a déjà été effectuée
	select into nb_quete_perso
		pquete_nombre
		from quete_perso
		where pquete_quete_cod = num_quete
		and pquete_perso_cod = personnage;
	if not found then
		nb_quete_perso = 0;
	end if;
	nb_quete_perso := nb_quete_perso + 1;
	px_gagne := round(px_gagne/nb_quete_perso);
	update perso set perso_px = perso_px + px_gagne where perso_cod = personnage;
-- 2.5 on rajoute le compteur de quêtes
	update quete_perso
		set pquete_nombre = nb_quete_perso
		where pquete_perso_cod = personnage
		and pquete_quete_cod = num_quete;
-- 2.6 on génère un code retour

	code_retour := code_retour||'<br><br>Félicitations, vous gagnez <b>'||trim(to_char(or_gagne,'99999'))||'</b> brouzoufs et <b>'||trim(to_char(px_gagne,'99999'));
	code_retour := code_retour||'</b> points d''expérience pour cette vente.<br>';
	return code_retour;
end;$_$;


ALTER FUNCTION public.vente_perso(integer, integer) OWNER TO delain;

--
-- Name: verse_solde(); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.verse_solde() RETURNS text
    LANGUAGE plpgsql
    AS $$/*********************************************************/
/* verse_solde                                           */
/*********************************************************/
declare
	code_retour text;
	ligne record;
	num_mes integer;
begin
	for ligne in select perso_cod,rguilde_solde
		from guilde_perso,guilde_rang,perso
		where pguilde_valide = 'O'
		and pguilde_guilde_cod = 49
		and rguilde_guilde_cod = 49
		and pguilde_rang_cod = rguilde_rang_cod
		and perso_actif != 'N'
		and pguilde_perso_cod = perso_cod loop
		update guilde_perso set pguilde_solde = pguilde_solde + ligne.rguilde_solde
			where pguilde_perso_cod = ligne.perso_cod;
		update parametres set parm_valeur = parm_valeur - ligne.rguilde_solde where parm_cod = 39;
		num_mes := nextval('seq_msg_cod');
	end loop;
	return 'Paye versée !';
end;$$;


ALTER FUNCTION public.verse_solde() OWNER TO delain;

--
-- Name: vide_cosmique(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vide_cosmique(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vide cosmique : Dissipe toute magie sur une case     */
/*												 et sur x cases aux alentours					*/
/* On passe en paramètres                                        */
/*    $1 = pos_cod              	                               */
/*    $2 = distance concernée		                                 */
/* Pas de code sortie						                                  */
/*****************************************************************/
/* Créé le 22/12/2007                                            */
/* Liste des modifications :                                     */
/*****************************************************************/
declare
        compt integer;    -- variable pour suppression automap
	code_retour text;
	position_case alias for $1;
	v_distance alias for $2;
	v_x integer;
	v_y integer;
	v_etage integer;
-- variable pour les evts
	texte_evt text;
	ligne record;
	ligne_bonus record;
	ligne_arme record;
	ligne_lieu record;
        lieu_depart integer;		--lieu cod du depart passage a partir du lieu arrivee
	lieu_arrivee integer;		--lieu cod de l'arrivée du passage pour sa suppression aussi
	compteur integer;               -- pour saisir le code text dans la zone retour
compteur_text text;
	v_perso integer;				-- Code du perso suite à la première boucle
	v_nom text;							-- Nom du perso suite à la première boucle

begin
/*on détermine toutes les positions touchées, et donc, tous les persos*/
code_retour := '';
texte_evt := '';
select into v_x,v_y,v_etage
pos_x,pos_y,pos_etage
from positions
where pos_cod = position_case;

for ligne in select pos_cod,perso_cod,perso_nom
				from perso,perso_position,positions
				where perso_actif = 'O'
				and perso_tangible = 'O'
				and ppos_perso_cod = perso_cod
				and ppos_pos_cod = pos_cod
				and perso_tangible = 'O'
				and pos_x between (v_x - v_distance) and (v_x + v_distance)
				and pos_y between (v_y - v_distance) and (v_y + v_distance)
				and pos_etage = v_etage
				and not exists
				(select 1 from lieu_position,lieu
				where lpos_pos_cod = pos_cod
				and lpos_lieu_cod = lieu_cod
				and lieu_refuge = 'O')
                order by perso_cod loop
/*On commence à générer les évènements, et le code retour*/
		texte_evt := '';
		compteur := 1;
		v_perso := ligne.perso_cod;
		v_nom := ligne.perso_nom;
/* Suppression des armes élémentaires  : on a la liste des persos qui peuvent être concernés, on va regarder leur équipement porté*/
		texte_evt := '';
		for ligne_arme in select perobj_obj_cod,obj_nom from perso_objets,objets,objet_generique
				where perobj_perso_cod = v_perso
				and perobj_equipe = 'O'
				and obj_cod = perobj_obj_cod
				and obj_gobj_cod = gobj_cod
				and perobj_dfin IS NOT NULL
				and perobj_dfin - '50 hours'::interval < now() loop
				if compteur = 1 then
					code_retour := code_retour||'Pour '||v_nom;
					texte_evt := 'l''arme de [cible], '||ligne_arme.obj_nom||', a été dissipée par une sphère d''annulation de magie';
				else
					texte_evt := texte_evt||', tout comme '||ligne_arme.obj_nom;
				end if;
				compteur := compteur + 1;
				code_retour := code_retour||', '||ligne_arme.obj_nom||' supprimé';
/*Suppression de l objet en question*/
perform f_del_objet (ligne_arme.perobj_obj_cod);
		end loop;
		if compteur > 1 then
		code_retour := code_retour||'. ';
		end if;
	/*rajout de l évènement pour le perso concerné*/
			values(nextval('seq_levt_cod'),14,now(),1,v_perso,texte_evt,'O','N',v_perso);

	end loop;

/*Suppression de l objet en question*/

/* Suppression des passages magiques */
compteur := 0;
for ligne_lieu in select lpos_lieu_cod,lpos_pos_cod,lieu_dest from lieu,lieu_position,positions
				where lpos_pos_cod = pos_cod
				and pos_x between (v_x - v_distance) and (v_x + v_distance)
				and pos_y between (v_y - v_distance) and (v_y + v_distance)
				and pos_etage = v_etage
				and lieu_cod = lpos_lieu_cod
				and lieu_tlieu_cod	= 10
				and (lieu_url = 'passage.php'
					or lieu_url = 'passage_b.php')
				and lieu_port_dfin is not NULL loop
-- on regarde si on est sur un lieu de depart ou non
                                if ligne_lieu.lieu_dest <> 0 then
					select into lieu_arrivee lpos_lieu_cod from lieu_position where lpos_pos_cod = ligne_lieu.lieu_dest;
				else
					select into lieu_arrivee lieu_cod from lieu, lieu_position where lieu_dest = lpos_pos_cod and lpos_lieu_cod = ligne_lieu.lpos_lieu_cod;
				end if;
				update lieu set lieu_port_dfin = now() where lieu_cod = ligne_lieu.lpos_lieu_cod;
				update lieu set lieu_port_dfin = now() where lieu_cod = lieu_arrivee;
				compteur := compteur + 1;
				end loop;
compteur_text := compteur;
code_retour := code_retour||'<br>'||compteur_text||' lieu(x) supprimé(s) (passages magiques)';
return code_retour;
end;$_$;


ALTER FUNCTION public.vide_cosmique(integer, integer) OWNER TO delain;

--
-- Name: vol(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vol(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vol : un voleur tente de d&#233;trousser sa victime       */
/* On passe en param&#232;tres                                        */
/*    $1 = perso_cod voleur                                      */
/*    $2 = perso_cod cible                                       */
/* Le code sortie est une chaine html utilisable directement     */
/*****************************************************************/
/* Cr&#233;&#233; le 01/04/2003                                            */
/*****************************************************************/
declare
--------------------------------------------------------------------------------
-- variables fourre tout
--------------------------------------------------------------------------------
	texte_evt text;	                -- Texte de l'&#233;vennement
	texte_evt_bis text;	            -- Texte de l'&#233;vennement pour la cible
	code_retour text;				-- chaine qui contiendra le html de retour
	compt integer;					-- compteur mutli usage
	des integer;					-- lancer de des
--------------------------------------------------------------------------------
-- renseignements de l attaquant
--------------------------------------------------------------------------------
	v_attaquant alias for $1;	-- perso_cod attaquant
	pa integer; 					-- pa de l'attaquant
	v_cout_pa integer;			-- cout en PA de l'attaque
	pos_per1 integer;				-- position de l attaquant
	num_comp integer;				-- comp_cod utilis&#233;e
	nom_competence competences.comp_libelle%type;
										-- nom de la comp utilis&#233;e
	comp_vol integer;		-- valeur de la comp d'attaque
	comp_vol_init integer;	-- valeur initiale de la comp
	comp_vol_modifie integer; -- valeur de la comp d'attaque modifi&#233;e
	comp_vol_detection integer; -- valeur de la comp modifi&#233;e pour le jet de d&#233;tection

	malus_type_cible integer;
	malus_lock_a integer;
	malus_lock_d integer;
	bonus_malus_magie integer;
	malus_combat integer;
	malus_monstre integer;

	nb_lock_o integer;			-- nombre de locks offensifs de l'attaquant
	nb_lock_d integer;			-- nombre de locks d&#233;fensifs de l'attaquant

	nb_lock_d_cible integer;	-- nombre de locks d&#233;fensifs de la cible
	nb_lock_o_cible integer;	-- nombre de locks offensifs de la cible
   									-- bonus aux d&#233;gats de l'attaquant
    px_gagne numeric;				-- px gagn&#233;s par l'attaquant

   	pourcentage_br integer;
   	br_voles integer;
   	res_succes integer;
   	res_amelioration integer;
   	res_vu integer;

   limite_comp_maitre integer; -- limite pour le coup sp&#233;cial
   v_bonus_toucher integer;	-- bonus au toucher de l'attaquant (magie)
   v_bonus_degats integer;		-- bonus au toucher de l'attaquant (caracs)
  	nom_arme text;					-- nom de l'arme utilis&#233;e
	v_type_arme integer; 		-- type d'arme : 0 pas d arme, 1 contact, 2 distance
	distance_perso integer;		-- distance maxi d'attaque
	degats_portes integer;		-- degats th&#233;oriques de l'attaque
	degats_effectues integer;	-- degats r&#233;&#233;llement effectu&#233;s (armure d&#233;duite)
	temp_ameliore_competence text;
	temp_comp_vol numeric;
										-- texte temporaire pour l'amel de la comp&#233;tence
	type_attaquant integer;
	v_num_objet integer;

	v_type_lock integer;
	combat_groupe integer;
--------------------------------------------------------------------------------
-- renseignements de la cible
--------------------------------------------------------------------------------
	v_cible alias for $2;		-- perso_cod cible
	type_cible integer;			-- type de la cible (1 pour joueur, 2 pour monstre)
	pos_per2 integer;				-- position de la cible
	nom_per2 perso.perso_nom%type;
										-- nom de la cible
	armure integer;				-- armure de la cible
	po_cible integer;				-- points de vie de la cible
	v_cible_tangible text;		-- tangibilit&#233; de la cible
	v_compte_fam integer;
	v_compte integer;
	v_niveau_cible integer;

	v_dex_cible integer;
    v_int_cible integer;

	v_dex_voleur integer;
    v_int_voleur integer;
    v_comp_vol_cible integer;
    v_event_voleur_vis text;
    v_type_evt_cible integer;
    v_type_evt_voleur integer;
--------------------------------------------------------------------------------
-- variables &#233;v&#232;nements
--------------------------------------------------------------------------------
begin
	-- competence vol
	num_comp := 84;
        br_voles := 0;
	px_gagne := 0;
	v_event_voleur_vis := 'N';
        v_type_evt_cible := 60;
        v_type_evt_voleur := 55;
	malus_monstre := getparm_n(96);
	malus_combat := getparm_n(97);
	v_cout_pa := getparm_n(95);
	code_retour := '<p>'; -- par d&#233;faut, tout est OK

/***********************************************/
/* Etape 1 : on v&#233;rifie que le voleur existe */
/***********************************************/
-- on r&#233;cup&#232;re ici tous les &#233;l&#233;ments concernant l attaquant
	select into 		type_attaquant,
            			pa,
						pos_per1,
						v_cible_tangible,
						v_dex_voleur,
						v_int_voleur
				perso_type_perso,
				perso_pa,
				ppos_pos_cod,
				perso_tangible,
				perso_dex,
				perso_int
		from perso,perso_position
		where perso_cod = v_attaquant
		and ppos_perso_cod = perso_cod;
	if not found then
		code_retour := '<p>Erreur ! Voleur non trouv&#233; !';
		return code_retour;
	end if;
	if v_cible_tangible = 'N' then
		code_retour := '<p>Erreur ! Vous &#234;tes intangible, il vous est impossible de voler !';
		return code_retour;
	end if;
/*********************************************/
/* Etape 2 : on v&#233;rifie que la cible existe  */
/*********************************************/
-- on r&#233;cup&#232;re ici tous les &#233;l&#233;ments concernant la cible
	select into 	type_cible,
						nom_per2,
						pos_per2,
						po_cible,
						v_cible_tangible,
						v_niveau_cible,
						v_dex_cible,
						v_int_cible
					perso_type_perso,
					perso_nom,
					ppos_pos_cod,
					perso_po,
					perso_tangible,
					perso_niveau,
					perso_dex,
					perso_int
		from perso,perso_position
		where perso_cod = v_cible
		and ppos_perso_cod = perso_cod
		and perso_actif = 'O' for update;
	if not found then
		code_retour := '<p>Erreur ! Cible non trouv&#233;e !';
		return code_retour;
	end if;
	if v_cible_tangible = 'N' then
		code_retour := '<p>Erreur ! Cette cible est intangible, il vous est impossible de la voler !';
		return code_retour;
	end if;

	v_compte_fam := -1;
	-- compte de la cible
	if type_cible = 3 then
		select into v_compte_fam
				pcompt_compt_cod
				from perso_familier,perso_compte
				where pfam_familier_cod = v_cible
				and pfam_perso_cod = pcompt_perso_cod;
	elsif type_cible = 1 then
		select into v_compte_fam pcompt_compt_cod from perso_compte
				where pcompt_perso_cod = v_cible;
	end if;
	-- compte du voleur
	if type_attaquant = 3 then
		select into v_compte
				pcompt_compt_cod
				from perso_familier,perso_compte
				where pfam_familier_cod = v_attaquant
				and pfam_perso_cod = pcompt_perso_cod;
	elsif type_attaquant = 1 then
		select into v_compte pcompt_compt_cod from perso_compte
				where pcompt_perso_cod = v_attaquant;
	end if;
	if v_compte = v_compte_fam then
				code_retour := '<p>Erreur ! Vous ne pouvez pas voler un personnage ou un familier de votre compte !';
				return code_retour;
	end if;

	select into compt lieu_cod
		from lieu,lieu_position
		where lpos_pos_cod = pos_per2
		and lpos_lieu_cod = lieu_cod
		and lieu_refuge = 'O';
	if found then
		code_retour := '<p>Erreur ! La cible est sur un lieu prot&#233;g&#233; !';
		return code_retour;
	end if;
/****************************************************/
/* debut des controles li&#233;s aux combats de groupe   */
/****************************************************/

-- Les locks du voleurs donneront lieu &#224; des malus ou une impossiblit&#233; de voler.
	select into nb_lock_d count(lock_cod)
			from lock_combat
			where lock_cible = v_attaquant;
	select into nb_lock_o count(lock_cod)
			from lock_combat
			where lock_attaquant = v_attaquant;
-- les locks de la cible donneront lieu &#224; des malus ou impossibilit&#233; de voler.
	select into nb_lock_d_cible count(lock_cod)
			from lock_combat
			where lock_cible = v_cible;
	select into nb_lock_o_cible count(lock_cod)
			from lock_combat
			where lock_attaquant = v_cible;

/*******************************************************/
/* fin des contr&#244;les li&#233;s aux combats de groupe        */
/*******************************************************/
/*************************************************/
/* Etape 3 : on v&#233;rifie qu il y ait assez de pa  */
/*************************************************/
	if pa < v_cout_pa then
		code_retour := '<p>Erreur ! Pas assez de PA pour effectuer cette action';
		return code_retour;
	end if;
/*************************************************/
/* Etape 4 : on v&#233;rifie la distance d attaque    */
/*************************************************/
	if pos_per1 != pos_per2 then
		code_retour := '<p>Erreur ! La cible est trop &#233;loign&#233;e du voleur';
		return code_retour;
	end if;

/*************************************/
/* Etape 6 : les controles sont bons */
/*     On passe &#224; l attaque          */
/*************************************/

--  enleve les pa
	update perso
		set perso_pa = pa - v_cout_pa
		where perso_cod = v_attaquant;

-- valeur de la competence de base
		select into comp_vol,num_comp
			pcomp_modificateur,pcomp_pcomp_cod
			from perso_competences
			where pcomp_perso_cod = v_attaquant
			and pcomp_pcomp_cod IN(84,85,86);
		if not found then
			code_retour := '<p>Erreur ! Vous n''avez la comp&#233;tence requise pour voler !<br>';
			return code_retour;
		end if;
	comp_vol_init := comp_vol;
-- Bonus-Malus - 1 - Concentration
	select into compt concentration_perso_cod from concentrations
		where concentration_perso_cod = v_attaquant;
	if found then
		comp_vol_modifie := comp_vol + 20;
		delete from concentrations where concentration_perso_cod = v_attaquant;
		code_retour := code_retour||'Votre concentration augmente vos chances de r&#233;ussite: '||malus_type_cible::text||'%<br>';
	else
		comp_vol_modifie := comp_vol;
	end if;
-- Bonus-Malus - 2 - Type de cible (malus en cas de monstre ou familier)
	if type_cible != 1 then
	    malus_type_cible :=  -3 * v_niveau_cible;
	    if malus_type_cible > - malus_monstre then
			malus_type_cible := - malus_monstre;
		end if;
		comp_vol_modifie := comp_vol_modifie + malus_type_cible;
		code_retour := code_retour||'Vos chances sont r&#233;duites en attaquant un monstre: '||malus_type_cible::text||'%<br>';
	end if;
-- Bonus-Malus - 3 - Locks de combat.
	malus_lock_a := (nb_lock_d + nb_lock_o) * -1 * malus_combat;
	if malus_lock_a != 0 then
		comp_vol_modifie := comp_vol_modifie + malus_lock_a;
		code_retour := code_retour||'Vous &#234;tes en combat vos chances de r&#233;ussite sont diminu&#233;es: '||trim(to_char(malus_lock_a,'9999999'))||'%<br>';
	end if;
	malus_lock_d := (nb_lock_d_cible + nb_lock_o_cible) * -1 * malus_combat;
	if malus_lock_a != 0 then
		comp_vol_modifie := comp_vol_modifie + malus_lock_d;
		code_retour := code_retour||'Votre cible est en plein combat vos chances de r&#233;ussite sont diminu&#233;es: '||trim(to_char(malus_lock_d,'9999999'))||'%<br>';
	end if;
-- Bonus-Malus - 4 - Sorts.
	comp_vol_modifie := comp_vol_modifie + valeur_bonus(v_attaquant, 'VOL');

-- Bonus-Malus - 5 - Minimum de 10%
	if comp_vol_modifie < 10 then
		comp_vol_modifie := 10;
	end if;
-- limite pour un coup sp&#233;cial
	limite_comp_maitre := round(comp_vol_modifie*0.25);
-- comp pour la detection
	comp_vol_detection := round(comp_vol_modifie*0.30);
	if num_comp = 85 then
	-- niveau 2
		comp_vol_detection := round(comp_vol_modifie*0.60);
	end if;
	if num_comp = 86 then
	-- niveau 3
		comp_vol_detection := round(comp_vol_modifie*0.80);
	end if;
	comp_vol_detection := comp_vol_detection - v_dex_cible - v_int_cible + v_dex_voleur + v_int_voleur;
	--
	select into v_comp_vol_cible
			pcomp_modificateur,pcomp_pcomp_cod
			from perso_competences
			where pcomp_perso_cod = v_cible
			and pcomp_pcomp_cod IN(84,85,86);
        if v_comp_vol_cible is not null then
	  comp_vol_detection := comp_vol_detection - round(v_comp_vol_cible / 5);
	end if;
-- CALCUL DE LA PORPORTION DE BR SUBTILISEE
	pourcentage_br := 6; --valeur de d&#233;part 6% max
	if num_comp = 85 then
	-- niveau 2
		pourcentage_br := round(pourcentage_br*1.3);
	end if;
	if num_comp = 86 then
	-- niveau 3
		pourcentage_br := round(pourcentage_br*1.5);
	end if;

	pourcentage_br := lancer_des(1,pourcentage_br);
---------------------------------------------------------------------------
-- etape 5.2 : on commence &#224; g&#233;n&#233;rer un code retour
   	res_succes := 0;
   	res_amelioration := 0;
   	res_vu := 1;

	code_retour := code_retour||'<br>Vous tentez de voler le ';
	if type_cible = 1 then
		code_retour := code_retour||'joueur ';
	else
		code_retour := code_retour||'monstre ';
	end if;
	code_retour := code_retour||' <b>'||nom_per2||'</b><br><br>'; -- pos 2
	select into nom_competence comp_libelle from competences
		where comp_cod = num_comp;
	code_retour := code_retour||'Vous avez utilis&#233; la comp&#233;tence <b>'||nom_competence;
	code_retour := code_retour||'</b> (chance de r&#233;ussite en tenant compte des modificateurs :<b>'||trim(to_char(comp_vol_modifie,'999'))||'</b> %)<br>';

-- etape 5.3 : on regarde si l attaque a r&#233;ussi
	des := lancer_des(1,100);
	code_retour := code_retour||'Votre lancer de d&#233;s est de <b>'||trim(to_char(des,'999'))||'</b>, '; -- pos 5 lancer des
	if des > 96 then -- echec critique
		code_retour := code_retour||'il s''agit donc d''un &#233;chec automatique.<br><br>';
	elsif ((des > 5) and (des > limite_comp_maitre) and (des > comp_vol_modifie)) then
		code_retour := code_retour||'il s''agit donc d''un &#233;chec.<br><br>';
		if comp_vol_init <= getparm_n(1) then
			res_amelioration := 1;
		end if;
	elsif ((des > 5) and (des > limite_comp_maitre) and (des <= comp_vol_modifie)) then
		code_retour := code_retour||'il s''agit donc d''une r&#233;ussite.<br><br>';
		res_succes := 1;
   		res_amelioration := 1;
	elsif ((des > 5) and (des <= limite_comp_maitre)) then
		code_retour := code_retour||'il s''agit donc d''une r&#233;ussite sp&#233;ciale.<br><br>';
		pourcentage_br := pourcentage_br + 2;
		res_succes := 1;
   		res_amelioration := 1;
	elsif (des <= 5) then
		code_retour := code_retour||'il s''agit donc d''une r&#233;ussite critique.<br><br>';

		pourcentage_br := pourcentage_br + 5;
		res_succes := 1;
   		res_amelioration := 1;
	end if;
	-- VU OU PAS ?

	if res_succes > 0 then
		code_retour := code_retour||'Chances de ne pas &#234;tre vu en tenant compte des modificateurs :<b>'|| trim(to_char(comp_vol_detection,'999'))||'</b> )<br>';
		des := lancer_des(1,100);
		code_retour := code_retour||'Votre lancer de d&eacute;s est de <b>'||trim(to_char(des,'999'))||'</b>, ';
		if des > comp_vol_detection then
			code_retour := code_retour||'La cible a vu qui &eacute;tait le voleur.<br><br>';
			res_vu := 1;
			v_event_voleur_vis := 'O';
		        v_type_evt_cible := 58;
                        v_type_evt_voleur := 58;
		else
			code_retour := code_retour||'La cible n''a pas pu voir qui &eacute;tait le voleur.<br><br>';
			res_vu := 0;
		end if;
	else
	    v_type_evt_cible := 59;
            v_type_evt_voleur := 59;
	    v_event_voleur_vis := 'O';
	end if;

	-- AMELIORATION
	if res_amelioration > 0 then
		temp_ameliore_competence := ameliore_competence_px(v_attaquant,num_comp,comp_vol_init);
		code_retour := code_retour||'Votre jet d''am&#233;lioration est de '||split_part(temp_ameliore_competence,';',1)||', ';
		if split_part(temp_ameliore_competence,';',2) = '1' then
			code_retour := code_retour||'vous avez donc <b>am&#233;lior&#233;</b> cette comp&#233;tence.<br> ';
			code_retour := code_retour||'Sa nouvelle valeur est '||split_part(temp_ameliore_competence,';',3)||'<br><br>';
			px_gagne := px_gagne + 1;
		else
			code_retour := code_retour||'vous n''avez pas am&#233;lior&#233; cette comp&#233;tence.<br><br> ';
		end if;
	end if;

	-- TRANSFERT DE BR
	if res_succes > 0 then
		br_voles :=  round((pourcentage_br * po_cible) /100);
	        if br_voles is null then
		   br_voles := 0;
	        end if;
		if type_attaquant = 2 then
		  update perso
			 set perso_po = perso_po +  round(br_voles*0.5)
			 where perso_cod = v_attaquant;
		else
		  update perso
			 set perso_po = perso_po + br_voles
			 where perso_cod = v_attaquant;
                end if;
		update perso
			set perso_po = perso_po - br_voles
			where perso_cod = v_cible;
		code_retour := code_retour||'Vous volez <b>'||trim(to_char(br_voles,'9999999'))||' Br</b>.<br><br> ';
	end if;

	-- EVENEMENTS

	if res_succes > 0 then
		if res_vu > 0 then
			-- VU
			texte_evt := '[attaquant] a vol&#233; <b>'||trim(to_char(br_voles,'999999999'))||'Br</b> &#224; [cible] qui s''en est aper&#231;u';
			texte_evt_bis := '[attaquant] a vol&#233; <b>'||trim(to_char(br_voles,'999999999'))||'Br</b> &#224; [cible] qui s''en est aper&#231;u';
			if type_attaquant = 2 then
			    texte_evt := texte_evt || ' et a cach&#233; une partie de son butin';
			    texte_evt_bis := texte_evt_bis || ' et a cach&#233; une partie de son butin';
			end if;
			-- INSERTION DU LOCK
			if type_attaquant != 3 then
				if type_cible != 3 then
					delete from lock_combat where lock_attaquant = v_attaquant and lock_cible = v_cible;
						values (nextval('seq_lock_cod'),v_attaquant,v_cible,getparm_n(17));
					end if;
			end if;
		else
			texte_evt := '[attaquant] a vol&#233; <b>'||trim(to_char(br_voles,'9999999'))||'Br</b> &#224; [cible] en toute discr&#233;tion';
			texte_evt_bis := 'un inconnu a vol&#233; <b>'||trim(to_char(br_voles,'9999999'))||'Br</b> &#224; [cible] en toute discr&#233;tion';
			if type_attaquant = 2 then
			    texte_evt := texte_evt || ' et a cach&#233; une partie de son butin';
			end if;
		end if;

	else
		texte_evt := '[attaquant] a rat&#233; un vol sur [cible]';
		texte_evt_bis := '[attaquant] a rat&#233; un vol sur [cible]';
	end if;

		values(nextval('seq_levt_cod'),v_type_evt_voleur,now(),1,v_attaquant,texte_evt,'O',v_event_voleur_vis,v_attaquant,v_cible);
		values(nextval('seq_levt_cod'),v_type_evt_cible,now(),1,v_cible,texte_evt_bis,'N','O',v_attaquant,v_cible);

	-- XP
        if br_voles = 0 then
          px_gagne := px_gagne + 0;
	elsif br_voles > 2000 then
		px_gagne := px_gagne + 2;
	else
		px_gagne := px_gagne + (br_voles*0.001::numeric);
	end if;
	if px_gagne is null then
		px_gagne := 0.0;
	end if;
	update perso
	set perso_px = perso_px + px_gagne
	where perso_cod = v_attaquant;
	code_retour := code_retour||'Vous gagnez '||to_char(px_gagne,'999999990D99')||' PX pour cette action.';

	return code_retour;
end;$_$;


ALTER FUNCTION public.vol(integer, integer) OWNER TO delain;

--
-- Name: vol_objet(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vol_objet(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vol : un voleur tente de d&#233;trousser sa victime       */
/* On passe en param&#232;tres                                        */
/*    $1 = perso_cod voleur                                      */
/*    $2 = perso_cod cible                                       */
/* Le code sortie est une chaine html utilisable directement     */
/*****************************************************************/
/* Cr&#233;&#233; le 01/04/2003                                            */
/*****************************************************************/
declare
--------------------------------------------------------------------------------
-- variables fourre tout
--------------------------------------------------------------------------------
	texte_evt text;	                -- Texte de l'&#233;vennement
	texte_evt_bis text;	            -- Texte de l'&#233;vennement pour la cible
	code_retour text;				-- chaine qui contiendra le html de retour
	compt integer;					-- compteur mutli usage
	des integer;					-- lancer de des
--------------------------------------------------------------------------------
-- renseignements de l attaquant
--------------------------------------------------------------------------------
	v_attaquant alias for $1;	-- perso_cod attaquant
	pa integer; 					-- pa de l'attaquant
	v_cout_pa integer;			-- cout en PA de l'attaque
	pos_per1 integer;				-- position de l attaquant
	num_comp integer;				-- comp_cod utilis&#233;e
	nom_competence competences.comp_libelle%type;
										-- nom de la comp utilis&#233;e
	comp_vol integer;		-- valeur de la comp d'attaque
	comp_vol_init integer;	-- valeur initiale de la comp
	comp_vol_modifie integer; -- valeur de la comp d'attaque modifi&#233;e
	comp_vol_detection integer; -- valeur de la comp modifi&#233;e pour le jet de d&#233;tection

	malus_type_cible integer;
	malus_lock_a integer;
	malus_lock_d integer;
	bonus_malus_magie integer;
	malus_combat integer;
	malus_monstre integer;

	nb_lock_o integer;			-- nombre de locks offensifs de l'attaquant
	nb_lock_d integer;			-- nombre de locks d&#233;fensifs de l'attaquant

	nb_lock_d_cible integer;	-- nombre de locks d&#233;fensifs de la cible
	nb_lock_o_cible integer;	-- nombre de locks offensifs de la cible
   									-- bonus aux d&#233;gats de l'attaquant
    px_gagne numeric;				-- px gagn&#233;s par l'attaquant

   	num_obj_vole integer;
   	res_succes integer;
   	res_amelioration integer;
   	res_vu integer;

   limite_comp_maitre integer; -- limite pour le coup sp&#233;cial
   v_bonus_toucher integer;	-- bonus au toucher de l'attaquant (magie)
   v_bonus_degats integer;		-- bonus au toucher de l'attaquant (caracs)
  	nom_arme text;					-- nom de l'arme utilis&#233;e
	v_type_arme integer; 		-- type d'arme : 0 pas d arme, 1 contact, 2 distance
	distance_perso integer;		-- distance maxi d'attaque
	degats_portes integer;		-- degats th&#233;oriques de l'attaque
	degats_effectues integer;	-- degats r&#233;&#233;llement effectu&#233;s (armure d&#233;duite)
	temp_ameliore_competence text;
	temp_comp_vol numeric;
										-- texte temporaire pour l'amel de la comp&#233;tence
	type_attaquant integer;
	v_num_objet integer;
	v_nom_objet text;

	v_type_lock integer;
	combat_groupe integer;
--------------------------------------------------------------------------------
-- renseignements de la cible
--------------------------------------------------------------------------------
	v_cible alias for $2;		-- perso_cod cible
	type_cible integer;			-- type de la cible (1 pour joueur, 2 pour monstre)
	pos_per2 integer;				-- position de la cible
	nom_per2 perso.perso_nom%type;
										-- nom de la cible
	armure integer;				-- armure de la cible
	po_cible integer;				-- points de vie de la cible
	v_cible_tangible text;		-- tangibilit&#233; de la cible
	v_compte_fam integer;
	v_compte integer;
	temp_texte_titre text;
	v_niveau_cible integer;
	v_dex_cible integer;
    v_int_cible integer;

	v_dex_voleur integer;
    v_int_voleur integer;
    v_comp_vol_cible integer;

    v_poids_objet numeric;

--------------------------------------------------------------------------------
-- variables &#233;v&#232;nements
--------------------------------------------------------------------------------
begin
	-- competence vol
	num_comp := 86;
	px_gagne := 0;
	malus_monstre := getparm_n(96);
	malus_combat := getparm_n(97);
	v_cout_pa := getparm_n(95);
	code_retour := '<p>'; -- par d&#233;faut, tout est OK

/***********************************************/
/* Etape 1 : on v&#233;rifie que le voleur existe */
/***********************************************/
-- on r&#233;cup&#232;re ici tous les &#233;l&#233;ments concernant l attaquant
	select into 		pa,
						pos_per1,
						v_cible_tangible,
						v_dex_voleur,
						v_int_voleur
				perso_pa,
				ppos_pos_cod,
				perso_tangible,
				perso_dex,
				perso_int
		from perso,perso_position
		where perso_cod = v_attaquant
		and ppos_perso_cod = perso_cod;
	if not found then
		code_retour := '<p>Erreur ! Voleur non trouv&#233; !';
		return code_retour;
	end if;
	if v_cible_tangible = 'N' then
		code_retour := '<p>Erreur ! Vous &#234;tes intangible, il vous est impossible de voler !';
		return code_retour;
	end if;
/*********************************************/
/* Etape 2 : on v&#233;rifie que la cible existe  */
/*********************************************/
-- on r&#233;cup&#232;re ici tous les &#233;l&#233;ments concernant la cible
	select into 	type_cible,
						nom_per2,
						pos_per2,
						po_cible,
						v_cible_tangible,
						v_niveau_cible,
						v_dex_cible,
						v_int_cible
					perso_type_perso,
					perso_nom,
					ppos_pos_cod,
					perso_po,
					perso_tangible,
					perso_niveau,
					perso_dex,
					perso_int
		from perso,perso_position
		where perso_cod = v_cible
		and ppos_perso_cod = perso_cod
		and perso_actif = 'O' for update;
	if not found then
		code_retour := '<p>Erreur ! Cible non trouv&#233;e !';
		return code_retour;
	end if;
	if v_cible_tangible = 'N' then
		code_retour := '<p>Erreur ! Cette cible est intangible, il vous est impossible de la voler !';
		return code_retour;
	end if;
	if type_cible = 3 then
		if type_attaquant = 1 then
			select into v_compte_fam
				pcompt_compt_cod
				from perso_familier,perso_compte
				where pfam_familier_cod = v_cible
				and pfam_perso_cod = pcompt_perso_cod;
			select into v_compte pcompt_compt_cod from perso_compte
				where pcompt_perso_cod = v_attaquant;
			if v_compte = v_compte_fam then
				code_retour := '<p>Erreur ! Vous ne pouvez pas voler les familiers d''un des persos de votre compte !';
				return code_retour;
			end if;
		end if;
	end if;
	select into compt lieu_cod
		from lieu,lieu_position
		where lpos_pos_cod = pos_per2
		and lpos_lieu_cod = lieu_cod
		and lieu_refuge = 'O';
	if found then
		code_retour := '<p>Erreur ! La cible est sur un lieu prot&#233;g&#233; !';
		return code_retour;
	end if;
/****************************************************/
/* debut des controles li&#233;s aux combats de groupe   */
/****************************************************/

-- Les locks du voleurs donneront lieu &#224; des malus ou une impossiblit&#233; de voler.
	select into nb_lock_d count(lock_cod)
			from lock_combat
			where lock_cible = v_attaquant;
	select into nb_lock_o count(lock_cod)
			from lock_combat
			where lock_attaquant = v_attaquant;
-- les locks de la cible donneront lieu &#224; des malus ou impossibilit&#233; de voler.
	select into nb_lock_d_cible count(lock_cod)
			from lock_combat
			where lock_cible = v_cible;
	select into nb_lock_o_cible count(lock_cod)
			from lock_combat
			where lock_attaquant = v_cible;

/*******************************************************/
/* fin des contr&#244;les li&#233;s aux combats de groupe        */
/*******************************************************/
/*************************************************/
/* Etape 3 : on v&#233;rifie qu il y ait assez de pa  */
/*************************************************/
	if pa < v_cout_pa then
		code_retour := '<p>Erreur ! Pas assez de PA pour effectuer cette action';
		return code_retour;
	end if;
/*************************************************/
/* Etape 4 : on v&#233;rifie la distance d attaque    */
/*************************************************/
	if pos_per1 != pos_per2 then
		code_retour := '<p>Erreur ! La cible est trop &#233;loign&#233;e du voleur';
		return code_retour;
	end if;

/*************************************/
/* Etape 6 : les controles sont bons */
/*     On passe &#224; l attaque          */
/*************************************/

--  enleve les pa
	update perso
		set perso_pa = pa - v_cout_pa
		where perso_cod = v_attaquant;

-- valeur de la competence de base
		select into comp_vol,num_comp
			pcomp_modificateur,pcomp_pcomp_cod
			from perso_competences
			where pcomp_perso_cod = v_attaquant
			and pcomp_pcomp_cod = 86;
		if not found then
			code_retour := '<p>Erreur ! Vous n''avez la comp&#233;tence requise pour voler !<br>';
			return code_retour;
		end if;
	comp_vol_init := comp_vol;
-- Bonus-Malus - 1 - Concentration
	select into compt concentration_perso_cod from concentrations
		where concentration_perso_cod = v_attaquant;
	if found then
		comp_vol_modifie := comp_vol + 20;
		delete from concentrations where concentration_perso_cod = v_attaquant;
		code_retour := code_retour||'Votre concentration augmente vos chances de r&#233;ussite: '||malus_type_cible::text||'%<br>';
	else
		comp_vol_modifie := comp_vol;
	end if;
-- Bonus-Malus - 2 - Type de cible (malus en cas de monstre ou familier)
	if type_cible != 1 then
		malus_type_cible :=  -3 * v_niveau_cible;
	    if malus_type_cible > - malus_monstre then
			malus_type_cible := - malus_monstre;
		end if;
		comp_vol_modifie := comp_vol_modifie + malus_type_cible;
		code_retour := code_retour||'Vos chances sont r&#233;duites en attaquant un monstre: '||malus_type_cible::text||'%<br>';
	end if;
-- Bonus-Malus - 3 - Locks de combat.
	malus_lock_a := (nb_lock_d + nb_lock_o) * -1 * malus_combat;
	if malus_lock_a != 0 then
		comp_vol_modifie := comp_vol_modifie + malus_lock_a;
		code_retour := code_retour||'Vous &#234;tes en combat vos chances de r&#233;ussite sont diminu&#233;es: '||malus_lock_a::text||'%<br>';
	end if;
	malus_lock_d := (nb_lock_d_cible + nb_lock_o_cible) * -1 * malus_combat;
	if malus_lock_a != 0 then
		comp_vol_modifie := comp_vol_modifie + malus_lock_d;
		code_retour := code_retour||'Votre cible est en plein combat vos chances de r&#233;ussite sont diminu&#233;es: '||malus_lock_d::text||'%<br>';
	end if;
-- Bonus-Malus - 4 - Sorts.
	comp_vol_modifie := comp_vol_modifie + valeur_bonus(v_attaquant, 'VOL');

-- Bonus-Malus - 5 - Minimum de 10%
	if comp_vol_modifie < 10 then
		comp_vol_modifie := 10;
	end if;
-- limite pour un coup sp&#233;cial
	limite_comp_maitre := round(comp_vol_modifie*0.25);
-- comp pour la detection
	comp_vol_detection := round(comp_vol_modifie*0.30);
	if num_comp = 85 then
	-- niveau 2
		comp_vol_detection := round(comp_vol_modifie*0.60);
	end if;
	if num_comp = 86 then
	-- niveau 3
		comp_vol_detection := round(comp_vol_modifie*0.80);
	end if;
	comp_vol_detection := comp_vol_detection - v_dex_cible - v_int_cible + v_dex_voleur + v_int_voleur;
	--
	select into v_comp_vol_cible
			pcomp_modificateur,pcomp_pcomp_cod
			from perso_competences
			where pcomp_perso_cod = v_cible
			and pcomp_pcomp_cod IN(84,85,86);
	comp_vol_detection := comp_vol_detection - (v_comp_vol_cible / 5);

---------------------------------------------------------------------------
-- etape 5.2 : on commence &#224; g&#233;n&#233;rer un code retour
   	res_succes := 0;
   	res_amelioration := 0;
   	res_vu := 1;

	code_retour := code_retour||'<br>Vous tentez de voler le ';
	if type_cible = 1 then
		code_retour := code_retour||'joueur ';
	else
		code_retour := code_retour||'monstre ';
	end if;
	code_retour := code_retour||' <b>'||nom_per2||'</b><br><br>'; -- pos 2
	select into nom_competence comp_libelle from competences
		where comp_cod = num_comp;
	code_retour := code_retour||'Vous avez utilis&#233; la comp&#233;tence <b>'||nom_competence;
	code_retour := code_retour||'</b> (chance de r&#233;ussite en tenant compte des modificateurs :<b>'||trim(to_char(comp_vol_modifie,'999'))||'</b> %)<br>';

-- etape 5.3 : on regarde si l attaque a r&#233;ussi
	des := lancer_des(1,100);
	code_retour := code_retour||'Votre lancer de d&#233;s est de <b>'||trim(to_char(des,'999'))||'</b>, '; -- pos 5 lancer des
	if des > 96 then -- echec critique
		code_retour := code_retour||'il s''agit donc d''un &#233;chec automatique.<br><br>';
		-- INSERTION DU TITRE
		temp_texte_titre :='Voleur pas tr&#232;s dou&#233;';
		select into compt ptitre_perso_cod from  perso_titre
		where ptitre_perso_cod = v_attaquant and ptitre_titre = temp_texte_titre;
		if not found then
			values(v_attaquant,temp_texte_titre,now());
		end if;
	elsif ((des > 5) and (des > limite_comp_maitre) and (des > comp_vol_modifie)) then
		code_retour := code_retour||'il s''agit donc d''un &#233;chec.<br><br>';
		if comp_vol_init <= getparm_n(1) then
			res_amelioration := 1;
		end if;
	elsif ((des > 5) and (des > limite_comp_maitre) and (des <= comp_vol_modifie)) then
		code_retour := code_retour||'il s''agit donc d''une r&#233;ussite.<br><br>';
		res_succes := 1;
   		res_amelioration := 1;
	elsif ((des > 5) and (des <= limite_comp_maitre)) then
		code_retour := code_retour||'il s''agit donc d''une r&#233;ussite sp&#233;ciale.<br><br>';
		res_succes := 1;
   		res_amelioration := 1;
	elsif (des <= 5) then
		code_retour := code_retour||'il s''agit donc d''une r&#233;ussite critique.<br><br>';
		res_succes := 1;
   		res_amelioration := 1;
	end if;
	-- TRANSFERT DE L'OBJET
	v_poids_objet := 0;
	if res_succes > 0 then
		-- Selection de l'objet
		select into compt count(obj_cod)as num from objets, perso_objets
		  where perobj_obj_cod = obj_cod
		  and perobj_perso_cod = v_cible
		  and perobj_equipe <> 'O'
		  and obj_poids <= 2
		  and not exists (select 1 from perso_glyphes -- Bleda 30/01/11 : Glyphes
		  		  where pglyphe_perso_cod = v_attaquant
		  		  and pglyphe_obj_cod = obj_cod);
	        if compt < 1 then
		  		code_retour := code_retour||'Dommage, la cible n''a aucun petit objet dans son sac !<br><br> ';
		  		v_nom_objet := 'rien du tout';
            else
			  des := lancer_des(1,compt)-1;
			  select into v_num_objet,v_nom_objet,v_poids_objet obj_cod,obj_nom,obj_poids from objets, perso_objets
				where perobj_obj_cod = obj_cod
		  		and perobj_perso_cod = v_cible
		 		and perobj_equipe <> 'O'
		  		and obj_poids <= 2
				offset des limit 1;
              update perso_objets set perobj_perso_cod = v_attaquant
                where perobj_obj_cod = v_num_objet;
              px_gagne := px_gagne + 0.33;
			  code_retour := code_retour||'Vous d&#233;robez l''objet <b>'||v_nom_objet||'</b><br><br> ';
            end if;
	end if;
	--code_retour := code_retour||'Poids='||v_poids_objet||'<br>';
	comp_vol_detection := round(comp_vol_detection - (v_poids_objet *10));

	-- VU OU PAS ?
	if res_succes > 0 then
		code_retour := code_retour||'Chances de ne pas &#234;tre vu en tenant compte des modificateurs :<b>'||trim(to_char(comp_vol_detection,'999'))||'</b> %)<br>';
		des := lancer_des(1,100);
		code_retour := code_retour||'Votre lancer de d&#233;s est de <b>'||trim(to_char(des,'999'))||'</b>, ';
		if des > comp_vol_detection then
			code_retour := code_retour||'La cible a vu qui &#233;tait le voleur.<br><br>';
			res_vu := 1;
		else
			code_retour := code_retour||'La cible n''a pas pu voir qui &#233;tait le voleur.<br><br>';
			res_vu := 0;
		end if;
	end if;

	-- AMELIORATION
	if res_amelioration > 0 then
		temp_ameliore_competence := ameliore_competence_px(v_attaquant,num_comp,comp_vol_init);
		code_retour := code_retour||'Votre jet d''am&#233;lioration est de '||split_part(temp_ameliore_competence,';',1)||', '; -- pos 7 8 9 10
		if split_part(temp_ameliore_competence,';',2) = '1' then
			code_retour := code_retour||'vous avez donc <b>am&#233;lior&#233;</b> cette comp&#233;tence.<br> ';
			code_retour := code_retour||'Sa nouvelle valeur est '||split_part(temp_ameliore_competence,';',3)||'<br><br>';
			px_gagne := px_gagne + 1;
		else
			code_retour := code_retour||'vous n''avez pas am&#233;lior&#233; cette comp&#233;tence.<br><br> ';
		end if;
	end if;

	-- EVENEMENTS
	if res_succes > 0 then
		if res_vu > 0 then
			-- VU
			texte_evt := '[attaquant] a vol&#233; '||v_nom_objet||' &#224; [cible] qui s''en est aper&#231;u';
			texte_evt_bis := '[attaquant] a vol&#233; '||v_nom_objet||' &#224; [cible] qui s''en est aper&#231;u';
			-- INSERTION DU LOCK
			if type_attaquant != 3 then
				if type_cible != 3 then
					delete from lock_combat where lock_attaquant = v_attaquant and lock_cible = v_cible;
						values (nextval('seq_lock_cod'),v_attaquant,v_cible,getparm_n(17));
					end if;
			end if;
		else
			texte_evt := '[attaquant] a vol&#233; '||v_nom_objet||' &#224; [cible] en toute discr&#233;tion';
			texte_evt_bis := 'un inconnu a vol&#233; '||v_nom_objet||' &#224; [cible] en toute discr&#233;tion';
		end if;
	else
		if res_vu > 0 then
		  texte_evt := '[attaquant] a rat&#233; un vol sur [cible]';
		  texte_evt_bis := '[attaquant] a rat&#233; un vol sur [cible]';
    else
      texte_evt := '[attaquant] a rat&#233; un vol sur [cible]';
		  texte_evt_bis := 'un inconnu a rat&#233; un vol sur [cible]';
    end if;
	end if;
		values(nextval('seq_levt_cod'),55,now(),1,v_attaquant,texte_evt,'O','N',v_attaquant,v_cible);
		values(nextval('seq_levt_cod'),55,now(),1,v_cible,texte_evt_bis,'N','N',v_attaquant,v_cible);
	-- XP
	if px_gagne is null then
		px_gagne := 0.0;
	end if;
	update perso
	set perso_px = perso_px + px_gagne, perso_kharma = perso_kharma - 0.1
	where perso_cod = v_attaquant;
	code_retour := code_retour||'Vous gagnez '||to_char(px_gagne,'999999990D99')||' PX pour cette action.';

	return code_retour;
end;$_$;


ALTER FUNCTION public.vol_objet(integer, integer) OWNER TO delain;

--
-- Name: vol_objet2(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vol_objet2(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vol : un voleur tente de d&#233;trousser sa victime       */
/* On passe en param&#232;tres                                        */
/*    $1 = perso_cod voleur                                      */
/*    $2 = perso_cod cible                                       */
/* Le code sortie est une chaine html utilisable directement     */
/*****************************************************************/
/* Cr&#233;&#233; le 01/04/2003                                            */
/*****************************************************************/
declare
--------------------------------------------------------------------------------
-- variables fourre tout
--------------------------------------------------------------------------------
	texte_evt text;	                -- Texte de l'&#233;vennement
	texte_evt_bis text;	            -- Texte de l'&#233;vennement pour la cible
	code_retour text;				-- chaine qui contiendra le html de retour
	compt integer;					-- compteur mutli usage
	des integer;					-- lancer de des
--------------------------------------------------------------------------------
-- renseignements de l attaquant
--------------------------------------------------------------------------------
	v_attaquant alias for $1;	-- perso_cod attaquant
	pa integer; 					-- pa de l'attaquant
	v_cout_pa integer;			-- cout en PA de l'attaque
	pos_per1 integer;				-- position de l attaquant
	num_comp integer;				-- comp_cod utilis&#233;e
	nom_competence competences.comp_libelle%type;
										-- nom de la comp utilis&#233;e
	comp_vol integer;		-- valeur de la comp d'attaque
	comp_vol_init integer;	-- valeur initiale de la comp
	comp_vol_modifie integer; -- valeur de la comp d'attaque modifi&#233;e
	comp_vol_detection integer; -- valeur de la comp modifi&#233;e pour le jet de d&#233;tection

	malus_type_cible integer;
	malus_lock_a integer;
	malus_lock_d integer;
	bonus_malus_magie integer;
	malus_combat integer;
	malus_monstre integer;

	nb_lock_o integer;			-- nombre de locks offensifs de l'attaquant
	nb_lock_d integer;			-- nombre de locks d&#233;fensifs de l'attaquant

	nb_lock_d_cible integer;	-- nombre de locks d&#233;fensifs de la cible
	nb_lock_o_cible integer;	-- nombre de locks offensifs de la cible
   									-- bonus aux d&#233;gats de l'attaquant
    px_gagne numeric;				-- px gagn&#233;s par l'attaquant

   	num_obj_vole integer;
   	res_succes integer;
   	res_amelioration integer;
   	res_vu integer;

   limite_comp_maitre integer; -- limite pour le coup sp&#233;cial
   v_bonus_toucher integer;	-- bonus au toucher de l'attaquant (magie)
   v_bonus_degats integer;		-- bonus au toucher de l'attaquant (caracs)
  	nom_arme text;					-- nom de l'arme utilis&#233;e
	v_type_arme integer; 		-- type d'arme : 0 pas d arme, 1 contact, 2 distance
	distance_perso integer;		-- distance maxi d'attaque
	degats_portes integer;		-- degats th&#233;oriques de l'attaque
	degats_effectues integer;	-- degats r&#233;&#233;llement effectu&#233;s (armure d&#233;duite)
	temp_ameliore_competence text;
	temp_comp_vol numeric;
										-- texte temporaire pour l'amel de la comp&#233;tence
	type_attaquant integer;
	v_num_objet integer;
	v_nom_objet text;

	v_type_lock integer;
	combat_groupe integer;
--------------------------------------------------------------------------------
-- renseignements de la cible
--------------------------------------------------------------------------------
	v_cible alias for $2;		-- perso_cod cible
	type_cible integer;			-- type de la cible (1 pour joueur, 2 pour monstre)
	pos_per2 integer;				-- position de la cible
	nom_per2 perso.perso_nom%type;
										-- nom de la cible
	armure integer;				-- armure de la cible
	po_cible integer;				-- points de vie de la cible
	v_cible_tangible text;		-- tangibilit&#233; de la cible
	v_compte_fam integer;
	v_compte integer;
	temp_texte_titre text;
	v_niveau_cible integer;
	v_dex_cible integer;
    v_int_cible integer;

	v_dex_voleur integer;
    v_int_voleur integer;
    v_comp_vol_cible integer;

    v_poids_objet numeric;

--------------------------------------------------------------------------------
-- variables &#233;v&#232;nements
--------------------------------------------------------------------------------
begin
	-- competence vol
	num_comp := 86;
	px_gagne := 0;
	malus_monstre := getparm_n(96);
	malus_combat := getparm_n(97);
	v_cout_pa := getparm_n(95);
	code_retour := '<p>'; -- par d&#233;faut, tout est OK

/***********************************************/
/* Etape 1 : on v&#233;rifie que le voleur existe */
/***********************************************/
-- on r&#233;cup&#232;re ici tous les &#233;l&#233;ments concernant l attaquant
	select into 		pa,
						pos_per1,
						v_cible_tangible,
						v_dex_voleur,
						v_int_voleur
				perso_pa,
				ppos_pos_cod,
				perso_tangible,
				perso_dex,
				perso_int
		from perso,perso_position
		where perso_cod = v_attaquant
		and ppos_perso_cod = perso_cod;
	if not found then
		code_retour := '<p>Erreur ! Voleur non trouv&#233; !';
		return code_retour;
	end if;
	if v_cible_tangible = 'N' then
		code_retour := '<p>Erreur ! Vous &#234;tes intangible, il vous est impossible de voler !';
		return code_retour;
	end if;
/*********************************************/
/* Etape 2 : on v&#233;rifie que la cible existe  */
/*********************************************/
-- on r&#233;cup&#232;re ici tous les &#233;l&#233;ments concernant la cible
	select into 	type_cible,
						nom_per2,
						pos_per2,
						po_cible,
						v_cible_tangible,
						v_niveau_cible,
						v_dex_cible,
						v_int_cible
					perso_type_perso,
					perso_nom,
					ppos_pos_cod,
					perso_po,
					perso_tangible,
					perso_niveau,
					perso_dex,
					perso_int
		from perso,perso_position
		where perso_cod = v_cible
		and ppos_perso_cod = perso_cod
		and perso_actif = 'O' for update;
	if not found then
		code_retour := '<p>Erreur ! Cible non trouv&#233;e !';
		return code_retour;
	end if;
	if v_cible_tangible = 'N' then
		code_retour := '<p>Erreur ! Cette cible est intangible, il vous est impossible de la voler !';
		return code_retour;
	end if;
	if type_cible = 3 then
		if type_attaquant = 1 then
			select into v_compte_fam
				pcompt_compt_cod
				from perso_familier,perso_compte
				where pfam_familier_cod = v_cible
				and pfam_perso_cod = pcompt_perso_cod;
			select into v_compte pcompt_compt_cod from perso_compte
				where pcompt_perso_cod = v_attaquant;
			if v_compte = v_compte_fam then
				code_retour := '<p>Erreur ! Vous ne pouvez pas voler les familiers d''un des persos de votre compte !';
				return code_retour;
			end if;
		end if;
	end if;
	select into compt lieu_cod
		from lieu,lieu_position
		where lpos_pos_cod = pos_per2
		and lpos_lieu_cod = lieu_cod
		and lieu_refuge = 'O';
	if found then
		code_retour := '<p>Erreur ! La cible est sur un lieu prot&#233;g&#233; !';
		return code_retour;
	end if;
/****************************************************/
/* debut des controles li&#233;s aux combats de groupe   */
/****************************************************/

-- Les locks du voleurs donneront lieu &#224; des malus ou une impossiblit&#233; de voler.
	select into nb_lock_d count(lock_cod)
			from lock_combat
			where lock_cible = v_attaquant;
	select into nb_lock_o count(lock_cod)
			from lock_combat
			where lock_attaquant = v_attaquant;
-- les locks de la cible donneront lieu &#224; des malus ou impossibilit&#233; de voler.
	select into nb_lock_d_cible count(lock_cod)
			from lock_combat
			where lock_cible = v_cible;
	select into nb_lock_o_cible count(lock_cod)
			from lock_combat
			where lock_attaquant = v_cible;

/*******************************************************/
/* fin des contr&#244;les li&#233;s aux combats de groupe        */
/*******************************************************/
/*************************************************/
/* Etape 3 : on v&#233;rifie qu il y ait assez de pa  */
/*************************************************/
	if pa < v_cout_pa then
		code_retour := '<p>Erreur ! Pas assez de PA pour effectuer cette action';
		return code_retour;
	end if;
/*************************************************/
/* Etape 4 : on v&#233;rifie la distance d attaque    */
/*************************************************/
	if pos_per1 != pos_per2 then
		code_retour := '<p>Erreur ! La cible est trop &#233;loign&#233;e du voleur';
		return code_retour;
	end if;

/*************************************/
/* Etape 6 : les controles sont bons */
/*     On passe &#224; l attaque          */
/*************************************/

--  enleve les pa
	update perso
		set perso_pa = pa - v_cout_pa
		where perso_cod = v_attaquant;

-- valeur de la competence de base
		select into comp_vol,num_comp
			pcomp_modificateur,pcomp_pcomp_cod
			from perso_competences
			where pcomp_perso_cod = v_attaquant
			and pcomp_pcomp_cod = 86;
		if not found then
			code_retour := '<p>Erreur ! Vous n''avez la comp&#233;tence requise pour voler !<br>';
			return code_retour;
		end if;
	comp_vol_init := comp_vol;
-- Bonus-Malus - 1 - Concentration
	select into compt concentration_perso_cod from concentrations
		where concentration_perso_cod = v_attaquant;
	if found then
		comp_vol_modifie := comp_vol + 20;
		delete from concentrations where concentration_perso_cod = v_attaquant;
		code_retour := code_retour||'Votre concentration augmente vos chances de r&#233;ussite: '||malus_type_cible||'%<br>';
	else
		comp_vol_modifie := comp_vol;
	end if;
-- Bonus-Malus - 2 - Type de cible (malus en cas de monstre ou familier)
	if type_cible != 1 then
		malus_type_cible :=  -3 * v_niveau_cible;
	    if malus_type_cible > - malus_monstre then
			malus_type_cible := - malus_monstre;
		end if;
		comp_vol_modifie := comp_vol_modifie + malus_type_cible;
		code_retour := code_retour||'Vos chances sont r&#233;duites en attaquant un monstre: '||malus_type_cible||'%<br>';
	end if;
-- Bonus-Malus - 3 - Locks de combat.
	malus_lock_a := (nb_lock_d + nb_lock_o) * -1 * malus_combat;
	if malus_lock_a != 0 then
		comp_vol_modifie := comp_vol_modifie + malus_lock_a;
		code_retour := code_retour||'Vous &#234;tes en combat vos chances de r&#233;ussite sont diminu&#233;es: '||malus_lock_a||'%<br>';
	end if;
	malus_lock_d := (nb_lock_d_cible + nb_lock_o_cible) * -1 * malus_combat;
	if malus_lock_a != 0 then
		comp_vol_modifie := comp_vol_modifie + malus_lock_d;
		code_retour := code_retour||'Votre cible est en plein combat vos chances de r&#233;ussite sont diminu&#233;es: '||malus_lock_d||'%<br>';
	end if;
-- Bonus-Malus - 4 - Sorts.
	comp_vol_modifie := comp_vol_modifie + valeur_bonus(v_attaquant, 'VOL');

-- Bonus-Malus - 5 - Minimum de 10%
	if comp_vol_modifie < 10 then
		comp_vol_modifie := 10;
	end if;
-- limite pour un coup sp&#233;cial
	limite_comp_maitre := round(comp_vol_modifie*0.25);
-- comp pour la detection
	comp_vol_detection := round(comp_vol_modifie*0.30);
	if num_comp = 85 then
	-- niveau 2
		comp_vol_detection := round(comp_vol_modifie*0.60);
	end if;
	if num_comp = 86 then
	-- niveau 3
		comp_vol_detection := round(comp_vol_modifie*0.80);
	end if;
	comp_vol_detection := comp_vol_detection - v_dex_cible - v_int_cible + v_dex_voleur + v_int_voleur;
	--
	select into v_comp_vol_cible
			pcomp_modificateur,pcomp_pcomp_cod
			from perso_competences
			where pcomp_perso_cod = v_cible
			and pcomp_pcomp_cod IN(84,85,86);
	comp_vol_detection := comp_vol_detection - (v_comp_vol_cible / 5);

---------------------------------------------------------------------------
-- etape 5.2 : on commence &#224; g&#233;n&#233;rer un code retour
   	res_succes := 0;
   	res_amelioration := 0;
   	res_vu := 1;

	code_retour := code_retour||'<br>Vous tentez de voler le ';
	if type_cible = 1 then
		code_retour := code_retour||'joueur ';
	else
		code_retour := code_retour||'monstre ';
	end if;
	code_retour := code_retour||' <b>'||nom_per2||'</b><br><br>'; -- pos 2
	select into nom_competence comp_libelle from competences
		where comp_cod = num_comp;
	code_retour := code_retour||'Vous avez utilis&#233; la comp&#233;tence <b>'||nom_competence;
	code_retour := code_retour||'</b> (chance de r&#233;ussite en tenant compte des modificateurs :<b>'||trim(to_char(comp_vol_modifie,'999'))||'</b> %)<br>';

-- etape 5.3 : on regarde si l attaque a r&#233;ussi
	des := lancer_des(1,100);
	code_retour := code_retour||'Votre lancer de d&#233;s est de <b>'||trim(to_char(des,'999'))||'</b>, '; -- pos 5 lancer des
	if des > 96 then -- echec critique
		code_retour := code_retour||'il s''agit donc d''un &#233;chec automatique.<br><br>';
		-- INSERTION DU TITRE
		temp_texte_titre :='Voleur pas tr&#232;s dou&#233;';
		select into compt ptitre_perso_cod from  perso_titre
		where ptitre_perso_cod = v_attaquant and ptitre_titre = temp_texte_titre;
		if not found then
			values(v_attaquant,temp_texte_titre,now());
		end if;
	elsif ((des > 5) and (des > limite_comp_maitre) and (des > comp_vol_modifie)) then
		code_retour := code_retour||'il s''agit donc d''un &#233;chec.<br><br>';
		if comp_vol_init <= getparm_n(1) then
			res_amelioration := 1;
		end if;
	elsif ((des > 5) and (des > limite_comp_maitre) and (des <= comp_vol_modifie)) then
		code_retour := code_retour||'il s''agit donc d''une r&#233;ussite.<br><br>';
		res_succes := 1;
   		res_amelioration := 1;
	elsif ((des > 5) and (des <= limite_comp_maitre)) then
		code_retour := code_retour||'il s''agit donc d''une r&#233;ussite sp&#233;ciale.<br><br>';
		res_succes := 1;
   		res_amelioration := 1;
	elsif (des <= 5) then
		code_retour := code_retour||'il s''agit donc d''une r&#233;ussite critique.<br><br>';
		res_succes := 1;
   		res_amelioration := 1;
	end if;
	-- TRANSFERT DE L'OBJET
	v_poids_objet := 0;
	if res_succes > 0 then
		-- Selection de l'objet
		select into compt count(obj_cod)as num from objets, perso_objets
		  where perobj_obj_cod = obj_cod
		  and perobj_perso_cod = v_cible
		  and perobj_equipe <> 'O'
		  and obj_poids <= 2
		  and not exists (select 1 from perso_glyphes -- Bleda 30/01/11 : Glyphes
		  		  where pglyphe_perso_cod = v_attaquant
		  		  and pglyphe_obj_cod = obj_cod);
	        if compt < 1 then
		  		code_retour := code_retour||'Dommage, la cible n''a aucun petit objet dans son sac !<br><br> ';
		  		v_nom_objet := 'rien du tout';
            else
			  des := lancer_des(1,compt)-1;
			  select into v_num_objet,v_nom_objet,v_poids_objet obj_cod,obj_nom,obj_poids from objets, perso_objets
				where perobj_obj_cod = obj_cod
		  		and perobj_perso_cod = v_cible
		 		and perobj_equipe <> 'O'
		  		and obj_poids <= 2
				offset des limit 1;
              update perso_objets set perobj_perso_cod = v_attaquant
                where perobj_obj_cod = v_num_objet;
              px_gagne := px_gagne + 0.33;
			  code_retour := code_retour||'Vous d&#233;robez l''objet <b>'||v_nom_objet||'</b><br><br> ';
            end if;
	end if;
	--code_retour := code_retour||'Poids='||v_poids_objet||'<br>';
	comp_vol_detection := round(comp_vol_detection - (v_poids_objet *10));

	-- VU OU PAS ?
	if res_succes > 0 then
		code_retour := code_retour||'Chances de ne pas &#234;tre vu en tenant compte des modificateurs :<b>'||trim(to_char(comp_vol_detection,'999'))||'</b> %)<br>';
		des := lancer_des(1,100);
		code_retour := code_retour||'Votre lancer de d&#233;s est de <b>'||trim(to_char(des,'999'))||'</b>, ';
		if des > comp_vol_detection then
			code_retour := code_retour||'La cible a vu qui &#233;tait le voleur.<br><br>';
			res_vu := 1;
		else
			code_retour := code_retour||'La cible n''a pas pu voir qui &#233;tait le voleur.<br><br>';
			res_vu := 0;
		end if;
	end if;

	-- AMELIORATION
	if res_amelioration > 0 then
		temp_ameliore_competence := ameliore_competence_px(v_attaquant,num_comp,comp_vol_init);
		code_retour := code_retour||'Votre jet d''am&#233;lioration est de '||split_part(temp_ameliore_competence,';',1)||', '; -- pos 7 8 9 10
		if split_part(temp_ameliore_competence,';',2) = '1' then
			code_retour := code_retour||'vous avez donc <b>am&#233;lior&#233;</b> cette comp&#233;tence.<br> ';
			code_retour := code_retour||'Sa nouvelle valeur est '||split_part(temp_ameliore_competence,';',3)||'<br><br>';
			px_gagne := px_gagne + 1;
		else
			code_retour := code_retour||'vous n''avez pas am&#233;lior&#233; cette comp&#233;tence.<br><br> ';
		end if;
	end if;

	-- EVENEMENTS
	if res_succes > 0 then
		if res_vu > 0 then
			-- VU
			texte_evt := '[attaquant] a vol&#233; '||v_nom_objet||' &#224; [cible] qui s''en est aper&#231;u';
			texte_evt_bis := '[attaquant] a vol&#233; '||v_nom_objet||' &#224; [cible] qui s''en est aper&#231;u';
			-- INSERTION DU LOCK
			if type_attaquant != 3 then
				if type_cible != 3 then
					delete from lock_combat where lock_attaquant = v_attaquant and lock_cible = v_cible;
						values (nextval('seq_lock_cod'),v_attaquant,v_cible,getparm_n(17));
					end if;
			end if;
		else
			texte_evt := '[attaquant] a vol&#233; '||v_nom_objet||' &#224; [cible] en toute discr&#233;tion';
			texte_evt_bis := 'un inconnu a vol&#233; '||v_nom_objet||' &#224; [cible] en toute discr&#233;tion';
		end if;
	else
		if res_vu > 0 then
		  texte_evt := '[attaquant] a rat&#233; un vol sur [cible]';
		  texte_evt_bis := '[attaquant] a rat&#233; un vol sur [cible]';
    else
      texte_evt := '[attaquant] a rat&#233; un vol sur [cible]';
		  texte_evt_bis := 'un inconnu a rat&#233; un vol sur [cible]';
    end if;
	end if;
		values(nextval('seq_levt_cod'),55,now(),1,v_attaquant,texte_evt,'O','N',v_attaquant,v_cible);
		values(nextval('seq_levt_cod'),55,now(),1,v_cible,texte_evt_bis,'N','N',v_attaquant,v_cible);
	-- XP
	if px_gagne is null then
		px_gagne := 0.0;
	end if;
	update perso
	set perso_px = perso_px + px_gagne, perso_kharma = perso_kharma - 0.1
	where perso_cod = v_attaquant;
	code_retour := code_retour||'Vous gagnez '||to_char(px_gagne,'999999990D99')||' PX pour cette action.';

	return code_retour;
end;$_$;


ALTER FUNCTION public.vol_objet2(integer, integer, integer) OWNER TO delain;

--
-- Name: vote_revolution(integer, integer, text); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vote_revolution(integer, integer, text) RETURNS text
    LANGUAGE plpgsql
    AS $_$/**********************************************************/
/* fonction vote_revolution : enregistre un vote dans une */
/*   revolution de guilde                                 */
/* on passe en paramètres :                               */
/*   $1 = le perso_cod du votant                          */
/*   $2 = le revguilde_cod de la révolution               */
/*   $3 = le vote                                         */
/* on a en sortie une chaine html utilisable dans la page */
/*   action.php                                           */
/**********************************************************/
/* créé le vendredi 13/02/2004                            */
/* 18/01/2007 Blade : rajout d'un titre à l'expulsion     */
/**********************************************************/
declare
------------------------------------------------------------
-- variables du votant
------------------------------------------------------------
	votant alias for $1;				-- perso_cod du votant
	vote alias for $3;				-- vote à prendre en compte
	v_guilde integer;					-- guilde du votant
------------------------------------------------------------
-- variables de la guilde
------------------------------------------------------------
	code_revolution alias for $2;	-- code révolution
	v_guilde_revolution integer;	-- guilde de la révolution
	nom_guilde text; 			-- nom de la guilde en révolution
	nom_cible text;					-- nom de la cible
	code_cible integer;				-- perso_cod de la cible
	nom_lanceur text;					-- nom du lanceur
	code_lanceur integer;			-- perso_cod du lanceur
------------------------------------------------------------
-- variables de contrôle et de retour
------------------------------------------------------------
	code_retour text;					-- texte de retour
	temp integer;						-- fourre tout
	nb_oui integer;					-- nombre de oui
	taux_oui numeric;					-- taux de oui
	nb_non integer;					-- nombre de non
	taux_non numeric;					-- taux de non
	nb_membre integer;				-- nombre de membres
	limite_oui integer;				-- nombre de oui à atteindre
	limite_non integer;				-- nombre de non à atteindre
	code_message integer;			-- numéro des messages envoyés
	titre_message text;				-- Titre du message
	corps_message text;				-- corps du message
	liste_membres record;			-- liste des membres de la guilde
	score_oui integer;
	score_non integer;
	v_renommee numeric;				-- variation de renommee
begin
------------------------------------------------------------
-- on contrôle tout ce qu'on nous a donné
------------------------------------------------------------
	select into temp perso_cod from perso
		where perso_cod = votant;
	if not found then
		code_retour := '<p>Erreur ! Votant non trouvé !';
		return code_retour;
	end if;
	select into v_guilde,nom_guilde pguilde_guilde_cod,guilde_nom
		from guilde_perso,guilde
		where pguilde_perso_cod = votant
		and pguilde_valide = 'O'
		and guilde_cod = pguilde_guilde_cod;
	if not found then
		code_retour := '<p>Erreur ! Le votant n''appartient pas à une guilde !';
		return code_retour;
	end if;
	select into v_guilde_revolution revguilde_guilde_cod
		from guilde_revolution
		where revguilde_cod = code_revolution;
	if not found then
		code_retour := '<p>Erreur ! Pas de révolution trouvée !';
		return code_retour;
	end if;
	if v_guilde != v_guilde_revolution then
		code_retour := '<p>Erreur ! Le votant ne fait pas partie de la guilde en révolution !';
		return code_retour;
	end if;
	select into nom_lanceur,code_lanceur perso_nom,perso_cod from perso,guilde_revolution
		where revguilde_cod = code_revolution
		and perso_cod = revguilde_lanceur;
	select into nom_cible,code_cible perso_nom,perso_cod from perso,guilde_revolution
		where revguilde_cod = code_revolution
		and perso_cod = revguilde_cible;
------------------------------------------------------------
-- Tout semble bon, on enregistre le vote
------------------------------------------------------------
------------------------------------------------------------
-- on prend les résultats
------------------------------------------------------------
	select into nb_oui count(vrevguilde_cod)
		from guilde_revolution_vote
		where vrevguilde_revguilde_cod = code_revolution
		and vrevguilde_vote = 'O';
	select into nb_non count(vrevguilde_cod)
		from guilde_revolution_vote
		where vrevguilde_revguilde_cod = code_revolution
		and vrevguilde_vote = 'N';
	select into nb_membre count(perso_cod)
       FROM guilde_perso, perso
       WHERE pguilde_guilde_cod = v_guilde
       AND pguilde_perso_cod = perso_cod
       AND pguilde_valide = 'O'
       AND perso_actif = 'O'
       AND perso_type_perso = 1;
    limite_oui := round(nb_membre * getparm_n(35) / 100);
    limite_non := round(nb_membre * (100 - getparm_n(35)) / 100);
       score_oui := getparm_n(35);
       score_non := 100 - getparm_n(35);
   if nb_oui > limite_oui then
-----------------------------------------------------------
-- Le OUI a gagné !
------------------------------------------------------------
--	1° on envoie un message de soutien au pauvre admin.....
		code_message := nextval('seq_msg_cod');
		titre_message := 'Révolution : résultat';
		corps_message := 'La révolution menée par '||nom_lanceur||' à votre encontre à malheureusement abouti.<br>';
		corps_message := corps_message||'Vous avez perdu cette partie de bras de fer, et vous êtes banni de votre propre guilde.<br>';
		corps_message := corps_message||'Mais ne désespérez pas, vous retrouverez certainement '||nom_lanceur||' sur votre route, et vous aurez l''occasion de vous venger.';
-- On rajoute un titre
		nom_guilde := '[Ancien Administrateur de la guilde '||nom_guilde||', exclu suite à une révolution]';
-- 2° on le vire méchamment de la guilde
		delete from guilde_perso where pguilde_perso_cod = code_cible;
-- 3° on prévient le lanceur de la révolution
		code_message := nextval('seq_msg_cod');
		titre_message := 'Révolution : résultat';
		corps_message := 'La révolution menée contre '||nom_cible||' a abouti.<br>';
		corps_message := corps_message||'Vous avez gagné cette partie de bras de fer, et '||nom_cible||' a été banni de sa propre guilde.<br>';
		corps_message := corps_message||'De plus, vous avez été promu administrateur de la guilde.';
-- 4° on le met en admin
		update guilde_perso
			set pguilde_rang_cod = 0
			where pguilde_perso_cod = code_lanceur;
-- 5° on prévient quand même par acquis de conscience tous les membres de la guilde
		code_message := nextval('seq_msg_cod');
		titre_message := 'Révolution : résultat';
		corps_message := 'La révolution menée par '||nom_lanceur||' contre '||nom_cible||' a abouti.<br>';
		corps_message := corps_message||nom_lanceur||' a gagné et '||nom_cible||' a été banni de sa propre guilde.';
		for liste_membres in
			select perso_cod
			from guilde_perso,perso
			where pguilde_guilde_cod = v_guilde
			and pguilde_perso_cod = perso_cod
			and pguilde_valide = 'O'
			and perso_actif = 'O'
			and perso_type_perso = 1
			and perso_cod != code_cible loop
		end loop;
-- 6° on génère quand même un code retour
		code_retour := '<p>Votre compte a bien été pris en compte, et il a fait pencher la bascule du côté des frondeurs !<br>';
		code_retour := code_retour||nom_cible||' a été renvoyé de la guilde !';
-- 7° on efface la révolution en cours
		delete from guilde_revolution_vote
			where vrevguilde_revguilde_cod = code_revolution;
		delete from guilde_revolution
			where revguilde_cod = code_revolution;
-- 8 ° on met à jour la renommee
		v_renommee := nb_oui/10;
		if v_renommee > 2 then
			v_renommee := 2;
		end if;
		update perso set perso_renommee = perso_renommee - v_renommee where perso_cod = code_cible;
		update perso set perso_renommee = perso_renommee + v_renommee where perso_cod = code_lanceur;
		return code_retour;
	end if;
	if nb_non >= limite_non then
-----------------------------------------------------------
-- Le NON a gagné !
------------------------------------------------------------
--	1° on envoie un message de soutien au pauvre frondeur.....
		code_message := nextval('seq_msg_cod');
		titre_message := 'Révolution : résultat';
		corps_message := 'La révolution que vous avez mené a lamentablement échoué.<br>';
		corps_message := corps_message||'Vous avez perdu cette partie de bras de fer, et vous êtes banni de votre propre guilde.<br>';
		corps_message := corps_message||'Mais ne désespérez pas, vous retrouverez certainement '||nom_cible||' sur votre route, et vous aurez l''occasion de vous venger.';
-- On rajoute un titre
		nom_guilde := '[Ancien membre de la guilde '||nom_guilde||', exclu suite à une révolution]';
-- 2° on le vire méchamment de la guilde
		delete from guilde_perso where pguilde_perso_cod = code_lanceur;
-- 3° on prévient la cible de la révolution
		code_message := nextval('seq_msg_cod');
		titre_message := 'Révolution : résultat';
		corps_message := 'La révolution menée par '||nom_lanceur||' a échoué.<br>';
		corps_message := corps_message||'De ce fait, '||nom_lanceur||' a été banni de sa guilde.<br>';
-- 5° on prévient quand même par acquis de conscience tous les membres de la guilde
		code_message := nextval('seq_msg_cod');
		titre_message := 'Révolution : résultat';
		corps_message := 'La révolution menée par '||nom_lanceur||' contre '||nom_cible||' a échoué.<br>';
		corps_message := corps_message||nom_lanceur||' a perdu et a été banni de sa propre guilde.';
		for liste_membres in
			select perso_cod
			from guilde_perso,perso
			where pguilde_guilde_cod = v_guilde
			and pguilde_perso_cod = perso_cod
			and pguilde_valide = 'O'
			and perso_actif = 'O'
			and perso_type_perso = 1
			and perso_cod != code_lanceur loop
		end loop;
-- 6° on génère quand même un code retour
		code_retour := '<p>Votre compte a bien été pris en compte, et il a fait pencher la bascule du côté de '||nom_cible||' !<br>';
		code_retour := code_retour||nom_lanceur||' a été renvoyé de la guilde !';
-- 7° on efface la révolution en cours
		delete from guilde_revolution_vote
			where vrevguilde_revguilde_cod = code_revolution;
		delete from guilde_revolution
			where revguilde_cod = code_revolution;
-- 8 ° on met à jour la renommee
		v_renommee := nb_oui/10;
		if v_renommee > 2 then
			v_renommee := 2;
		end if;
		update perso set perso_renommee = perso_renommee + v_renommee where perso_cod = code_cible;
		update perso set perso_renommee = perso_renommee - v_renommee where perso_cod = code_lanceur;
		return code_retour;

	end if;
-----------------------------------------------------------
-- Pas de bascule
------------------------------------------------------------
	code_retour := '<p>Votre vote a bien été pris en compte, mais n''a pas été suffisant pour faire pencher la balance d''un côté ou de l''autre.';
	return code_retour;
end;
$_$;


ALTER FUNCTION public.vote_revolution(integer, integer, text) OWNER TO delain;

--
-- Name: vue_etage(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vue_etage(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vue_etage :Procédure de détermination de la zone     */
/*                        de vue d un etage                      */
/* On passe en paramètres                                        */
/*    $1 = etage ciblé                                           */
/* En sortie, on a une chaine formatée des pos_cod séparés par   */
/* des virgules (utilisable dans php)                            */
/* La forme est :                                                */
/* pos1,x1,y0,distance,vue;pos2x1,y1,vue                         */
/* Les infos dans chaque positions sont séparées par ,           */
/* Les positions dans la même ligne sont séparées par des @      */
/* Les "lignes" de x sont séparées par #                         */
/* la vue est :                                                  */
/*    -1 : hors limite                                           */
/*   999 : un mur....                                            */
/*     0 : rien                                                  */
/*     1 : au moins un joueur                                    */
/*     2 : au moins un monstre                                   */
/*     4 : au moins un objet                                     */
/*     8 : au moins un site                                      */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications :                                     */
/*****************************************************************/
declare
	texte_retour text; -- sert de code retour
	temp_texte text;
	temp_x integer;
	temp_y integer;
	temp_calcul integer;
	etage alias for $1;
	ligne_pos record;
	temp_distance integer;
	trouve_objet integer;
	v_type_mur integer;
	nb_perso integer;
	nb_monstre integer;

begin
	temp_y := -2000;
	texte_retour := '';
	for ligne_pos in select pos_cod,pos_x,pos_y from positions
		where pos_etage = etage
		order by pos_y desc,pos_x asc	loop
		if temp_y = ligne_pos.pos_y then -- on est toujours sur le même y
			temp_texte := '@';
		else    -- if temp_y = ligne_pos.pos_y
			if temp_y != -2000 then
				temp_texte := '#';
				temp_y := ligne_pos.pos_y;
			else
				temp_texte := '';
				temp_y := ligne_pos.pos_y;
			end if;
		end if; --	if temp_x = ligne_pos.pos_x
		temp_calcul := 0;
		temp_texte := temp_texte||to_char(ligne_pos.pos_cod,'9999999')||','||to_char(ligne_pos.pos_x,'9999')||',';
		temp_texte := temp_texte||to_char(ligne_pos.pos_y,'9999')||',';
		/* calcul pour la distance */
		temp_texte := temp_texte||to_char(0,'999')||',';
/**************************************/
/* On calcule pour les perso visibles */
/**************************************/
		select into nb_perso count(perso_cod)
			from perso_position,perso
			where ppos_pos_cod = ligne_pos.pos_cod
			and ppos_perso_cod = perso_cod
			and perso_actif = 'O' and perso_type_perso = 1;
		if nb_perso != 0 then
			temp_calcul := temp_calcul + 1;
		end if; -- if exists pour perso
/*****************************************/
/* On calcule pour les monstres visibles */
/*****************************************/
		select into nb_monstre count(perso_cod)
			from perso_position,perso
			where ppos_pos_cod = ligne_pos.pos_cod
			and ppos_perso_cod = perso_cod
			and perso_actif = 'O' and perso_type_perso = 2;
		if nb_monstre != 0 then
			temp_calcul := temp_calcul + 2;
		end if; -- if exists pour monstre
/*****************************/
/* On calcule pour les sites */
/*****************************/
		if exists (select 1 from lieu_position
			where lpos_pos_cod = ligne_pos.pos_cod) then
			temp_calcul := temp_calcul + 8;
		end if; -- if exists pour monstre
/***************************************/
/* On calcule pour les objets visibles */
/***************************************/
		trouve_objet := 0;
		if exists (select 1 from objet_position
			where pobj_pos_cod = ligne_pos.pos_cod) then
			temp_calcul := temp_calcul + 4;
			trouve_objet := 1;
		end if; -- if exists pour objet
		if exists (select 1 from or_position where por_pos_cod = ligne_pos.pos_cod) then
			if (trouve_objet = 0) then
				temp_calcul := temp_calcul + 4;
				trouve_objet := 1;
			end if;  -- if exists pour or
		end if ;		-- if trouve_objet = 0
/********************************/
/* On calcule ici pour les murs */
/********************************/
		if exists (select 1 from murs where mur_pos_cod = ligne_pos.pos_cod) then
			select into v_type_mur mur_type from murs
				where mur_pos_cod = ligne_pos.pos_cod;
			temp_calcul := v_type_mur;
		end if;		-- if exists pour mur
		/***************************************************/
		/* On rajoutera plus tard ici le calcul pour les   */
		/* montres, lieux à rajouter dans                  */
		/* temp_calcul                                     */
		/***************************************************/
		temp_texte := temp_texte||to_char(temp_calcul,'999');
		temp_texte := temp_texte||','||trim(to_char(nb_perso,'999999'))||','||trim(to_char(nb_monstre,'999999'))||',';
		texte_retour := texte_retour||temp_texte;
	end loop;
return texte_retour;
end;


$_$;


ALTER FUNCTION public.vue_etage(integer) OWNER TO delain;

--
-- Name: vue_etage2(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vue_etage2(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vue_perso :Procédure de détermination de la zone     */
/*                        de vue du personnage                   */
/* On passe en paramètres                                        */
/*    $1 = etage                                                 */
/* En sortie, on a la chaine exploitable par JS                  */
/*		ordre de sortie :                                          */
/*		1 - position                                               */
/*    2 - X                                                      */
/*    3 - Y                                                      */
/*    4 - Nb persos                                              */
/*    5 - Nb monstres                                            */
/*    6 - Type affichage                                         */
/*    7 - Objets                                                 */
/*    8 - Or                                                     */
/*    9 - Distance                                               */
/*   10 - Type mur                                               */
/*   11 - Type case                                              */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications : 19/01/2004 : adaptation pour JS     */
/*****************************************************************/
declare
	ligne record;
	personnage alias for $1;
	texte_retour text;
	nb_monstre integer;
	cpt integer;
	position_actuelle integer;
	x_actuel integer;
	y_actuel integer;
	etage_actuel integer;
	d_vue integer;
	nb_objet integer;
	nb_or integer;
	nb_joueur integer;
	v_dauto_valeur integer;
	v_dauto_type_bat integer;
	v_dauto_vue integer;

begin
	texte_retour := '';
	cpt := 0;
	for ligne in SELECT 	pos_cod,
			pos_x,
			pos_y,
			pos_etage,
			pos_type_aff
	FROM 	positions
	where pos_etage = personnage
	ORDER BY pos_y desc,pos_x asc loop
		select into v_dauto_valeur,v_dauto_type_bat,v_dauto_vue
			dauto_valeur,dauto_type_bat,dauto_vue
			from donnees_automap
			where dauto_pos_cod = ligne.pos_cod;

		select into nb_objet count(distinct(pobj_cod)) from objet_position
				where pobj_pos_cod = ligne.pos_cod;
		select into nb_or count(distinct(por_cod)) from or_position
				where por_pos_cod = ligne.pos_cod;
		select into nb_joueur COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 1
				and perso_actif != 'N';
		select into nb_monstre COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 2
				and perso_actif != 'N';
		texte_retour := texte_retour||'carte['''||trim(to_char(cpt,'999999'))||''']=';
		texte_retour := texte_retour||'['''||trim(to_char(ligne.pos_cod,'999999'))||''','''; -- position
		texte_retour := texte_retour||trim(to_char(ligne.pos_x,'999999'))||''','''; -- X
		texte_retour := texte_retour||trim(to_char(ligne.pos_y,'999999'))||''','''; -- Y
		texte_retour := texte_retour||trim(to_char(nb_joueur,'999999'))||''',''';  -- nb persos
		texte_retour := texte_retour||trim(to_char(nb_monstre,'9999999'))||''',''';  -- nb monstre
		texte_retour := texte_retour||trim(to_char(v_dauto_valeur,'999999'))||''','''; -- type affichage
		texte_retour := texte_retour||trim(to_char(nb_objet,'999999'))||''','''; -- objets
		texte_retour := texte_retour||trim(to_char(nb_or,'999999'))||''','''; -- or
		texte_retour := texte_retour||'1'||''','''; -- distance
		texte_retour := texte_retour||trim(to_char(v_dauto_vue,'999999'))||''','''; -- type mur
		texte_retour := texte_retour||trim(to_char(ligne.pos_type_aff,'999999'))||''','''; -- type case
		texte_retour := texte_retour||trim(to_char(v_dauto_type_bat,'999999'))||'''];'; -- type case
		texte_retour := texte_retour||E'\r\n';
		cpt := cpt + 1;

	end loop;




return texte_retour;
end;


$_$;


ALTER FUNCTION public.vue_etage2(integer) OWNER TO delain;

--
-- Name: vue_etage2(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vue_etage2(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vue_perso :Procédure de détermination de la zone     */
/*                        de vue du personnage                   */
/* On passe en paramètres                                        */
/*    $1 = etage                                                 */
/* En sortie, on a la chaine exploitable par JS                  */
/*		ordre de sortie :                                          */
/*		1 - position                                               */
/*    2 - X                                                      */
/*    3 - Y                                                      */
/*    4 - Nb persos                                              */
/*    5 - Nb monstres                                            */
/*    6 - Type affichage                                         */
/*    7 - Objets                                                 */
/*    8 - Or                                                     */
/*    9 - Distance                                               */
/*   10 - Type mur                                               */
/*   11 - Type case                                              */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications : 19/01/2004 : adaptation pour JS     */
/*****************************************************************/
declare
	ligne record;
	v_etage alias for $1;
	v_ligne alias for $2;
	texte_retour text;
	nb_monstre integer;
	cpt integer;
	position_actuelle integer;
	x_actuel integer;
	y_actuel integer;
	etage_actuel integer;
	d_vue integer;
	nb_objet integer;
	nb_or integer;
	nb_joueur integer;
	v_dauto_valeur integer;
	v_dauto_type_bat integer;
	v_dauto_vue integer;

begin
	texte_retour := '';
	cpt := 0;
	for ligne in SELECT 	pos_cod,
			pos_x,
			pos_y,
			pos_etage,
			pos_type_aff
	FROM 	positions
	where pos_etage = v_etage
	and pos_y = v_ligne
	ORDER BY pos_y desc,pos_x asc loop
		select into v_dauto_valeur,v_dauto_type_bat,v_dauto_vue
			dauto_valeur,dauto_type_bat,dauto_vue
			from donnees_automap
			where dauto_pos_cod = ligne.pos_cod;

		select into nb_objet count(distinct(pobj_cod)) from objet_position
				where pobj_pos_cod = ligne.pos_cod;
		select into nb_or count(distinct(por_cod)) from or_position
				where por_pos_cod = ligne.pos_cod;
		select into nb_joueur COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 1
				and perso_actif != 'N';
		select into nb_monstre COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 2
				and perso_actif != 'N';
		texte_retour := texte_retour||'carte['''||trim(to_char(cpt,'999999'))||''']=';
		texte_retour := texte_retour||'['||trim(to_char(ligne.pos_cod,'999999'))||','; -- position
		texte_retour := texte_retour||trim(to_char(ligne.pos_x,'999999'))||','; -- X
		texte_retour := texte_retour||trim(to_char(ligne.pos_y,'999999'))||','; -- Y
		texte_retour := texte_retour||trim(to_char(nb_joueur,'999999'))||',';  -- nb persos
		texte_retour := texte_retour||trim(to_char(nb_monstre,'9999999'))||',';  -- nb monstre
		texte_retour := texte_retour||trim(to_char(v_dauto_valeur,'999999'))||','; -- type affichage
		texte_retour := texte_retour||trim(to_char(nb_objet,'999999'))||','; -- objets
		texte_retour := texte_retour||trim(to_char(nb_or,'999999'))||','; -- or
		texte_retour := texte_retour||'1'||','; -- distance
		texte_retour := texte_retour||trim(to_char(v_dauto_vue,'999999'))||','; -- type mur
		texte_retour := texte_retour||trim(to_char(ligne.pos_type_aff,'999999'))||','; -- type case
		texte_retour := texte_retour||trim(to_char(v_dauto_type_bat,'999999'))||'];'; -- type case
		texte_retour := texte_retour||E'\r\n';
		cpt := cpt + 1;

	end loop;




return texte_retour;
end;


$_$;


ALTER FUNCTION public.vue_etage2(integer, integer) OWNER TO delain;

--
-- Name: vue_etage2(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vue_etage2(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vue_perso :Procédure de détermination de la zone     */
/*                        de vue du personnage                   */
/* On passe en paramètres                                        */
/*    $1 = etage                                                 */
/* En sortie, on a la chaine exploitable par JS                  */
/*		ordre de sortie :                                          */
/*		1 - position                                               */
/*    2 - X                                                      */
/*    3 - Y                                                      */
/*    4 - Nb persos                                              */
/*    5 - Nb monstres                                            */
/*    6 - Type affichage                                         */
/*    7 - Objets                                                 */
/*    8 - Or                                                     */
/*    9 - Distance                                               */
/*   10 - Type mur                                               */
/*   11 - Type case                                              */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications : 19/01/2004 : adaptation pour JS     */
/*****************************************************************/
declare
	ligne record;
	v_etage alias for $1;
	v_ligne alias for $2;
	v_debut alias for $3;
	texte_retour text;
	nb_monstre integer;
	cpt integer;
	position_actuelle integer;
	x_actuel integer;
	y_actuel integer;
	etage_actuel integer;
	d_vue integer;
	nb_objet integer;
	nb_or integer;
	nb_joueur integer;
	v_dauto_valeur integer;
	v_dauto_type_bat integer;
	v_dauto_vue integer;
	v_decor integer;

begin
	texte_retour := '';
	cpt := v_debut;
	for ligne in SELECT 	pos_cod,
			pos_x,
			pos_y,
			pos_etage,
			pos_type_aff,
			pos_decor
	FROM 	positions
	where pos_etage = v_etage
	and pos_y = v_ligne
	ORDER BY pos_y desc,pos_x asc loop
		select into v_dauto_valeur,v_dauto_type_bat,v_dauto_vue
			dauto_valeur,dauto_type_bat,dauto_vue
			from donnees_automap
			where dauto_pos_cod = ligne.pos_cod;

		select into nb_objet count(distinct(pobj_cod)) from objet_position
				where pobj_pos_cod = ligne.pos_cod;
		select into nb_or count(distinct(por_cod)) from or_position
				where por_pos_cod = ligne.pos_cod;
		select into nb_joueur COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 1
				and perso_actif != 'N';
		select into nb_monstre COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 2
				and perso_actif != 'N';
		texte_retour := texte_retour||'carte['''||trim(to_char(cpt,'999999'))||''']=';
		texte_retour := texte_retour||'['||trim(to_char(ligne.pos_cod,'999999'))||','; -- position
		texte_retour := texte_retour||trim(to_char(ligne.pos_x,'999999'))||','; -- X
		texte_retour := texte_retour||trim(to_char(ligne.pos_y,'999999'))||','; -- Y
		texte_retour := texte_retour||trim(to_char(nb_joueur,'999999'))||',';  -- nb persos
		texte_retour := texte_retour||trim(to_char(nb_monstre,'9999999'))||',';  -- nb monstre
		texte_retour := texte_retour||trim(to_char(v_dauto_valeur,'999999'))||','; -- type affichage
		texte_retour := texte_retour||trim(to_char(nb_objet,'999999'))||','; -- objets
		texte_retour := texte_retour||trim(to_char(nb_or,'999999'))||','; -- or
		texte_retour := texte_retour||'1'||','; -- distance
		texte_retour := texte_retour||trim(to_char(v_dauto_vue,'999999'))||','; -- type mur
		texte_retour := texte_retour||trim(to_char(ligne.pos_type_aff,'999999'))||','; -- type case
		texte_retour := texte_retour||trim(to_char(v_dauto_type_bat,'999999'))||','; -- type case
		v_decor := 0;
		if ligne.pos_decor is not null then
			v_decor = ligne.pos_decor;
		end if;
		texte_retour := texte_retour||trim(to_char(v_decor,'999999'))||'];'; -- decor
		texte_retour := texte_retour||E'\r\n';
		cpt := cpt + 1;

	end loop;
	texte_retour := texte_retour||'#'||trim(to_char(cpt,'9999999999999'));



return texte_retour;
end;


$_$;


ALTER FUNCTION public.vue_etage2(integer, integer, integer) OWNER TO delain;

--
-- Name: vue_perso3(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vue_perso3(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vue_perso :Procédure de détermination de la zone     */
/*                        de vue du personnage                   */
/* On passe en paramètres                                        */
/*    $1 = perso ciblé                                           */
/* En sortie, on a la chaine exploitable par JS                  */
/*		ordre de sortie :                                          */
/*		1 - position                                               */
/*    2 - X                                                      */
/*    3 - Y                                                      */
/*    4 - Nb persos                                              */
/*    5 - Nb monstres                                            */
/*    6 - Type affichage                                         */
/*    7 - Objets                                                 */
/*    8 - Or                                                     */
/*    9 - Distance                                               */
/*   10 - Type mur                                               */
/*   11 - Type case                                              */
/*	  12 - type batiment                                          */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications : 19/01/2004 : adaptation pour JS     */
/*****************************************************************/
declare
	ligne record;
	personnage alias for $1;
	texte_retour text;
	nb_monstre integer;
	cpt integer;
	position_actuelle integer;
	x_actuel integer;
	y_actuel integer;
	etage_actuel integer;
	d_vue integer;

begin
	texte_retour := '';
	cpt := 0;
	select into x_actuel,y_actuel,etage_actuel,position_actuelle,d_vue
		pos_x,pos_y,pos_etage,pos_cod,distance_vue(personnage)
		from perso_position,positions
		where ppos_perso_cod = personnage
		and ppos_pos_cod = pos_cod;
	for ligne in SELECT 	posfin.pos_cod as pos_cod,
			posfin.pos_x,
			posfin.pos_y,
			posfin.pos_etage,
			posfin.pos_type_aff,
			posfin.pos_decor,
			posfin.pos_decor_dessus,
			automap.dauto_valeur,
			automap.dauto_type_bat,
			automap.dauto_vue,
			(select count(distinct(pobj_cod)) from objet_position
				where pobj_pos_cod = pos_cod) as objet,
			(select count(distinct(por_cod)) from or_position
				where por_pos_cod = pos_cod) as tas_or,
			distance(position_actuelle,posfin.pos_cod) AS distance,
			(select COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = posfin.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 1
				and perso_actif = 'O') as joueur,
			(select COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = posfin.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso in (2,3)
				and perso_actif = 'O') as monstre
	FROM 	positions posfin,
	donnees_automap automap
	where automap.dauto_pos_cod = posfin.pos_cod
	AND posfin.pos_etage = etage_actuel
	and posfin.pos_x between (x_actuel - d_vue) and (x_actuel + d_vue)
	AND posfin.pos_y between (y_actuel - d_vue) and (y_actuel + d_vue)
	ORDER BY pos_y desc,pos_x asc loop
		texte_retour := texte_retour||'tc['''||trim(to_char(cpt,'999999'))||''']=';
		texte_retour := texte_retour||'['||trim(to_char(ligne.pos_cod,'999999'))||','; -- position
		texte_retour := texte_retour||trim(to_char(ligne.pos_x,'999999'))||','; -- X
		texte_retour := texte_retour||trim(to_char(ligne.pos_y,'999999'))||','; -- Y
		texte_retour := texte_retour||trim(to_char(ligne.joueur,'999999'))||',';  -- nb persos
		texte_retour := texte_retour||trim(to_char(ligne.monstre,'9999999'))||',';  -- nb monstre
		texte_retour := texte_retour||trim(to_char(ligne.dauto_valeur,'999999'))||','; -- type affichage
		texte_retour := texte_retour||trim(to_char(ligne.objet,'999999'))||','; -- objets
		texte_retour := texte_retour||trim(to_char(ligne.tas_or,'999999'))||','; -- or
		texte_retour := texte_retour||trim(to_char(ligne.distance,'999999'))||','; -- distance
		texte_retour := texte_retour||trim(to_char(ligne.dauto_vue,'999999'))||','; -- type mur
		texte_retour := texte_retour||trim(to_char(ligne.pos_type_aff,'999999'))||','; -- type case
		texte_retour := texte_retour||trim(to_char(ligne.dauto_type_bat,'999999'))||',';
		texte_retour := texte_retour||trim(to_char(ligne.pos_decor,'999999'))||','; -- decor normal
		texte_retour := texte_retour||trim(to_char(ligne.pos_decor_dessus,'999999'))||'];'; -- decor dessus
		texte_retour := texte_retour||E'\r\n';
		cpt := cpt + 1;

	end loop;




return texte_retour;
end;


$_$;


