CREATE FUNCTION public.vue_perso6(integer) RETURNS SETOF public.type_vue
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vue_perso :Procédure de détermination de la zone     */
/*                        de vue du personnage                   */
/* On passe en paramètres                                        */
/*    $1 = perso ciblé                                           */
/* En sortie, on a la chaine exploitable par JS                  */
/*		ordre de sortie :                                          */
/*		1 - position                                               */
/*    2 - X                                                      */
/*    3 - Y                                                      */
/*    4 - Nb persos                                              */
/*    5 - Nb monstres                                            */
/*    6 - Type affichage                                         */
/*    7 - Objets                                                 */
/*    8 - Or                                                     */
/*    9 - Distance                                               */
/*   10 - Type mur                                               */
/*   11 - Type case                                              */
/*	  12 - type batiment                                          */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications : 19/01/2004 : adaptation pour JS     */
/*****************************************************************/
declare
	ligne record;
	personnage alias for $1;
	texte_retour text;
	nb_monstre integer;
	cpt integer;
	position_actuelle integer;
	x_actuel integer;
	y_actuel integer;
	etage_actuel integer;
	d_vue integer;
	nb_obj integer;
	nb_or integer;
	nb_perso integer;
	retour type_vue%rowtype;

begin
	texte_retour := '';
	cpt := 0;
	select into x_actuel,y_actuel,etage_actuel,position_actuelle,d_vue
		pos_x,pos_y,pos_etage,pos_cod,distance_vue(personnage)
		from perso_position,positions
		where ppos_perso_cod = personnage
		and ppos_pos_cod = pos_cod;
	for ligne in SELECT 	pos_cod,
			pos_x,
			pos_y,
			pos_etage,
			pos_type_aff,
			pos_decor,
			pos_decor_dessus,
			dauto_valeur,
			dauto_type_bat,
			dauto_vue,
			distance(position_actuelle,pos_cod) AS distance,
			trajectoire_vue3(position_actuelle,pos_cod) AS trajectoire
	FROM 	positions,donnees_automap
	where dauto_pos_cod = pos_cod
	AND pos_etage = etage_actuel
	and pos_x between (x_actuel - d_vue) and (x_actuel + d_vue)
	AND pos_y between (y_actuel - d_vue) and (y_actuel + d_vue)
	ORDER BY pos_y desc,pos_x asc loop
		nb_obj := 0;
		nb_or := 0;
		nb_perso := 0;
		nb_monstre := 0;
		if ligne.trajectoire != 0 then
			select into nb_obj count(distinct(pobj_cod)) from objet_position
				where pobj_pos_cod = ligne.pos_cod;
			select into nb_or count(distinct(por_cod)) from or_position
				where por_pos_cod = ligne.pos_cod;
			select into nb_perso COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 1
				and perso_actif = 'O';
			select into nb_monstre COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso in (2,3)
				and perso_actif = 'O';
		end if;
		retour.tvue_num := cpt;
		retour.t_pos_cod := ligne.pos_cod;
		retour.t_x := ligne.pos_x;
		retour.t_y := ligne.pos_y;
		retour.t_nb_perso := nb_perso;
		retour.t_nb_monstre := nb_monstre;
		retour.t_type_aff := ligne.dauto_valeur;
		retour.t_nb_obj := nb_obj;
		retour.t_or := nb_or;
		retour.t_dist := ligne.distance;
		retour.t_type_mur := ligne.dauto_vue;
		retour.t_type_case := ligne.pos_type_aff;
		retour.t_type_bat := ligne.dauto_type_bat;
		retour.t_decor := ligne.pos_decor;
		retour.t_traj := ligne.trajectoire;
		retour.t_decor_dessus := ligne.pos_decor_dessus;
		return next retour;
cpt := cpt + 1;
	end loop;
	return;
end;


$_$;


ALTER FUNCTION public.vue_perso6(integer) OWNER TO delain;


--
-- Name: vue_perso_6_optim(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vue_perso_6_optim(integer) RETURNS SETOF public.type_vue
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vue_perso :Procédure de détermination de la zone     */
/*                        de vue du personnage                   */
/* On passe en paramètres                                        */
/*    $1 = perso ciblé                                           */
/* En sortie, on a la chaine exploitable par JS                  */
/*		ordre de sortie :                                          */
/*		1 - position                                               */
/*    2 - X                                                      */
/*    3 - Y                                                      */
/*    4 - Nb persos                                              */
/*    5 - Nb monstres                                            */
/*    6 - Type affichage                                         */
/*    7 - Objets                                                 */
/*    8 - Or                                                     */
/*    9 - Distance                                               */
/*   10 - Type mur                                               */
/*   11 - Type case                                              */
/*	  12 - type batiment                                          */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications : 19/01/2004 : adaptation pour JS     */
/*****************************************************************/
declare
	ligne record;
	personnage alias for $1;
	nb_monstre integer;
	cpt integer;
	position_actuelle integer;
	x_actuel integer;
	y_actuel integer;
	etage_actuel integer;
	d_vue integer;
	nb_obj integer;
	nb_or integer;
	nb_perso integer;
	retour type_vue%rowtype;

begin
	SELECT into x_actuel, y_actuel, etage_actuel, position_actuelle, d_vue
		pos_x, pos_y, pos_etage, pos_cod, distance_vue(personnage)
	FROM perso_position
	INNER JOIN positions on pos_cod = ppos_pos_cod
	WHERE ppos_perso_cod = personnage;

	-- Cases concernées
	DROP TABLE IF EXISTS temp_cases;
	CREATE TEMP TABLE temp_cases (
		case_numero integer,
		case_pos_cod integer,
		case_pos_x integer,
		case_pos_y integer,
		case_pos_etage integer,
		case_pos_type_aff integer,
		case_pos_decor integer,
		case_pos_decor_dessus integer
	);

	SELECT rank() over (partition by 1 order by pos_y desc, pos_x asc) - 1,
		pos_cod, pos_x, pos_y, pos_etage, pos_type_aff, pos_decor, pos_decor_dessus
	FROM positions
	WHERE pos_x between (x_actuel - d_vue) and (x_actuel + d_vue)
		AND pos_y between (y_actuel - d_vue) and (y_actuel + d_vue)
		AND pos_etage = etage_actuel
	ORDER BY pos_y desc, pos_x asc;

	return query
	SELECT case_numero,
		case_pos_cod,
		case_pos_x,
		case_pos_y,
		coalesce(perso_nombre * traj_ok, 0) as perso_nombre,
		coalesce(monstre_nombre * traj_ok, 0) as monstre_nombre,
		dauto_valeur,
		coalesce(obj_nombre * traj_ok, 0) as obj_nombre,
		coalesce(bzf_nombre * traj_ok, 0) as bzf_nombre,
		distance,
		dauto_vue,
		case_pos_type_aff,
		dauto_type_bat,
		case_pos_decor,
		traj_ok,
		case_pos_decor_dessus
	FROM temp_cases
	INNER JOIN donnees_automap ON dauto_pos_cod = case_pos_cod

	INNER JOIN (
		SELECT case_pos_cod as traj_pos_cod,
			trajectoire_vue3(position_actuelle, case_pos_cod) as traj_ok,
			distance(position_actuelle, case_pos_cod) as distance
		FROM temp_cases
	) traj ON traj_pos_cod = case_pos_cod

	LEFT OUTER JOIN (
		-- Sous-requête brouzoufs
		SELECT por_pos_cod, count(*)::integer as bzf_nombre
		FROM or_position
		INNER JOIN temp_cases on case_pos_cod = por_pos_cod
		GROUP BY por_pos_cod
	) bzf ON por_pos_cod = case_pos_cod

	LEFT OUTER JOIN (
		-- sous-requête objets
		SELECT pobj_pos_cod, count(*)::integer as obj_nombre
		FROM objet_position
		INNER JOIN temp_cases on case_pos_cod = pobj_pos_cod
		GROUP BY pobj_pos_cod
	) obj ON pobj_pos_cod = case_pos_cod

	LEFT OUTER JOIN (
		-- sous-requête perso
		SELECT ppos_pos_cod as perso_pos, count(*)::integer as perso_nombre
		FROM perso_position
		INNER JOIN temp_cases on case_pos_cod = ppos_pos_cod
		INNER JOIN perso on perso_cod = ppos_perso_cod
		WHERE perso_actif = 'O' and perso_type_perso = 1
		GROUP BY ppos_pos_cod
	) per ON perso_pos = case_pos_cod

	LEFT OUTER JOIN (
		-- sous-requête perso
		SELECT ppos_pos_cod as monstre_pos, count(*)::integer as monstre_nombre
		FROM perso_position
		INNER JOIN temp_cases on case_pos_cod = ppos_pos_cod
		INNER JOIN perso on perso_cod = ppos_perso_cod
		WHERE perso_actif = 'O' and perso_type_perso IN (2, 3)
		GROUP BY ppos_pos_cod
	) mon ON monstre_pos = case_pos_cod
	ORDER BY case_pos_y desc, case_pos_x asc;
end;$_$;


ALTER FUNCTION public.vue_perso_6_optim(integer) OWNER TO delain;

--
-- Name: vue_perso_html(integer, text); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vue_perso_html(integer, text) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vue_perso :Procédure de détermination de la zone     */
/*                        de vue du personnage                   */
/* On passe en paramètres                                        */
/*    $1 = perso ciblé                                           */
/* En sortie, on a la chaine exploitable par JS                  */
/*		ordre de sortie :                                          */
/*		1 - position                                               */
/*    2 - X                                                      */
/*    3 - Y                                                      */
/*    4 - Nb persos                                              */
/*    5 - Nb monstres                                            */
/*    6 - Type affichage                                         */
/*    7 - Objets                                                 */
/*    8 - Or                                                     */
/*    9 - Distance                                               */
/*   10 - Type mur                                               */
/*   11 - Type case                                              */
/*	  12 - type batiment                                          */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications : 19/01/2004 : adaptation pour JS     */
/*****************************************************************/
declare
	ligne record;
	personnage alias for $1;
	texte_retour text;
	fin_texte text;
	v_comment text;
	nb_monstre integer;
	cpt integer;
	position_actuelle integer;
	x_actuel integer;
	y_actuel integer;
	etage_actuel integer;
	d_vue integer;
	nb_obj integer;
	nb_or integer;
	nb_perso integer;
	img_path alias for $2;
	y_encours integer;

begin
	y_encours = -2000;
	texte_retour := '';
	cpt := 0;
	select into x_actuel,y_actuel,etage_actuel,position_actuelle,d_vue
		pos_x,pos_y,pos_etage,pos_cod,distance_vue(personnage)
		from perso_position,positions
		where ppos_perso_cod = personnage
		and ppos_pos_cod = pos_cod;
	for ligne in SELECT 	pos_cod,
			pos_x,
			pos_y,
			pos_etage,
			pos_type_aff,
			pos_decor,
			pos_decor_dessus,
			dauto_valeur,
			dauto_type_bat,
			dauto_vue,
			distance(position_actuelle,pos_cod) AS distance,
			trajectoire_vue3(position_actuelle,pos_cod) AS trajectoire
	FROM 	positions,donnees_automap
	where dauto_pos_cod = pos_cod
	AND pos_etage = etage_actuel
	and pos_x between (x_actuel - d_vue) and (x_actuel + d_vue)
	AND pos_y between (y_actuel - d_vue) and (y_actuel + d_vue)
	ORDER BY pos_y desc,pos_x asc loop

	fin_texte := '';
	v_comment := '';
		nb_obj := 0;
		nb_or := 0;
		nb_perso := 0;
		nb_monstre := 0;
		if ligne.trajectoire != 0 then
			select into nb_obj count(distinct(pobj_cod)) from objet_position
				where pobj_pos_cod = ligne.pos_cod;
			select into nb_or count(distinct(por_cod)) from or_position
				where por_pos_cod = ligne.pos_cod;
			select into nb_perso COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 1
				and perso_actif = 'O';
			select into nb_monstre COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso in (2,3)
				and perso_actif = 'O';
		end if;
		if (y_encours != ligne.pos_y) then
			if y_encours != -2000 then
				texte_retour := texte_retour||'</tr>';
			end if;
			texte_retour := texte_retour||'<tr class="vueoff" height="10"><td height="10" class="coord2"><p class="coord">'||trim(to_char(ligne.pos_y,'999999'))||'</p></td>';
			y_encours = ligne.pos_y;
		end if;
		texte_retour := texte_retour||'<td class="v'||trim(to_char(ligne.pos_type_aff,'999999'))||'">';
		if ligne.pos_decor != 0 then
			texte_retour := texte_retour||'<div id="1" class="decor'||trim(to_char(ligne.pos_decor,'999999'))||'">';
			fin_texte := fin_texte||'</div>';
		end if;
		if nb_perso != 0 then
			v_comment := v_comment||trim(to_char(nb_perso,'999999'))||' aventuriers, ';
			texte_retour := texte_retour||'<div id="1" class="joueur">';
			fin_texte := fin_texte||'</div>';
		end if;
		if nb_monstre != 0 then
			v_comment := v_comment||trim(to_char(nb_monstre,'999999'))||' monstres, ';
			texte_retour := texte_retour||'<div id="1" class="monstre">';
			fin_texte := fin_texte||'</div>';
		end if;
		if nb_obj != 0 then
			v_comment := v_comment||trim(to_char(nb_obj,'999999'))||' objets, ';
			texte_retour := texte_retour||'<div id="1" class="objet">';
			fin_texte := fin_texte||'</div>';
		end if;
		if nb_or != 0 then
			v_comment := v_comment||trim(to_char(nb_or,'999999'))||' tas d''or, ';
			if nb_obj = 0 then
				texte_retour := texte_retour||'<div id="1" class="objet">';
				fin_texte := fin_texte||'</div>';
			end if;
		end if;
		if ligne.dauto_valeur = 1 then
			v_comment := v_comment||'1 mur';
			texte_retour := texte_retour||'<div id="1" class="mur_'||trim(to_char(ligne.dauto_vue,'999999'))||'">';
			fin_texte := fin_texte||'</div>';
		end if;
		if ligne.dauto_type_bat != 0 then
			v_comment := v_comment||'1 lieu, ';
			texte_retour := texte_retour||'<div id="1" <div class="lieu'||trim(to_char(ligne.dauto_type_bat,'999999'))||'">';
			fin_texte := fin_texte||'</div>';
		end if;
		if ligne.distance = 0 then
			texte_retour := texte_retour||'<div id="1" class="oncase">';
			fin_texte := fin_texte||'</div>';
		end if;
		texte_retour := texte_retour||'<div id="dep" class="main" onClick="javascript:window.parent.automap.document.det_cadre.position.value='''||trim(to_char(ligne.pos_cod,'999999'))||''';window.parent.automap.document.det_cadre.dist.value='''||trim(to_char(ligne.distance,'999999'))||''';window.parent.automap.document.det_cadre.submit();" title="'||v_comment||'">';
		if ligne.trajectoire = 0 then
			if ligne.dauto_valeur != 1 then
				texte_retour := texte_retour||'<div id="1" class="br">';
				fin_texte := fin_texte||'</div>';
			end if;
		end if;
		if ligne.trajectoire = 1 then
			texte_retour := texte_retour||'<div id="cell2'||trim(to_char(ligne.pos_cod,'999999'))||'">';
			fin_texte := fin_texte||'</div>';
		end if;
		if ligne.pos_decor_dessus != 0 then
			texte_retour := texte_retour||'<div id="1" class="decor'||trim(to_char(ligne.trajectoire,'999999'))||'">';
			fin_texte := fin_texte||'</div>';
		end if;
		texte_retour := texte_retour||'<div id="cell'||trim(to_char(ligne.pos_cod,'999999'))||'" class="pasvu" style="background:url('''||img_path||'c1.gif'')" onClick="javascript:document.deplacement.position.value='''||trim(to_char(ligne.pos_cod,'999999'))||''';document.deplacement.submit();" title="'||v_comment||'">';
		texte_retour := texte_retour||'<img src="'||img_path||'del.gif" width="28" height="28" alt="'||v_comment||'">';
		texte_retour := texte_retour||fin_texte||'</td>';


		/*texte_retour := texte_retour||'tc['''||trim(to_char(cpt,'999999'))||''']=';
		texte_retour := texte_retour||'['||trim(to_char(ligne.pos_cod,'999999'))||','; -- position 0
		texte_retour := texte_retour||trim(to_char(ligne.pos_x,'999999'))||','; -- X 1
		texte_retour := texte_retour||trim(to_char(ligne.pos_y,'999999'))||','; -- Y 2
		texte_retour := texte_retour||trim(to_char(nb_perso,'999999'))||',';  -- nb persos 3
		texte_retour := texte_retour||trim(to_char(nb_monstre,'9999999'))||',';  -- nb monstre 4
		texte_retour := texte_retour||trim(to_char(ligne.dauto_valeur,'999999'))||','; -- type affichage 5
		texte_retour := texte_retour||trim(to_char(nb_obj,'999999'))||','; -- objets 6
		texte_retour := texte_retour||trim(to_char(nb_or,'999999'))||','; -- or 7
		texte_retour := texte_retour||trim(to_char(ligne.distance,'999999'))||','; -- distance 8
		texte_retour := texte_retour||trim(to_char(ligne.dauto_vue,'999999'))||','; -- type mur 9
		texte_retour := texte_retour||trim(to_char(ligne.pos_type_aff,'999999'))||','; -- type case 10
		texte_retour := texte_retour||trim(to_char(ligne.dauto_type_bat,'999999'))||','; 11
		texte_retour := texte_retour||trim(to_char(ligne.pos_decor,'999999'))||','; -- decor normal 12
		texte_retour := texte_retour||trim(to_char(ligne.trajectoire,'999999'))||','; -- trajectoire 13
		texte_retour := texte_retour||trim(to_char(ligne.pos_decor_dessus,'999999'))||'];'; -- decor dessus 14
		texte_retour := texte_retour||E'\r\n';
		cpt := cpt + 1;*/

	end loop;




return texte_retour;
end;


$_$;


ALTER FUNCTION public.vue_perso_html(integer, text) OWNER TO delain;

--
-- Name: vue_perso_limite(integer, integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vue_perso_limite(integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/*****************************************************************/
/* function vue_perso_limite :Procédure de                       */
/*                        de vue du personnage                   */
/* On passe en paramètres                                        */
/*    $1 = perso ciblé                                           */
/*    $2 = limitation_vue                                        */
/* En sortie, on a la chaine exploitable par JS                  */
/*****************************************************************/
/* Créé le 07/03/2003                                            */
/* Liste des modifications : 19/01/2004 : adaptation pour JS     */
/*****************************************************************/
declare
	ligne record;
	personnage alias for $1;
	texte_retour text;
	cpt integer;
	position_actuelle integer;
	x_actuel integer;
	y_actuel integer;
	etage_actuel integer;
	d_vue alias for $2;
	nb_perso integer;
	nb_monstre integer;
	nb_or integer;
	nb_obj integer;

begin
	texte_retour := '';
	cpt := 0;
	select into x_actuel,y_actuel,etage_actuel,position_actuelle
		pos_x,pos_y,pos_etage,pos_cod
		from perso_position,positions
		where ppos_perso_cod = personnage
		and ppos_pos_cod = pos_cod;
	for ligne in SELECT 	pos_cod,
			pos_x,
			pos_y,
			pos_etage,
			pos_type_aff,
			pos_decor,
			pos_decor_dessus,
			dauto_valeur,
			dauto_type_bat,
			dauto_vue,
			distance(position_actuelle,pos_cod) AS distance,
			trajectoire_vue(position_actuelle,pos_cod) AS trajectoire
	FROM 	positions,donnees_automap
	where dauto_pos_cod = pos_cod
	AND pos_etage = etage_actuel
	and pos_x between (x_actuel - d_vue) and (x_actuel + d_vue)
	AND pos_y between (y_actuel - d_vue) and (y_actuel + d_vue)
	ORDER BY pos_y desc,pos_x asc loop
		nb_obj := 0;
		nb_or := 0;
		nb_perso := 0;
		nb_monstre := 0;
		if ligne.trajectoire != 0 then
			select into nb_obj count(distinct(pobj_cod)) from objet_position
				where pobj_pos_cod = ligne.pos_cod;
			select into nb_or count(distinct(por_cod)) from or_position
				where por_pos_cod = ligne.pos_cod;
			select into nb_perso COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso = 1
				and perso_actif = 'O';
			select into nb_monstre COUNT(DISTINCT(perso_cod)) from perso_position,perso
				where ppos_pos_cod = ligne.pos_cod
				and ppos_perso_cod = perso_cod
				and perso_type_perso in (2,3)
				and perso_actif = 'O';
		end if;

		texte_retour := texte_retour||'carte['''||trim(to_char(cpt,'999999'))||''']=';
		texte_retour := texte_retour||'['''||trim(to_char(ligne.pos_cod,'999999'))||''','''; -- position
		texte_retour := texte_retour||trim(to_char(ligne.pos_x,'999999'))||''','''; -- X
		texte_retour := texte_retour||trim(to_char(ligne.pos_y,'999999'))||''','''; -- Y
		texte_retour := texte_retour||trim(to_char(nb_perso,'999999'))||''',''';  -- nb persos
		texte_retour := texte_retour||trim(to_char(nb_monstre,'9999999'))||''',''';  -- nb monstre
		texte_retour := texte_retour||trim(to_char(ligne.dauto_valeur,'999999'))||''','''; -- type affichage
		texte_retour := texte_retour||trim(to_char(nb_obj,'999999'))||''','''; -- objets
		texte_retour := texte_retour||trim(to_char(nb_or,'999999'))||''','''; -- or
		texte_retour := texte_retour||trim(to_char(ligne.distance,'999999'))||''','''; -- distance
		texte_retour := texte_retour||trim(to_char(ligne.dauto_vue,'999999'))||''','''; -- type mur
		texte_retour := texte_retour||trim(to_char(ligne.pos_type_aff,'999999'))||''','''; -- type case
		texte_retour := texte_retour||trim(to_char(ligne.dauto_type_bat,'999999'))||''','; -- type case
		texte_retour := texte_retour||trim(to_char(ligne.pos_decor,'999999'))||','; -- decor normal
		texte_retour := texte_retour||trim(to_char(ligne.trajectoire,'999999'))||','; -- trajectoire
		texte_retour := texte_retour||trim(to_char(ligne.pos_decor_dessus,'999999'))||'];'; -- decor dessus
		texte_retour := texte_retour||e'\r\n';
		cpt := cpt + 1;

	end loop;




return texte_retour;
end;



$_$;


ALTER FUNCTION public.vue_perso_limite(integer, integer) OWNER TO delain;

--
-- Name: vue_pre(integer); Type: FUNCTION; Schema: public; Owner: delain
--

CREATE FUNCTION public.vue_pre(integer) RETURNS text
    LANGUAGE plpgsql STRICT
    AS $_$-- fonction vue_pre : Affiche la vue en mode texte
declare
    ligne record;
    v_perso alias for $1;
    v_pos integer;
    v_x integer;
    v_y integer;
    v_etage integer;
    v_vue integer;
    texte_retour text;
    v_dernier_y integer;
    v_pos_text text; -- Caractère représentant la case

    -- Caractères affichés
    v_aventurier boolean;
    v_murs boolean;
    v_lieux boolean;
    v_brouillard boolean;
    v_monstres boolean;
    v_persos boolean;
    v_melee boolean;
    v_objets boolean;
    v_brouzoufs boolean;


begin
    texte_retour := '<pre style="font-family:monospace;border:1px solid;float:left;">';
    v_dernier_y := 9999;
    -- Caractères affichés
    v_aventurier := false;
    v_murs := false;
    v_lieux := false;
    v_brouillard := false;
    v_monstres := false;
    v_persos := false;
    v_melee := false;
    v_objets := false;
    v_brouzoufs := false;

    select into v_pos, v_etage, v_x, v_y, v_vue
            ppos_pos_cod, pos_etage, pos_x, pos_y, distance_vue(ppos_perso_cod)
        from perso_position, positions
        where ppos_perso_cod = v_perso
        and ppos_pos_cod = pos_cod;
    if not found then
        return 'Position inconnue.';
    end if;

    for ligne in select pos_cod, pos_y, trajectoire_vue3(v_pos, pos_cod) as visible,
            dauto_vue, dauto_type_bat
            from positions, donnees_automap
            where dauto_pos_cod = pos_cod
            and pos_etage = v_etage
            and pos_x between v_x - v_vue and v_x + v_vue
            and pos_y between v_y - v_vue and v_y + v_vue
            order by pos_y desc, pos_x asc loop

        if v_dernier_y != ligne.pos_y then
            -- Nouvelle ligne ?
            texte_retour := texte_retour || e'\r\n';
            v_dernier_y := ligne.pos_y;
        end if;

        if v_pos = ligne.pos_cod then
            -- Perso : @
            texte_retour := texte_retour || '@';
            v_aventurier := true;

        elsif ligne.dauto_vue > 900 then
            -- Mur : #
            texte_retour := texte_retour || '#';
            v_murs := true;

        elsif ligne.dauto_type_bat != 0 then
            -- Bâtiment : ^
            texte_retour := texte_retour || '^';
            v_lieux := true;

        elsif ligne.visible != 1 then
            -- Brouillard de guerre : .
            texte_retour := texte_retour || '.';
            v_brouillard := true;

        else
            -- Position visible: On calcule son affichage
            select into v_pos_text substr(race_nom, 1, 1)
                    from race, perso, perso_position
                    where race_cod = perso_race_cod
                    and perso_cod = ppos_perso_cod
                    and ppos_pos_cod = ligne.pos_cod
                    and perso_type_perso = 2
                    and perso_actif = 'O'
                    order by random() limit 1;
            if not found then
                -- Monstres : Une des races au hasard
                -- Sinon : Rien
                v_pos_text := ' ';
            else
                v_monstres := true;
            end if;
            if exists ( select 1 from perso_position, perso
                   where ppos_perso_cod = perso_cod
                   and ppos_pos_cod = ligne.pos_cod
                   and perso_type_perso != 2
                   and perso_actif = 'O' ) then
                if v_pos_text != ' ' then
                    -- Aventuriers et monstres : %
                    v_pos_text := '%';
                    v_melee := true;
                else
                    -- Aventuriers : %
                    v_pos_text := '°';
                    v_persos := true;
                end if;
            end if;

            if v_pos_text = ' ' then
                -- Pas d''êtres vivants: On regarde les objets
                select into v_pos_text tobj_affichage_char
                        from type_objet, objet_generique, objets, objet_position
                        where tobj_cod = gobj_tobj_cod
                        and gobj_cod = obj_gobj_cod
                        and obj_cod = pobj_obj_cod
                        and pobj_pos_cod = ligne.pos_cod
                        order by random() limit 1;
                if not found then
                    -- Objets : Un des codes au hasard
                    -- Sinon : Rien
                    v_pos_text := ' ';
                else
                    v_objets := true;
                end if;
            end if;

            if v_pos_text = ' ' then
                -- Pas d''objets non plus. Brouzoufs : $
                if exists (select 1 from or_position
                        where por_pos_cod = ligne.pos_cod) then
                    v_brouzoufs := true;
                    v_pos_text := '$';
                end if;
            end if;
            texte_retour := texte_retour || v_pos_text;
        end if;

        -- On rajoute un espace pour rendre l''affichage plus "carré"
        texte_retour := texte_retour || ' ';
    end loop;
    texte_retour := texte_retour || '</pre>';

    -- Légende
    texte_retour := texte_retour || '<pre style="float:right;">';
    if v_aventurier then
        texte_retour := texte_retour || e'@ Vous-même\r\n';
    end if;
    if v_murs then
        texte_retour := texte_retour || e'# Un mur\r\n';
    end if;
    if v_lieux then
        texte_retour := texte_retour || e'^ Un lieu\r\n';
    end if;
    if v_brouillard then
        texte_retour := texte_retour || e'. Brouillard de guerre\r\n';
    end if;
    if v_monstres then
        texte_retour := texte_retour || e'A-Z Monstres\r\n';
    end if;
    if v_persos then
        texte_retour := texte_retour || e'° Aventuriers\r\n';
    end if;
    if v_melee then
        texte_retour := texte_retour || e'% Mêlée\r\n';
    end if;
    if v_brouzoufs then
        texte_retour := texte_retour || e'$ Brouzoufs\r\n';
    end if;
    if v_objets then
        texte_retour := texte_retour || e'Autres: Divers objets\r\n';
    end if;


return texte_retour;
end;
$_$;


ALTER FUNCTION public.vue_pre(integer) OWNER TO delain;

