--
-- Name: cree_groupe_mission(integer, integer, text); Type: FUNCTION; Schema: quetes; Owner: delain
--

CREATE FUNCTION quetes.cree_groupe_mission(integer, integer, text) RETURNS text
    LANGUAGE plpgsql
    AS $_$/***********************************************/
/* cree_mission                                */
/*  $1 = perso_cod                             */
/*  $2 = mission_cod	                         */
/*  $3 = nom du groupe                         */
/***********************************************/
declare
	code_retour text;
	v_nom_groupe alias for $3;
	v_mission alias for $2;
	v_perso alias for $1;
	temp integer;
	v_num_groupe integer;
begin
	select into temp
		mgroupedef_cod
		from quetes.mission_groupe_def
		where lower(mgroupedef_nom) = lower(v_nom_groupe);
	if found then
		return 'Désolé, un groupe de mission porte déjà ce nom.<br>
			<a href="''.$PHP_SELF.''?methode=cree">Retour à la création</a>';
	end if;
	--Controle sur l'étage de la mission et l'étage du perso
	select into v_num_groupe pos_etage from perso_position,positions,quetes.mission
		where ppos_perso_cod = v_perso
		and ppos_pos_cod = pos_cod
		and pos_etage = mission_etage_numero
		and mission_cod = v_mission;
	if not found then
		return 'Erreur ! Vous essayez de créer un groupe de mission dans le mauvais étage pour cette mission.';
	end if;
	--controle sur l'appartenance du perso à un autre groupe
	select into v_num_groupe mgroupedef_cod from quetes.mission_groupe_def,quetes.mission_groupe
				where mgroupedef_cod = mgroupe_groupe_cod
				and mgroupe_perso_cod = v_perso
				and mgroupedef_mission_cod = v_mission
				and mgroupedef_statut = 'O';
	if found then
		return 'Erreur ! Vous ne pouvez pas créer un nouveau groupe de mission car vous appartenez déjà à un groupe pour cette mission.';
	end if;
	-- on prend la séquence
	v_num_groupe := nextval('quetes.seq_mgroupe_cod');
	-- on crée le groupe
	-- on intègre perso comme chef
	return '<br>Le groupe a bien été créé.<br>';
end;$_$;


ALTER FUNCTION quetes.cree_groupe_mission(integer, integer, text) OWNER TO delain;

--
-- Name: invite_mission(integer, integer, integer, text); Type: FUNCTION; Schema: quetes; Owner: delain
--

CREATE FUNCTION quetes.invite_mission(integer, integer, integer, text) RETURNS text
    LANGUAGE plpgsql
    AS $_$/***********************************************/
/* invite_groupe                               */
/*  $1 = perso_cod invitant                    */
/*  $2 = mission_cod                            */
/*  $3 = perso_cod invité                      */
/*  $4 = message au perso                      */
/***********************************************/
declare
	code_retour text;
	v_invitant alias for $1;
	v_groupe_cod alias for $2;
	v_invite alias for $3;
	v_message alias for $4;
	v_num_mes integer;
	v_texte_mes text;
	v_nom_invitant text;
	v_nom_invite text;
	v_type integer;
	v_nom_groupe text;
	is_visible integer;
	pos_perso_lead integer;
	pos_perso_invit integer;
	chef text;                 --Détermine si le perso invitant est chef du groupe
	v_groupe integer;
	v_taille_groupe integer;
	v_taille_mission integer;
	v_mission_statut text;
	nombre_participation integer;
	participation_max integer;
	v_corps text;

begin
	select into v_num_mes
		mgroupe_perso_cod
		from quetes.mission_groupe
		where mgroupe_perso_cod = v_invite
		and mgroupe_groupe_cod = v_groupe_cod;
	if found then
		return '<b>Erreur ! Cet aventurier fait déjà partie de ce groupe de mission</b>';
	end if;

/*********************************************/
/******     CONTROLES                   ******/
/*********************************************/

	select into v_nom_invite,v_type perso_nom,perso_type_perso
		from perso
		where perso_cod = v_invite;
	if v_type != 1 then
		return 'Erreur ! Seuls les aventuriers peuvent décider de participer à une mission. Sont prohibés notamment les familiers.';
	end if;
	--Controle de l'invité
	select into v_groupe mgroupedef_cod
		from quetes.mission_groupe,quetes.mission_groupe_def
		where mgroupe_perso_cod = v_invite
		and mgroupedef_mission_cod = v_groupe_cod
		and mgroupedef_cod = mgroupe_groupe_cod
		and mgroupe_statut != 'D'
		and mgroupedef_statut = 'O';
	if found then
		return 'Erreur ! '||v_nom_invite||' fait déjà partie d''un groupe pour cette mission';
	end if;
	-- Controle de l'invitant
	select into chef,v_groupe mgroupe_statut,mgroupedef_cod
		from quetes.mission_groupe,quetes.mission_groupe_def
		where mgroupe_perso_cod = v_invitant
		and mgroupedef_mission_cod = v_groupe_cod
		and mgroupedef_cod = mgroupe_groupe_cod
		and mgroupe_statut = 'O'
		and mgroupedef_statut = 'O';
	if not found or chef != 'O' then
		return 'Erreur ! Vous n''êtes pas le chef du groupe, vous ne pouvez pas inviter un autre membre !';
	end if;
	select into v_num_mes pos_etage from perso_position,positions,quetes.mission,quetes.mission_groupe_def
		where ppos_perso_cod = v_invite
		and ppos_pos_cod = pos_cod
		and pos_etage = mission_etage_numero
		and mgroupedef_mission_cod = v_groupe_cod
		and mgroupedef_mission_cod = mission_cod
		and mgroupedef_statut = 'O';
	if not found then
		return 'Erreur ! '||v_nom_invite||' ne se trouve pas a l''étage où doit se dérouler cette mission';
	end if;
	--Controle taille du groupe
	select into v_taille_mission,participation_max,v_mission_statut mission_taille,mission_perso_participe,mission_statut from quetes.mission
		where  mission_cod = v_groupe_cod;
	if v_mission_statut = 'N' then
		return 'Cette mission est fermée !';
	end if;
	select into v_taille_groupe
		count(mgroupe_perso_cod)
		from quetes.mission_groupe,quetes.mission_groupe_def
		where mgroupe_statut in ('O','N')
		and mgroupe_groupe_cod = mgroupedef_cod
		and mgroupedef_mission_cod = v_groupe_cod
		and mgroupedef_cod = v_groupe;
	if v_taille_groupe >= v_taille_mission then
		return 'Ce groupe est déjà complet pour cette mission.';
	end if;


	--Gérer le nombre de participation à une même mission
	select into nombre_participation count(mhall_perso_cod) from quetes.mission_hall
			where mhall_mission_cod = v_groupe_cod
			and mhall_perso_cod = v_invite;
	if found and nombre_participation >= participation_max then
		return 'Erreur ! '||v_nom_invite||' a réalisé suffisamment de fois cette mission. Il ne peut pas être inclus à nouveau dans un groupe de mission';
	end if;

/********  Fin des controles  *******/
	--On intègre une invitation
	values (v_groupe,v_invite,'E');
	-- on prépare un message
	select into v_nom_invitant perso_nom
		from perso
		where perso_cod = v_invitant;
	select into v_nom_groupe mgroupedef_nom
		from quetes.mission_groupe_def
		where mgroupedef_cod = v_groupe;
	v_num_mes := nextval('seq_msg_cod');
	--
	v_corps := v_nom_invitant||' vous invite dans son groupe de combat <b>'||v_nom_groupe||'</b>.<br>
		Voici son message :<br>
		<i><b>"'||v_message||'"</b></i><br><br>
		Vous pouvez visualiser le statut de cette mission en <a href="desc_etage.php">cliquant ici</a>, et ainsi postuler à ce groupe';
		values (v_num_mes,v_invitant);
		values (v_num_mes,v_invite,'N','N');
	return '<br>L''invitation a bien été envoyée. Le destinataire peut faire acte de candidature si il le désire.<br>';
end;$_$;


ALTER FUNCTION quetes.invite_mission(integer, integer, integer, text) OWNER TO delain;

--
-- Name: liste_etapes_quete(integer); Type: FUNCTION; Schema: quetes; Owner: delain
--

CREATE FUNCTION quetes.liste_etapes_quete(integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/* Liste les étapes d'une quête automatique
   Retourne une chaine de codes d'étapes séparés par des espaces. */
declare
    v_quete_cod alias for $1;
    code_retour text;
    v_etape_suivante integer;
begin
    v_etape_suivante := 0;
    select into v_etape_suivante aquete_etape_cod from quetes.quete_automatique where aquete_cod = v_quete_cod;
    code_retour := v_etape_suivante::text;

    while v_etape_suivante != 0 loop
        select into v_etape_suivante equete_etape_suivante from quetes.quete_automatique_etape where equete_aquete_cod = v_quete_cod and equete_etape_cod = v_etape_suivante;
        code_retour := code_retour || ' ' || v_etape_suivante::text;
    end loop;
    return code_retour;
end;$_$;


ALTER FUNCTION quetes.liste_etapes_quete(integer) OWNER TO delain;

--
-- Name: rejoindre_mission(integer, integer, integer); Type: FUNCTION; Schema: quetes; Owner: delain
--

CREATE FUNCTION quetes.rejoindre_mission(integer, integer, integer) RETURNS text
    LANGUAGE plpgsql
    AS $_$/***********************************************/
/* rejoindre_mission                           */
/*  $1 = perso_cod                             */
/*  $2 = mission_cod                           */
/*  $3 = groupe_cod                            */
/***********************************************/
declare
	code_retour text;
	v_perso alias for $1;
	v_mission alias for $2;
	v_groupe_cod alias for $3;
	v_chef integer;
	v_num_mes integer;
	v_texte_mes text;
	v_nom_invite text;
	v_type integer;
	v_nom_groupe text;
	invitation text;
	ligne record;
	v_taille_mission integer;
	v_taille_groupe integer;
	v_mission_statut text;
	participation_max integer;
	nombre_participation integer;


begin
	select into v_nom_invite,v_type perso_nom,perso_type_perso from perso where perso_cod = v_perso;
	if v_type != 1 then
		return 'Erreur ! Seuls les aventuriers peuvent décider de participer à une mission. Sont prohibés notamment les familiers.';
	end if;
/*Controle de l'étage, pour voir si en adéquation avec la mission*/
	select into v_taille_mission,participation_max,v_mission_statut mission_taille,mission_perso_participe,mission_statut from perso_position,positions,quetes.mission
		where ppos_perso_cod = v_perso
		and ppos_pos_cod = pos_cod
		and pos_etage = mission_etage_numero
		and mission_cod = v_mission;
	if not found then
		return 'Erreur ! Vous n''êtes pas à l''étage où doit se dérouler cette mission';
	end if;
	if v_mission_statut = 'N' then
		return 'Cette mission est fermée !';
	end if;
	select into v_num_mes
		mgroupe_perso_cod
		from quetes.mission_groupe,quetes.mission_groupe_def
		where mgroupe_perso_cod = v_perso
		and mgroupe_statut in ('O','N')
		and mgroupe_groupe_cod = mgroupedef_cod
		and mgroupedef_mission_cod = v_mission;
	if found then
		return 'Erreur ! Vous faites déjà partie d''un autre groupe de mission.';
	end if;
/*Controle de la bonne réception d'une invitation */
	select into v_taille_groupe
		count(mgroupe_perso_cod)
		from quetes.mission_groupe,quetes.mission_groupe_def
		where mgroupe_statut in ('O','N')
		and mgroupe_groupe_cod = mgroupedef_cod
		and mgroupedef_mission_cod = v_mission
    and mgroupe_groupe_cod = v_groupe_cod;
	if v_taille_groupe >= v_taille_mission then
		return 'Ce groupe est déjà complet pour cette mission. Vous devriez soit chercher un autre groupe, soit convaincre les chefs de ce groupe de changer leur stratégie ...';
	end if;
	--Gérer le nombre de participation à une même mission
	select into nombre_participation count(mhall_perso_cod) from quetes.mission_hall where mhall_mission_cod = v_mission and mhall_perso_cod = v_perso;
	if found and nombre_participation >= participation_max then
		return 'Vous avez déjà réalisé cette mission un nombre de fois suffisant. Vous n''en apprendrez rien de plus. Rien ne sert donc de vous inscrire à nouveau.';
	end if;
	select into invitation mgroupe_statut from quetes.mission_groupe
		where mgroupe_perso_cod = v_perso
		and mgroupe_groupe_cod = v_groupe_cod;
	if not found then
		-- on prépare un message
		v_num_mes := nextval('seq_msg_cod');
												values (v_num_mes,v_perso);
										values (v_num_mes,'Demande accès à votre groupe de mission',v_nom_invite||' souhaiterait être intégré dans votre groupe de mission.');
		for ligne in select mgroupe_perso_cod,perso_nom from perso,quetes.mission_groupe
			where mgroupe_perso_cod = perso_cod
			and mgroupe_groupe_cod = v_groupe_cod
			and mgroupe_statut = 'O' loop
													values (v_num_mes,ligne.mgroupe_perso_cod,'N','N');
		end loop;
		return 'Vous n''avez pas été invité par les chefs à faire partie de ce groupe. Une demande d''invitation va leur être envoyé.
		<br>Il est conseillé de prendre directement contact avec eux pour valoriser votre candidature.<br><br>';


	elsif invitation = 'E' then

		-- on commence par valider l'invitation
		update quetes.mission_groupe
			set mgroupe_statut = 'N'
			where mgroupe_perso_cod = v_perso
			and mgroupe_groupe_cod = v_groupe_cod;
		-- on prépare un message
			v_num_mes := nextval('seq_msg_cod');
				values (v_num_mes,v_perso);
		--Message pour les chefs
		for ligne in select mgroupe_perso_cod,perso_nom from perso,quetes.mission_groupe
			where perso_cod = v_perso
			and mgroupe_perso_cod = v_perso
			and mgroupe_groupe_cod = v_groupe_cod
			and mgroupe_statut = 'O' loop
										values (v_num_mes,'Invitation acceptée à un groupe de mission',v_nom_invite||' a accepté votre invitation pour faire partie de votre groupe de mission.');
													values (v_num_mes,ligne.mgroupe_perso_cod,'N','N');
		end loop;
		return 'Vous faites maintenant partie d''un groupe de mission.';
	end if;

end;$_$;


ALTER FUNCTION quetes.rejoindre_mission(integer, integer, integer) OWNER TO delain;

--
-- Name: CAST (integer AS text); Type: CAST; Schema: -; Owner:
--

CREATE CAST (integer AS text) WITH FUNCTION public.int_to_text(integer) AS IMPLICIT;


SET default_tablespace = '';

