    gmon_amelioration_armure integer NOT NULL,
    gmon_niveau integer NOT NULL,
    gmon_nb_des_degats integer,
    gmon_val_des_degats integer,
    gmon_or integer,
    gmon_arme integer,
    gmon_armure integer,
    gmon_soutien character varying(1),
    gmon_amel_deg_dist integer,
    gmon_vampirisme numeric,
    gmon_taille integer,
    gmon_avatar character varying,
    gmon_description text,
    gmon_fonction_mort text,
    gmon_type_ia integer DEFAULT 1,
    gmon_fonction_debut_dlt character varying,
    gmon_fonction_tue character varying,
