--
-- Name: Monstres; Type: VIEW; Schema: public; Owner: delain
--

CREATE VIEW public."Monstres" AS
 SELECT monstre_generique.gmon_cod,
    monstre_generique.gmon_nom,
    monstre_generique.gmon_avatar
   FROM public.monstre_generique
  WHERE ((monstre_generique.gmon_avatar)::text = NULL::text)
  ORDER BY monstre_generique.gmon_nom;


ALTER TABLE public."Monstres" OWNER TO delain;

