--
-- Name: v_factions_lieux; Type: VIEW; Schema: public; Owner: delain
--

CREATE VIEW public.v_factions_lieux AS
 SELECT faction_lieu_type.tlfac_fac_cod AS fac_cod,
    l.lieu_tlieu_cod AS tlieu_cod,
    l.pos_cod,
    l.pos_etage,
    l.etage_reference,
    l.lieu_dieu_cod AS dieu_cod,
    l.lieu_levo_niveau,
    l.etage_libelle,
    l.lieu_nom,
    factions.fac_nom,
    l.lieu_cod
   FROM ((public.faction_lieu_type
     JOIN public.factions ON ((factions.fac_cod = faction_lieu_type.tlfac_fac_cod)))
     JOIN ( SELECT lieu.lieu_tlieu_cod,
            positions.pos_cod,
            lieu.lieu_levo_niveau,
            lieu.lieu_dieu_cod,
            positions.pos_etage,
            etage.etage_reference,
            etage.etage_libelle,
            lieu.lieu_nom,
            lieu.lieu_cod
           FROM (((public.lieu
             JOIN public.lieu_position ON ((lieu_position.lpos_lieu_cod = lieu.lieu_cod)))
             JOIN public.positions ON ((positions.pos_cod = lieu_position.lpos_pos_cod)))
             JOIN public.etage ON ((etage.etage_numero = positions.pos_etage)))) l ON (((l.lieu_tlieu_cod = faction_lieu_type.tlfac_tlieu_cod) AND ((l.lieu_dieu_cod = faction_lieu_type.tlfac_dieu_cod) OR (faction_lieu_type.tlfac_dieu_cod = '-1'::integer)) AND (faction_lieu_type.tlfac_levo_niveau <= l.lieu_levo_niveau) AND (l.etage_reference <= faction_lieu_type.tlfac_etage_min) AND ((l.etage_reference > faction_lieu_type.tlfac_etage_max) OR (faction_lieu_type.tlfac_etage_max IS NULL)))))
  WHERE (factions.fac_active = 'O'::bpchar);


ALTER TABLE public.v_factions_lieux OWNER TO delain;

--
-- Name: VIEW v_factions_lieux; Type: COMMENT; Schema: public; Owner: delain
--

COMMENT ON VIEW public.v_factions_lieux IS 'Vue donnant les lieux dispo pour chaque faction (évite de coder la grosse jointure à chaque fois...)';


--
-- Name: v_revguilde; Type: VIEW; Schema: public; Owner: delain
--

CREATE VIEW public.v_revguilde AS
 SELECT lanceur.perso_cod AS code_lanceur,
    lanceur.perso_nom AS nom_lanceur,
    cible.perso_cod AS code_cible,
    cible.perso_nom AS nom_cible,
    guilde_revolution.revguilde_cod AS code_rev,
    guilde_revolution.revguilde_guilde_cod AS guilde,
    ( SELECT count(guilde_revolution_vote.vrevguilde_cod) AS count
           FROM public.guilde_revolution_vote
          WHERE ((guilde_revolution_vote.vrevguilde_revguilde_cod = guilde_revolution.revguilde_cod) AND ((guilde_revolution_vote.vrevguilde_vote)::text = 'O'::text))) AS oui,
    ( SELECT count(guilde_revolution_vote.vrevguilde_cod) AS count
           FROM public.guilde_revolution_vote
          WHERE ((guilde_revolution_vote.vrevguilde_revguilde_cod = guilde_revolution.revguilde_cod) AND ((guilde_revolution_vote.vrevguilde_vote)::text = 'N'::text))) AS non,
    ( SELECT count(perso.perso_cod) AS count
           FROM public.guilde_perso,
            public.perso
          WHERE ((guilde_perso.pguilde_guilde_cod = guilde_revolution.revguilde_guilde_cod) AND (guilde_perso.pguilde_perso_cod = perso.perso_cod) AND ((guilde_perso.pguilde_valide)::text = 'O'::text) AND ((perso.perso_actif)::text = 'O'::text) AND (perso.perso_type_perso = 1))) AS nb_membres,
    to_char(guilde_revolution.revguilde_datfin, 'DD/MM/YYYY hh24:mi:ss'::text) AS date_fin
   FROM public.perso lanceur,
    public.perso cible,
    public.guilde_revolution
  WHERE ((guilde_revolution.revguilde_lanceur = lanceur.perso_cod) AND (guilde_revolution.revguilde_cible = cible.perso_cod));


ALTER TABLE public.v_revguilde OWNER TO delain;

