--

CREATE TABLE quetes.mission_objectif (
    mobject_object_cod integer NOT NULL,
    mobject_mission_cod integer NOT NULL,
    mobject_date_deb timestamp with time zone DEFAULT now(),
    mobject_date_prise timestamp with time zone DEFAULT now(),
    mobject_perso_cod integer,
    mobject_desc text,
    mobject_pos_cod integer,
    mobject_type_object integer NOT NULL,
    mobject_action text,
    mobject_statut character varying DEFAULT 'D'::character varying,
    mobject_temps integer DEFAULT 0,
    mobject_param_text text,
    mobject_object_suivant text,
    mobject_ouverture text
);


ALTER TABLE quetes.mission_objectif OWNER TO delain;

--
-- Name: COLUMN mission_objectif.mobject_type_object; Type: COMMENT; Schema: quetes; Owner: delain
--

COMMENT ON COLUMN quetes.mission_objectif.mobject_type_object IS 'Type d''objectif (prise de point, flag ...)';


--
-- Name: COLUMN mission_objectif.mobject_action; Type: COMMENT; Schema: quetes; Owner: delain
--

COMMENT ON COLUMN quetes.mission_objectif.mobject_action IS 'Fonction qui peut se déclencher à l''issue de la réalisation de l''objectif (création de monstres, création de nouvel objectif, création d''objet ...)';


--
-- Name: COLUMN mission_objectif.mobject_statut; Type: COMMENT; Schema: quetes; Owner: delain
--

COMMENT ON COLUMN quetes.mission_objectif.mobject_statut IS 'Objectif réalisé ou non (si c''est O, il est considéré comme cloturé), ou non disponible (D) car devant être débloquée, ou R pour raté dans certains cas (temps ou autre)';


--
-- Name: COLUMN mission_objectif.mobject_temps; Type: COMMENT; Schema: quetes; Owner: delain
--

COMMENT ON COLUMN quetes.mission_objectif.mobject_temps IS 'temps en heure pour considérer l''objectif comme pris';


